window.BANK={"big": {"1": [{"id": "big-k1-0", "name": "Colors and numbers", "desc": "Warna dan angka 1-20", "idx": 0, "soal": [{"lv": 1, "q": "Angka 2 dalam Bahasa Inggris adalah...", "o": ["Two", "Three", "One", "Four"], "a": 0, "p": "Angka 2 disebut 'Two' dalam Bahasa Inggris."}, {"lv": 1, "q": "The sky is blue. Apa warna 'blue'?", "o": ["Merah", "Biru", "Hijau", "Kuning"], "a": 1, "p": "Blue artinya warna biru."}, {"lv": 1, "q": "Angka 10 dalam Bahasa Inggris adalah...", "o": ["Nine", "Eight", "Ten", "Seven"], "a": 2, "p": "Angka 10 disebut 'Ten' dalam Bahasa Inggris."}, {"lv": 1, "q": "A banana is...", "o": ["Purple", "Black", "Pink", "Yellow"], "a": 3, "p": "Pisang umumnya berwarna kuning atau 'Yellow'."}, {"lv": 2, "q": "Five plus three is...", "o": ["Eight", "Seven", "Nine", "Six"], "a": 0, "p": "5 + 3 = 8. Angka 8 adalah 'Eight'."}, {"lv": 2, "q": "What number comes after eleven?", "o": ["Thirteen", "Twelve", "Ten", "Fourteen"], "a": 1, "p": "Setelah eleven (11) adalah twelve (12)."}, {"lv": 2, "q": "What is the color of grass?", "o": ["Orange", "Blue", "Green", "White"], "a": 2, "p": "Rumput berwarna hijau atau 'Green'."}, {"lv": 2, "q": "Six plus four is...", "o": ["Seven", "Eight", "Nine", "Ten"], "a": 3, "p": "6 + 4 = 10. Angka 10 adalah 'Ten'."}, {"lv": 3, "q": "I have 3 red balls and 4 blue balls. How many balls do I have?", "o": ["Seven", "Six", "Eight", "Five"], "a": 0, "p": "3 + 4 = 7. Total bola ada tujuh atau 'Seven'."}, {"lv": 3, "q": "What is the number before twenty?", "o": ["Eighteen", "Nineteen", "Seventeen", "Sixteen"], "a": 1, "p": "Sebelum twenty (20) adalah nineteen (19)."}, {"lv": 3, "q": "How do you spell (mengeja) number 13?", "o": ["Tigabelas", "Thirty", "Thirteen", "Three"], "a": 2, "p": "Ejaan 13 yang benar adalah 'Thirteen'. Hati-hati tertukar dengan 30 (Thirty)."}, {"lv": 3, "q": "I have ten fingers. I hide five fingers. How many fingers are left?", "o": ["Six", "Four", "Seven", "Five"], "a": 3, "p": "10 - 5 = 5. Sisanya ada lima jari atau 'Five'."}]}, {"id": "big-k1-1", "name": "Animals", "desc": "Nama-nama hewan", "idx": 1, "soal": [{"lv": 1, "q": "Apa Bahasa Inggris dari 'Kucing'?", "o": ["Bird", "Cat", "Dog", "Fish"], "a": 1, "p": "Kucing dalam Bahasa Inggris disebut 'Cat'."}, {"lv": 1, "q": "Apa Bahasa Inggris dari 'Anjing'?", "o": ["Dog", "Elephant", "Ant", "Bee"], "a": 0, "p": "Anjing dalam Bahasa Inggris disebut 'Dog'."}, {"lv": 1, "q": "Apa Bahasa Inggris dari 'Ikan'?", "o": ["Lion", "Snake", "Fish", "Tiger"], "a": 2, "p": "Ikan dalam Bahasa Inggris disebut 'Fish'."}, {"lv": 1, "q": "Apa Bahasa Inggris dari 'Burung'?", "o": ["Duck", "Chicken", "Cow", "Bird"], "a": 3, "p": "Burung dalam Bahasa Inggris disebut 'Bird'."}, {"lv": 2, "q": "Hewan yang bisa terbang (fly) adalah...", "o": ["Bird", "Rabbit", "Cat", "Fish"], "a": 0, "p": "Burung atau 'Bird' adalah hewan yang bisa terbang di langit."}, {"lv": 2, "q": "Hewan besar yang punya belalai (trunk) adalah...", "o": ["Ant", "Elephant", "Monkey", "Spider"], "a": 1, "p": "Gajah dalam Bahasa Inggris adalah 'Elephant', ia punya belalai panjang."}, {"lv": 2, "q": "Hewan yang hidup di dalam air (water) adalah...", "o": ["Cow", "Lion", "Fish", "Horse"], "a": 2, "p": "Ikan atau 'Fish' adalah hewan yang tinggal dan bernapas di dalam air."}, {"lv": 2, "q": "Hewan yang telinganya panjang dan melompat (hop) adalah...", "o": ["Snake", "Bee", "Bear", "Rabbit"], "a": 3, "p": "Kelinci atau 'Rabbit' punya telinga panjang dan jalannya melompat."}, {"lv": 3, "q": "Aku punya leher yang sangat panjang (very long neck). Aku adalah...", "o": ["Giraffe", "Zebra", "Lion", "Hippo"], "a": 0, "p": "Jerapah atau 'Giraffe' adalah hewan yang terkenal karena lehernya yang sangat panjang."}, {"lv": 3, "q": "Aku hewan kecil, suka makan keju (cheese), dan berbunyi 'cit-cit'. Aku adalah...", "o": ["Cat", "Mouse", "Dog", "Elephant"], "a": 1, "p": "Tikus atau 'Mouse' adalah hewan kecil yang sering digambarkan suka makan keju."}, {"lv": 3, "q": "Hewan yang badannya punya garis hitam dan putih (stripes) adalah...", "o": ["Tiger", "Cow", "Zebra", "Horse"], "a": 2, "p": "Zebra adalah hewan yang mirip kuda tetapi memiliki pola garis hitam dan putih."}, {"lv": 3, "q": "Aku berkaki empat, menghasilkan susu, dan suaraku 'moo-moo'. Aku adalah...", "o": ["Goat", "Sheep", "Chicken", "Cow"], "a": 3, "p": "Sapi dalam Bahasa Inggris adalah 'Cow', suaranya khas 'moo' dan menghasilkan susu."}]}, {"id": "big-k1-2", "name": "Greetings", "desc": "Salam dan perkenalan", "idx": 2, "soal": [{"lv": 1, "q": "Saat bertemu teman di pagi hari, kita mengucapkan...", "o": ["Good morning", "Good night", "Good evening", "Goodbye"], "a": 0, "p": "'Good morning' adalah salam yang digunakan di pagi hari."}, {"lv": 1, "q": "Jika ada orang menyapa 'Hello!', kita bisa menjawab dengan...", "o": ["I am fine", "Thank you", "Hi!", "You are welcome"], "a": 2, "p": "Sapaan 'Hello' paling tepat dibalas dengan 'Hi' atau 'Hello' juga."}, {"lv": 1, "q": "Untuk menyebutkan nama, kita bilang: 'My ___ is Andy.'", "o": ["Color", "Number", "Name", "Animal"], "a": 2, "p": "'My name is...' artinya 'Nama saya adalah...'."}, {"lv": 1, "q": "Cara menanyakan nama seseorang adalah: 'What is your ___?'", "o": ["Home", "Friend", "Age", "Name"], "a": 3, "p": "'What is your name?' digunakan untuk menanyakan nama orang lain."}, {"lv": 2, "q": "A: 'How are you?' B: 'I am ___, thank you.'", "o": ["Fine", "Seven", "Yellow", "Cat"], "a": 0, "p": "'Fine' berarti baik, digunakan untuk membalas pertanyaan kabar."}, {"lv": 2, "q": "Sudah jam 7 malam. Salam yang kita ucapkan adalah...", "o": ["Good morning", "Good evening", "Good afternoon", "Goodbye"], "a": 1, "p": "Di atas jam 6 sore sampai malam, kita menyapa dengan 'Good evening'."}, {"lv": 2, "q": "Saat pulang sekolah dan berpamitan kepada guru, kita bilang...", "o": ["Hello", "Good morning", "Goodbye", "I am fine"], "a": 2, "p": "'Goodbye' artinya 'Selamat tinggal' atau 'Sampai jumpa'."}, {"lv": 2, "q": "Lengkapi kalimat ini: 'Nice to ___ you.'", "o": ["Fine", "Hello", "Meet", "Name"], "a": 2, "p": "'Nice to meet you' artinya 'Senang berkenalan/bertemu denganmu'."}, {"lv": 3, "q": "Ani: 'My name is Ani. What is your name?' Budi: '...'", "o": ["Hi, I am Budi", "I am fine", "Thank you", "Good morning"], "a": 0, "p": "Jawaban terbaik saat ditanya nama adalah menyebutkan nama diri sendiri."}, {"lv": 3, "q": "Kamu akan pergi tidur. Apa yang kamu katakan ke Ibu?", "o": ["Good morning", "Good night", "Good afternoon", "Hello"], "a": 1, "p": "'Good night' diucapkan saat akan pergi tidur atau berpisah di malam hari."}, {"lv": 3, "q": "Tom: 'Nice to meet you.' Jerry: 'Nice to meet you, ___.'", "o": ["See", "Hello", "Too", "Fine"], "a": 2, "p": "Kata 'Too' artinya 'juga', digunakan untuk membalas ungkapan yang sama."}, {"lv": 3, "q": "Matahari sedang panas-panasnya di jam 1 siang. Kita menyapa dengan...", "o": ["Good night", "Good morning", "Goodbye", "Good afternoon"], "a": 3, "p": "Siang hari (setelah jam 12 siang) kita menggunakan 'Good afternoon'."}]}], "10": [{"id": "big-k10-0", "name": "Descriptive text", "desc": "Mendeskripsikan tempat dan orang", "idx": 0, "soal": [{"lv": 1, "q": "What is the primary social function of a descriptive text?", "o": ["To retell past experiences chronologically", "To explain how something is made through steps", "To describe a particular person, place, or thing specifically", "To persuade readers to agree with an opinion"], "a": 2, "p": "Fungsi sosial teks deskriptif adalah mendeskripsikan secara spesifik ciri-ciri suatu objek tertentu, baik orang, tempat, maupun benda."}, {"lv": 1, "q": "Which of the following is the correct generic structure of a descriptive text?", "o": ["Orientation - Complication - Resolution", "Identification - Description", "Goal - Materials - Steps", "General Classification - Description"], "a": 1, "p": "Struktur teks deskriptif terdiri dari dua bagian utama: Identification (pengenalan objek) dan Description (penjelasan detail ciri-ciri objek)."}, {"lv": 1, "q": "Which tense is predominantly used in writing a descriptive text?", "o": ["Simple Past Tense", "Present Continuous Tense", "Simple Present Tense", "Past Perfect Tense"], "a": 2, "p": "Teks deskriptif menggunakan Simple Present Tense karena mendeskripsikan fakta atau sifat permanen dari suatu objek yang sedang dibahas."}, {"lv": 1, "q": "In the descriptive text structure, the part that introduces the specific object being described is called...", "o": ["Identification", "Resolution", "Reorientation", "Conclusion"], "a": 0, "p": "Bagian Identification terletak di paragraf awal untuk mengenalkan objek apa atau siapa yang akan dideskripsikan secara umum."}, {"lv": 2, "q": "Read the excerpt: 'My English teacher, Mr. David, is a very charismatic person. He is quite tall with short wavy hair and wears glasses.' \nWhat specific aspect of Mr. David is being described?", "o": ["His personality and daily habits", "His physical appearance and personal traits", "His educational background", "His professional achievements"], "a": 1, "p": "Kutipan tersebut menjelaskan ciri fisik (tall, wavy hair, glasses) dan sifat (charismatic), yang mencakup aspek fisik dan karakter."}, {"lv": 2, "q": "Which sentence uses an adjective clause correctly to describe a place?", "o": ["Raja Ampat is a place where many divers love to explore.", "Raja Ampat is visiting by tourists every year.", "Raja Ampat has beautiful beaches and swim there.", "Raja Ampat is where to beautiful underwater scenery."], "a": 0, "p": "Pilihan A menggunakan adjective clause yang tepat ('where many divers love to explore') untuk memperjelas tempat Raja Ampat."}, {"lv": 2, "q": "Read the sentence: 'Borobudur Temple stands majestically as a giant Buddhist monument in Central Java.' \nThe word 'majestically' functions as an...", "o": ["Adjective modifying the temple", "Adverb describing how the temple stands", "Noun phrase indicating location", "Action verb showing movement"], "a": 1, "p": "Kata 'majestically' adalah adverb (kata keterangan) yang menjelaskan cara kata kerja 'stands' (berdiri dengan megah)."}, {"lv": 2, "q": "When writing a descriptive text about a historical building, why do we use specific (particular) nouns instead of general nouns?", "o": ["To make the readers confused about the location", "To focus on describing one specific object rather than a category", "To show that the building is old and abandoned", "To change the text into a recount text"], "a": 1, "p": "Ciri kebahasaan teks deskriptif adalah menggunakan specific participant (objek khusus seperti 'Eiffel Tower', bukan 'a tower')."}, {"lv": 3, "q": "Read the text excerpt: \n'Mount Bromo is an active volcano in East Java. Its caldera is surrounded by a vast sea of sand known as the Whispering Sands, creating a lunar-like landscape that mesmerizes every traveler.' \nWhat does the phrase 'lunar-like landscape' imply?", "o": ["The landscape is dark and completely covered in deep water.", "The landscape resembles the surface of the moon due to its volcanic sand and barren terrain.", "The area is located on the moon rather than on Earth.", "The sand glows brightly only during full moon nights."], "a": 1, "p": "Frasa 'lunar-like landscape' adalah metafora yang menggambarkan permukaan kawasan pasir Bromo yang mirip dengan permukaan bulan yang tandus dan berpasir."}, {"lv": 3, "q": "Analyze the following sentences about a person. Which one best represents the 'Description' part focusing on personality rather than physical traits?", "o": ["She has piercing blue eyes and a small nose.", "She always greets everyone with a warm smile and is willing to help those in need.", "She stands about 170 centimeters tall with blonde hair.", "She wears a casual denim jacket and sneakers."], "a": 1, "p": "Pilihan B mendeskripsikan sifat/kepribadian (ramah dan suka menolong), sedangkan pilihan lainnya mendiskusikan atribut fisik."}, {"lv": 3, "q": "Why is the use of attributive and identifying adjectives (e.g., 'ancient', 'magnificent', 'tranquil') crucial in a descriptive text about a tourist destination?", "o": ["To confuse the reader with difficult vocabulary", "To create a vivid mental image and sensory experience for the reader", "To explain the historical timeline of the destination", "To persuade readers to buy tickets online"], "a": 1, "p": "Penggunaan kata sifat (adjective) yang kaya membantu pembaca membayangkan dan merasakan suasana tempat tersebut secara nyata (vivid imagery)."}, {"lv": 3, "q": "Consider a descriptive text about a bustling traditional market. Which sensory detail would be least appropriate to include as a primary focus?", "o": ["The pungent aroma of fresh spices mingling in the air", "The cacophony of vendors shouting their prices", "The historical political debate between local leaders", "The vibrant colors of tropical fruits displayed in stalls"], "a": 2, "p": "Teks deskriptif berfokus pada pengalaman indrawi (pemandangan, suara, bau). Perdebatan politik tidak sesuai dengan fungsi deskripsi suasana pasar."}]}, {"id": "big-k10-1", "name": "Announcement", "desc": "Pengumuman", "idx": 1, "soal": [{"lv": 1, "q": "What is the primary purpose of an announcement text?", "o": ["To tell a fictional story with a moral lesson", "To give formal or informal information to the public or specific readers", "To explain how to operate a mechanical device", "To persuade readers to buy a commercial product"], "a": 1, "p": "Tujuan utama dari teks pengumuman (announcement) adalah memberikan informasi resmi atau informal kepada publik atau pembaca tertentu."}, {"lv": 1, "q": "Which of the following elements is usually included in an announcement?", "o": ["A detailed recipe of ingredients", "Title or type of event, date, time, and contact person", "A romantic conversation between characters", "Steps on how to repair a car engine"], "a": 1, "p": "Sebuah pengumuman umumnya memuat judul/jenis kegiatan, tanggal, waktu, tempat, serta narahubung (contact person)."}, {"lv": 1, "q": "What tense is commonly used in writing an announcement to state schedule and facts?", "o": ["Simple present tense", "Simple past tense", "Past continuous tense", "Past perfect tense"], "a": 0, "p": "Pengumuman sering kali menggunakan Simple Present Tense untuk menyatakan informasi faktual, jadwal, dan ketetapan."}, {"lv": 1, "q": "In a school announcement about a competition, who is usually the sender or issuer of the notice?", "o": ["The store manager", "The school principal or student organization committee", "A fictional novelist", "A tourist guide"], "a": 1, "p": "Pengumuman di sekolah biasanya diterbitkan oleh kepala sekolah atau panitia OSIS (student organization committee)."}, {"lv": 2, "q": "Read the announcement excerpt: 'Due to maintenance work, the computer laboratory will be closed until further notice.' What is the reason for closing the lab?", "o": ["Student holiday", "Maintenance work", "A singing competition", "A graduation ceremony"], "a": 1, "p": "Alasan penutupan laboratorium komputer dinyatakan secara jelas dalam teks, yaitu karena adanya pekerjaan pemeliharaan (maintenance work)."}, {"lv": 2, "q": "An announcement states: 'All participants must register before Friday, 5 p.m.' What does this mean for the participants?", "o": ["Registration is optional", "They can register anytime next week", "There is a strict deadline they must follow", "Registration is free of charge"], "a": 2, "p": "Kata 'must register before' menunjukkan adanya batas waktu atau deadline yang wajib dipatuhi oleh peserta."}, {"lv": 2, "q": "Which phrase is typically used at the end of an announcement to provide a person for inquiries?", "o": ["For further information, please contact Mr. Smith", "Once upon a time in a kingdom", "Mix the flour with sugar", "The end of the story"], "a": 0, "p": "Frasa 'For further information, please contact...' adalah penutup standar dalam pengumuman untuk tempat bertanya."}, {"lv": 2, "q": "If an announcement says 'Attendance is compulsory for all grade X students', what does 'compulsory' mean?", "o": ["Optional / pilihan", "Forbidden / dilarang", "Mandatory / wajib", "Recommended / disarankan"], "a": 2, "p": "Kata 'compulsory' memiliki arti wajib atau harus dihadiri (mandatory)."}, {"lv": 3, "q": "Read the announcement: 'Attention all English Club members. There will be a guest lecture this Saturday at the hall. Please bring your own notebook.' Who is the target audience of this announcement?", "o": ["All school teachers", "All English Club members", "Science laboratory assistants", "General public outside the school"], "a": 1, "p": "Pembaca sasaran (target audience) dari pengumuman tersebut secara spesifik adalah semua anggota English Club ('Attention all English Club members')."}, {"lv": 3, "q": "Analyze the statement in an announcement: 'Latecomers will not be permitted to enter the examination room.' What inference can we make?", "o": ["Students can come anytime they want", "Punctuality is strictly enforced for the exam", "The exam is cancelled", "Late students will receive extra points"], "a": 1, "p": "Pernyataan bahwa peserta yang terlambat tidak diizinkan masuk menunjukkan bahwa ketepatan waktu (punctuality) diberlakukan secara ketat."}, {"lv": 3, "q": "Why is a clear and concise title important at the beginning of an announcement?", "o": ["To make the readers confused", "To immediately grab readers' attention and state what the notice is about", "To turn the announcement into a narrative story", "To hide the main purpose of the text"], "a": 1, "p": "Judul yang jelas dan ringkas berfungsi untuk langsung menarik perhatian pembaca dan memperjelas topik utama pengumuman tersebut."}, {"lv": 3, "q": "Read the excerpt: 'Should you have any questions regarding the scholarship program, kindly reach out to the administration office.' What is the communicative function of this concluding sentence?", "o": ["Providing contact instructions for inquiries", "Giving cooking steps", "Telling a fable", "Describing a tourist resort"], "a": 0, "p": "Kalimat tersebut berfungsi untuk memberikan petunjuk kepada pembaca mengenai cara mengajukan pertanyaan (inquiries) jika membutuhkan informasi lebih lanjut."}]}, {"id": "big-k10-2", "name": "Present perfect tense", "desc": "Have/has + V3", "idx": 2, "soal": [{"lv": 1, "q": "What is the correct auxiliary verb used with singular subjects (he, she, it) in the present perfect tense?", "o": ["Have", "Has", "Had", "Is"], "a": 1, "p": "Dalam present perfect tense, subjek tunggal orang ketiga (he, she, it) menggunakan auxiliary verb 'has' yang diikuti oleh bentuk V3."}, {"lv": 1, "q": "The main verb in a present perfect tense sentence must always be in the form of...", "o": ["Verb 1 (Infinitive)", "Verb 2 (Past Tense)", "Verb 3 (Past Participle)", "Verb-ing (Present Participle)"], "a": 2, "p": "Pola utama dari present perfect tense adalah 'have/has + Verb 3 (Past Participle)' untuk menyatakan aksi yang telah selesai."}, {"lv": 1, "q": "Which of the following sentences is written in the correct present perfect tense form?", "o": ["I has finished my homework.", "They have visited Bali twice.", "She have cooked dinner.", "We is gone to the museum."], "a": 1, "p": "Subjek 'They' menggunakan auxiliary 'have' dan V3 'visited', yang membentuk kalimat present perfect secara gramatikal tepat."}, {"lv": 1, "q": "Which time marker is commonly used in present perfect tense to indicate an action that happened at an unspecified time before now?", "o": ["Yesterday", "Already", "Last week", "Tomorrow"], "a": 1, "p": "Kata keterangan seperti 'already', 'just', dan 'yet' sering digunakan dalam present perfect untuk waktu yang tidak spesifik."}, {"lv": 2, "q": "Complete the sentence: 'My parents ... lived in this town for over twenty years.'", "o": ["has", "have", "had", "are"], "a": 1, "p": "Subjek 'My parents' berbentuk jamak (plural), sehingga auxiliary verb yang tepat digunakan adalah 'have'."}, {"lv": 2, "q": "Change this sentence into a negative present perfect form: 'She has eaten breakfast.'", "o": ["She has not ate breakfast.", "She have not eaten breakfast.", "She has not eaten breakfast.", "She did not eat breakfast."], "a": 2, "p": "Bentuk negatif present perfect adalah 'Subject + has/have + not + V3'. Maka yang benar adalah 'She has not eaten breakfast'."}, {"lv": 2, "q": "Choose the correct interrogative present perfect sentence:", "o": ["Did you finish your project?", "Have you ever been to Japan?", "Are you visited Tokyo?", "Do you has finished it?"], "a": 1, "p": "Kalimat tanya present perfect dimulai dengan pola 'Have/Has + subject + V3'. Pilihan B adalah bentuk interogatif yang tepat."}, {"lv": 2, "q": "We use 'since' in the present perfect tense to show...", "o": ["A duration of time (e.g., for three years)", "A specific starting point in time (e.g., since 2010)", "A future plan", "A habitual action in the past"], "a": 1, "p": "Kata 'since' digunakan untuk menunjukkan titik awal spesifik dimulainya suatu aksi di masa lalu hingga sekarang."}, {"lv": 3, "q": "Choose the correct sentence that uses 'already' in a present perfect statement:", "o": ["I have already read this interesting novel.", "I already have read this novel yesterday.", "I had already read this novel last year.", "I am already reading this novel now."], "a": 0, "p": "Adverb 'already' diletakkan di antara auxiliary (have/has) dan V3 dalam kalimat pernyataan present perfect."}, {"lv": 3, "q": "Dika: 'Can I borrow your umbrella?'\nRina: 'I'm sorry, I ... it to my sister.'", "o": ["have already lent", "has already lend", "had already lent", "already lent"], "a": 0, "p": "Subjek 'I' menggunakan 'have', V3 dari 'lend' adalah 'lent', dan posisi 'already' berada di tengah."}, {"lv": 3, "q": "Identify the grammatical error in this sentence: 'Sinta (A) have (B) not received (C) any email from him (D) yet.'", "o": ["A", "B", "C", "D"], "a": 1, "p": "Bagian (B) salah karena subjek 'Sinta' adalah tunggal orang ketiga (she), sehingga auxiliary verb yang benar adalah 'has', bukan 'have'."}, {"lv": 3, "q": "What is the structural difference in meaning between 'He has gone to London' and 'He has been to London'?", "o": ["There is no difference at all.", "'Has gone' means he went and is still there, while 'has been' means he visited and has returned.", "'Has been' means he is currently on his way to London.", "'Has gone' refers to a future trip."], "a": 1, "p": "'Has gone' menunjukkan subjek sedang berada di perjalanan atau di tujuan (belum kembali), sedangkan 'has been' berarti pernah berkunjung dan sudah pulang."}]}], "11": [{"id": "big-k11-0", "name": "Conditional sentences", "desc": "If clause tipe 1 dan 2", "idx": 0, "soal": [{"lv": 1, "q": "What is the correct structure for a Conditional Sentence Type 1?", "o": ["If + Simple Past, Subject + would + V1", "If + Simple Present, Subject + will + V1", "If + Past Perfect, Subject + would have + V3", "If + Simple Present, Subject + would + V1"], "a": 1, "p": "Pola baku Conditional Sentence Type 1 adalah 'If + Simple Present, Subject + will + V1'."}, {"lv": 1, "q": "If it ... tomorrow, we will stay at home.", "o": ["rains", "rained", "will rain", "had rained"], "a": 0, "p": "Kalimat ini menggunakan Tipe 1. Klausa 'if' membutuhkan Simple Present Tense (subject 'it' + V1-s/es -> rains)."}, {"lv": 1, "q": "Conditional Sentence Type 2 is used to express...", "o": ["A real possibility in the future", "An unreal or hypothetical situation in the present or future", "A past regret that cannot be changed", "A general scientific truth"], "a": 1, "p": "Tipe 2 digunakan untuk menyatakan pengandaian/situasi tidak nyata yang bertentangan dengan kenyataan saat ini."}, {"lv": 1, "q": "If I had a lot of money, I ... a new sports car.", "o": ["will buy", "bought", "would buy", "buy"], "a": 2, "p": "Kalimat ini menggunakan Tipe 2 (If + Simple Past 'had'), sehingga klausa utama menggunakan 'would + V1' (would buy)."}, {"lv": 2, "q": "If Maya ... harder, she will pass the final examination with good grades.", "o": ["studies", "studied", "would study", "study"], "a": 0, "p": "Klausa utama menggunakan 'will pass' (Tipe 1), sehingga klausa 'if' membutuhkan Simple Present Tense dengan subjek tunggal (studies)."}, {"lv": 2, "q": "If I ... you, I would take that job offer immediately.", "o": ["am", "was", "were", "been"], "a": 2, "p": "Dalam Conditional Type 2, bentuk 'to be' formal yang digunakan untuk semua subjek (termasuk I, he, she, it) adalah 'were'."}, {"lv": 2, "q": "What will happen if we ... the submission deadline?", "o": ["missed", "missing", "would miss", "miss"], "a": 3, "p": "Klausa utama 'What will happen' menunjukkan Tipe 1, sehingga klausa 'if' harus menggunakan Simple Present Tense (miss)."}, {"lv": 2, "q": "Rian would travel around the world if he ... fluent in English.", "o": ["is", "were", "will be", "has been"], "a": 1, "p": "Klausa utama menggunakan 'would travel' (Tipe 2), sehingga klausa 'if' membutuhkan bentuk Simple Past yaitu 'were'."}, {"lv": 3, "q": "Read the sentence: 'If I knew her phone number, I would call her right now.'\nWhat does the sentence actually mean?", "o": ["I know her phone number, so I call her.", "I knew her phone number, so I called her.", "I don't know her phone number, so I don't call her.", "I will know her phone number soon."], "a": 2, "p": "Kalimat Tipe 2 menyatakan pengandaian yang bertentangan dengan fakta masa kini. Faktanya: 'I don't know her phone number, so I don't call her'."}, {"lv": 3, "q": "Fact: 'Tom doesn't have enough time, so he doesn't join the football club.'\nWhich conditional sentence correctly expresses this situation?", "o": ["If Tom has enough time, he will join the football club.", "If Tom had enough time, he would join the football club.", "If Tom had had enough time, he would have joined the football club.", "If Tom doesn't have enough time, he wouldn't join the football club."], "a": 1, "p": "Fakta berbentuk Simple Present negatif. Untuk mengubahnya ke pengandaian Tipe 2 (berlawanan dengan fakta), gunakan Simple Past positif ('had') dan 'would + V1' ('would join')."}, {"lv": 3, "q": "Andi: 'Should I buy this expensive laptop?'\nBagus: 'If I ... you, I ... save my money for college instead.'", "o": ["am / will", "was / will", "had been / would have", "were / would"], "a": 3, "p": "Dialog ini merupakan ungkapan memberi saran (nasihat) menggunakan Tipe 2: 'If I were you, I would...'."}, {"lv": 3, "q": "Read the statement: 'If the weather is good tomorrow, we will go hiking.'\nWhich scenario is consistent with this statement?", "o": ["It rained tomorrow, so they went hiking anyway.", "It is sunny tomorrow, so they go hiking.", "It rains tomorrow, so they decide to stay home.", "They went hiking yesterday because the weather was fine."], "a": 1, "p": "Kalimat Tipe 1 menyatakan aksi yang berpeluang terjadi di masa depan jika syarat terpenuhi. Jika cuaca cerah (sunny/good), mereka akan pergi mendaki (go hiking)."}]}, {"id": "big-k11-1", "name": "Analytical exposition", "desc": "Teks argumentasi", "idx": 1, "soal": [{"lv": 1, "q": "What is the primary social function of an analytical exposition text?", "o": ["To entertain readers with an amusing story", "To persuade readers that a particular topic is important or an issue needs attention", "To explain step-by-step how to make or do something", "To describe a specific person or place in detail"], "a": 1, "p": "Fungsi utama teks analytical exposition adalah meyakinkan pembaca bahwa topik atau isu yang dibahas itu penting untuk diperhatikan."}, {"lv": 1, "q": "Which of the following is the correct generic structure of an analytical exposition text?", "o": ["Thesis - Arguments - Reiteration", "Orientation - Complication - Resolution", "Goal - Materials - Steps", "Identification - Description"], "a": 0, "p": "Struktur generik teks analytical exposition terdiri dari Thesis (pernyataan pendapat), Arguments (alasan/bukti), dan Reiteration (penegasan ulang)."}, {"lv": 1, "q": "Which tense is predominantly used in writing an analytical exposition text?", "o": ["Simple Past Tense", "Future Continuous Tense", "Simple Present Tense", "Past Perfect Tense"], "a": 2, "p": "Analytical exposition sebagian besar menggunakan Simple Present Tense karena menyampaikan fakta, pandangan, dan argumen umum yang berlaku saat ini."}, {"lv": 1, "q": "The final paragraph of an analytical exposition text which restates the writer's point of view is called...", "o": ["Thesis", "Complication", "Recommendation", "Reiteration"], "a": 3, "p": "Reiteration (kesimpulan/penutup) adalah bagian akhir dari analytical exposition yang menegaskan kembali tesis atau pendapat penulis."}, {"lv": 2, "q": "Which of the following transition words is used to introduce an additional argument in an analytical exposition text?", "o": ["However", "Furthermore", "Therefore", "In contrast"], "a": 1, "p": "Kata transisi 'Furthermore' (selain itu/lagipula) digunakan untuk menambahkan argumen pendukung baru."}, {"lv": 2, "q": "Read the excerpt: 'In conclusion, reading daily not only expands our knowledge but also improves our analytical thinking skills. Therefore, making reading a daily habit is essential.' \nWhich structure of an analytical exposition text is represented by this paragraph?", "o": ["Thesis", "Argument", "Reiteration", "Recommendation"], "a": 2, "p": "Paragraf tersebut merupakan Reiteration karena diawali dengan penanda kesimpulan 'In conclusion' dan menegaskan kembali poin utama penulis."}, {"lv": 2, "q": "Which modal auxiliary verb is commonly used in analytical exposition to express strong necessity or recommendation?", "o": ["Should", "Might", "Could", "Would"], "a": 0, "p": "Modal 'Should' (seharusnya/hendaknya) sering digunakan untuk menyatakan saran kuat atau kebutuhan penting terkait isu yang dibahas."}, {"lv": 2, "q": "Read the sentence: 'Using public transport can significantly reduce air pollution in urban areas.' \nWhat is the synonym of the word 'significantly' in this context?", "o": ["Slightly", "Considerably", "Rarely", "Casually"], "a": 1, "p": "Kata 'significantly' berarti secara signifikan atau secara berarti, yang bersinonim dengan 'considerably'."}, {"lv": 3, "q": "Read the short text: \n'Plastic waste is a severe environmental threat. Firstly, plastic takes hundreds of years to decompose, clogging rivers and oceans. Secondly, microplastics are now ingested by marine creatures, eventually entering the human food chain. Thus, we must urgently reduce single-use plastic consumption.' \nWhat is the writer's thesis in the text above?", "o": ["Plastic waste decomposes very quickly in the ocean.", "Marine creatures benefit from microplastics in the water.", "Plastic waste poses a serious threat to the environment.", "People should use more single-use plastic bags."], "a": 2, "p": "Tesis penulis dinyatakan di kalimat awal, yaitu bahwa sampah plastik merupakan ancaman lingkungan yang sangat serius."}, {"lv": 3, "q": "How does an Analytical Exposition differ from a Hortatory Exposition in terms of their concluding section?", "o": ["Analytical Exposition ends with a resolution, while Hortatory ends with an orientation.", "Analytical Exposition ends with a reiteration of the thesis, while Hortatory ends with a recommendation for action.", "Analytical Exposition ends with a step-by-step guide, while Hortatory ends with a story summary.", "There is no difference between the conclusion of both text types."], "a": 1, "p": "Analytical Exposition diakhiri dengan Reiteration (penegasan ulang tesis), sedangkan Hortatory Exposition diakhiri dengan Recommendation (saran/tindakan konkret)."}, {"lv": 3, "q": "Thesis: 'Breakfast is the most important meal of the day.' \nWhich of the following arguments LEAST supports this thesis?", "o": ["Eating breakfast boosts concentration and academic performance in students.", "Breakfast provides essential nutrients to kickstart energy after overnight fasting.", "Regular breakfast consumption lowers the risk of chronic metabolic diseases.", "Skipping breakfast helps people save time in their busy morning routine."], "a": 3, "p": "Pilihan D justru mendukung tindakan melewatkan sarapan (skipping breakfast), sehingga tidak mendukung tesis tentang pentingnya sarapan."}, {"lv": 3, "q": "Read the argument: 'Cyberbullying can lead to severe psychological trauma among teenagers because online harassment occurs 24/7 without a physical safe space.' \nWhat can be inferred from this argument?", "o": ["Teenagers feel safer online than in physical environments.", "Cyberbullying is less harmful than traditional physical bullying.", "Victims of cyberbullying find it hard to escape the harassment even at home.", "Online harassment only happens during school hours."], "a": 2, "p": "Ungkapan 'occurs 24/7 without a physical safe space' menyiratkan bahwa korban cyberbullying sangat sulit terbebas dari perundungan meskipun di rumah."}]}, {"id": "big-k11-2", "name": "Suggestions and offers", "desc": "Memberi saran dan tawaran", "idx": 2, "soal": [{"lv": 1, "q": "Which expression is used to give a suggestion?", "o": ["Can I help you carry those books?", "May I offer you something to drink?", "Why don't we study together for the exam?", "Would you like me to open the window?"], "a": 2, "p": "Ungkapan 'Why don't we...?' digunakan untuk memberikan saran (suggestion), sedangkan pilihan lainnya merupakan ekspresi menawarkan bantuan (offer)."}, {"lv": 1, "q": "Which expression is an offer of help?", "o": ["You should see a doctor soon.", "May I help you with your baggage?", "How about going to the beach this weekend?", "Let's clean the classroom together."], "a": 1, "p": "Ungkapan 'May I help you...?' digunakan secara langsung untuk menawarkan bantuan (offer)."}, {"lv": 1, "q": "A: 'I'm feeling very thirsty.'\nB: '...' (Offering a drink)", "o": ["Why don't you take a rest?", "You ought to drink more water daily.", "Let's go to the pharmacy.", "Would you like a glass of iced tea?"], "a": 3, "p": "Kalimat 'Would you like a glass of iced tea?' merupakan bentuk tawaran (offer) minuman yang tepat."}, {"lv": 1, "q": "What is the appropriate response to ACCEPT a suggestion: 'Why don't we watch a movie tonight?'", "o": ["That sounds like a great idea!", "I'm sorry, I don't need your help.", "No, thanks. I can do it myself.", "I don't think you should do that."], "a": 0, "p": "Kalimat 'That sounds like a great idea!' adalah bentuk penerimaan (accepting) terhadap sebuah saran."}, {"lv": 2, "q": "Maya: 'I have a headache and I can't concentrate on my study.'\nSiti: '...' (Giving a suggestion)", "o": ["Shall I bring you a cup of tea?", "You should take a break and get some rest.", "Would you like me to read the book for you?", "Can I help you finish your homework?"], "a": 1, "p": "Siti memberikan saran kesehatan yang tepat dengan modal 'should' (You should take a break...)."}, {"lv": 2, "q": "John: 'This box is too heavy for me to carry alone.'\nDavid: '...' (Offering help)", "o": ["How about carrying it tomorrow?", "Why don't you leave it here?", "Can I give you a hand with that?", "You had better carry it carefully."], "a": 2, "p": "Ungkapan 'Can I give you a hand...?' merupakan ungkapan idiomatik untuk menawarkan bantuan mengangkat barang."}, {"lv": 2, "q": "Teacher: 'You look confused with the math problem. ...'\nStudent: 'Yes, please. I would really appreciate that, Sir.'", "o": ["Would you like me to explain it to you again?", "Why don't you practice more at home?", "You ought to study harder for the test.", "How about asking your classmates?"], "a": 0, "p": "Respon siswa ('Yes, please. I would really appreciate that') menunjukkan penerimaan atas tawaran bantuan guru ('Would you like me to explain...')."}, {"lv": 2, "q": "Which response POLITELY DECLINES an offer of help?", "o": ["Yes, please. That's very kind of you.", "Sure, I'd love to go with you.", "Why not? Let me help you.", "Thank you, but I can manage it myself."], "a": 3, "p": "Ungkapan 'Thank you, but I can manage it myself' adalah cara menolak tawaran bantuan secara sopan."}, {"lv": 3, "q": "Read the dialogue:\nRani: 'I'm struggling to complete this history essay before the midnight deadline.'\nBudi: 'What if we outline the key points together now, and then I proofread your draft later?'\nWhat can be inferred from Budi's statement?", "o": ["Budi is refusing to assist Rani with her essay.", "Budi is making a combined suggestion and offer of assistance.", "Budi is instructing Rani to finish her work alone.", "Budi is asking Rani to proofread his paper."], "a": 1, "p": "Budi mengombinasikan saran ('What if we outline...') dan tawaran bantuan ('then I proofread your draft later')."}, {"lv": 3, "q": "Read the dialogue:\nCustomer: 'Good afternoon. I'm looking for a jacket, but I can't find my size.'\nShop Assistant: 'May I check our stockroom for your size, Ma'am?'\nCustomer: 'Oh, don't trouble yourself. I'll just check another store.'\nWhat does the customer mean by her response?", "o": ["She accepts the shop assistant's offer eagerly.", "She gives a suggestion to the shop assistant.", "She politely declines the shop assistant's offer.", "She asks the shop assistant to bring a different model."], "a": 2, "p": "Ungkapan 'don't trouble yourself. I'll just check another store' bermakna menolak tawaran bantuan petugas toko secara halus."}, {"lv": 3, "q": "Choose the grammatically correct sentence that offers help using modal auxiliary verbs:", "o": ["How about I will help you with the dishes?", "Why don't I will drive you to the airport?", "Would you mind if I am help you?", "Shall I carry those heavy bags for you?"], "a": 3, "p": "Bentuk 'Shall I + V1...?' ('Shall I carry...') adalah struktur tata bahasa yang tepat dan baku untuk menawarkan bantuan."}, {"lv": 3, "q": "Situation: Your friend failed the driving test because he was extremely nervous. What is the most constructive suggestion to give him?", "o": ["How about taking a mock test with an instructor to build your confidence?", "You should give up driving altogether.", "Would you like me to drive your car every day?", "Why don't you drive without a license next time?"], "a": 0, "p": "Saran konstruktif (membangun) yang paling tepat untuk seseorang yang gugup ujian mengemudi adalah menyuruhnya latihan simulasi (mock test) agar lebih percaya diri."}]}], "12": [{"id": "big-k12-0", "name": "Discussion text", "desc": "Pro dan kontra", "idx": 0, "soal": [{"lv": 1, "q": "A discussion text presents ...", "o": ["only one side of an issue", "two or more points of view about an issue", "steps to make something", "a past experience"], "a": 1, "p": "A discussion text presents arguments for (pros) and against (cons) an issue."}, {"lv": 1, "q": "The generic structure of a discussion text is ...", "o": ["orientation – events – reorientation", "issue – arguments for – arguments against – conclusion/recommendation", "goal – materials – steps", "identification – description"], "a": 1, "p": "Discussion text: issue, supporting arguments, contrasting arguments, then conclusion or recommendation."}, {"lv": 1, "q": "Which title is most suitable for a discussion text?", "o": ["How to Make Fried Rice", "My Holiday in Bali", "Should Students Wear Uniforms?", "The Legend of Lake Toba"], "a": 2, "p": "A discussion text is usually about a debatable issue, often written as a question."}, {"lv": 1, "q": "Conjunctions commonly used to show contrast in a discussion text are ...", "o": ["first, then, finally", "however, on the other hand", "once upon a time", "because of that, so"], "a": 1, "p": "\"However\" and \"on the other hand\" introduce the opposing side."}, {"lv": 2, "q": "\"Some people believe that online learning saves time. ______, others argue that it reduces social interaction.\" The best word to fill the blank is ...", "o": ["Therefore", "Moreover", "On the other hand", "For example"], "a": 2, "p": "The sentence introduces an opposing view, so a contrast connector is needed."}, {"lv": 2, "q": "\"Homework helps students review the lessons at home.\" This sentence is part of the ...", "o": ["issue", "argument for (pro)", "argument against (con)", "orientation"], "a": 1, "p": "It supports the benefit of homework, so it is an argument for."}, {"lv": 2, "q": "The conclusion of a discussion text usually contains ...", "o": ["the writer's recommendation or final opinion after weighing both sides", "a list of materials", "a new character", "the time and place of events"], "a": 0, "p": "The conclusion summarises both sides and gives a recommendation."}, {"lv": 2, "q": "Which sentence states an ISSUE?", "o": ["Smartphones help students find information quickly.", "There has been a debate about whether smartphones should be allowed in classrooms.", "However, smartphones can distract students.", "In conclusion, smartphones should be used wisely."], "a": 1, "p": "The issue introduces the topic being debated."}, {"lv": 3, "q": "Read: \"Nuclear energy produces little carbon emission and generates a large amount of power. However, nuclear waste remains dangerous for thousands of years, and accidents can be catastrophic. Therefore, the government should invest in nuclear energy only with very strict safety regulations.\" The writer's final position is ...", "o": ["completely against nuclear energy", "completely supports nuclear energy without conditions", "supports nuclear energy with strict conditions", "has no opinion"], "a": 2, "p": "The last sentence recommends investment only with strict safety regulations: conditional support."}, {"lv": 3, "q": "Which sentence best serves as an argument AGAINST a four-day school week?", "o": ["Students would have more time to rest.", "Teachers could plan lessons better.", "Longer school days may make students tired and less focused.", "Schools could save on electricity costs."], "a": 2, "p": "Only this sentence points out a disadvantage of the four-day week."}, {"lv": 3, "q": "\"Although social media connects people across the world, it can also spread false information rapidly.\" The function of \"although\" in this sentence is to ...", "o": ["show a result", "show contrast between two ideas", "give an example", "show time order"], "a": 1, "p": "\"Although\" introduces a concession, contrasting a benefit with a drawback."}, {"lv": 3, "q": "What makes a discussion text different from an analytical exposition?", "o": ["A discussion text presents both sides before concluding, while an analytical exposition argues for one side only.", "A discussion text has no conclusion.", "An analytical exposition presents both sides equally.", "They are exactly the same."], "a": 0, "p": "Analytical exposition persuades from one viewpoint; discussion considers pros and cons."}]}, {"id": "big-k12-1", "name": "Gerund and to-infinitive", "desc": "Penggunaan V-ing dan to V1", "idx": 1, "soal": [{"lv": 1, "q": "I enjoy ______ novels in my free time.", "o": ["read", "to read", "reading", "reads"], "a": 2, "p": "\"Enjoy\" is followed by a gerund (verb-ing)."}, {"lv": 1, "q": "She wants ______ a doctor in the future.", "o": ["become", "to become", "becoming", "became"], "a": 1, "p": "\"Want\" is followed by a to-infinitive."}, {"lv": 1, "q": "______ is good for your health.", "o": ["Swim", "Swimming", "Swam", "Swims"], "a": 1, "p": "A gerund can act as the subject of a sentence."}, {"lv": 1, "q": "They decided ______ the meeting until next week.", "o": ["postpone", "postponing", "to postpone", "postponed"], "a": 2, "p": "\"Decide\" is followed by a to-infinitive."}, {"lv": 2, "q": "My father stopped ______ ten years ago because it was bad for his health.", "o": ["to smoke", "smoking", "smoke", "smoked"], "a": 1, "p": "\"Stop + V-ing\" means quitting an activity. \"Stop + to V\" means stopping in order to do something else."}, {"lv": 2, "q": "He is interested in ______ a new language.", "o": ["learn", "to learn", "learning", "learned"], "a": 2, "p": "After a preposition (in), use a gerund."}, {"lv": 2, "q": "Would you mind ______ the window, please?", "o": ["open", "to open", "opening", "opened"], "a": 2, "p": "\"Mind\" is followed by a gerund."}, {"lv": 2, "q": "We hope ______ you again soon.", "o": ["seeing", "to see", "see", "saw"], "a": 1, "p": "\"Hope\" is followed by a to-infinitive."}, {"lv": 3, "q": "\"I remember locking the door.\" This sentence means ...", "o": ["I must lock the door later.", "I locked the door and I have a memory of doing it.", "I forgot to lock the door.", "I never lock the door."], "a": 1, "p": "\"Remember + V-ing\" refers to a memory of a past action. \"Remember + to V\" means not forgetting a future task."}, {"lv": 3, "q": "Choose the correct sentence.", "o": ["She avoided to answer the question.", "She avoided answering the question.", "She avoided answer the question.", "She avoided answered the question."], "a": 1, "p": "\"Avoid\" is always followed by a gerund."}, {"lv": 3, "q": "On the way home, Rina stopped ______ some fruit at the market.", "o": ["buying", "to buy", "buy", "bought"], "a": 1, "p": "She stopped (her walk) in order to buy fruit, so \"stop + to-infinitive\" expresses purpose."}, {"lv": 3, "q": "Which sentence uses a gerund as the object of a preposition?", "o": ["Reading is my hobby.", "I want to read more.", "She is good at drawing portraits.", "They agreed to come."], "a": 2, "p": "\"Drawing\" follows the preposition \"at\", so it is the object of a preposition."}]}, {"id": "big-k12-2", "name": "Caption and news item", "desc": "Teks berita dan keterangan gambar", "idx": 2, "soal": [{"lv": 1, "q": "A caption is ...", "o": ["a long story about an event", "a short text that explains a picture or photo", "a letter to a friend", "a recipe"], "a": 1, "p": "A caption is a short description that accompanies an image."}, {"lv": 1, "q": "The purpose of a news item text is to ...", "o": ["entertain readers with a fairy tale", "inform readers about newsworthy events of the day", "persuade readers to buy a product", "describe a person"], "a": 1, "p": "A news item reports important or interesting recent events."}, {"lv": 1, "q": "The generic structure of a news item is ...", "o": ["newsworthy event – background events – sources", "orientation – complication – resolution", "goal – steps", "thesis – arguments – reiteration"], "a": 0, "p": "News item: main event, background (details), and sources (comments from witnesses or officials)."}, {"lv": 1, "q": "Captions are usually written in the ______ tense to make them feel current.", "o": ["simple present", "past perfect", "future continuous", "past continuous"], "a": 0, "p": "Captions often use the simple present, e.g., \"Students plant trees in the school garden.\""}, {"lv": 2, "q": "\"Jakarta – Heavy rain flooded several areas of the capital on Monday morning, forcing hundreds of residents to evacuate.\" This sentence is the ...", "o": ["source", "newsworthy event", "background event", "caption"], "a": 1, "p": "The opening sentence summarises the main event: the newsworthy event."}, {"lv": 2, "q": "\"'We have opened three shelters for the victims,' said the head of the local disaster agency.\" This part of a news item is called ...", "o": ["newsworthy event", "background event", "sources", "orientation"], "a": 2, "p": "Comments from officials or witnesses are the sources."}, {"lv": 2, "q": "Which is the best caption for a photo of students cleaning a beach?", "o": ["Students Clean Up Kuta Beach to Celebrate Environment Day", "Once upon a time there was a beach", "How to clean a beach in five steps", "I think beaches are beautiful"], "a": 0, "p": "A good caption briefly states who, what, and why in the present tense."}, {"lv": 2, "q": "News items often use passive voice, for example ...", "o": ["The thief was arrested by the police yesterday.", "Arrest the thief now!", "I am arresting the thief.", "Do you arrest the thief?"], "a": 0, "p": "Passive voice focuses on the event or victim rather than the doer."}, {"lv": 3, "q": "Read: \"A 6.2-magnitude earthquake struck West Sulawesi early Friday. The quake, centred 6 km northeast of Majene, damaged hundreds of houses. The meteorology agency said there was no tsunami threat.\" The background event is ...", "o": ["A 6.2-magnitude earthquake struck West Sulawesi early Friday.", "The quake, centred 6 km northeast of Majene, damaged hundreds of houses.", "The meteorology agency said there was no tsunami threat.", "There is no background event."], "a": 1, "p": "Sentence 2 gives details about the event: the background. Sentence 1 is the newsworthy event and sentence 3 is the source."}, {"lv": 3, "q": "Why do news items rarely contain the writer's personal opinion?", "o": ["Because news should be factual and objective.", "Because writers are not allowed to write.", "Because opinions are always wrong.", "Because news is fiction."], "a": 0, "p": "News items aim to inform objectively; opinions belong in editorials."}, {"lv": 3, "q": "Which headline is written in correct news style?", "o": ["Government Raised Fuel Price Yesterday", "Government Raises Fuel Prices", "The Government Will Have Been Raising The Fuel", "Fuel Price, Government, Raise"], "a": 1, "p": "Headlines use the simple present and are short, even for past events."}, {"lv": 3, "q": "The main difference between a caption and a news item is that a caption ...", "o": ["is longer than a news item", "is a brief explanation tied to an image, while a news item is a full report of an event", "always contains sources", "must use the future tense"], "a": 1, "p": "A caption is short and supports a picture; a news item reports the event with background and sources."}]}], "2": [{"id": "big-k2-0", "name": "Family members", "desc": "Anggota keluarga", "idx": 0, "soal": [{"lv": 1, "q": "What is the English word for 'Ayah'?", "o": ["Father", "Mother", "Brother", "Sister"], "a": 0, "p": "Ayah dalam Bahasa Inggris disebut 'Father'."}, {"lv": 1, "q": "What is the English word for 'Ibu'?", "o": ["Sister", "Brother", "Mother", "Father"], "a": 2, "p": "Ibu dalam Bahasa Inggris disebut 'Mother'."}, {"lv": 1, "q": "A male sibling (saudara laki-laki) is called a...", "o": ["Sister", "Brother", "Uncle", "Aunt"], "a": 1, "p": "Saudara laki-laki dalam Bahasa Inggris disebut 'Brother'."}, {"lv": 1, "q": "A female sibling (saudara perempuan) is called a...", "o": ["Brother", "Father", "Grandpa", "Sister"], "a": 3, "p": "Saudara perempuan dalam Bahasa Inggris disebut 'Sister'."}, {"lv": 2, "q": "My father and mother are my...", "o": ["Friends", "Parents", "Children", "Teachers"], "a": 1, "p": "Ayah dan ibu adalah orang tua kita, dalam Bahasa Inggris disebut 'Parents'."}, {"lv": 2, "q": "My mother has a daughter. She is my...", "o": ["Sister", "Brother", "Father", "Mother"], "a": 0, "p": "Anak perempuan dari ibu kita adalah saudara perempuan kita atau 'Sister'."}, {"lv": 2, "q": "He is my mother's father. He is my...", "o": ["Uncle", "Brother", "Grandfather", "Father"], "a": 2, "p": "Ayah dari ibu kita adalah kakek, dalam Bahasa Inggris disebut 'Grandfather'."}, {"lv": 2, "q": "She is my father's mother. She is my...", "o": ["Grandmother", "Grandfather", "Sister", "Aunt"], "a": 0, "p": "Ibu dari ayah kita adalah nenek, dalam Bahasa Inggris disebut 'Grandmother'."}, {"lv": 3, "q": "My father's sister is my...", "o": ["Uncle", "Aunt", "Cousin", "Grandmother"], "a": 1, "p": "Saudara perempuan dari ayah kita adalah bibi atau 'Aunt'."}, {"lv": 3, "q": "My mother's brother is my...", "o": ["Uncle", "Father", "Grandfather", "Cousin"], "a": 0, "p": "Saudara laki-laki dari ibu kita adalah paman atau 'Uncle'."}, {"lv": 3, "q": "The child of my uncle is my...", "o": ["Brother", "Sister", "Cousin", "Parent"], "a": 2, "p": "Anak dari paman atau bibi disebut sepupu, dalam Bahasa Inggris adalah 'Cousin'."}, {"lv": 3, "q": "My father has a son. He is my...", "o": ["Sister", "Aunt", "Mother", "Brother"], "a": 3, "p": "Anak laki-laki dari ayah kita adalah saudara laki-laki kita atau 'Brother'."}]}, {"id": "big-k2-1", "name": "Parts of the body", "desc": "Bagian tubuh", "idx": 1, "soal": [{"lv": 1, "q": "What is the Indonesian meaning of 'eyes'?", "o": ["Telinga", "Mata", "Hidung", "Mulut"], "a": 1, "p": "'Eyes' artinya mata. Telinga adalah ear, hidung adalah nose, dan mulut adalah mouth."}, {"lv": 1, "q": "We use our ... to smell a flower.", "o": ["hand", "mouth", "nose", "eye"], "a": 2, "p": "Kita menggunakan hidung (nose) untuk mencium bau bunga."}, {"lv": 1, "q": "Which part of the body is used to walk?", "o": ["Foot", "Hand", "Head", "Arm"], "a": 0, "p": "Kaki (foot) digunakan untuk berjalan."}, {"lv": 1, "q": "What is Bahasa Indonesia of 'head'?", "o": ["Kepala", "Rambut", "Leher", "Pundak"], "a": 0, "p": "'Head' artinya kepala."}, {"lv": 2, "q": "I have two ... to listen to music.", "o": ["eyes", "ears", "hands", "legs"], "a": 1, "p": "Kita mendengarkan musik menggunakan telinga (ears). Jumlah telinga ada dua."}, {"lv": 2, "q": "Budi wants to write a letter. He uses his ...", "o": ["foot", "nose", "hand", "ear"], "a": 2, "p": "Untuk menulis surat, Budi menggunakan tangan (hand)."}, {"lv": 2, "q": "Look in the mirror! You have hair on your ...", "o": ["head", "knee", "toe", "foot"], "a": 0, "p": "Rambut tumbuh di atas kepala (head)."}, {"lv": 2, "q": "Which of these body parts are on your face?", "o": ["Knees and toes", "Hands and arms", "Eyes and nose", "Legs and feet"], "a": 2, "p": "Mata (eyes) dan hidung (nose) adalah bagian tubuh yang terletak di wajah (face)."}, {"lv": 3, "q": "Siti is eating an apple. She uses her ... to chew the food.", "o": ["teeth", "eyes", "ears", "nose"], "a": 0, "p": "Untuk mengunyah (chew) makanan seperti apel, Siti menggunakan gigi (teeth)."}, {"lv": 3, "q": "Ani is playing football with her friends. She kicks the ball using her ...", "o": ["hands", "foot", "head", "ears"], "a": 1, "p": "Saat bermain sepak bola, kita menendang bola menggunakan kaki (foot)."}, {"lv": 3, "q": "Before eating, Roni washes his ... with soap because he touched dirty things.", "o": ["eyes", "hair", "hands", "knees"], "a": 2, "p": "Kita mencuci tangan (hands) dengan sabun sebelum makan karena tangan sering menyentuh benda kotor."}, {"lv": 3, "q": "The teacher asks Beni to point to the body part between his head and his shoulders. It is the ...", "o": ["neck", "knee", "toe", "finger"], "a": 0, "p": "Bagian tubuh yang berada di antara kepala (head) dan pundak (shoulders) adalah leher (neck)."}]}, {"id": "big-k2-2", "name": "Things in the classroom", "desc": "Benda di kelas", "idx": 2, "soal": [{"lv": 1, "q": "What is the Indonesian meaning of 'book'?", "o": ["Buku", "Pensil", "Penggaris", "Penghapus"], "a": 0, "p": "'Book' artinya buku. Pensil adalah pencil, penggaris adalah ruler, dan penghapus adalah eraser."}, {"lv": 1, "q": "We use a ... to write on a paper.", "o": ["book", "pencil", "bag", "chair"], "a": 1, "p": "Kita menggunakan pensil (pencil) untuk menulis di atas kertas."}, {"lv": 1, "q": "What is Bahasa Indonesia of 'table'?", "o": ["Kursi", "Papan tulis", "Meja", "Pintu"], "a": 2, "p": "'Table' artinya meja."}, {"lv": 1, "q": "Which object in the classroom do we sit on?", "o": ["Window", "Chair", "Door", "Clock"], "a": 1, "p": "Kursi (chair) adalah benda di kelas yang kita gunakan untuk duduk."}, {"lv": 2, "q": "Siti wants to clean her writing on the book. She uses an ...", "o": ["eraser", "ruler", "pen", "pencil"], "a": 0, "p": "Untuk menghapus tulisan di buku, Siti menggunakan penghapus (eraser)."}, {"lv": 2, "q": "To draw a straight line, Budi needs a ...", "o": ["book", "bag", "ruler", "chair"], "a": 2, "p": "Untuk menggambar garis lurus, Budi membutuhkan penggaris (ruler)."}, {"lv": 2, "q": "The teacher writes the lesson on the ... using a marker.", "o": ["table", "whiteboard", "door", "window"], "a": 1, "p": "Guru menulis pelajaran di papan tulis putih (whiteboard) menggunakan spidol."}, {"lv": 2, "q": "Ani puts her books, pencils, and lunch box inside her ...", "o": ["bag", "chair", "clock", "ruler"], "a": 0, "p": "Ani memasukkan buku, pensil, dan kotak bekalnya ke dalam tas (bag)."}, {"lv": 3, "q": "Before the class begins, the students look at the ... on the wall to check what time it is.", "o": ["door", "clock", "window", "floor"], "a": 1, "p": "Untuk melihat jam berapa sekarang, siswa melihat jam dinding (clock) yang ada di dinding."}, {"lv": 3, "q": "Roni's pencil tip is broken. He needs to sharpen it, so he asks to borrow a ... from his friend.", "o": ["eraser", "ruler", "sharpener", "book"], "a": 2, "p": "Ketika ujung pensil patah dan perlu ditajamkan, Roni membutuhkan rautan (sharpener)."}, {"lv": 3, "q": "The classroom is a bit hot. The teacher opens the ... to let the fresh air come in.", "o": ["window", "book", "bag", "whiteboard"], "a": 0, "p": "Agar udara segar masuk saat kelas terasa panas, guru membuka jendela (window)."}, {"lv": 3, "q": "When the bell rings indicating school is over, the students pack their things and walk through the ... to exit the room.", "o": ["whiteboard", "door", "clock", "window"], "a": 1, "p": "Saat jam sekolah usai, siswa berjalan keluar ruangan melalui pintu (door)."}]}], "3": [{"id": "big-k3-0", "name": "Days and months", "desc": "Nama hari dan bulan", "idx": 0, "soal": [{"lv": 1, "q": "What is the Indonesian meaning of 'Sunday'?", "o": ["Senin", "Selasa", "Minggu", "Sabtu"], "a": 2, "p": "'Sunday' artinya hari Minggu. Senin adalah Monday, Selasa adalah Tuesday, dan Sabtu adalah Saturday."}, {"lv": 1, "q": "Which month comes after January?", "o": ["February", "March", "December", "April"], "a": 0, "p": "Bulan yang datang setelah Januari adalah Februari (February)."}, {"lv": 1, "q": "What is the first day of the school week in Indonesia?", "o": ["Monday", "Saturday", "Sunday", "Friday"], "a": 0, "p": "Hari pertama dalam minggu sekolah di Indonesia adalah hari Senin (Monday)."}, {"lv": 1, "q": "How many months are there in a year?", "o": ["Ten", "Twelve", "Seven", "Thirty"], "a": 1, "p": "Ada 12 bulan (twelve months) dalam satu tahun."}, {"lv": 2, "q": "Today is Wednesday. What day was yesterday?", "o": ["Thursday", "Tuesday", "Monday", "Friday"], "a": 1, "p": "Jika hari ini Rabu (Wednesday), maka kemarin adalah Selasa (Tuesday)."}, {"lv": 2, "q": "Independence Day of Indonesia is celebrated in the month of ...", "o": ["January", "August", "May", "December"], "a": 1, "p": "Hari Kemerdekaan Indonesia dirayakan pada bulan Agustus (August, tanggal 17 Agustus)."}, {"lv": 2, "q": "If today is Friday, what day will tomorrow be?", "o": ["Thursday", "Saturday", "Sunday", "Wednesday"], "a": 1, "p": "Jika hari ini Jumat (Friday), maka besok adalah Sabtu (Saturday)."}, {"lv": 2, "q": "Which month is the last month of the year?", "o": ["November", "January", "December", "October"], "a": 2, "p": "Bulan terakhir dalam satu tahun adalah Desember (December)."}, {"lv": 3, "q": "Siti has a piano lesson every two days after Monday. Her lesson is on ...", "o": ["Wednesday", "Thursday", "Tuesday", "Friday"], "a": 0, "p": "Dua hari setelah hari Senin (Monday) adalah Rabu (Wednesday)."}, {"lv": 3, "q": "Budi's birthday is in the month before April. His birthday is in ...", "o": ["May", "March", "February", "June"], "a": 1, "p": "Bulan yang berada sebelum bulan April adalah Maret (March)."}, {"lv": 3, "q": "The school holiday starts in June and ends in July. How many months is the school holiday?", "o": ["One month", "Two months", "Three months", "Four months"], "a": 1, "p": "Libur sekolah dimulai pada bulan Juni dan berakhir di bulan Juli, yang berarti berlangsung selama dua bulan (two months)."}, {"lv": 3, "q": "Ani goes to her grandmother's house on the weekend. Which days does she visit her grandmother?", "o": ["Monday and Tuesday", "Wednesday and Thursday", "Saturday and Sunday", "Friday and Saturday"], "a": 2, "p": "Akhir pekan (weekend) terdiri dari hari Sabtu (Saturday) dan Minggu (Sunday)."}]}, {"id": "big-k3-1", "name": "Fruits and food", "desc": "Buah dan makanan", "idx": 1, "soal": [{"lv": 1, "q": "What is the Indonesian meaning of 'apple'?", "o": ["Pisang", "Apel", "Jeruk", "Mangga"], "a": 1, "p": "'Apple' artinya buah apel. Pisang adalah banana, jeruk adalah orange, dan mangga adalah mango."}, {"lv": 1, "q": "Which fruit is typically yellow and curved?", "o": ["Banana", "Watermelon", "Grape", "Strawberry"], "a": 0, "p": "Pisang (banana) adalah buah yang berwarna kuning dan bentuknya melengkung."}, {"lv": 1, "q": "What is Bahasa Indonesia of 'rice'?", "o": ["Roti", "Mie", "Nasi", "Bubur"], "a": 2, "p": "'Rice' artinya nasi. Roti adalah bread, mie adalah noodle, dan bubur adalah porridge."}, {"lv": 1, "q": "We drink ... when we are thirsty.", "o": ["bread", "water", "rice", "fish"], "a": 1, "p": "Kita minum air (water) saat merasa haus."}, {"lv": 2, "q": "Siti likes eating sweet food made from flour, sugar, and butter that we usually have on birthdays. It is a ...", "o": ["cake", "soup", "fish", "rice"], "a": 0, "p": "Makanan manis yang terbuat dari tepung, gula, dan mentega yang biasa ada saat ulang tahun adalah kue (cake)."}, {"lv": 2, "q": "Budi wants to eat breakfast. He spreads butter and strawberry jam on a slice of ...", "o": ["chicken", "egg", "bread", "soup"], "a": 2, "p": "Kita mengoleskan mentega dan selai pada sepotong roti (bread) untuk sarapan."}, {"lv": 2, "q": "Which of these fruits is small, round, and usually comes in bunches of purple or green?", "o": ["Watermelon", "Papaya", "Grapes", "Pineapple"], "a": 2, "p": "Buah yang kecil, bulat, dan tumbuh bergerombol dengan warna ungu atau hijau adalah anggur (grapes)."}, {"lv": 2, "q": "Ani is peeling a hairy brown fruit with sweet white flesh inside. It is a ...", "o": ["rambutan", "orange", "banana", "apple"], "a": 0, "p": "Buah yang kulitnya berambut cokelat dan daging buahnya berwarna putih manis adalah rambutan."}, {"lv": 3, "q": "Roni is having a fever and sore throat. His mother makes a warm liquid food containing chicken broth, vegetables, and shredded chicken. It is ...", "o": ["fried rice", "chicken soup", "french fries", "burger"], "a": 1, "p": "Makanan berkuah hangat yang berisi kaldu ayam dan sayuran saat sakit adalah sup ayam (chicken soup)."}, {"lv": 3, "q": "Mother goes to the traditional market to buy ingredients for lunch. She buys a large green fruit with a thick rind and sweet red flesh full of black seeds. It is ...", "o": ["melon", "avocado", "watermelon", "jackfruit"], "a": 2, "p": "Buah besar berkulit hijau dengan daging merah manis dan banyak biji hitam adalah semangka (watermelon)."}, {"lv": 3, "q": "Dina wants to make a glass of fresh orange juice. Which fruit does she need to squeeze?", "o": ["Oranges", "Apples", "Bananas", "Mangoes"], "a": 0, "p": "Untuk membuat jus jeruk, Dina perlu memeras buah jeruk (oranges)."}, {"lv": 3, "q": "Before cooking eggs, mother cracks the hard outer shell. What is the English word for 'cangkang telur'?", "o": ["Egg white", "Egg yolk", "Eggshell", "Fried egg"], "a": 2, "p": "Cangkang atau kulit keras pelindung telur dalam bahasa Inggris disebut eggshell."}]}, {"id": "big-k3-2", "name": "To be: am, is, are", "desc": "Kalimat sederhana dengan to be", "idx": 2, "soal": [{"lv": 1, "q": "Complete the sentence: I ... a student.", "o": ["is", "are", "am", "be"], "a": 2, "p": "Subjek 'I' selalu berpasangan dengan to be 'am'."}, {"lv": 1, "q": "Complete the sentence: She ... a smart girl.", "o": ["is", "am", "are", "be"], "a": 0, "p": "Subjek tunggal orang ketiga seperti 'she' menggunakan to be 'is'."}, {"lv": 1, "q": "Complete the sentence: They ... playing football in the yard.", "o": ["am", "is", "are", "be"], "a": 2, "p": "Subjek jamak seperti 'they' menggunakan to be 'are'."}, {"lv": 1, "q": "Complete the sentence: He ... my best friend.", "o": ["are", "am", "be", "is"], "a": 3, "p": "Subjek 'he' merupakan subjek tunggal orang ketiga yang menggunakan to be 'is'."}, {"lv": 2, "q": "Budi and Andi ... in the classroom now.", "o": ["are", "is", "am", "be"], "a": 0, "p": "Subjek 'Budi and Andi' berjumlah lebih dari satu (jamak), sehingga menggunakan to be 'are'."}, {"lv": 2, "q": "My cat ... sleeping on the sofa.", "o": ["are", "is", "am", "be"], "a": 1, "p": "Kata 'My cat' merujuk pada satu hewan (tunggal), sehingga menggunakan to be 'is'."}, {"lv": 2, "q": "You ... a very kind person, Lina.", "o": ["is", "am", "are", "be"], "a": 2, "p": "Subjek 'You' selalu berpasangan dengan to be 'are'."}, {"lv": 2, "q": "The apples on the table ... sweet and red.", "o": ["is", "am", "are", "be"], "a": 2, "p": "Subjek 'The apples' berbentuk jamak (ditandai dengan huruf -s), sehingga menggunakan to be 'are'."}, {"lv": 3, "q": "Siti and I ... studying English together in the library.", "o": ["am", "is", "are", "be"], "a": 2, "p": "Subjek 'Siti and I' setara dengan 'we' (kami/kita), yang merupakan bentuk jamak dan menggunakan to be 'are'."}, {"lv": 3, "q": "My mother and father ... cooking delicious food in the kitchen.", "o": ["is", "am", "are", "be"], "a": 2, "p": "Subjek 'My mother and father' berjumlah dua orang (jamak), sehingga menggunakan to be 'are'."}, {"lv": 3, "q": "The new book that I bought yesterday ... very interesting.", "o": ["are", "am", "is", "be"], "a": 2, "p": "Inti subjek kalimat ini adalah 'The new book' yang berjumlah satu (tunggal), sehingga menggunakan to be 'is'."}, {"lv": 3, "q": "Look at those birds! They ... flying high in the sky.", "o": ["is", "am", "are", "be"], "a": 2, "p": "Subjek pada kalimat kedua adalah 'They' (merujuk pada 'those birds' yang jamak), sehingga menggunakan to be 'are'."}]}], "4": [{"id": "big-k4-0", "name": "Telling time", "desc": "Menyebutkan jam", "idx": 0, "soal": [{"lv": 1, "q": "What is the English expression for 'jam tujuh tepat'?", "o": ["It is seven past seven", "It is seven o'clock", "It is half past seven", "It is a quarter to seven"], "a": 1, "p": "'Jam tujuh tepat' dalam bahasa Inggris dikatakan sebagai 'It is seven o'clock'."}, {"lv": 1, "q": "In English, 'quarter past' means ... minutes past the hour.", "o": ["15", "30", "45", "60"], "a": 0, "p": "'Quarter past' berarti seperempat jam atau 15 menit lewat dari jam tersebut."}, {"lv": 1, "q": "How do you say 'jam setengah sepuluh' in English?", "o": ["It is ten past ten", "It is ten o'clock", "It is half past nine", "It is a quarter to ten"], "a": 2, "p": "'Jam setengah sepuluh' (pukul 09.30) dalam bahasa Inggris adalah 'It is half past nine'."}, {"lv": 1, "q": "What does 'o'clock' mean when telling time?", "o": ["Tepat (jam pas tanpa lebih/kurang menit)", "Lebih 15 menit", "Kurang 15 menit", "Lebih 30 menit"], "a": 0, "p": "Istilah 'o'clock' digunakan untuk menunjukkan waktu tepat pada jam bulat (00 menit)."}, {"lv": 2, "q": "It is fifteen minutes past four. Another way to say this is ...", "o": ["It is half past four", "It is a quarter past four", "It is a quarter to four", "It is four o'clock"], "a": 1, "p": "15 menit lewat dalam bahasa Inggris disebut 'a quarter past'. Jadi, 15 menit lewat pukul 4 adalah 'It is a quarter past four'."}, {"lv": 2, "q": "Budi wakes up at 05.15 every morning. How do we read 05.15 in English?", "o": ["It is five past five", "It is a quarter past five", "It is half past five", "It is a quarter to five"], "a": 1, "p": "Pukul 05.15 dibaca 'a quarter past five' (lewat 15 menit dari pukul 5)."}, {"lv": 2, "q": "Ani has lunch at 12.30. In English, 12.30 is read as ...", "o": ["It is half past twelve", "It is twelve past twelve", "It is a quarter past twelve", "It is twelve o'clock"], "a": 0, "p": "Pukul 12.30 dibaca 'half past twelve' (30 menit atau setengah jam lewat dari pukul 12)."}, {"lv": 2, "q": "What is the English for 'pukul sepuluh kurang seperempat' (09.45)?", "o": ["It is a quarter past nine", "It is half past nine", "It is a quarter to ten", "It is ten past nine"], "a": 2, "p": "'Kurang 15 menit' menuju jam berikutnya disebut 'a quarter to'. Jadi, 09.45 adalah 'It is a quarter to ten'."}, {"lv": 3, "q": "Siti arrives at school at twenty minutes past seven (07.20). How do we express this time?", "o": ["It is twenty past seven", "It is twenty to seven", "It is seven past twenty", "It is half past seven"], "a": 0, "p": "Untuk waktu menit lewat 1 hingga 30 menggunakan pola '[menit] past [jam]'. Jadi 07.20 adalah 'It is twenty past seven'."}, {"lv": 3, "q": "Roni goes to bed at ten minutes to nine (08.50). How is this time written in English words?", "o": ["It is ten past eight", "It is ten to nine", "It is nine past ten", "It is ten to eight"], "a": 1, "p": "Untuk waktu menit ke-31 hingga 59 menggunakan pola '[menit menuju] to [jam berikutnya]'. Pukul 08.50 (10 menit menuju pukul 9) adalah 'It is ten to nine'."}, {"lv": 3, "q": "The math test starts at 08.00 and finishes at 09.30. How long is the math test?", "o": ["One hour", "One hour and a half", "Two hours", "Half an hour"], "a": 1, "p": "Dari pukul 08.00 ke 09.30 adalah selang waktu 1 jam 30 menit, yang dalam bahasa Inggris disebut 'one hour and a half'."}, {"lv": 3, "q": "Mother started baking cookies at 02.10 and finished at 02.50. How many minutes did it take?", "o": ["Ten minutes", "Thirty minutes", "Forty minutes", "Fifty minutes"], "a": 2, "p": "Selisih waktu dari 02.10 hingga 02.50 adalah 50 menit dikurangi 10 menit, yaitu 40 menit (forty minutes)."}]}, {"id": "big-k4-1", "name": "Hobbies", "desc": "Hobi dan kegiatan", "idx": 1, "soal": [{"lv": 1, "q": "What is the Indonesian meaning of the hobby 'reading'?", "o": ["Menulis", "Membaca", "Menggambar", "Menyanyi"], "a": 1, "p": "'Reading' artinya membaca. Menulis adalah writing, menggambar adalah drawing, dan menyanyi adalah singing."}, {"lv": 1, "q": "Which hobby involves moving your body to music?", "o": ["Swimming", "Cycling", "Dancing", "Fishing"], "a": 2, "p": "Menari (dancing) adalah hobi yang melibatkan gerakan tubuh mengikuti alunan musik."}, {"lv": 1, "q": "What is Bahasa Indonesia of 'swimming'?", "o": ["Bersepeda", "Memancing", "Berenang", "Berlari"], "a": 2, "p": "'Swimming' artinya berenang."}, {"lv": 1, "q": "We use a pencil and paper when our hobby is ...", "o": ["drawing", "cooking", "gardening", "swimming"], "a": 0, "p": "Kita menggunakan pensil dan kertas ketika hobi kita adalah menggambar (drawing)."}, {"lv": 2, "q": "Siti likes planting flowers and watering plants in the yard every afternoon. Her hobby is ...", "o": ["cooking", "gardening", "fishing", "reading"], "a": 1, "p": "Menanam bunga dan menyiram tanaman di pekarangan adalah hobi berkebun (gardening)."}, {"lv": 2, "q": "Budi wears a helmet and rides his bicycle around the neighborhood park. His hobby is ...", "o": ["running", "swimming", "cycling", "reading"], "a": 2, "p": "Mengendarai sepeda keliling taman menggunakan helm adalah hobi bersepeda (cycling)."}, {"lv": 2, "q": "Ani has a nice voice and loves performing songs on stage. Her hobby is ...", "o": ["singing", "painting", "dancing", "cooking"], "a": 0, "p": "Memiliki suara bagus dan suka membawakan lagu adalah hobi menyanyi (singing)."}, {"lv": 2, "q": "Roni goes to the river or lake with a rod and bait to catch fish. His hobby is ...", "o": ["camping", "fishing", "hiking", "running"], "a": 1, "p": "Pergi ke sungai atau danau menggunakan joran dan umpan untuk menangkap ikan adalah hobi memancing (fishing)."}, {"lv": 3, "q": "Every Sunday morning, Lina wears her sports shoes and runs around the stadium to stay healthy. Her hobby is ...", "o": ["swimming", "jogging", "reading", "cooking"], "a": 1, "p": "Berlari santai di sekitar stadion untuk menjaga kesehatan setiap Minggu pagi adalah hobi lari santai (jogging)."}, {"lv": 3, "q": "Dina likes making delicious fried rice and cakes in the kitchen for her family. What is her hobby?", "o": ["Cooking", "Reading", "Gardening", "Drawing"], "a": 0, "p": "Membuat makanan dan kue yang lezat di dapur adalah hobi memasak (cooking)."}, {"lv": 3, "q": "Ahmad collects many interesting stories and adventure books in his cupboard because he loves ...", "o": ["painting", "cycling", "reading", "fishing"], "a": 2, "p": "Mengoleksi banyak buku cerita dan petualangan di lemari menunjukkan bahwa hobinya adalah membaca (reading)."}, {"lv": 3, "q": "Sinta uses colorful paints, a brush, and a canvas to create beautiful scenery pictures. Her hobby is ...", "o": ["singing", "swimming", "painting", "cooking"], "a": 2, "p": "Menggunakan cat warna-warni, kuas, dan kanvas untuk membuat gambar pemandangan adalah hobi melukis (painting)."}]}, {"id": "big-k4-2", "name": "Prepositions of place", "desc": "In, on, under, next to", "idx": 2, "soal": [{"lv": 1, "q": "What is the Indonesian meaning of the preposition 'in'?", "o": ["Di atas", "Di dalam", "Di bawah", "Di sebelah"], "a": 1, "p": "'In' artinya di dalam. Di atas adalah on, di bawah adalah under, dan di sebelah adalah next to."}, {"lv": 1, "q": "Complete the sentence: The pencil is ... the pencil case.", "o": ["on", "under", "in", "next to"], "a": 2, "p": "Pensil berada di dalam kotak pensil, sehingga preposisi yang tepat adalah 'in'."}, {"lv": 1, "q": "What is Bahasa Indonesia of 'under'?", "o": ["Di bawah", "Di atas", "Di dalam", "Di depan"], "a": 0, "p": "'Under' memiliki arti di bawah."}, {"lv": 1, "q": "Complete the sentence: The book is ... the table.", "o": ["in", "under", "next to", "on"], "a": 3, "p": "Buku yang diletakkan di atas meja menggunakan preposisi 'on'."}, {"lv": 2, "q": "Budi hides his toy car ... the bed so nobody can step on it.", "o": ["under", "on", "in", "next to"], "a": 0, "p": "Mainan yang disembunyikan di kolong tempat tidur berada di bawah (under) kasur."}, {"lv": 2, "q": "Siti puts her cup of tea ... the wooden table while eating breakfast.", "o": ["in", "on", "under", "next to"], "a": 1, "p": "Cangkir teh diletakkan di atas meja kayu, menggunakan preposisi 'on'."}, {"lv": 2, "q": "The cat is sleeping peacefully ... the warm blanket on the sofa.", "o": ["under", "next to", "in", "on"], "a": 0, "p": "Kucing yang tidur tertutup selimut berada di bawah (under) selimut tersebut."}, {"lv": 2, "q": "Ani's chair is placed right ... her desk so she can study comfortably.", "o": ["in", "on", "next to", "under"], "a": 2, "p": "Kursi belajar diletakkan tepat di sebelah meja menggunakan preposisi 'next to'."}, {"lv": 3, "q": "Roni cannot find his eraser. After checking his room, he finds it rolling down and resting ... the heavy wardrobe.", "o": ["under", "in", "on", "next to"], "a": 0, "p": "Penghapus yang menggelinding dan berada di kolong lemari besar menggunakan preposisi 'under'."}, {"lv": 3, "q": "Mother puts fresh apples and bananas ... the refrigerator to keep them cool and fresh.", "o": ["on", "in", "under", "next to"], "a": 1, "p": "Buah-buahan yang disimpan di dalam kulkas menggunakan preposisi 'in'."}, {"lv": 3, "q": "The whiteboard in the classroom is attached to the wall, and the teacher's desk is standing right ... it.", "o": ["in", "under", "next to", "on"], "a": 2, "p": "Meja guru yang berdiri di samping papan tulis menggunakan preposisi 'next to'."}, {"lv": 3, "q": "Dina keeps her precious diary book locked safely ... the drawer of her study desk.", "o": ["on", "under", "next to", "in"], "a": 3, "p": "Buku harian yang disimpan di dalam laci meja menggunakan preposisi 'in'."}]}], "5": [{"id": "big-k5-0", "name": "Simple present tense", "desc": "Kebiasaan sehari-hari", "idx": 0, "soal": [{"lv": 1, "q": "Complete the sentence: I ... to school every morning.", "o": ["goes", "going", "go", "went"], "a": 2, "p": "Dalam Simple Present Tense, subjek 'I' menggunakan verb 1 bentuk dasar, yaitu 'go'."}, {"lv": 1, "q": "Complete the sentence: She ... English on Mondays.", "o": ["study", "studies", "studying", "studied"], "a": 1, "p": "Subjek tunggal orang ketiga ('She') dalam kalimat positif Simple Present Tense menggunakan verb+s/es, yaitu 'studies'."}, {"lv": 1, "q": "Complete the sentence: They ... football in the afternoon.", "o": ["plays", "playing", "play", "played"], "a": 2, "p": "Subjek jamak 'They' menggunakan verb 1 bentuk dasar tanpa penambahan -s/es, yaitu 'play'."}, {"lv": 1, "q": "Which sentence is correct in Simple Present Tense?", "o": ["He likes apples.", "He like apples.", "He liking apples.", "He is like apples."], "a": 0, "p": "Untuk subjek 'He', kata kerja 'like' harus ditambah -s menjadi 'likes'."}, {"lv": 2, "q": "Budi ... breakfast with his family at six o'clock every day.", "o": ["have", "has", "having", "had"], "a": 1, "p": "Subjek tunggal 'Budi' menggunakan kata kerja 'has' untuk bentuk Simple Present Tense."}, {"lv": 2, "q": "Complete the negative sentence: Siti ... not like eating spicy food.", "o": ["do", "does", "is", "are"], "a": 1, "p": "Untuk subjek tunggal 'Siti', bentuk negatif dalam Simple Present Tense menggunakan 'does not' (doesn't)."}, {"lv": 2, "q": "Complete the question: ... you speak English fluently?", "o": ["Does", "Is", "Do", "Are"], "a": 2, "p": "Kalimat tanya Simple Present Tense dengan subjek 'you' diawali dengan auxiliary verb 'Do'."}, {"lv": 2, "q": "The sun ... in the east every morning.", "o": ["rise", "rises", "rising", "rose"], "a": 1, "p": "Fakta umum (kebenaran universal) menggunakan Simple Present Tense. Karena 'The sun' tunggal, kata kerjanya menjadi 'rises'."}, {"lv": 3, "q": "My mother and father ... hard at the office from Monday to Friday.", "o": ["works", "working", "work", "worked"], "a": 2, "p": "Subjek 'My mother and father' berjumlah lebih dari satu (jamak), sehingga kata kerja dasarnya adalah 'work'."}, {"lv": 3, "q": "Complete the negative sentence: We ... watch television during study hours.", "o": ["does not", "do not", "is not", "are not"], "a": 1, "p": "Subjek jamak 'We' menggunakan 'do not' (don't) untuk membentuk kalimat negatif dalam Simple Present Tense."}, {"lv": 3, "q": "Roni is a diligent student. He always ... his homework before playing games.", "o": ["do", "does", "doing", "did"], "a": 1, "p": "Untuk subjek 'He', kata kerja 'do' dalam Simple Present Tense berubah menjadi 'does'."}, {"lv": 3, "q": "Complete the dialogue correctly:\nA: Does Lina wash her own clothes?\nB: Yes, she ...", "o": ["do", "does", "is", "has"], "a": 1, "p": "Pertanyaan yang diawali dengan 'Does' dijawab dengan 'Yes, she does' pada respons singkat."}]}, {"id": "big-k5-1", "name": "Daily routines", "desc": "Kegiatan rutin", "idx": 1, "soal": [{"lv": 1, "q": "What do you usually do in the morning after waking up?", "o": ["Take a bath", "Go to sleep", "Have dinner", "Brush my teeth"], "a": 0, "p": "Kegiatan rutin yang biasa dilakukan setelah bangun tidur di pagi hari adalah mandi (take a bath) atau menyikat gigi."}, {"lv": 1, "q": "Complete the sentence: I ... breakfast at 06.00 a.m. every day.", "o": ["eat", "sleep", "play", "wash"], "a": 0, "p": "Kita menyantap (eat) sarapan di pagi hari pukul 06.00."}, {"lv": 1, "q": "What is the Indonesian meaning of 'wake up'?", "o": ["Pergi tidur", "Bangun tidur", "Mandi", "Berpakaian"], "a": 1, "p": "'Wake up' artinya bangun tidur."}, {"lv": 1, "q": "Before going to school, students usually wear their school ...", "o": ["pajamas", "uniform", "swimsuit", "jacket"], "a": 1, "p": "Sebelum pergi ke sekolah, murid-murid biasanya mengenakan seragam sekolah (school uniform)."}, {"lv": 2, "q": "Siti arrives home from school in the afternoon. What does she usually do first?", "o": ["Go to sleep until morning", "Change her clothes and wash her hands", "Brush her teeth for bed", "Eat breakfast"], "a": 1, "p": "Sesampainya di rumah dari sekolah pada siang hari, rutinitas yang wajar adalah mengganti pakaian dan mencuci tangan."}, {"lv": 2, "q": "Budi has a test tomorrow, so he spends his evening time to ... his lessons.", "o": ["play", "sleep", "study", "cook"], "a": 2, "p": "Ketika ada ujian keesokan harinya, Budi meluangkan waktu malamnya untuk belajar (study) pelajarannya."}, {"lv": 2, "q": "After finishing dinner with his family, Roni helps his mother to ... the dishes.", "o": ["wash", "cook", "eat", "wear"], "a": 0, "p": "Setelah makan malam, kegiatan rutin yang biasa dilakukan untuk membantu ibu adalah mencuci (wash) piring."}, {"lv": 2, "q": "Ani turns off the lights and goes to her bedroom at 09.00 p.m. because she wants to ...", "o": ["wake up", "sleep", "study", "run"], "a": 1, "p": "Mematikan lampu dan pergi ke kamar tidur pada pukul 09.00 malam dilakukan untuk tidur (sleep)."}, {"lv": 3, "q": "Read the short text: 'Every day, Lina wakes up at 05.00 a.m. She makes her bed, takes a bath, and has breakfast before catching the school bus at 06.30 a.m.' What does Lina do right after waking up?", "o": ["Catches the school bus", "Makes her bed", "Has breakfast", "Takes a bath"], "a": 1, "p": "Berdasarkan teks, setelah bangun tidur Lina langsung merapikan tempat tidurnya (makes her bed)."}, {"lv": 3, "q": "Look at the sequence of Ahmad's afternoon routine: 1) Playing football, 2) Taking a bath, 3) Doing homework. Which sequence is the most logical after school?", "o": ["2, 1, 3", "1, 2, 3", "3, 1, 2", "1, 3, 2"], "a": 1, "p": "Urutan kegiatan sore yang paling logis sepulang sekolah adalah bermain bola (berkeringat), lalu mandi, kemudian mengerjakan PR."}, {"lv": 3, "q": "Dina says: 'I never skip my morning routine.' Which of the following sentences best describes a healthy morning routine habit?", "o": ["I sleep until noon and miss school.", "I wake up early, clean myself, and eat a healthy breakfast.", "I watch television all night long.", "I skip brushing my teeth every day."], "a": 1, "p": "Kebiasaan rutin pagi yang sehat adalah bangun pagi, membersihkan diri, dan makan sarapan yang sehat."}, {"lv": 3, "q": "Father finishes his work at the office, drives back home, and arrives at 07.00 p.m. What meal does he usually have with the family at this time?", "o": ["Breakfast", "Lunch", "Dinner", "Brunch"], "a": 2, "p": "Makan yang disantap bersama keluarga pada pukul 07.00 malam (evening/night) adalah makan malam (dinner)."}]}, {"id": "big-k5-2", "name": "Jobs", "desc": "Nama dan tugas pekerjaan", "idx": 2, "soal": [{"lv": 1, "q": "What is the Indonesian meaning of the job 'teacher'?", "o": ["Dokter", "Guru", "Polisi", "Petani"], "a": 1, "p": "'Teacher' artinya guru. Dokter adalah doctor, polisi adalah police officer, dan petani adalah farmer."}, {"lv": 1, "q": "Who works in a hospital and helps sick people?", "o": ["Teacher", "Chef", "Doctor", "Driver"], "a": 2, "p": "Seseorang yang bekerja di rumah sakit dan membantu orang sakit adalah dokter (doctor)."}, {"lv": 1, "q": "What is Bahasa Indonesia of 'firefighter'?", "o": ["Pemadam kebakaran", "Pilot", "Nelayan", "Penyiar"], "a": 0, "p": "'Firefighter' artinya petugas pemadam kebakaran."}, {"lv": 1, "q": "A person who flies an airplane is called a ...", "o": ["driver", "pilot", "sailor", "conductor"], "a": 1, "p": "Seseorang yang menerbangkan pesawat terbang disebut pilot."}, {"lv": 2, "q": "Budi wants to report a thief in his neighborhood. He needs to ask help from a ...", "o": ["doctor", "police officer", "chef", "mechanic"], "a": 1, "p": "Untuk melaporkan pencuri atau menjaga keamanan lingkungan, kita meminta bantuan polisi (police officer)."}, {"lv": 2, "q": "Siti likes cooking delicious food in a restaurant kitchen. Her job is a ...", "o": ["teacher", "nurse", "chef", "dentist"], "a": 2, "p": "Seseorang yang memasak makanan lezat di dapur restoran adalah seorang koki (chef)."}, {"lv": 2, "q": "Ani has a toothache, so her mother takes her to see a ...", "o": ["dentist", "vet", "pharmacist", "librarian"], "a": 0, "p": "Dokter yang khusus mengobati sakit gigi disebut dokter gigi (dentist)."}, {"lv": 2, "q": "A farmer plants rice and vegetables in the field. What is the main workplace of a farmer?", "o": ["Hospital", "School", "Farm or field", "Office"], "a": 2, "p": "Tempat kerja utama seorang petani (farmer) adalah di sawah atau ladang (farm or field)."}, {"lv": 3, "q": "Roni's cat is sick and cannot eat. Roni takes the cat to an animal doctor, which is called a ...", "o": ["dentist", "surgeon", "veterinarian", "pediatrician"], "a": 2, "p": "Dokter yang khusus mengobati hewan (animal doctor) disebut dokter hewan atau veterinarian (vet)."}, {"lv": 3, "q": "Read the short text: 'Mr. John delivers letters and packages to houses in our neighborhood every morning.' What is Mr. John's job?", "o": ["Postman", "Driver", "Mechanic", "Carpenter"], "a": 0, "p": "Orang yang mengantar surat dan paket ke rumah-rumah adalah tukang pos (postman)."}, {"lv": 3, "q": "Dina wants to build a wooden bookshelf for her study room. Which worker should she hire?", "o": ["Painter", "Carpenter", "Plumber", "Electrician"], "a": 1, "p": "Orang yang ahli membuat benda-benda dari kayu seperti meja dan rak buku adalah tukang kayu (carpenter)."}, {"lv": 3, "q": "Father's car broke down on the highway because of an engine problem. Who should he call to fix the car?", "o": ["Mechanic", "Barber", "Tailor", "Baker"], "a": 0, "p": "Orang yang ahli memperbaiki mesin kendaraan yang rusak adalah mekanik (mechanic)."}]}], "6": [{"id": "big-k6-0", "name": "Simple past tense", "desc": "Kata kerja lampau beraturan dan tidak", "idx": 0, "soal": [{"lv": 1, "q": "What is the past tense (Verb 2) of the regular verb 'visit'?", "o": ["visiting", "visited", "visits", "visite"], "a": 1, "p": "Kata kerja beraturan (regular verb) 'visit' membentuk past tense dengan menambahkan akhiran -ed menjadi 'visited'."}, {"lv": 1, "q": "Complete the sentence: Yesterday, I ... to the zoo with my family.", "o": ["go", "going", "went", "gone"], "a": 2, "p": "Keterangan waktu 'yesterday' menunjukkan Simple Past Tense. Bentuk Verb 2 dari 'go' adalah 'went'."}, {"lv": 1, "q": "What is the past tense (Verb 2) of the irregular verb 'eat'?", "o": ["eated", "eating", "ate", "aten"], "a": 2, "p": "'Eat' adalah kata kerja tidak beraturan (irregular verb) yang bentuk Verb 2-nya adalah 'ate'."}, {"lv": 1, "q": "Which sentence is in the Simple Past Tense?", "o": ["She plays football now.", "She played football yesterday.", "She is playing football.", "She will play football."], "a": 1, "p": "Kalimat yang menggunakan kata kerja bentuk kedua ('played') dan keterangan waktu lampau ('yesterday') adalah bentuk Simple Past Tense."}, {"lv": 2, "q": "Complete the negative sentence: Budi ... not watch television last night.", "o": ["do", "does", "did", "done"], "a": 2, "p": "Bentuk kalimat negatif dalam Simple Past Tense menggunakan auxiliary verb 'did not' (didn't) untuk semua subjek."}, {"lv": 2, "q": "Complete the sentence: Mother ... a delicious cake for my birthday last week.", "o": ["make", "makes", "making", "made"], "a": 3, "p": "Keterangan waktu 'last week' menunjukkan masa lampau. Verb 2 dari 'make' adalah 'made'."}, {"lv": 2, "q": "Complete the interrogative sentence: ... you buy a new book two days ago?", "o": ["Do", "Does", "Did", "Done"], "a": 2, "p": "Kalimat tanya dalam Simple Past Tense selalu diawali dengan auxiliary verb 'Did'."}, {"lv": 2, "q": "Change the verb in brackets into past tense: 'They (play) basketball in the school yard this morning.'", "o": ["play", "played", "playing", "plays"], "a": 1, "p": "Kata kerja 'play' adalah regular verb, sehingga bentuk lampaunya (Verb 2) dengan menambahkan -ed menjadi 'played'."}, {"lv": 3, "q": "Complete the dialogue correctly:\nA: Did Siti finish her homework last night?\nB: Yes, she ...", "o": ["did", "does", "was", "had"], "a": 0, "p": "Pertanyaan dalam Simple Past Tense yang diawali dengan 'Did' dijawab dengan 'Yes, she did' pada respons singkat."}, {"lv": 3, "q": "Read the sentence and choose the correct form: 'Last holiday, my friends and I ... to Bali by plane, and we ... a lot of amazing places.'", "o": ["go / visit", "went / visited", "went / visiting", "gone / visited"], "a": 1, "p": "Karena terjadi di masa lalu ('Last holiday'), kedua kata kerja harus menggunakan bentuk Verb 2: 'went' (dari go) dan 'visited' (dari visit)."}, {"lv": 3, "q": "Complete the negative sentence correctly: 'Ani ... to school yesterday because she was sick.'", "o": ["does not go", "did not went", "did not go", "was not go"], "a": 2, "p": "Dalam kalimat negatif Simple Past Tense, setelah 'did not' (didn't), kata kerja utama harus kembali ke bentuk dasar (Verb 1), yaitu 'go'."}, {"lv": 3, "q": "Which of the following irregular verbs has the SAME form in Verb 1, Verb 2, and Verb 3?", "o": ["eat - ate - eaten", "go - went - gone", "cut - cut - cut", "write - wrote - written"], "a": 2, "p": "Kata kerja 'cut' memiliki bentuk yang sama untuk Verb 1, Verb 2, dan Verb 3 (cut - cut - cut), berbeda dengan eat, go, dan write yang berubah bentuknya."}]}, {"id": "big-k6-1", "name": "Giving directions", "desc": "Menunjukkan arah", "idx": 1, "soal": [{"lv": 1, "q": "What is the Indonesian meaning of 'turn left'?", "o": ["Belok kanan", "Belok kiri", "Berjalan lurus", "Berhenti"], "a": 1, "p": "'Turn left' artinya belok kiri. Belok kanan adalah turn right, berjalan lurus adalah go straight."}, {"lv": 1, "q": "Which expression means 'berjalan lurus' in English?", "o": ["Turn right", "Go straight", "Turn left", "Stop here"], "a": 1, "p": "'Go straight' adalah ungkapan dalam bahasa Inggris untuk menyuruh berjalan lurus."}, {"lv": 1, "q": "What is Bahasa Indonesia of 'turn right'?", "o": ["Belok kanan", "Belok kiri", "Jalan terus", "Putar balik"], "a": 0, "p": "'Turn right' artinya belok kanan."}, {"lv": 1, "q": "When someone asks for directions politely, they usually start by saying ...", "o": ["Give me money", "Excuse me", "Go away", "Hurry up"], "a": 1, "p": "Saat seseorang ingin menanyakan arah dengan sopan, mereka biasanya mengawalinya dengan kata 'Excuse me' (Permisi)."}, {"lv": 2, "q": "Budi wants to go to the post office. A stranger tells him: 'Walk along this street and you will see the building on your right side.' What does 'walk along' mean?", "o": ["Berjalan menyusuri / mengikuti jalan", "Berlari cepat", "Menyeberang jalan", "Berhenti berjalan"], "a": 0, "p": "'Walk along' dalam konteks menunjukkan arah berarti berjalan menyusuri atau mengikuti jalan tersebut."}, {"lv": 2, "q": "Siti is looking for the bookstore. Her friend says: 'It is located between the bank and the hospital.' Where is the bookstore?", "o": ["Di sebelah bank saja", "Di seberang rumah sakit", "Di antara bank dan rumah sakit", "Di belakang rumah sakit"], "a": 2, "p": "Ungkapan 'between the bank and the hospital' berarti toko buku tersebut terletak di antara bank dan rumah sakit."}, {"lv": 2, "q": "Roni is at the corner of the street. The person helping him says: 'Take the second turning on your left.' What does this instruction mean?", "o": ["Belokan pertama ke kiri", "Belokan kedua ke kiri", "Belokan kedua ke kanan", "Jangan berbelok"], "a": 1, "p": "'Take the second turning on your left' artinya ambil belokan kedua di sebelah kiri."}, {"lv": 2, "q": "Ani asks: 'Is there a supermarket near here?' The local replies: 'Yes, it is just ... the street from the cinema.'", "o": ["across", "next", "behind", "under"], "a": 0, "p": "Frasa 'across the street' berarti di seberang jalan (dari bioskop)."}, {"lv": 3, "q": "Read the direction: 'Go straight ahead for two blocks, then turn left at the T-junction. The library is on your right, opposite the grand park.' Where is the library located?", "o": ["Di sebelah kiri jalan", "Di seberang taman besar", "Di sebelah taman besar", "Di belakang gedung bioskop"], "a": 1, "p": "Berdasarkan petunjuk 'opposite the grand park', perpustakaan tersebut terletak di seberang taman besar (opposite berarti di seberang)."}, {"lv": 3, "q": "A tourist is lost and asks: 'Could you tell me the way to the railway station?' Which of the following is the most polite and natural response?", "o": ["I don't know, go away!", "Sure! Go straight down this road, and it's on your left.", "You must build a railway station now.", "Why do you ask me?"], "a": 1, "p": "Respon yang paling sopan dan natural saat seseorang menanyakan arah stasiun kereta adalah menunjukkan jalannya dengan ramah."}, {"lv": 3, "q": "Look at the preposition usage: 'The museum is ... the corner of Main Street and Oak Avenue.' Which preposition fits best?", "o": ["in", "on", "at", "under"], "a": 2, "p": "Untuk menunjukkan posisi di suatu tikungan atau sudut jalan (corner of...), preposisi yang tepat adalah 'at'."}, {"lv": 3, "q": "Dina is giving directions to her house: 'Walk past the traditional market, and my house is the second house ... the bakery.'", "o": ["next to", "across from", "behind", "between"], "a": 0, "p": "Ungkapan 'next to the bakery' berarti rumah tersebut berada di sebelah toko roti."}]}, {"id": "big-k6-2", "name": "Comparison of adjectives", "desc": "-er, -est, more, most", "idx": 2, "soal": [{"lv": 1, "q": "What is the comparative form (-er) of the adjective 'tall'?", "o": ["taller", "tallest", "more tall", "most tall"], "a": 0, "p": "Kata sifat bersuku kata satu 'tall' membentuk comparative dengan menambahkan -er menjadi 'taller'."}, {"lv": 1, "q": "Complete the sentence: An elephant is ... than a dog.", "o": ["big", "bigger", "biggest", "more big"], "a": 1, "p": "Kalimat perbandingan antara dua benda menggunakan bentuk comparative (-er). Karena membandingkan gajah dan anjing, kata 'big' menjadi 'bigger'."}, {"lv": 1, "q": "What is the superlative form (-est) of the adjective 'small'?", "o": ["smaller", "smallest", "more small", "most small"], "a": 1, "p": "Bentuk superlative dari kata sifat satu suku kata 'small' adalah 'smallest'."}, {"lv": 1, "q": "Which adjective uses 'more' to form its comparative degree because it has two or more syllables?", "o": ["fast", "cold", "beautiful", "short"], "a": 2, "p": "Kata sifat yang terdiri dari tiga suku kata atau lebih seperti 'beautiful' menggunakan 'more' untuk perbandingannya."}, {"lv": 2, "q": "Complete the sentence: Mount Everest is the ... mountain in the world.", "o": ["high", "higher", "highest", "more high"], "a": 2, "p": "Perbandingan melebihi semua benda dalam satu kelompok (superlative) menggunakan akhiran -est, yaitu 'highest'."}, {"lv": 2, "q": "Budi is 12 years old. Andi is 14 years old. Roni is 10 years old. Who is the youngest?", "o": ["Budi", "Andi", "Roni", "Budi and Andi"], "a": 2, "p": "Roni berusia 10 tahun, yang merupakan usia paling kecil di antara ketiganya, sehingga Roni adalah yang paling muda (the youngest)."}, {"lv": 2, "q": "Mathematics is ... than History for me. (difficult)", "o": ["difficult", "difficulter", "more difficult", "most difficult"], "a": 2, "p": "Kata 'difficult' memiliki tiga suku kata, sehingga bentuk perbandingannya (comparative) menggunakan 'more difficult'."}, {"lv": 2, "q": "Complete the sentence: Cheetahs are the ... land animals in the world.", "o": ["fast", "faster", "fastest", "more fast"], "a": 2, "p": "Karena cheetah dibandingkan dengan seluruh hewan darat lainnya (tingkat superlatif), bentuk yang tepat adalah 'fastest'."}, {"lv": 3, "q": "Which of the following irregular adjectives changes its form completely in the comparative and superlative degrees?", "o": ["tall - taller - tallest", "good - better - best", "smart - smarter - smartest", "fast - faster - fastest"], "a": 1, "p": "Kata sifat 'good' adalah kata sifat tidak beraturan (irregular adjective) yang berubah menjadi 'better' (comparative) dan 'best' (superlative)."}, {"lv": 3, "q": "Read the sentence and choose the correct words: 'This summer is ... than last summer, but July was the ... month of all.'", "o": ["hot / hotter", "hotter / hottest", "hottest / hotter", "more hot / most hot"], "a": 1, "p": "Perbandingan dua musim panas menggunakan 'hotter', sedangkan perbandingan bulan terpanas di antara semua bulan menggunakan 'hottest'."}, {"lv": 3, "q": "Complete the sentence with the correct superlative form: 'Of all the students in the classroom, Sinta is the ... girl.' (intelligent)", "o": ["intelligenter", "most intelligent", "more intelligent", "intelligentest"], "a": 1, "p": "Kata sifat panjang 'intelligent' membentuk superlative dengan menambahkan 'most' di depannya menjadi 'most intelligent'."}, {"lv": 3, "q": "Which sentence has an INCORRECT comparison of adjectives?", "o": ["My house is bigger than yours.", "That is the most interesting book I have ever read.", "A car is more expensive than a bicycle.", "English is more easier than Mathematics."], "a": 3, "p": "Kalimat keempat salah karena kata 'easy' sudah bersuku kata dua berakhiran -y (mudah menjadi easier), tidak boleh digabung dengan 'more' menjadi 'more easier'."}]}], "7": [{"id": "big-k7-0", "name": "Describing people", "desc": "Ciri fisik dan sifat", "idx": 0, "soal": [{"lv": 1, "q": "What is the Indonesian meaning of the adjective 'tall' when describing someone's physical appearance?", "o": ["Pendek", "Tinggi", "Gemuk", "Kurus"], "a": 1, "p": "'Tall' artinya tinggi. Pendek adalah short, gemuk adalah fat, dan kurus adalah thin."}, {"lv": 1, "q": "Which adjective describes a person who has a friendly and pleasant personality?", "o": ["Mean", "Kind", "Lazy", "Angry"], "a": 1, "p": "'Kind' berarti baik hati atau ramah, yang merupakan sifat positif seseorang."}, {"lv": 1, "q": "What is the opposite of 'short' when describing hair length?", "o": ["Long", "Curly", "Straight", "Dark"], "a": 0, "p": "Lawan kata dari 'short' (pendek) untuk mendeskripsikan rambut adalah 'long' (panjang)."}, {"lv": 1, "q": "Complete the sentence: My brother has ... hair. It is not straight at all; it forms small rings.", "o": ["straight", "bald", "curly", "short"], "a": 2, "p": "Rambut yang ikal atau keriting yang membentuk seperti lingkaran kecil disebut 'curly'."}, {"lv": 2, "q": "Siti always shares her snacks with her friends and helps them when they are in trouble. She is a very ... girl.", "o": ["selfish", "generous", "lazy", "shy"], "a": 1, "p": "Suka berbagi dan menolong orang lain menunjukkan sifat dermawan atau suka memberi (generous)."}, {"lv": 2, "q": "Budi is not fat, and he is not too thin. He has a normal and healthy body shape. We can describe him as ...", "o": ["slim", "overweight", "tall", "short"], "a": 0, "p": "Bentuk tubuh yang ideal, langsing, atau proporsional disebut 'slim'."}, {"lv": 2, "q": "Ani doesn't like talking much when she meets new people at school because she feels nervous. She is a bit ...", "o": ["outgoing", "confident", "shy", "cheerful"], "a": 2, "p": "Orang yang pemalu dan kurang suka berbicara saat bertemu orang baru disebut 'shy'."}, {"lv": 2, "q": "Father works hard every day from morning until night and always completes his tasks on time. He is a ... man.", "o": ["lazy", "diligent", "arrogant", "noisy"], "a": 1, "p": "Orang yang bekerja keras dan rajin menyelesaikan tugas disebut 'diligent'."}, {"lv": 3, "q": "Read the short description: 'Dina is a 13-year-old student. She has shoulder-length wavy black hair, round glasses, and a sweet smile. She is very helpful and always studies hard.' Which of the following describes her physical traits?", "o": ["Helpful and studies hard", "Shoulder-length wavy black hair and round glasses", "13-year-old student", "Always cheerful"], "a": 1, "p": "Ciri fisik (physical traits) dari teks tersebut adalah rambut hitam bergelombang sebahu dan berkacamata bulat, sedangkan 'helpful' adalah sifat (personality)."}, {"lv": 3, "q": "Roni is known as an 'outgoing' person in his class. What does 'outgoing' mean in describing someone's personality?", "o": ["Suka menyendiri dan pendiam", "Ramah, mudah bergaul, dan suka berteman", "Pemarah dan mudah tersinggung", "Malas keluar rumah"], "a": 1, "p": "'Outgoing' berarti ramah, supel, dan mudah bergaul dengan orang lain."}, {"lv": 3, "q": "Look at the sentence structure: 'She has beautiful long black hair.' Why is the adjective order 'long' before 'black'?", "o": ["Karena 'long' adalah ukuran dan 'black' adalah warna (aturan ukuran mendahului warna)", "Karena aturan abjad", "Karena warna harus selalu di depan", "Karena 'black' lebih penting daripada 'long'"], "a": 0, "p": "Dalam susunan kata sifat bahasa Inggris (Adjective Order), ukuran (size: long) mendahului warna (color: black)."}, {"lv": 3, "q": "Your new classmate never gets angry even when people tease him, and he always greets everyone with a smile. Which words best describe him?", "o": ["Strict and moody", "Patient and friendly", "Lazy and selfish", "Anxious and shy"], "a": 1, "p": "Sifat tidak mudah marah (sabar) dan selalu menyapa dengan senyuman (ramah) paling tepat digambarkan dengan 'patient and friendly'."}]}, {"id": "big-k7-1", "name": "Present continuous tense", "desc": "Kegiatan yang sedang terjadi", "idx": 1, "soal": [{"lv": 1, "q": "She ... a book in the library now.", "o": ["read", "reads", "is reading", "reading"], "a": 2, "p": "Subject 'She' menggunakan to be 'is' dan verb-ing 'reading' karena menyatakan kegiatan yang sedang berlangsung (now)."}, {"lv": 1, "q": "They ... football in the yard at the moment.", "o": ["are playing", "is playing", "play", "plays"], "a": 0, "p": "Subject 'They' menggunakan to be 'are' diikuti dengan verb-ing 'playing'."}, {"lv": 1, "q": "I ... breakfast in the kitchen right now.", "o": ["is eating", "are eating", "am eating", "eat"], "a": 2, "p": "Subject 'I' selalu berpasangan dengan to be 'am' dan verb-ing 'eating'."}, {"lv": 1, "q": "Look! The cat ... on the sofa.", "o": ["sleep", "sleeps", "are sleeping", "is sleeping"], "a": 3, "p": "Kata seru 'Look!' menunjukkan kejadian sedang berlangsung. 'The cat' adalah singular (kata ganti it), sehingga menggunakan 'is sleeping'."}, {"lv": 2, "q": "Listen! The birds ... sweetly in the trees.", "o": ["are singing", "is singing", "sing", "sang"], "a": 0, "p": "Kata 'Listen!' menandakan aksi sedang terjadi. 'The birds' bentuk jamak (plural), maka menggunakan 'are singing'."}, {"lv": 2, "q": "What ... you ... at the moment?", "o": ["do / do", "are / doing", "is / doing", "does / do"], "a": 1, "p": "Dalam kalimat tanya present continuous untuk subject 'you', susunannya adalah 'Are + you + doing?'."}, {"lv": 2, "q": "Budi and Andi ... not ... English right now; they are studying math.", "o": ["is / studying", "are / studying", "are / study", "is / study"], "a": 1, "p": "Subject 'Budi and Andi' adalah plural (jamak), menggunakan 'are not studying'."}, {"lv": 2, "q": "My mother ... dinner in the kitchen at present.", "o": ["cook", "cooks", "is cooking", "are cooking"], "a": 2, "p": "Keterangan waktu 'at present' menunjukkan present continuous. 'My mother' (She) menggunakan 'is cooking'."}, {"lv": 3, "q": "Sinta cannot answer the phone because she ... a shower.", "o": ["takes", "took", "is taking", "are taking"], "a": 2, "p": "Situasi menjelaskan kejadian yang sedang berlangsung saat ini ('cannot answer the phone because she...'). 'She' menggunakan 'is taking'."}, {"lv": 3, "q": "Rearrange the words into a correct present continuous sentence:\n[is - playing - the piano - Lina - now]", "o": ["Lina is playing the piano now.", "Lina playing the piano is now.", "Is Lina playing now the piano?", "Now Lina playing the piano is."], "a": 0, "p": "Struktur kalimat positif present continuous: Subject (Lina) + to be (is) + verb-ing (playing) + object (the piano) + time marker (now)."}, {"lv": 3, "q": "Randi: 'Where is your brother?'\nDoni: 'He is in his bedroom. He ... his homework.'", "o": ["does", "did", "is doing", "are doing"], "a": 2, "p": "Pertanyaan menanyakan keberadaan dan aktivitas saat ini. 'He' menggunakan to be 'is' dan verb-ing 'doing'."}, {"lv": 3, "q": "Which of the following sentences is INCORRECT in Present Continuous Tense?", "o": ["We are studying English together.", "The baby is crying loudly in the room.", "She is write a letter to her friend.", "Am I disturbing you right now?"], "a": 2, "p": "Pilihan C tidak tepat karena menggunakan verb dasar 'write' setelah 'is'. Seharusnya menggunakan verb-ing 'writing' ('She is writing a letter...')."}]}, {"id": "big-k7-2", "name": "Asking and giving information", "desc": "Pertanyaan WH-", "idx": 2, "soal": [{"lv": 1, "q": "... is your name?", "o": ["What", "Where", "When", "Who"], "a": 0, "p": "Kata tanya 'What' digunakan untuk menanyakan identitas atau nama."}, {"lv": 1, "q": "... do you live?", "o": ["What", "Where", "Who", "When"], "a": 1, "p": "Kata tanya 'Where' digunakan untuk menanyakan tempat atau lokasi (tinggal)."}, {"lv": 1, "q": "... old are you?", "o": ["How", "What", "Where", "Which"], "a": 0, "p": "Frasa 'How old' digunakan untuk menanyakan usia seseorang."}, {"lv": 1, "q": "... do you go to school?", "o": ["Who", "Why", "When", "What"], "a": 2, "p": "Kata tanya 'When' digunakan untuk menanyakan waktu kegiatan."}, {"lv": 2, "q": "Andi: '... is that woman in the blue dress?'\nSinta: 'She is my English teacher.'", "o": ["Where", "When", "Who", "Why"], "a": 2, "p": "Jawaban menunjuk pada seseorang (guru bahasa Inggris), sehingga kata tanya yang tepat adalah 'Who' (siapa)."}, {"lv": 2, "q": "Randi: '... do you look so sad?'\nDoni: 'Because I lost my favorite pen.'", "o": ["Why", "What", "How", "Where"], "a": 0, "p": "Jawaban dimulai dengan 'Because' yang menyatakan alasan, sehingga pertanyaan diawali dengan 'Why' (mengapa)."}, {"lv": 2, "q": "Budi: '... do you go to Bali?'\nJoko: 'I go there by airplane.'", "o": ["What", "How", "When", "Who"], "a": 1, "p": "Jawaban menjelaskan cara atau moda transportasi ('by airplane'), sehingga menggunakan 'How'."}, {"lv": 2, "q": "Siti: '... jacket do you like better, the red one or the blue one?'\nAni: 'I prefer the blue one.'", "o": ["What", "Who", "Which", "Where"], "a": 2, "p": "Kata tanya 'Which' digunakan ketika ada pilihan terbatas (antara jaket merah atau biru)."}, {"lv": 3, "q": "Complete the dialogue correctly:\nTourist: 'Excuse me, ... is the nearest post office?'\nLocal: 'It is on Merdeka Street, next to the bank.'", "o": ["What", "Where", "How", "When"], "a": 1, "p": "Jawaban menunjukkan lokasi ('on Merdeka Street'), maka pertanyaan yang tepat menanyakan tempat adalah 'Where'."}, {"lv": 3, "q": "Choose the correct WH-question to match the answer:\nAnswer: 'There are five students in the classroom.'", "o": ["How many students are there in the classroom?", "How much are the students in the classroom?", "What are the students doing in the classroom?", "Where are the students in the classroom?"], "a": 0, "p": "Untuk menanyakan jumlah benda/orang yang dapat dihitung (students), digunakan 'How many'."}, {"lv": 3, "q": "Rina: '... does the English class finish?'\nToni: 'It finishes at ten o'clock.'", "o": ["What time", "How long", "How often", "Where"], "a": 0, "p": "Jawaban menyebutkan jam/waktu spesifik ('at ten o'clock'), sehingga menanyakan waktu menggunakan 'What time' atau 'When'."}, {"lv": 3, "q": "Which of the following questions is grammatically INCORRECT?", "o": ["Where do you live?", "What is your hobby?", "Why you are late to school?", "When does the train arrive?"], "a": 2, "p": "Pilihan C tidak tepat secara gramatikal karena susunan kalimat tanya simple present menggunakan to be/auxiliary sebelum subject. Seharusnya 'Why are you late to school?'."}]}], "8": [{"id": "big-k8-0", "name": "Recount text", "desc": "Menceritakan pengalaman", "idx": 0, "soal": [{"lv": 1, "q": "What is the primary social function of a recount text?", "o": ["To retell past events for the purpose of informing or entertaining", "To explain how something works step by step", "To persuade readers to buy a product", "To describe a specific person or place in detail"], "a": 0, "p": "Fungsi sosial utama dari recount text adalah menceritakan kembali kejadian atau pengalaman di masa lalu (to retell past events)."}, {"lv": 1, "q": "Which tense is predominantly used in writing a recount text?", "o": ["Simple Present Tense", "Simple Past Tense", "Present Continuous Tense", "Future Tense"], "a": 1, "p": "Recount text menceritakan kejadian lampau, sehingga tenses utama yang digunakan adalah Simple Past Tense."}, {"lv": 1, "q": "What is the correct structure of a recount text?", "o": ["Orientation - Complication - Resolution", "Goal - Materials - Steps", "Orientation - Events - Re-orientation", "General Classification - Description"], "a": 2, "p": "Struktur umum recount text terdiri dari Orientation (pengenalan), Events (serangkaian kejadian), dan Re-orientation (kesimpulan/penutup)."}, {"lv": 1, "q": "Which of the following words is commonly found as a past verb in a recount text?", "o": ["Go", "Went", "Going", "Goes"], "a": 1, "p": "Kata 'went' adalah bentuk verb 2 (past tense) dari kata 'go', yang sering digunakan dalam recount text."}, {"lv": 2, "q": "Read the sentence: 'Last weekend, my family and I went camping in Mount Bromo.' This part of the text belongs to...", "o": ["Orientation", "Events", "Re-orientation", "Complication"], "a": 0, "p": "Bagian awal yang mengenalkan pelaku (my family and I), waktu (last weekend), dan tempat (Mount Bromo) disebut orientation."}, {"lv": 2, "q": "Choose the correct past form to complete the sentence: 'Yesterday, Andi ... a new bicycle from his father.'", "o": ["get", "gets", "got", "getting"], "a": 2, "p": "Keterangan waktu 'Yesterday' menunjukkan masa lampau, sehingga menggunakan verb 2 yaitu 'got'."}, {"lv": 2, "q": "Which sentence uses the correct grammar for a recount text?", "o": ["She visits her grandparents last week.", "They visited their grandparents last week.", "They visiting their grandparents last week.", "She is visiting her grandparents last week."], "a": 1, "p": "Penggunaan subject 'They' dengan verb 2 'visited' dan keterangan waktu 'last week' sudah sesuai dengan kaidah simple past tense."}, {"lv": 2, "q": "What is the purpose of the 'Re-orientation' section at the end of a recount text?", "o": ["To state the chronological steps of an experiment", "To introduce the main characters and setting", "To give personal comments or a summary of the experience", "To present a problem and solve it"], "a": 2, "p": "Re-orientation berfungsi untuk memberikan komentar pribadi atau kesimpulan akhir mengenai pengalaman yang diceritakan."}, {"lv": 3, "q": "Read the paragraph:\n'First, we arrived at the beach early in the morning. After that, we built a sandcastle and swam in the water. Finally, we ate grilled fish before going home.'\nWhat kind of conjunctions are predominantly used in the paragraph?", "o": ["Causal conjunctions (because, due to)", "Temporal conjunctions / sequence words (first, after that, finally)", "Correlative conjunctions (either... or)", "Comparative conjunctions (as... as)"], "a": 1, "p": "Kata seperti 'first', 'after that', dan 'finally' adalah konjungsi temporal (sequence words) untuk menunjukkan urutan waktu kejadian."}, {"lv": 3, "q": "Rearrange the following sentences into a coherent recount paragraph:\n1) We felt very tired but extremely happy.\n2) Last holiday, my friends and I visited a waterfall.\n3) We took many photos and played in the fresh water.\n\nThe correct arrangement is...", "o": ["2 - 3 - 1", "1 - 2 - 3", "3 - 2 - 1", "2 - 1 - 3"], "a": 0, "p": "Susunan yang logis: perkenalan/orientation (2), kejadian/events (3), lalu penutup/re-orientation berupa kesan (1)."}, {"lv": 3, "q": "Read the sentence and find the grammatical error:\n'When I was walking to school yesterday, I meet my old friend along the street.'\nThe incorrect word/phrase is...", "o": ["When I was walking", "to school", "yesterday", "I meet"], "a": 3, "p": "Karena kalimat menceritakan masa lampau (yesterday), kata kerja 'meet' seharusnya dalam bentuk past tense menjadi 'met'."}, {"lv": 3, "q": "Which of the following texts is most likely a personal recount text?", "o": ["A recipe explaining how to make chocolate cookies", "A diary entry written by a student about their unforgettable school trip", "A scientific report about animal migration patterns", "A fictional story about a magical kingdom and a dragon"], "a": 1, "p": "Diary entry tentang liburan sekolah adalah contoh personal recount text karena menceritakan pengalaman pribadi penulis di masa lalu."}]}, {"id": "big-k8-1", "name": "Invitations", "desc": "Undangan, menerima dan menolak", "idx": 1, "soal": [{"lv": 1, "q": "Which of the following phrases is used to invite someone to an event?", "o": ["I'm sorry to hear that.", "Would you like to come to my party?", "Thank you for the gift.", "I think you are right."], "a": 1, "p": "Kalimat 'Would you like to come...?' adalah ungkapan standar dalam bahasa Inggris untuk mengundang seseorang menghadiri sebuah acara."}, {"lv": 1, "q": "If you want to accept an invitation, you can say...", "o": ["I'd love to, thank you!", "I'm afraid I can't.", "Maybe some other time.", "I'm very busy right now."], "a": 0, "p": "Ungkapan 'I'd love to' (saya akan sangat senang) digunakan untuk menunjukkan bahwa seseorang menerima undangan tersebut."}, {"lv": 1, "q": "A written or spoken request to ask someone to go somewhere or do something is called...", "o": ["An announcement", "An advertisement", "An invitation", "A compliment"], "a": 2, "p": "Invitation (undangan) adalah permintaan baik lisan maupun tertulis untuk mengajak seseorang ke suatu tempat atau melakukan sesuatu."}, {"lv": 1, "q": "Which expression is used to decline (refuse) an invitation?", "o": ["Sure, I'll be there.", "That sounds like a great idea!", "I'm sorry, I can't make it.", "With pleasure."], "a": 2, "p": "Kalimat 'I'm sorry, I can't make it' adalah cara sopan untuk menolak (decline) sebuah undangan karena tidak bisa hadir."}, {"lv": 2, "q": "Santi: 'We are going to the new library this afternoon. Do you want to join us?'\nBudi: '... I have to help my mother at the shop.'", "o": ["I'd love to, but I can't.", "Yes, of course.", "That would be great.", "I will go there."], "a": 0, "p": "Budi memberikan alasan bahwa ia harus membantu ibunya, maka ia perlu menolak secara sopan menggunakan 'I'd love to, but I can't'."}, {"lv": 2, "q": "Raka: 'I'm having a birthday dinner at 7 PM tonight. Can you come?'\nTio: '... I'll see you there!'", "o": ["I'm not sure.", "I don't think so.", "I'm sorry, I'm busy.", "Sure, I'd be happy to come."], "a": 3, "p": "Kalimat 'I'll see you there' menandakan Tio setuju untuk datang, sehingga jawaban yang tepat adalah ekspresi menerima undangan."}, {"lv": 2, "q": "To: All Basketball Club Members\nPlease attend our weekly meeting on:\nDay/Date: Saturday, October 12th\nTime: 02.00 PM\nPlace: School Hall\n\nWhat is the purpose of the text above?", "o": ["To describe the school hall.", "To invite members to a meeting.", "To announce a basketball competition.", "To ask members to play basketball."], "a": 1, "p": "Teks tersebut mencantumkan waktu, tempat, dan agenda (meeting), yang merupakan tujuan dari sebuah undangan (invitation)."}, {"lv": 2, "q": "Which sentence is the most appropriate to invite your teacher to a school art exhibition?", "o": ["Hey, come to the art show!", "Do you want to see some art?", "Would you like to attend our school art exhibition, Sir?", "You must come to our school hall now."], "a": 2, "p": "Untuk situasi formal seperti mengundang guru, kita menggunakan bahasa yang lebih sopan (Would you like to attend...?)."}, {"lv": 3, "q": "Dina: 'I have two tickets for the music concert tomorrow. I was wondering if you'd like to go with me.'\nEko: 'I really appreciate the offer, but I've already made plans with my family.'\n\nFrom the dialogue, we know that Eko...", "o": ["Will go to the concert with Dina.", "Is asking for a ticket from Dina.", "Is declining the invitation politely.", "Doesn't like music concerts."], "a": 2, "p": "Eko menggunakan kata 'but' dan menjelaskan rencana lain, yang berarti ia menolak tawaran tersebut dengan tetap menghargai (polite decline)."}, {"lv": 3, "q": "Someone invites you to a party, but you are not sure if you can go. What is the best response?", "o": ["I will definitely come.", "I can't come at all.", "I'd love to, but I'll have to check my schedule first.", "Don't invite me, I'm busy."], "a": 2, "p": "Saat merasa tidak yakin, jawaban paling sopan adalah menunjukkan ketertarikan (I'd love to) namun memberi tahu bahwa perlu memeriksa jadwal."}, {"lv": 3, "q": "Linda: 'I'm throwing a housewarming party this Saturday. It won't be the same without you.'\nWhat does Linda's second sentence imply?", "o": ["The party feels incomplete if the person doesn't attend.", "Linda wants the person to help her clean the house.", "The person is not actually invited to the party.", "The house is too small for many people."], "a": 0, "p": "Ungkapan 'It won't be the same without you' menyiratkan bahwa kehadiran orang tersebut sangat penting bagi Linda."}, {"lv": 3, "q": "In a formal invitation, which part is used to request a response for attendance confirmation?", "o": ["The Salutation", "The Body", "RSVP", "The Closing"], "a": 2, "p": "RSVP berasal dari bahasa Prancis 'Répondez s'il vous plaît' yang artinya 'mohon jawaban' untuk konfirmasi kehadiran."}]}, {"id": "big-k8-2", "name": "Simple past vs past continuous", "desc": "Perbedaan penggunaan", "idx": 2, "soal": [{"lv": 1, "q": "While I ... dinner, the phone rang.", "o": ["cooked", "was cooking", "is cooking", "cooks"], "a": 1, "p": "Dalam kalimat yang menggabungkan past continuous dan simple past dengan kata 'while', kejadian yang sedang berlangsung menggunakan past continuous ('was cooking')."}, {"lv": 1, "q": "She ... a book when the lights went out.", "o": ["read", "reads", "were reading", "was reading"], "a": 3, "p": "Subjek 'She' menggunakan to be 'was' dan verb-ing 'reading' untuk menyatakan aktivitas yang sedang terjadi saat kejadian lain menyela."}, {"lv": 1, "q": "They played football yesterday afternoon. What tense is predominantly used in this sentence?", "o": ["Simple Past Tense", "Past Continuous Tense", "Present Perfect Tense", "Simple Present Tense"], "a": 0, "p": "Kalimat tersebut menggunakan verb 2 ('played') dan keterangan waktu lampau ('yesterday afternoon'), yang merupakan ciri Simple Past Tense."}, {"lv": 1, "q": "What were you doing at 8 PM last night?", "o": ["I sleep in my room.", "I am sleeping in my room.", "I was sleeping in my room.", "I will sleep in my room."], "a": 2, "p": "Pertanyaan menanyakan aktivitas yang sedang terjadi pada waktu tertentu di masa lalu, dijawab menggunakan Past Continuous Tense ('was sleeping')."}, {"lv": 2, "q": "He ... his car when it started to rain heavily.", "o": ["was washing", "washed", "is washing", "was wash"], "a": 0, "p": "Aksi yang sedang berlangsung (mencuci mobil) disela oleh kejadian lain (mulai hujan), sehingga menggunakan past continuous ('was washing')."}, {"lv": 2, "q": "When the teacher entered the classroom, the students ... noisy.", "o": ["are", "were", "was", "did"], "a": 1, "p": "Subjek 'the students' berbentuk jamak (plural) dan kalimat berada dalam konteks lampau, sehingga menggunakan to be 'were'."}, {"lv": 2, "q": "Mother was cooking in the kitchen ... Father was reading a newspaper in the living room.", "o": ["when", "while", "because", "although"], "a": 1, "p": "Kata hubung 'while' digunakan untuk menghubungkan dua kegiatan yang terjadi secara bersamaan di masa lampau (dua-duanya past continuous)."}, {"lv": 2, "q": "Choose the correct combination of Simple Past and Past Continuous in one sentence:", "o": ["I was walking home when I saw my old friend.", "I walked home when I was seeing my old friend.", "I was walking home while I see my old friend.", "I walked home while I saw my old friend."], "a": 0, "p": "Aksi yang sedang berjalan ('was walking') disela oleh aksi pendek ('saw'), biasanya dihubungkan dengan kata 'when'."}, {"lv": 3, "q": "Read the dialogue:\nBudi: 'I called you last night, but you didn't pick up.'\nAndi: 'Sorry, I ... my homework at that time.'", "o": ["do", "did", "was doing", "am doing"], "a": 2, "p": "Frasa 'at that time' merujuk pada aktivitas yang sedang berlangsung di masa lampau ketika panggilan terjadi, sehingga menggunakan past continuous ('was doing')."}, {"lv": 3, "q": "Analyze the sentences below and find the INCORRECT one:", "o": ["While they were playing football, it began to rain.", "She was dropping her glass while she washed the dishes.", "The sun was shining brightly when we woke up.", "What were you doing when I phoned you?"], "a": 1, "p": "Pilihan B kurang tepat karena aksi pendek yang menyela seharusnya berbentuk simple past ('dropped'), bukan past continuous ('was washing' di klausa sebelah atau posisi terbalik)."}, {"lv": 3, "q": "Complete the sentence with the correct verb forms:\n'As I ... down the street, I ... a loud noise.'", "o": ["walk / hear", "was walking / heard", "walked / was hearing", "were walking / hear"], "a": 1, "p": "Penggunaan kata 'as' (ketika/sementara) diikuti past continuous ('was walking') untuk aksi yang sedang berlangsung, disusul simple past ('heard') untuk aksi seketika."}, {"lv": 3, "q": "Why do we use Past Continuous Tense instead of Simple Past Tense in a story narrative?", "o": ["To show a completed action in the past", "To describe a habit or routine in the past", "To set the background or describe an ongoing action interrupted by another", "To state a future plan that never happened"], "a": 2, "p": "Dalam narasi, past continuous digunakan untuk memberikan latar belakang situasi (background scene) atau aksi yang sedang berlangsung sebelum disela."}]}], "9": [{"id": "big-k9-0", "name": "Procedure text", "desc": "Langkah membuat sesuatu", "idx": 0, "soal": [{"lv": 1, "q": "What is the social function of a Procedure Text?", "o": ["To describe a particular person or place", "To retell a past event or experience", "To tell the reader how to do or make something", "To entertain the reader with a story"], "a": 2, "p": "Fungsi sosial dari teks prosedur adalah memberikan petunjuk kepada pembaca tentang cara melakukan atau membuat sesuatu melalui urutan langkah-langkah."}, {"lv": 1, "q": "The part of the procedure text that lists the things we need is called...", "o": ["Goal", "Materials or Ingredients", "Steps", "Conclusion"], "a": 1, "p": "Bagian 'Materials' (alat/bahan) atau 'Ingredients' (bahan makanan) berisi daftar hal-hal yang diperlukan untuk mencapai tujuan dalam teks prosedur."}, {"lv": 1, "q": "Which of these words is a common 'temporal conjunction' used in procedure texts?", "o": ["Because", "Although", "Finally", "Beautifully"], "a": 2, "p": "Temporal conjunction adalah kata hubung waktu seperti 'First', 'Next', 'Then', dan 'Finally' yang berfungsi menunjukkan urutan pengerjaan."}, {"lv": 1, "q": "Procedure texts usually use 'imperative sentences'. Which one is an example of an imperative?", "o": ["The water is boiling", "Stir the mixture slowly", "I like making coffee", "He cooks some rice"], "a": 1, "p": "Kalimat imperatif adalah kalimat perintah yang memberikan instruksi langsung, seperti 'Stir the mixture slowly' (Aduk campurannya perlahan)."}, {"lv": 2, "q": "Read these steps: \n1. Boil the water in a pan. \n2. Put the tea bag into a cup. \n3. ... \n4. Add some sugar and stir it well. \n\nWhat is the most suitable sentence for step 3?", "o": ["Drink the tea immediately", "Pour the hot water into the cup", "Buy some tea at the market", "Wash the cup with soap"], "a": 1, "p": "Sesuai urutan logis pembuatan teh, setelah air mendidih dan kantong teh siap di cangkir, langkah selanjutnya adalah menuangkan air panas ke dalam cangkir."}, {"lv": 2, "q": "To make a glass of iced lemon tea, we need these materials, EXCEPT...", "o": ["Tea bag and hot water", "Lemon juice and sugar", "Ice cubes", "Frying pan and oil"], "a": 3, "p": "Wajan (frying pan) dan minyak (oil) adalah alat dan bahan untuk menggoreng, sehingga tidak diperlukan dalam pembuatan teh lemon es."}, {"lv": 2, "q": "Which verb is the most appropriate for this instruction: '... the onion into small pieces before frying them.'", "o": ["Chop", "Boil", "Bake", "Whisk"], "a": 0, "p": "Kata 'Chop' berarti mencincang atau memotong-motong menjadi bagian kecil, yang merupakan tindakan tepat untuk menyiapkan bawang."}, {"lv": 2, "q": "If a recipe says 'Whisk the egg whites until stiff', what tool should you use?", "o": ["A blender", "A knife", "A whisk or mixer", "A spatula"], "a": 2, "p": "Untuk mengocok (whisk) bahan sampai kaku atau mengembang, alat yang paling sesuai adalah pengocok manual (whisk) atau mixer elektrik."}, {"lv": 3, "q": "Arrange these jumbled steps into a good procedure of making an omelet: \n1. Fold the omelet in half. \n2. Heat the oil in a frying pan. \n3. Beat the eggs with a pinch of salt. \n4. Pour the egg mixture into the pan. \n5. Serve on a plate.", "o": ["3 - 2 - 4 - 1 - 5", "2 - 3 - 4 - 5 - 1", "3 - 4 - 2 - 1 - 5", "2 - 4 - 3 - 1 - 5"], "a": 0, "p": "Urutan yang benar adalah: mengocok telur (3), memanaskan minyak (2), menuangkan telur (4), melipat telur (1), dan terakhir menyajikannya (5)."}, {"lv": 3, "q": "In a manual on how to use a camera: 'Press the shutter button halfway to focus, then press it all the way to take the picture.' \nWhat happens if you only press the button halfway?", "o": ["The camera will take a photo", "The camera will turn off", "The camera will only focus on the object", "The camera will delete the previous photo"], "a": 2, "p": "Berdasarkan instruksi tersebut, menekan tombol shutter setengah (halfway) hanya berfungsi untuk memfokuskan lensa pada objek, bukan mengambil gambar."}, {"lv": 3, "q": "Look at this snippet: 'First, insert your card into the slot. Second, enter your 6-digit PIN. Third, choose the withdrawal amount.' \nWhat is the 'Goal' of this procedure?", "o": ["How to create a new bank account", "How to withdraw money from an ATM", "How to pay for groceries with a card", "How to block a lost credit card"], "a": 1, "p": "Instruksi memasukkan kartu, mengisi PIN, dan memilih jumlah penarikan (withdrawal amount) menunjukkan prosedur mengambil uang di mesin ATM."}, {"lv": 3, "q": "Why is the use of 'Action Verbs' (like cut, mix, pour) important in a procedure text?", "o": ["To describe the taste of the food", "To tell the reader's feeling about the activity", "To explain the background of the ingredients", "To provide clear instructions on what the reader should do"], "a": 3, "p": "Action verbs (kata kerja aksi) sangat penting karena memberikan instruksi spesifik tentang tindakan fisik apa yang harus dilakukan pembaca untuk mencapai hasil akhir."}]}, {"id": "big-k9-1", "name": "Passive voice", "desc": "Kalimat pasif sederhana", "idx": 1, "soal": [{"lv": 1, "q": "In a passive voice sentence, the main verb must be in the form of...", "o": ["Infinitive (V1)", "Present Participle (V-ing)", "Past Participle (V3)", "Past Tense (V2)"], "a": 2, "p": "Dalam kalimat pasif (passive voice), kata kerja utama yang digunakan selalu bentuk kata kerja ketiga atau Past Participle (V3)."}, {"lv": 1, "q": "Which of the following sentences is an example of passive voice?", "o": ["The cat chased the mouse.", "The mouse was chased by the cat.", "The cat is chasing the mouse.", "The cat will chase the mouse."], "a": 1, "p": "Kalimat pasif ditandai dengan pola 'to be + V3' dan subjeknya menerima aksi. Pilihan B (was chased) adalah bentuk pasif."}, {"lv": 1, "q": "What is the common word used to introduce the 'doer' (agent) in a passive sentence?", "o": ["With", "For", "At", "By"], "a": 3, "p": "Kata 'by' digunakan untuk menunjukkan pelaku aksi (agent) dalam kalimat pasif, contohnya: 'The book was written by him'."}, {"lv": 1, "q": "The classroom ... every morning by the students.", "o": ["is cleaned", "cleans", "is clean", "cleaning"], "a": 0, "p": "Karena subjeknya tunggal (The classroom) dan kegiatannya bersifat rutin (every morning), kita gunakan Present Passive: 'is' + V3 (cleaned)."}, {"lv": 2, "q": "Change this active sentence into passive: 'The students played football yesterday.'", "o": ["Football is played by the students yesterday.", "Football was played by the students yesterday.", "Football were played by the students yesterday.", "Football is playing by the students yesterday."], "a": 1, "p": "Kalimat aktif menggunakan Past Tense (played). Untuk pasif, gunakan 'was/were + V3'. Karena 'football' tunggal, maka yang benar adalah 'was played'."}, {"lv": 2, "q": "Change this active sentence into passive: 'Many people visit Borobudur Temple.'", "o": ["Borobudur Temple is visited by many people.", "Borobudur Temple was visited by many people.", "Borobudur Temple are visited by many people.", "Borobudur Temple visited by many people."], "a": 0, "p": "Kalimat aktif menggunakan Present Tense (visit). Karena subjek baru 'Borobudur Temple' tunggal, maka bentuk pasifnya menggunakan 'is visited'."}, {"lv": 2, "q": "These delicious cookies ... by my grandmother two hours ago.", "o": ["are baked", "is baked", "were baked", "was baked"], "a": 2, "p": "Subjek 'cookies' adalah jamak (plural) dan ada keterangan lampau (two hours ago). Maka, 'to be' yang tepat adalah 'were' diikuti V3 (baked)."}, {"lv": 2, "q": "Active: 'Rina does not write the letter.'\nPassive: 'The letter ... by Rina.'", "o": ["was not written", "is not written", "is not write", "does not written"], "a": 1, "p": "Kalimat aktif negatif Present Tense menggunakan 'does not'. Dalam bentuk pasif, rumusnya adalah 'is/am/are + not + V3'. Jadi, 'is not written'."}, {"lv": 3, "q": "Dika: 'Where is my motorcycle?'\nBudi: 'Don't worry, it ... by the mechanic right now.'", "o": ["is repaired", "is being repaired", "was repaired", "repaired"], "a": 1, "p": "Keterangan 'right now' menunjukkan aksi sedang berlangsung (Continuous). Bentuk pasif Present Continuous adalah 'is/am/are + being + V3'."}, {"lv": 3, "q": "Choose the correct passive form of this question: 'Did Thomas Edison invent the light bulb?'", "o": ["Is the light bulb invented by Thomas Edison?", "Was the light bulb invent by Thomas Edison?", "Was the light bulb invented by Thomas Edison?", "Did the light bulb be invented by Thomas Edison?"], "a": 2, "p": "Untuk kalimat tanya lampau (Did...?), bentuk pasifnya menggunakan 'Was/Were + Subject + V3'. Karena 'light bulb' tunggal, gunakan 'Was... invented?'"}, {"lv": 3, "q": "Identify the incorrect part in this passive sentence: 'The important documents (A) was (B) sent (C) by (D) the secretary yesterday.'", "o": ["A", "B", "C", "D"], "a": 1, "p": "Bagian (B) salah karena 'The important documents' adalah subjek jamak (plural), sehingga 'to be' yang seharusnya digunakan adalah 'were', bukan 'was'."}, {"lv": 3, "q": "In many Asian countries, rice ... as a staple food for centuries.", "o": ["is grown", "has been grown", "was grown", "is being grown"], "a": 1, "p": "Keterangan 'for centuries' menunjukkan durasi (Present Perfect). Bentuk pasifnya adalah 'has/have + been + V3'. Maka yang tepat adalah 'has been grown'."}]}, {"id": "big-k9-2", "name": "Narrative text", "desc": "Cerita rakyat dan fabel", "idx": 2, "soal": [{"lv": 1, "q": "What is the primary social function of a narrative text?", "o": ["To describe a specific object in detail", "To amuse or entertain the readers with a moral story", "To explain how something is made step by step", "To persuade readers to buy a product"], "a": 1, "p": "Fungsi sosial utama dari teks naratif (narrative text) adalah untuk menghibur pembaca melalui cerita khayalan, fabel, atau legenda yang memuat pesan moral."}, {"lv": 1, "q": "Which of the following is usually found at the beginning (orientation) of a narrative text?", "o": ["The resolution of the problem", "The moral lesson of the story", "The introduction of characters, time, and setting", "A detailed list of ingredients"], "a": 2, "p": "Bagian orientation di awal teks naratif berfungsi memperkenalkan tokoh (characters), waktu (time), dan tempat kejadian (setting)."}, {"lv": 1, "q": "What tense is predominantly used in writing a narrative text?", "o": ["Simple present tense", "Simple past tense", "Present continuous tense", "Simple future tense"], "a": 1, "p": "Karena teks naratif menceritakan kisah di masa lampau, tenses yang dominan digunakan adalah Simple Past Tense."}, {"lv": 1, "q": "In a fable, who are typically the main characters of the story?", "o": ["Kings and queens", "Animals that behave like humans", "Superheroes and villains", "Scientists and researchers"], "a": 1, "p": "Fabel adalah cerita naratif yang tokoh utamanya adalah hewan (animals) yang digambarkan bertingkah laku seperti manusia."}, {"lv": 2, "q": "Read the generic structure of a narrative text: Orientation - Complication - ... - Reorientation. What is the missing part?", "o": ["Resolution", "Arguments", "Description", "Identification"], "a": 0, "p": "Struktur umum teks naratif secara berurutan adalah Orientation, Complication (muncul masalah), Resolution (penyelesaian masalah), dan Reorientation."}, {"lv": 2, "q": "What is the section called where the main problem or crisis arises in a narrative text?", "o": ["Resolution", "Orientation", "Complication", "Coda"], "a": 2, "p": "Bagian di mana masalah atau konflik mulai muncul dan berkembang dalam cerita disebut 'complication'."}, {"lv": 2, "q": "Which of the following phrases is commonly used to open a fairy tale or legend in a narrative text?", "o": ["Once upon a time", "First, mix the sugar", "Dear Sir or Madam", "Attention, please"], "a": 0, "p": "Frasa 'Once upon a time' (pada suatu ketika) adalah pembuka klasik yang sangat sering digunakan dalam cerita naratif."}, {"lv": 2, "q": "In a story where the wolf tries to trick the little rabbit, the wolf represents the ... character.", "o": ["hero", "protagonist", "antagonist", "narrator"], "a": 2, "p": "Tokoh yang menentang atau menjadi musuh tokoh utama dalam cerita disebut antagonis (antagonist)."}, {"lv": 3, "q": "Read the short paragraph: 'The arrogant hare laughed at the slow tortoise. He challenged the tortoise to a race, feeling completely confident that he would win easily.' Based on this excerpt, what can we infer about the hare's character?", "o": ["He is humble and kind", "He is boastful and overconfident", "He is fearful and nervous", "He is helpful and honest"], "a": 1, "p": "Kata 'arrogant' dan keyakinan berlebih bahwa dia akan menang menunjukkan bahwa kelinci tersebut sombong dan terlalu percaya diri (boastful and overconfident)."}, {"lv": 3, "q": "Read the excerpt: 'Slowly and steadily, the tortoise kept walking without stopping, while the hare took a long nap under a shady tree.' What literary device or narrative element is highlighted in this part of the story?", "o": ["The turning point leading to the climax", "The setting of the place only", "The moral lesson directly stated", "The resolution of the conflict"], "a": 0, "p": "Bagian ini menunjukkan kontras tindakan tokoh yang menjadi titik balik (turning point) sebelum kura-kura memenangkan perlombaan."}, {"lv": 3, "q": "Why do narrative texts frequently use action verbs such as 'escaped', 'fought', 'whispered', and 'cried'?", "o": ["To describe the physical appearance of an object", "To make the events in the story feel alive and dynamic", "To explain scientific facts clearly", "To give instructions on how to build something"], "a": 1, "p": "Penggunaan action verbs dalam bentuk lampau membuat alur peristiwa dalam cerita naratif terasa lebih hidup, dinamis, dan menarik bagi pembaca."}, {"lv": 3, "q": "What is the function of the 'Coda' or moral lesson at the end of some narrative texts?", "o": ["To summarize the recipe steps", "To give a concluding advice or lesson learned from the story", "To introduce new characters for a sequel", "To explain the geographical location of the setting"], "a": 1, "p": "Coda atau pesan moral di akhir cerita naratif berfungsi memberikan nasihat atau pelajaran hidup yang dapat dipetik oleh pembaca dari kisah tersebut."}]}]}, "bin": {"1": [{"id": "bin-k1-0", "name": "Huruf dan suku kata", "desc": "Mengenal huruf, suku kata, dan merangkai kata", "idx": 0, "soal": [{"lv": 1, "q": "Huruf pertama pada kata 'Buku' adalah...", "o": ["a", "b", "c", "d"], "a": 1, "p": "Kata 'Buku' dimulai dengan huruf 'b'."}, {"lv": 1, "q": "Manakah yang termasuk huruf vokal?", "o": ["b", "k", "a", "s"], "a": 2, "p": "Huruf vokal ada lima, yaitu: a, i, u, e, o."}, {"lv": 1, "q": "Setelah huruf 'j' adalah huruf...", "o": ["k", "l", "i", "m"], "a": 0, "p": "Urutan abjad yang benar adalah ... h, i, j, k."}, {"lv": 1, "q": "Ada berapa huruf pada kata 'Bola'?", "o": ["2 huruf", "3 huruf", "4 huruf", "5 huruf"], "a": 2, "p": "Kata 'Bola' terdiri dari huruf b-o-l-a (4 huruf)."}, {"lv": 2, "q": "Pemisahan suku kata yang benar untuk 'Baju' adalah...", "o": ["Baj-u", "Ba-ju", "B-aju", "Baju-u"], "a": 1, "p": "Kata 'Baju' dibaca menjadi dua ketukan: Ba dan ju."}, {"lv": 2, "q": "Ka - ... . Bunyi untuk melengkapi kata 'Kaki' adalah...", "o": ["ku", "ka", "ke", "ki"], "a": 3, "p": "Suku kata 'ka' ditambah 'ki' menjadi kata 'kaki'."}, {"lv": 2, "q": "Kata yang diawali dengan suku kata 'Ma' adalah...", "o": ["Mata", "Buku", "Topi", "Sapi"], "a": 0, "p": "Mata diawali dengan Ma- (Ma-ta)."}, {"lv": 2, "q": "Ada berapa suku kata pada kata 'Pepaya'?", "o": ["2 suku kata", "3 suku kata", "4 suku kata", "5 suku kata"], "a": 1, "p": "Pe-pa-ya terdiri dari 3 suku kata."}, {"lv": 3, "q": "Jika huruf m-a-k-a-n disusun, akan menjadi kata...", "o": ["Makam", "Makan", "Malas", "Malam"], "a": 1, "p": "Huruf m-a-k-a-n membentuk kata 'makan'."}, {"lv": 3, "q": "Manakah kata yang paling panjang (paling banyak hurufnya)?", "o": ["Meja", "Tas", "Sekolah", "Buku"], "a": 2, "p": "Sekolah memiliki 7 huruf, paling banyak dibanding pilihan lainnya."}, {"lv": 3, "q": "Kata yang bunyi belakangnya sama dengan 'Buku' adalah...", "o": ["Sapi", "Bola", "Suku", "Roti"], "a": 2, "p": "Buku dan Suku memiliki bunyi akhir yang sama, yaitu '-ku'."}, {"lv": 3, "q": "Ganti huruf 'm' pada kata 'Madu' menjadi 'p'. Kata itu menjadi...", "o": ["Padu", "Palu", "Paku", "Pasu"], "a": 0, "p": "Jika huruf depan 'm' diganti 'p', maka 'madu' berubah menjadi 'padu'."}]}, {"id": "bin-k1-1", "name": "Kosakata sehari-hari", "desc": "Benda, anggota keluarga, dan kegiatan di sekitar", "idx": 1, "soal": [{"lv": 1, "q": "Benda yang digunakan di kepala agar tidak kepanasan adalah...", "o": ["Topi", "Sepatu", "Baju", "Tas"], "a": 0, "p": "Topi dipakai di kepala untuk melindungi dari panas matahari."}, {"lv": 1, "q": "Anggota tubuh yang kita gunakan untuk melihat adalah...", "o": ["Telinga", "Mata", "Hidung", "Mulut"], "a": 1, "p": "Mata berfungsi untuk melihat benda-benda di sekitar kita."}, {"lv": 1, "q": "Panggilan untuk orang tua perempuan kita adalah...", "o": ["Ayah", "Ibu", "Kakek", "Paman"], "a": 1, "p": "Orang tua perempuan dipanggil Ibu atau Mama."}, {"lv": 1, "q": "Benda yang kita gunakan untuk membersihkan lantai adalah...", "o": ["Meja", "Piring", "Buku", "Sapu"], "a": 3, "p": "Sapu adalah alat untuk menyapu kotoran di lantai."}, {"lv": 2, "q": "Panggilan untuk saudara perempuan yang usianya lebih tua dari kita adalah...", "o": ["Kakak", "Adik", "Nenek", "Bibi"], "a": 0, "p": "Saudara yang lebih tua, baik laki-laki atau perempuan, dipanggil Kakak."}, {"lv": 2, "q": "Supaya bersih, saat mandi kita menggunakan air dan...", "o": ["Pasta gigi", "Sabun", "Sikat gigi", "Sisir"], "a": 1, "p": "Sabun digunakan untuk membersihkan kuman di kulit saat mandi."}, {"lv": 2, "q": "Alat yang digunakan untuk makan makanan berkuah (sup) adalah...", "o": ["Garpu", "Pisau", "Sendok", "Piring"], "a": 2, "p": "Sendok digunakan untuk mengambil makanan cair atau berkuah."}, {"lv": 2, "q": "Apa yang harus kita lakukan pada piring kotor setelah makan?", "o": ["Dibuang", "Dibiarkan", "Disimpan", "Dicuci"], "a": 3, "p": "Piring kotor harus dicuci agar bersih kembali dan bisa digunakan lagi."}, {"lv": 3, "q": "Ayah dari orang tua kita (ayah atau ibu) dipanggil...", "o": ["Kakek", "Nenek", "Paman", "Kakak"], "a": 0, "p": "Orang tua laki-laki dari ayah atau ibu kita disebut Kakek."}, {"lv": 3, "q": "Kegiatan makan yang dilakukan pada pagi hari disebut...", "o": ["Makan siang", "Sarapan", "Makan malam", "Jajan"], "a": 1, "p": "Sarapan adalah makan pagi sebelum kita memulai kegiatan sekolah."}, {"lv": 3, "q": "Ibu ingin memotong sayuran di dapur. Ibu membutuhkan...", "o": ["Gunting", "Sendok", "Pisau", "Garpu"], "a": 2, "p": "Pisau adalah alat dapur yang digunakan untuk memotong bahan masakan."}, {"lv": 3, "q": "Langit tampak mendung dan gelap. Sebelum keluar rumah kita harus menyiapkan...", "o": ["Topi", "Kacamata", "Sepatu", "Payung"], "a": 3, "p": "Mendung tandanya akan hujan, jadi kita butuh payung agar tidak basah."}]}, {"id": "bin-k1-2", "name": "Membaca kalimat sederhana", "desc": "Memahami kalimat pendek", "idx": 2, "soal": [{"lv": 1, "q": "Ibu memasak nasi. Apa yang dimasak Ibu?", "o": ["Ikan", "Sayur", "Nasi", "Roti"], "a": 2, "p": "Kalimat tersebut menyebutkan secara jelas bahwa yang dimasak Ibu adalah nasi."}, {"lv": 1, "q": "Budi membaca buku. Apa yang sedang dilakukan Budi?", "o": ["Membaca", "Mandi", "Makan", "Lari"], "a": 0, "p": "Dalam kalimat ini, kegiatan atau kata kerja yang dilakukan Budi adalah membaca."}, {"lv": 1, "q": "Adik minum susu. Apa yang diminum Adik?", "o": ["Air", "Susu", "Teh", "Jus"], "a": 1, "p": "Kalimat menjelaskan bahwa benda cair yang diminum oleh Adik adalah susu."}, {"lv": 1, "q": "Ani punya tas merah. Apa warna tas Ani?", "o": ["Biru", "Hijau", "Kuning", "Merah"], "a": 3, "p": "Warna tas milik Ani adalah merah, sesuai dengan keterangan di dalam kalimat."}, {"lv": 2, "q": "Kelinci suka makan wortel. Hewan apa yang suka makan wortel?", "o": ["Kucing", "Ayam", "Kelinci", "Ikan"], "a": 2, "p": "Subjek atau hewan yang diceritakan dalam kalimat tersebut adalah kelinci."}, {"lv": 2, "q": "Edo cuci kaki sebelum tidur. Kapan Edo mencuci kakinya?", "o": ["Pagi hari", "Sebelum tidur", "Siang hari", "Saat makan"], "a": 1, "p": "Keterangan waktu dalam kalimat ini menunjukkan kegiatan cuci kaki dilakukan sebelum tidur."}, {"lv": 2, "q": "Lani menyiram bunga di kebun. Di mana Lani menyiram bunga?", "o": ["Di kebun", "Di kelas", "Di dapur", "Di pasar"], "a": 0, "p": "Tempat Lani melakukan kegiatannya adalah di kebun."}, {"lv": 2, "q": "Bapak pergi ke kantor naik motor. Bapak naik apa?", "o": ["Sepeda", "Mobil", "Bus", "Motor"], "a": 3, "p": "Alat transportasi yang digunakan Bapak dalam kalimat tersebut adalah motor."}, {"lv": 3, "q": "Lampu di kelas mati. Suasana kelas sekarang menjadi...", "o": ["Ramai", "Gelap", "Terang", "Bersih"], "a": 1, "p": "Jika lampu mati, maka tidak ada cahaya sehingga ruangan kelas akan menjadi gelap."}, {"lv": 3, "q": "Dina merasa sangat lapar. Apa yang sebaiknya dilakukan Dina?", "o": ["Makan nasi", "Minum air", "Pergi tidur", "Mandi pagi"], "a": 0, "p": "Rasa lapar adalah tanda tubuh butuh asupan makanan, jadi Dina sebaiknya makan."}, {"lv": 3, "q": "Hari ini hujan deras. Tono memakai ... agar badannya tidak basah.", "o": ["Topi", "Sepatu", "Payung", "Tas"], "a": 2, "p": "Payung adalah benda yang digunakan untuk melindungi tubuh dari air hujan agar tidak basah."}, {"lv": 3, "q": "Siti rajin belajar setiap hari. Siti akan menjadi anak yang...", "o": ["Tinggi", "Lucu", "Kuat", "Pintar"], "a": 3, "p": "Anak yang rajin belajar biasanya memiliki pengetahuan yang luas atau menjadi pintar."}]}], "10": [{"id": "bin-k10-0", "name": "Teks laporan hasil observasi", "desc": "Definisi umum dan deskripsi bagian", "idx": 0, "soal": [{"lv": 1, "q": "Teks yang menyajikan informasi mengenai suatu objek atau fenomena berdasarkan hasil pengamatan secara sistematis disebut...", "o": ["Teks eksposisi", "Teks laporan hasil observasi", "Teks prosedur", "Teks deskripsi"], "a": 1, "p": "Teks laporan hasil observasi (LHO) berisi penjabaran umum mengenai suatu objek berdasarkan fakta hasil pengamatan langsung."}, {"lv": 1, "q": "Bagian awal dalam struktur teks laporan hasil observasi yang berisi pembukaan atau pengenalan objek yang diamati disebut...", "o": ["Deskripsi bagian", "Simpulan", "Pernyataan umum atau definisi umum", "Deskripsi manfaat"], "a": 2, "p": "Pernyataan umum (definisi umum) terletak di bagian awal untuk memberikan gambaran global mengenai objek yang akan dilaporkan."}, {"lv": 1, "q": "Secara garis besar, struktur teks laporan hasil observasi terdiri atas...", "o": ["Pernyataan umum dan deskripsi bagian", "Abstraksi dan orientasi", "Tujuan dan langkah-langkah", "Tesis dan argumen"], "a": 0, "p": "Struktur utama teks LHO terdiri dari pernyataan umum (klasifikasi/definisi) serta deskripsi bagian (rincian rinci ciri objek)."}, {"lv": 1, "q": "Salah satu sifat mutlak yang harus dimiliki oleh isi dalam teks laporan hasil observasi adalah...", "o": ["Subjektif sesuai perasaan penulis", "Faktual dan objektif berdasarkan fakta", "Imajinatif dan penuh fantasi", "Persuasif untuk membujuk pembaca"], "a": 1, "p": "Teks LHO harus bersifat objektif dan faktual, artinya disusun murni berdasarkan kenyataan yang ada tanpa dipengaruhi opini pribadi."}, {"lv": 2, "q": "Perhatikan kutipan teks berikut: 'Kunyit adalah salah satu tanaman rempah yang biasa digunakan sebagai bumbu dapur maupun obat herbal. Tanaman ini termasuk ke dalam suku temu-temuan (Zingiberaceae).' \nKutipan tersebut merupakan bagian dari...", "o": ["Deskripsi bagian", "Pernyataan umum", "Deskripsi manfaat", "Penutup"], "a": 1, "p": "Kutipan tersebut mengenalkan tanaman kunyit secara umum serta mengklasifikasikannya ke dalam suku tertentu, yang merupakan ciri definisi umum."}, {"lv": 2, "q": "Perhatikan kutipan berikut: 'Batang kunyit beruas-ruas, berwarna hijau kekuningan, dan memiliki tinggi sekitar 40 hingga 100 cm. Bagian akarnya membentuk rimpang yang berwarna jingga pekat.' \nKutipan teks di atas termasuk ke dalam struktur...", "o": ["Pernyataan umum", "Deskripsi manfaat", "Deskripsi bagian", "Abstraksi"], "a": 2, "p": "Bagian tersebut merinci bentuk fisik secara spesifik (batang, tinggi, akar), yang merupakan ciri struktur deskripsi bagian."}, {"lv": 2, "q": "Manakah di bawah ini kalimat yang menggunakan kaidah bahasa berupa 'kalimat definisi' dalam teks laporan hasil observasi?", "o": ["Kucing Anggora memiliki bulu yang sangat lebat dan panjang.", "Mamalia adalah jenis hewan vertebrata yang menyusui anaknya.", "Ambillah sampel darah kucing tersebut untuk diperiksa di laboratorium.", "Kucing itu berlari dengan sangat cepat mengejar mangsanya."], "a": 1, "p": "Kalimat definisi ditandai dengan penggunaan verba penghubung seperti 'adalah' atau 'merupakan' untuk menerangkan suatu istilah (Mamalia adalah...)."}, {"lv": 2, "q": "Dalam menyusun teks laporan hasil observasi, penggunaan kata bernuansa keilmuan (istilah teknis) sangat dianjurkan. Contoh kalimat yang mengandung istilah teknis adalah...", "o": ["Pemandangan di pantai itu sangat indah dan menyejukkan mata.", "Kucing sangat suka bermain bola benang di ruang tamu.", "Ekosistem laut terdiri dari berbagai komponen biotik dan abiotik.", "Ibu memasak makanan kesukaan kami dengan sangat lezat."], "a": 2, "p": "Kata 'ekosistem', 'biotik', dan 'abiotik' merupakan istilah teknis atau ilmiah yang sering digunakan dalam laporan hasil observasi biologi/lingkungan."}, {"lv": 3, "q": "Cermati kalimat berikut: 'Pohon kelapa (Cocos nucifera) adalah tumbuhan palma yang buahnya dimanfaatkan banyak orang.' \nKaidah kebahasaan apakah yang dominan pada awal kalimat tersebut?", "o": ["Penggunaan frasa nomina dan verba pengisi predikat", "Penggunaan kalimat perintah dan konjungsi syarat", "Penggunaan kalimat langsung dan kata ganti orang", "Penggunaan majas personifikasi dan hiperbola"], "a": 0, "p": "Kalimat tersebut diawali dengan frasa nomina (Pohon kelapa) sebagai subjek dan diikuti verba penghubung 'adalah' sebagai predikat."}, {"lv": 3, "q": "Bacalah dua kutipan teks berikut!\nTeks 1: Harimau sumatera memiliki ciri loreng yang lebih rapat dibandingkan subspesies harimau lainnya.\nTeks 2: Harimau merupakan hewan karnivora pemakan daging yang berada di puncak rantai makanan.\n\nPerbedaan fokus isi dari kedua teks tersebut adalah...", "o": ["Teks 1 membahas klasifikasi umum, Teks 2 membahas habitat asli.", "Teks 1 merupakan deskripsi bagian fisik, Teks 2 merupakan pernyataan umum (definisi).", "Teks 1 adalah simpulan, Teks 2 adalah langkah-langkah observasi.", "Teks 1 bersifat subjektif, Teks 2 bersifat opini pribadi."], "a": 1, "p": "Teks 1 merinci ciri fisik khusus (deskripsi bagian), sedangkan Teks 2 mendefinisikan harimau secara umum dalam kelompoknya (pernyataan/definisi umum)."}, {"lv": 3, "q": "Mengapa dalam menulis teks laporan hasil observasi penulis dilarang memasukkan unsur opini pribadi yang bersifat subyektif pada bagian isi?", "o": ["Agar teks menjadi lebih panjang dan menarik dibaca", "Karena laporan harus menyajikan data faktual berdasarkan pengamatan nyata, bukan khayalan", "Agar pembaca tidak memahami isi teks dengan mudah", "Karena opini pribadi hanya boleh ditulis dalam bentuk puisi"], "a": 1, "p": "Laporan observasi bersifat ilmiah dan objektif, sehingga seluruh informasi harus murni berdasarkan fakta di lapangan tanpa campur tangan opini penulis."}, {"lv": 3, "q": "Manakah susunan paragraf yang paling tepat untuk membentuk struktur teks laporan hasil observasi yang runtut mengenai 'Bunga Rosella'?", "o": ["(1) Manfaat rosella; (2) Definisi umum rosella; (3) Ciri fisik batang dan bunga.", "(1) Definisi umum rosella; (2) Ciri fisik batang dan kelopak bunga; (3) Manfaat kesehatan dari rosella.", "(1) Kesimpulan penelitian; (2) Definisi umum; (3) Langkah penanaman rosella.", "(1) Pendapat penulis tentang rosella; (2) Cerita asal-usul rosella; (3) Penutup."], "a": 1, "p": "Susunan runtut teks LHO dimulai dari pengenalan/definisi umum objek, diikuti rincian bagian-bagiannya (deskripsi bagian), lalu diakhiri dengan manfaat."}]}, {"id": "bin-k10-1", "name": "Teks negosiasi", "desc": "Orientasi, pengajuan, penawaran, persetujuan", "idx": 1, "soal": [{"lv": 1, "q": "Tujuan utama dari pembuatan teks negosiasi adalah...", "o": ["Menceritakan kisah hidup seseorang secara kronologis", "Mencapai kesepakatan bersama yang menguntungkan kedua belah pihak", "Menjelaskan langkah-langkah membuat suatu produk", "Menggambarkan suatu objek secara rinci dan objektif"], "a": 1, "p": "Teks negosiasi bertujuan untuk menyelesaikan perbedaan atau mencapai kesepakatan yang disetujui bersama oleh pihak-pihak yang berinteraksi."}, {"lv": 1, "q": "Bagian awal dalam struktur teks negosiasi yang biasanya berisi salam pembuka dan pembawaan topik disebut...", "o": ["Persetujuan", "Penawaran", "Orientasi", "Pengajuan"], "a": 2, "p": "Orientasi adalah bagian awal untuk memulai percakapan negosiasi, seperti salam, tegur sapa, atau pembuka pembicaraan."}, {"lv": 1, "q": "Dalam proses jual beli, pihak pembeli biasanya menyampaikan permintaan terhadap suatu barang atau jasa pada tahap...", "o": ["Pengajuan", "Persetujuan", "Penutup", "Penolakan"], "a": 0, "p": "Tahap pengajuan adalah saat salah satu pihak (misal pembeli) mengutarakan maksud atau barang yang diinginkan kepada pihak lain."}, {"lv": 1, "q": "Proses tawar-menawar harga atau fasilitas antara penjual dan pembeli terjadi pada bagian struktur...", "o": ["Orientasi", "Penawaran", "Persetujuan", "Penutup"], "a": 1, "p": "Penawaran merupakan inti dari negosiasi di mana kedua belah pihak saling tawar-menawar harga atau syarat hingga tercapai titik temu."}, {"lv": 2, "q": "Perhatikan kutipan teks negosiasi berikut:\nPenjual: \"Jaket kulit ini harganya Rp300.000, Mas. Sudah paling murah itu.\"\nPembeli: \"Wah, mahal banget, Bang. Rp200.000 ya, saya ambil sekarang.\"\n\nBagian struktur yang ditunjukkan oleh kutipan tersebut adalah...", "o": ["Orientasi", "Pengajuan", "Penawaran", "Persetujuan"], "a": 2, "p": "Percakapan tersebut menunjukkan proses tawar-menawar harga antara penjual dan pembeli, yang merupakan bagian dari penawaran."}, {"lv": 2, "q": "Kalimat manakah yang paling santun dan sesuai digunakan untuk melakukan pengajuan dalam kegiatan negosiasi jual beli?", "o": ["Cepat turunkan harga baju ini atau saya tidak jadi beli!", "Permisi, Kak, apakah harga tas ini bisa dikurangi sedikit?", "Saya memaksa Anda untuk memberikan diskon 50 persen sekarang.", "Kenapa barang di toko ini mahal sekali, tidak masuk akal!"], "a": 1, "p": "Negosiasi harus dilakukan dengan santun. Pilihan B menggunakan bahasa yang sopan untuk meminta pengurangan harga."}, {"lv": 2, "q": "Perhatikan kutipan berikut:\n\"Baiklah, Bu. Saya setuju dengan harga Rp250.000 untuk dua buku ini. Besok saya ambil barangnya.\"\n\nStruktur teks negosiasi yang tepat untuk kutipan tersebut adalah...", "o": ["Persetujuan", "Penawaran", "Pengajuan", "Orientasi"], "a": 0, "p": "Pernyataan 'Saya setuju' menandakan bahwa kedua belah pihak telah mencapai kesepakatan, yang masuk dalam struktur persetujuan."}, {"lv": 2, "q": "Ciri kebahasaan yang sering muncul dalam teks negosiasi berkaitan dengan sikap kedua belah pihak adalah...", "o": ["Menggunakan bahasa kiasan dan majas retoris", "Menggunakan kalimat perintah yang keras", "Menggunakan bahasa yang santun, persuasif, dan saling menghargai", "Menggunakan banyak istilah ilmiah kedokteran"], "a": 2, "p": "Agar negosiasi berhasil, bahasa yang digunakan harus santun, bersifat membujuk (persuasif), serta menunjukkan kesepahaman."}, {"lv": 3, "q": "Bacalah kutipan negosiasi berikut:\nPembeli: \"Bisa kurang sedikit, Bang? Rp150.000 ya?\"\nPenjual: \"Wah, kalau harga segitu belum dapat, Mas. Modalnya saja sudah Rp170.000. Bagaimana kalau Rp185.000? Itu sudah pas.\"\n\nTaktik atau strategi penawaran yang digunakan oleh penjual dalam dialog tersebut adalah...", "o": ["Menolak langsung tanpa memberikan alasan yang jelas", "Memberikan alasan berdasarkan modal dan menawarkan harga alternatif", "Memaksa pembeli untuk membeli dengan harga awal", "Mengalihkan pembicaraan ke barang lain yang lebih mahal"], "a": 1, "p": "Penjual menolak harga pembeli dengan memberikan argumen logis (modal barang) serta mengajukan angka kompromi (Rp185.000)."}, {"lv": 3, "q": "Manakah susunan struktur teks negosiasi yang paling runtut dan logis?", "o": ["Penawaran - Persetujuan - Orientasi - Pengajuan", "Orientasi - Pengajuan - Penawaran - Persetujuan", "Persetujuan - Penawaran - Pengajuan - Orientasi", "Pengajuan - Orientasi - Persetujuan - Penawaran"], "a": 1, "p": "Urutan struktur negosiasi yang benar dimulai dari pembuka/salam (orientasi), permintaan (pengajuan), tawar-menawar (penawaran), hingga tercapai kesepakatan (persetujuan)."}, {"lv": 3, "q": "Sebuah negosiasi jual beli antara pengusaha dan pihak bank mengalami jalan buntu (deadlock) karena tidak ada titik temu mengenai suku bunga pinjaman. Hal ini menunjukkan bahwa...", "o": ["Negosiasi tersebut sukses menghasilkan keuntungan besar", "Kedua belah pihak gagal mencapai kesepakatan karena mempertahankan kepentingan masing-masing", "Struktur teks negosiasi tidak memerlukan bagian persetujuan", "Pihak bank tidak berhak melakukan tawar-menawar"], "a": 1, "p": "Kegagalan negosiasi (deadlock) terjadi ketika kompromi tidak tercapai karena masing-masing pihak tidak mau mengalah atau sepakat."}, {"lv": 3, "q": "Perhatikan kalimat berikut: 'Meskipun harga yang Anda tawarkan cukup tinggi, kami bersedia membelinya jika kualitas bahan kain ini dijamin tahan lama.'\n\nFungsi kalimat tersebut dalam teks negosiasi adalah...", "o": ["Mengajukan syarat atau kompromi untuk mencapai kesepakatan", "Menolak mentah-mentah penawaran penjual", "Memulai percakapan dengan salam pembuka", "Menutup proses negosiasi secara permanen"], "a": 0, "p": "Kalimat tersebut menunjukkan bentuk kompromi bersyarat, di mana pembeli bersedia menaikkan pertimbangan harga asal ada jaminan kualitas."}]}, {"id": "bin-k10-2", "name": "Hikayat", "desc": "Ciri dan nilai hikayat", "idx": 2, "soal": [{"lv": 1, "q": "Hikayat adalah salah satu bentuk karya sastra lama Melayu berbentuk prosa yang memuat kisah mengenai...", "o": ["Kehidupan sehari-hari masyarakat modern perkotaan", "Tokoh-tokoh sakti, istana, atau keajaiban", "Langkah-langkah melakukan eksperimen ilmiah", "Data statistik kependudukan suatu negara"], "a": 1, "p": "Hikayat umumnya menceritakan kisah istana sentris, kepahlawanan, serta tokoh-tokoh yang memiliki kesaktian atau keajaiban."}, {"lv": 1, "q": "Salah satu ciri kebahasaan yang paling menonjol dan sering ditemukan pada awal kalimat dalam teks hikayat adalah...", "o": ["Penggunaan kata-kata ilmiah modern", "Penggunaan konjungsi antarkalimat seperti 'maka' dan 'syahdan'", "Penggunaan kalimat perintah dan larangan", "Penggunaan singkatan gaul masa kini"], "a": 1, "p": "Hikayat sangat identik dengan penggunaan kata arkais atau konjungsi masa lampau seperti 'maka', 'syahdan', 'alkisah', dan 'hatta'."}, {"lv": 1, "q": "Sifat penceritaan dalam hikayat yang tidak diketahui siapa pengarang aslinya disebut...", "o": ["Modern", "Biografis", "Anonim", "Objektif"], "a": 2, "p": "Sebagian besar karya sastra lama termasuk hikayat bersifat anonim (tanpa nama pengarang) karena disebarkan secara lisan turun-temurun."}, {"lv": 1, "q": "Nilai dalam hikayat yang berkaitan dengan hubungan manusia dengan Sang Pencipta (agama) disebut nilai...", "o": ["Nilai moral", "Nilai sosial", "Nilai religius", "Nilai budaya"], "a": 2, "p": "Nilai religius berhubungan dengan ajaran agama, keyakinan, dan kepatuhan manusia terhadap perintah Tuhan."}, {"lv": 2, "q": "Perhatikan kutipan berikut: 'Maka pada suatu hari, raja menyuruh orang memanggil seluruh peramal negeri untuk menafsirkan mimpi permaisuri.'\n\nCiri hikayat yang dominan dalam kutipan tersebut adalah...", "o": ["Bersifat istana sentris", "Menggunakan alur mundur", "Bersifat logis dan realistis", "Menggunakan latar tempat di kota modern"], "a": 0, "p": "Istana sentris berarti cerita berpusat pada kehidupan kerajaan, raja, permaisuri, dan lingkungan istana."}, {"lv": 2, "q": "Perhatikan kutipan hikayat berikut: 'Syahdan, maka anak raja itu pun bertitah kepada hulubalangnya agar segera menyiapkan pasukan panah sakti.'\n\nArti kata arkais 'syahdan' dalam kutipan tersebut adalah...", "o": ["Kemudian atau selanjutnya", "Meskipun demikian", "Oleh karena itu", "Sementara itu"], "a": 0, "p": "Kata 'syahdan' merupakan kata arkais dalam sastra Melayu klasik yang berarti 'kemudian' atau 'ceritanya bermula'."}, {"lv": 2, "q": "Perhatikan kutipan hikayat berikut: 'Maka anak raja itu pun dibekali dengan pedang bermata dua dan jubah tembus pandang oleh sang pertapa.'\n\nUnsur kemustahilan yang terkandung dalam kutipan tersebut adalah...", "o": ["Raja yang memiliki banyak anak", "Penggunaan pedang dalam pertempuran", "Jubah yang membuat pemakainya tembus pandang", "Pertapa yang tinggal di dalam hutan"], "a": 2, "p": "Kemustahilan atau hal yang tidak masuk akal (alogis) dalam hikayat ditunjukkan oleh adanya jubah sakti yang membuat tembus pandang."}, {"lv": 2, "q": "Nilai yang berkaitan dengan tata krama, sopan santun, atau perbuatan baik dan buruk antartokoh dalam hikayat disebut nilai...", "o": ["Nilai edukasi", "Nilai moral", "Nilai estetika", "Nilai politik"], "a": 1, "p": "Nilai moral berkaitan dengan budi pekerti, perilaku, serta ukuran baik dan buruk tindakan seseorang."}, {"lv": 3, "q": "Bacalah kutipan hikayat berikut: 'Maka baginda Sultan pun murka mendengar sembah patihnya. Tanpa berpikir panjang, beliau langsung menjatuhkan hukuman buang ke hutan belantara kepada sang menteri setia tanpa melalui pengadilan.'\n\nNilai moral yang terkandung dalam sikap Sultan tersebut menunjukkan pelanggaran terhadap...", "o": ["Kepatuhan beragama", "Keadilan dan kebijaksanaan pemimpin", "Tata krama makan di istana", "Tradisi turun-temurun kerajaan"], "a": 1, "p": "Sultan bertindak gegabah tanpa adil, yang bertentangan dengan nilai moral kepemimpinan yang bijaksana."}, {"lv": 3, "q": "Dalam sebuah hikayat dikisahkan seorang pemuda miskin menolong nenek tua renta yang ternyata adalah seorang peri sakti, lalu ia diberi kantong emas. Nilai sosial-budaya yang tersirat dari kisah tersebut adalah...", "o": ["Pentingnya memiliki kekayaan materi sejak lahir", "Budaya saling menolong dan berbuat baik kepada sesama manusia", "Larangan berbicara dengan orang asing di hutan", "Keharusan menjadi bangsawan untuk mendapat bantuan"], "a": 1, "p": "Tindakan menolong tanpa pamrih mencerminkan nilai sosial tentang pentingnya tolong-menolong dalam kehidupan bermasyarakat."}, {"lv": 3, "q": "Perhatikan kutipan berikut: 'Hatta, maka berkat doa sang nakhoda yang ikhlas, kapal besar itu pun selamat sampai di pelabuhan meskipun dihantam badai dahsyat.'\n\nNilai religius dalam kutipan tersebut tercermin dari...", "o": ["Kecanggihan teknologi pembuatan kapal", "Kekuatan fisik nakhoda menghadapi badai", "Keyakinan dan doa kepada Tuhan dalam menghadapi musibah", "Bantuan dari pedagang asing di pelabuhan"], "a": 2, "p": "Nilai religius terlihat dari kepasrahan dan permohonan doa kepada Sang Pencipta saat menghadapi kesulitan."}, {"lv": 3, "q": "Apa perbedaan utama antara unsur kemustahilan (fantasi) dalam hikayat dengan cerita fantasi modern?", "o": ["Hikayat tidak memiliki latar tempat sama sekali", "Kemustahilan dalam hikayat sering kali dianggap sebagai hal yang benar-benar terjadi dalam tradisi masyarakat lama, sedangkan fantasi modern disadari sepenuhnya sebagai karya imajinatif", "Cerita fantasi modern selalu menggunakan bahasa Melayu klasik", "Hikayat ditulis oleh penulis terkenal abad 21"], "a": 1, "p": "Pada masa sastra lama, hal-hal sakti atau istana dalam hikayat sering kali diterima masyarakat sebagai bagian dari realitas mistis mereka, berbeda dengan fiksi modern."}]}], "11": [{"id": "bin-k11-0", "name": "Teks prosedur kompleks", "desc": "Langkah dan kalimat imperatif", "idx": 0, "soal": [{"lv": 1, "q": "Teks prosedur kompleks bertujuan untuk ...", "o": ["menceritakan pengalaman pribadi penulis", "memberikan langkah-langkah melakukan sesuatu secara rinci dan berurutan", "meyakinkan pembaca tentang suatu pendapat", "menggambarkan suatu objek secara detail"], "a": 1, "p": "Teks prosedur kompleks berisi langkah-langkah rinci dan berurutan untuk melakukan suatu kegiatan, misalnya cara membuat paspor."}, {"lv": 1, "q": "Bagian teks prosedur yang berisi pengantar atau gambaran umum kegiatan disebut ...", "o": ["tujuan", "langkah-langkah", "penegasan ulang", "simpulan"], "a": 0, "p": "Struktur teks prosedur: tujuan (pengantar), langkah-langkah, dan penutup (opsional)."}, {"lv": 1, "q": "Kalimat yang paling banyak digunakan dalam teks prosedur adalah kalimat ...", "o": ["tanya", "seru", "perintah (imperatif)", "berita tentang masa lalu"], "a": 2, "p": "Teks prosedur memakai kalimat imperatif karena berisi petunjuk yang harus dilakukan pembaca."}, {"lv": 1, "q": "Kata yang menunjukkan urutan waktu dalam teks prosedur adalah ...", "o": ["namun", "kemudian", "karena", "meskipun"], "a": 1, "p": "\"Kemudian\" adalah konjungsi temporal yang menunjukkan urutan langkah."}, {"lv": 2, "q": "Perhatikan kalimat: \"Isilah formulir pendaftaran dengan huruf kapital.\" Kata kerja imperatif dalam kalimat tersebut adalah ...", "o": ["formulir", "pendaftaran", "isilah", "kapital"], "a": 2, "p": "Kata \"isilah\" adalah verba imperatif (kata kerja perintah) dengan partikel -lah."}, {"lv": 2, "q": "Manakah yang BUKAN ciri kebahasaan teks prosedur kompleks?", "o": ["menggunakan kalimat perintah", "menggunakan konjungsi temporal", "menggunakan kata kerja material", "menggunakan banyak kata ganti orang pertama untuk bercerita"], "a": 3, "p": "Teks prosedur tidak bercerita tentang pengalaman, sehingga tidak didominasi kata ganti orang pertama."}, {"lv": 2, "q": "\"Pastikan semua berkas sudah difotokopi ____ Anda menyerahkannya ke petugas.\" Konjungsi yang tepat adalah ...", "o": ["sebelum", "sehingga", "tetapi", "atau"], "a": 0, "p": "Berkas difotokopi lebih dulu, baru diserahkan, jadi konjungsi temporal yang tepat adalah \"sebelum\"."}, {"lv": 2, "q": "Kata kerja material adalah kata kerja yang menunjukkan perbuatan fisik. Contohnya adalah ...", "o": ["memikirkan", "menimbang", "merasakan", "menyadari"], "a": 1, "p": "\"Menimbang\" adalah perbuatan fisik yang bisa dilihat. Kata lain menunjukkan proses mental."}, {"lv": 3, "q": "Langkah membuat SIM: (1) mengikuti ujian teori, (2) membayar biaya di loket, (3) mengikuti ujian praktik, (4) mengisi formulir dan tes kesehatan. Urutan yang logis adalah ...", "o": ["1-2-3-4", "4-2-1-3", "2-1-4-3", "4-3-2-1"], "a": 1, "p": "Formulir dan tes kesehatan dulu, lalu bayar, kemudian ujian teori, terakhir ujian praktik: 4-2-1-3."}, {"lv": 3, "q": "Perbedaan utama teks prosedur kompleks dengan teks prosedur sederhana adalah ...", "o": ["teks prosedur kompleks tidak memiliki tujuan", "teks prosedur kompleks memiliki langkah yang lebih banyak, rinci, dan sering disertai langkah alternatif atau syarat", "teks prosedur sederhana selalu lebih panjang", "teks prosedur sederhana tidak memakai kalimat perintah"], "a": 1, "p": "Prosedur kompleks memuat banyak langkah yang rinci, kadang bercabang (jika ... maka ...), dan disertai syarat."}, {"lv": 3, "q": "\"Jika berkas Anda belum lengkap, petugas akan mengembalikannya.\" Kalimat ini dalam teks prosedur berfungsi sebagai ...", "o": ["langkah utama yang wajib dikerjakan", "keterangan syarat atau akibat dari suatu langkah", "tujuan teks", "judul teks"], "a": 1, "p": "Kalimat bersyarat (jika ...) menjelaskan syarat/akibat yang perlu diperhatikan pembaca."}, {"lv": 3, "q": "Kalimat imperatif yang paling santun untuk teks prosedur resmi adalah ...", "o": ["Isi formulir itu cepat!", "Kamu harus isi formulir.", "Silakan mengisi formulir yang telah disediakan.", "Formulir diisi atau tidak, terserah."], "a": 2, "p": "Kata \"silakan\" membuat perintah terasa santun dan sesuai untuk teks resmi."}]}, {"id": "bin-k11-1", "name": "Teks eksplanasi kompleks", "desc": "Hubungan sebab-akibat", "idx": 1, "soal": [{"lv": 1, "q": "Teks eksplanasi bertujuan untuk ...", "o": ["menjelaskan proses terjadinya suatu fenomena", "mengajak pembaca melakukan sesuatu", "menceritakan kisah fiksi", "memberi petunjuk memasak"], "a": 0, "p": "Teks eksplanasi menjelaskan bagaimana dan mengapa suatu fenomena (alam/sosial) terjadi."}, {"lv": 1, "q": "Struktur teks eksplanasi yang benar adalah ...", "o": ["orientasi – komplikasi – resolusi", "identifikasi fenomena – rangkaian kejadian – ulasan", "tesis – argumen – penegasan ulang", "pembuka – isi – salam penutup"], "a": 1, "p": "Struktur eksplanasi: identifikasi fenomena, rangkaian kejadian (sebab-akibat), dan ulasan (interpretasi)."}, {"lv": 1, "q": "Konjungsi yang sering muncul dalam teks eksplanasi untuk menyatakan sebab-akibat adalah ...", "o": ["dan, atau", "karena, sehingga", "namun, tetapi", "seperti, bagaikan"], "a": 1, "p": "Teks eksplanasi banyak memakai konjungsi kausalitas: karena, sebab, sehingga, akibatnya."}, {"lv": 1, "q": "Contoh judul teks eksplanasi adalah ...", "o": ["Cara Membuat Nasi Goreng", "Proses Terjadinya Tsunami", "Liburanku ke Bali", "Ayo Buang Sampah pada Tempatnya"], "a": 1, "p": "\"Proses Terjadinya Tsunami\" menjelaskan fenomena alam beserta prosesnya."}, {"lv": 2, "q": "\"Hujan deras turun selama tiga hari, ____ sungai meluap dan merendam permukiman.\" Konjungsi yang tepat adalah ...", "o": ["meskipun", "akibatnya", "sebelum", "bahkan jika"], "a": 1, "p": "Sungai meluap adalah akibat hujan deras, jadi konjungsi yang tepat \"akibatnya\"."}, {"lv": 2, "q": "Bagian ulasan dalam teks eksplanasi berisi ...", "o": ["daftar alat dan bahan", "komentar atau simpulan penulis tentang fenomena", "dialog antartokoh", "langkah-langkah percobaan"], "a": 1, "p": "Ulasan berisi tanggapan, simpulan, atau saran penulis terhadap fenomena yang dijelaskan."}, {"lv": 2, "q": "Istilah teknis \"episentrum\" dalam teks eksplanasi gempa bumi berarti ...", "o": ["pusat gempa di dalam bumi", "titik di permukaan bumi tepat di atas pusat gempa", "alat pengukur gempa", "gelombang laut akibat gempa"], "a": 1, "p": "Episentrum adalah titik di permukaan bumi tepat di atas hiposentrum (pusat gempa di dalam bumi)."}, {"lv": 2, "q": "Ciri kebahasaan teks eksplanasi yang benar adalah ...", "o": ["banyak menggunakan kalimat perintah", "menggunakan kata kerja pasif dan istilah teknis", "menggunakan kata ganti aku dan kamu", "menggunakan majas yang berlebihan"], "a": 1, "p": "Teks eksplanasi bersifat ilmiah, banyak memakai istilah teknis dan kalimat pasif."}, {"lv": 3, "q": "Rangkaian: (1) suhu muka laut naik, (2) uap air berkumpul membentuk awan cumulonimbus, (3) terjadi hujan lebat disertai angin kencang, (4) penguapan air laut meningkat. Urutan kausal yang benar adalah ...", "o": ["1-4-2-3", "4-1-3-2", "2-3-1-4", "1-2-4-3"], "a": 0, "p": "Suhu naik → penguapan meningkat → awan terbentuk → hujan lebat: 1-4-2-3."}, {"lv": 3, "q": "Hubungan antarkalimat \"Hutan ditebang secara liar. Daerah resapan air berkurang. Banjir bandang melanda desa.\" adalah ...", "o": ["kronologis tanpa hubungan sebab", "sebab-akibat berantai (kausalitas)", "perbandingan", "pertentangan"], "a": 1, "p": "Penebangan menyebabkan resapan berkurang, yang kemudian menyebabkan banjir: rantai sebab-akibat."}, {"lv": 3, "q": "Teks eksplanasi kompleks berbeda dari teks eksplanasi biasa karena ...", "o": ["hanya menjelaskan satu sebab saja", "menjelaskan banyak faktor penyebab dan akibat yang saling berkaitan secara rinci", "tidak memiliki struktur", "ditulis dalam bentuk puisi"], "a": 1, "p": "Eksplanasi kompleks menguraikan banyak faktor dan hubungan sebab-akibat yang saling berkait."}, {"lv": 3, "q": "Kalimat yang paling tepat sebagai identifikasi fenomena teks eksplanasi tentang pemanasan global adalah ...", "o": ["Ayo kurangi pemakaian plastik mulai hari ini!", "Pemanasan global adalah meningkatnya suhu rata-rata atmosfer, laut, dan daratan bumi.", "Kemarin saya merasa udara sangat panas.", "Pertama, siapkan termometer dan catat suhunya."], "a": 1, "p": "Identifikasi fenomena memperkenalkan fenomena secara umum dan objektif, biasanya berupa definisi."}]}, {"id": "bin-k11-2", "name": "Drama", "desc": "Unsur dan dialog drama", "idx": 2, "soal": [{"lv": 1, "q": "Percakapan antartokoh dalam drama disebut ...", "o": ["prolog", "dialog", "epilog", "monolog"], "a": 1, "p": "Dialog adalah percakapan antara dua tokoh atau lebih; ini unsur utama naskah drama."}, {"lv": 1, "q": "Petunjuk dalam naskah drama yang menjelaskan gerak, ekspresi, atau suasana disebut ...", "o": ["babak", "prolog", "kramagung (petunjuk lakuan)", "amanat"], "a": 2, "p": "Kramagung atau petunjuk lakuan biasanya ditulis dalam kurung, misalnya (berjalan sambil menunduk)."}, {"lv": 1, "q": "Bagian pembuka sebuah pertunjukan drama yang berisi pengantar cerita disebut ...", "o": ["epilog", "prolog", "klimaks", "dialog"], "a": 1, "p": "Prolog adalah bagian pembuka yang mengantarkan penonton pada cerita."}, {"lv": 1, "q": "Tokoh yang menjadi lawan atau penentang tokoh utama disebut ...", "o": ["protagonis", "antagonis", "tritagonis", "figuran"], "a": 1, "p": "Antagonis adalah tokoh penentang protagonis; tritagonis adalah tokoh penengah."}, {"lv": 2, "q": "Tahapan alur drama ketika konflik mencapai puncak ketegangan disebut ...", "o": ["eksposisi", "komplikasi", "klimaks", "resolusi"], "a": 2, "p": "Klimaks adalah puncak konflik; setelahnya ada resolusi (penyelesaian)."}, {"lv": 2, "q": "Ibu: \"Sudah berapa kali Ibu bilang, jangan pulang larut malam!\" (membanting pintu). Watak Ibu yang tergambar adalah ...", "o": ["sabar dan lembut", "marah dan tegas", "sedih dan putus asa", "gembira"], "a": 1, "p": "Kalimat bernada keras dan tindakan membanting pintu menunjukkan Ibu sedang marah dan tegas."}, {"lv": 2, "q": "Tokoh yang berada di pihak tengah dan sering menjadi penengah konflik disebut ...", "o": ["protagonis", "antagonis", "tritagonis", "deuteragonis"], "a": 2, "p": "Tritagonis adalah tokoh penengah atau pendamai antara protagonis dan antagonis."}, {"lv": 2, "q": "Pernyataan yang benar tentang unsur latar dalam drama adalah ...", "o": ["latar hanya berupa tempat", "latar meliputi tempat, waktu, dan suasana", "latar adalah pesan moral cerita", "latar sama dengan tokoh"], "a": 1, "p": "Latar mencakup tempat, waktu, dan suasana terjadinya peristiwa."}, {"lv": 3, "q": "Andi: \"Aku tidak mencuri uang itu, Pak!\" Pak Guru: \"Lalu kenapa dompetnya ada di tasmu?\" Andi: (menunduk, suaranya bergetar) \"Saya... saya dijebak.\" Konflik yang tampak dalam penggalan ini adalah ...", "o": ["konflik batin Pak Guru", "konflik antara Andi dan Pak Guru tentang tuduhan pencurian", "konflik Andi dengan alam", "tidak ada konflik"], "a": 1, "p": "Konflik terjadi antartokoh: Pak Guru menuduh, Andi membantah. Ini konflik eksternal (manusia dengan manusia)."}, {"lv": 3, "q": "Amanat yang paling sesuai untuk drama tentang anak yang menyesal karena berbohong kepada orang tuanya adalah ...", "o": ["Kebohongan selalu membawa keuntungan.", "Kejujuran itu penting karena kebohongan dapat merusak kepercayaan.", "Orang tua tidak perlu dihormati.", "Lebih baik diam daripada berbicara."], "a": 1, "p": "Penyesalan tokoh menunjukkan pesan bahwa kejujuran penting dan kebohongan merugikan."}, {"lv": 3, "q": "Dalam naskah: \"(Panggung gelap. Terdengar suara hujan dan petir. Lampu menyorot seorang lelaki tua yang duduk sendirian.)\" Fungsi bagian ini adalah ...", "o": ["menunjukkan dialog tokoh", "memberi petunjuk pementasan tentang suasana dan latar", "menyampaikan amanat secara langsung", "menjadi epilog cerita"], "a": 1, "p": "Teks dalam kurung adalah petunjuk pementasan yang membangun latar dan suasana muram."}, {"lv": 3, "q": "Perbedaan monolog dan dialog dalam drama adalah ...", "o": ["monolog diucapkan satu tokoh kepada dirinya sendiri atau penonton, dialog melibatkan dua tokoh atau lebih", "monolog selalu di akhir cerita, dialog di awal", "monolog ditulis dalam kurung, dialog tidak", "keduanya sama saja"], "a": 0, "p": "Monolog adalah ujaran seorang tokoh (sering mengungkap isi hati), sedangkan dialog adalah percakapan antartokoh."}]}], "12": [{"id": "bin-k12-0", "name": "Surat lamaran kerja", "desc": "Bagian dan bahasa surat lamaran", "idx": 0, "soal": [{"lv": 1, "q": "Surat lamaran kerja termasuk jenis surat ...", "o": ["pribadi", "resmi", "niaga untuk penawaran", "undangan"], "a": 1, "p": "Surat lamaran kerja adalah surat resmi karena ditujukan kepada instansi atau perusahaan."}, {"lv": 1, "q": "Salam pembuka yang tepat dalam surat lamaran kerja adalah ...", "o": ["Hai, Pak!", "Dengan hormat,", "Halo semuanya,", "Salam sayang,"], "a": 1, "p": "Surat resmi menggunakan salam pembuka \"Dengan hormat,\"."}, {"lv": 1, "q": "Bagian surat lamaran yang berisi daftar dokumen pendukung disebut ...", "o": ["kop surat", "lampiran", "perihal", "tanda tangan"], "a": 1, "p": "Lampiran menyebutkan dokumen yang disertakan, misalnya fotokopi ijazah dan daftar riwayat hidup."}, {"lv": 1, "q": "Informasi lowongan kerja yang dilamar biasanya dicantumkan pada bagian ...", "o": ["pembuka isi surat", "tanda tangan", "alamat pengirim", "salam penutup"], "a": 0, "p": "Paragraf pembuka biasanya menyebut sumber informasi lowongan dan posisi yang dilamar."}, {"lv": 2, "q": "Kalimat pembuka isi surat lamaran yang paling tepat adalah ...", "o": ["Saya mau kerja di perusahaan Bapak.", "Berdasarkan iklan di harian Kompas tanggal 10 Mei 2026, saya bermaksud melamar posisi staf administrasi.", "Tolong terima saya bekerja.", "Perusahaan Bapak sangat bagus sekali banget."], "a": 1, "p": "Kalimat ini resmi, jelas menyebut sumber informasi dan posisi yang dilamar."}, {"lv": 2, "q": "Penulisan perihal surat yang benar adalah ...", "o": ["Perihal: lamaran pekerjaan!", "Perihal: Lamaran Pekerjaan", "perihal : LAMARAN KERJA ????", "Hal = lamaran"], "a": 1, "p": "Perihal ditulis singkat, setiap kata diawali huruf kapital, tanpa tanda seru atau tanya."}, {"lv": 2, "q": "Kalimat penutup surat lamaran yang santun adalah ...", "o": ["Saya tunggu jawabannya cepat ya.", "Atas perhatian Bapak/Ibu, saya ucapkan terima kasih.", "Kalau tidak diterima juga tidak apa-apa.", "Sekian dan sampai jumpa!"], "a": 1, "p": "Penutup surat resmi menyampaikan terima kasih dengan santun."}, {"lv": 2, "q": "Kata yang tidak baku dan harus diperbaiki dalam surat lamaran adalah ...", "o": ["ijazah", "fotokopi", "sertifikat", "praktek"], "a": 3, "p": "Bentuk baku menurut KBBI adalah \"praktik\", bukan \"praktek\"."}, {"lv": 3, "q": "Manakah kalimat surat lamaran yang paling efektif?", "o": ["Bersama surat ini saya yang bertanda tangan di bawah ini, saya mengajukan lamaran.", "Dengan ini, saya mengajukan lamaran untuk posisi desainer grafis.", "Saya ingin untuk melamar pekerjaan yang mana adalah sebagai desainer.", "Adapun daripada lamaran ini adalah untuk posisi desainer."], "a": 1, "p": "Kalimat B ringkas, tidak berulang (bukan \"saya ... saya\"), dan tidak memakai kata mubazir seperti \"yang mana\" atau \"daripada\"."}, {"lv": 3, "q": "Kelebihan diri yang tepat dicantumkan dalam surat lamaran untuk posisi kasir adalah ...", "o": ["Saya hobi bermain gim daring.", "Saya teliti dalam menghitung, jujur, dan terbiasa menggunakan komputer.", "Saya suka tidur siang.", "Saya punya banyak pengikut di media sosial."], "a": 1, "p": "Kelebihan yang ditulis harus relevan dengan pekerjaan: ketelitian, kejujuran, dan kemampuan komputer cocok untuk kasir."}, {"lv": 3, "q": "Urutan bagian surat lamaran yang benar adalah ...", "o": ["salam pembuka – tempat dan tanggal – isi – tanda tangan", "tempat dan tanggal – lampiran dan perihal – alamat tujuan – salam pembuka – isi – salam penutup – tanda tangan", "isi – salam pembuka – alamat tujuan – tanda tangan", "tanda tangan – perihal – isi – salam pembuka"], "a": 1, "p": "Urutan umum: tempat/tanggal, lampiran & perihal, alamat tujuan, salam pembuka, isi, salam penutup, tanda tangan dan nama."}, {"lv": 3, "q": "Perbedaan daftar riwayat hidup (CV) dan surat lamaran adalah ...", "o": ["CV berisi data diri, pendidikan, dan pengalaman secara rinci, sedangkan surat lamaran berisi permohonan bekerja", "CV adalah surat pribadi, surat lamaran adalah surat niaga", "Surat lamaran tidak perlu ditandatangani", "Keduanya tidak perlu disertakan"], "a": 0, "p": "Surat lamaran menyatakan permohonan; CV melampirkan data diri dan riwayat secara rinci."}]}, {"id": "bin-k12-1", "name": "Teks editorial", "desc": "Opini, fakta, dan argumen", "idx": 1, "soal": [{"lv": 1, "q": "Teks editorial adalah ...", "o": ["cerita fiksi di surat kabar", "artikel opini redaksi tentang isu aktual", "iklan produk", "berita olahraga"], "a": 1, "p": "Editorial (tajuk rencana) berisi pendapat redaksi media tentang isu yang sedang hangat."}, {"lv": 1, "q": "Struktur teks editorial adalah ...", "o": ["orientasi – komplikasi – resolusi", "pernyataan pendapat (tesis) – argumentasi – penegasan ulang", "tujuan – langkah – penutup", "identifikasi – deskripsi – simpulan"], "a": 1, "p": "Editorial tersusun atas tesis, argumen, dan penegasan ulang pendapat."}, {"lv": 1, "q": "Nama lain teks editorial adalah ...", "o": ["tajuk rencana", "cerpen", "resensi", "biografi"], "a": 0, "p": "Teks editorial juga disebut tajuk rencana."}, {"lv": 1, "q": "Isu yang cocok diangkat dalam teks editorial adalah ...", "o": ["dongeng Malin Kundang", "kenaikan harga bahan pokok menjelang hari raya", "resep kue lebaran", "pengalaman liburan penulis"], "a": 1, "p": "Editorial membahas isu aktual yang menyangkut kepentingan publik."}, {"lv": 2, "q": "Kalimat yang berupa FAKTA adalah ...", "o": ["Kebijakan ini sangat merugikan rakyat kecil.", "Pemerintah menaikkan harga BBM sebesar 10% pada 1 Mei 2026.", "Seharusnya pemerintah lebih bijak.", "Kenaikan ini tidak masuk akal."], "a": 1, "p": "Fakta bisa dibuktikan (angka, tanggal). Kalimat lain adalah opini atau penilaian."}, {"lv": 2, "q": "Kalimat yang berupa OPINI adalah ...", "o": ["Jumlah penduduk Indonesia lebih dari 270 juta jiwa.", "Banjir merendam 300 rumah di Kecamatan X.", "Pemerintah daerah tampaknya lamban menangani banjir.", "Hujan turun sejak pukul 02.00 WIB."], "a": 2, "p": "\"Tampaknya lamban\" adalah penilaian subjektif, sehingga termasuk opini."}, {"lv": 2, "q": "Bagian penegasan ulang dalam editorial berisi ...", "o": ["data statistik baru", "penguatan kembali pendapat redaksi, sering disertai saran atau harapan", "daftar pustaka", "kronologi kejadian secara rinci"], "a": 1, "p": "Penegasan ulang menegaskan kembali sikap redaksi dan biasanya ditutup dengan saran atau rekomendasi."}, {"lv": 2, "q": "Ciri kebahasaan teks editorial adalah ...", "o": ["banyak menggunakan kata rujukan waktu lampau dan tokoh rekaan", "menggunakan kata kerja mental, kata ganti penunjuk, dan konjungsi kausalitas", "menggunakan kalimat perintah berurutan", "menggunakan majas bombastis"], "a": 1, "p": "Editorial memakai verba mental (menduga, menyimpulkan), kata rujukan (ini, itu), dan konjungsi sebab-akibat untuk berargumen."}, {"lv": 3, "q": "\"Program makan siang gratis patut didukung. Data menunjukkan 1 dari 5 anak berangkat sekolah tanpa sarapan. Anak yang kenyang lebih mudah berkonsentrasi.\" Kalimat kedua berfungsi sebagai ...", "o": ["tesis", "argumen berupa data pendukung", "penegasan ulang", "judul"], "a": 1, "p": "Kalimat kedua memberikan data untuk mendukung pendapat (tesis) pada kalimat pertama."}, {"lv": 3, "q": "Sikap redaksi dalam kalimat \"Sudah saatnya pemerintah berhenti sekadar berjanji dan mulai bertindak nyata mengatasi polusi udara.\" adalah ...", "o": ["mendukung penuh kinerja pemerintah", "mengkritik dan mendesak pemerintah", "netral tanpa pendapat", "tidak peduli"], "a": 1, "p": "Ungkapan \"berhenti sekadar berjanji\" menunjukkan kritik, dan \"sudah saatnya ... bertindak\" adalah desakan."}, {"lv": 3, "q": "Argumen yang paling kuat untuk mendukung tesis \"Penggunaan plastik sekali pakai perlu dibatasi\" adalah ...", "o": ["Plastik warnanya bagus.", "Menurut KLHK, Indonesia menghasilkan jutaan ton sampah plastik per tahun dan sebagian besar tidak terolah.", "Banyak orang suka belanja.", "Plastik lebih ringan daripada kertas."], "a": 1, "p": "Argumen kuat didukung data dari sumber tepercaya dan relevan dengan tesis."}, {"lv": 3, "q": "Perbedaan teks editorial dengan teks berita adalah ...", "o": ["editorial berisi opini redaksi, berita menyajikan fakta peristiwa secara objektif", "berita berisi opini, editorial berisi fakta saja", "editorial tidak terbit di media massa", "keduanya sama-sama fiksi"], "a": 0, "p": "Berita melaporkan fakta 5W+1H secara objektif; editorial menyampaikan sikap/opini redaksi atas isu."}]}, {"id": "bin-k12-2", "name": "Novel", "desc": "Unsur intrinsik dan ekstrinsik novel", "idx": 2, "soal": [{"lv": 1, "q": "Novel termasuk jenis karya sastra ...", "o": ["puisi", "prosa", "drama", "pantun"], "a": 1, "p": "Novel adalah prosa fiksi yang panjang dan kompleks."}, {"lv": 1, "q": "Unsur intrinsik novel adalah unsur yang membangun cerita dari ...", "o": ["luar karya", "dalam karya", "latar belakang pengarang", "kondisi masyarakat"], "a": 1, "p": "Unsur intrinsik berasal dari dalam karya: tema, tokoh, alur, latar, sudut pandang, gaya bahasa, amanat."}, {"lv": 1, "q": "Gagasan pokok yang mendasari sebuah novel disebut ...", "o": ["alur", "tema", "latar", "penokohan"], "a": 1, "p": "Tema adalah gagasan utama atau ide pokok cerita."}, {"lv": 1, "q": "Yang termasuk unsur ekstrinsik novel adalah ...", "o": ["tokoh dan penokohan", "alur cerita", "latar belakang kehidupan pengarang", "sudut pandang"], "a": 2, "p": "Unsur ekstrinsik berasal dari luar karya, seperti biografi pengarang dan nilai sosial budaya."}, {"lv": 2, "q": "\"Aku tidak pernah menyangka hari itu akan mengubah hidupku.\" Sudut pandang yang digunakan adalah ...", "o": ["orang pertama pelaku utama", "orang ketiga serba tahu", "orang kedua", "orang ketiga terbatas"], "a": 0, "p": "Penggunaan \"aku\" sebagai pelaku menunjukkan sudut pandang orang pertama."}, {"lv": 2, "q": "Alur yang menceritakan peristiwa masa kini lalu kembali ke masa lalu disebut alur ...", "o": ["maju", "mundur (flashback)", "lurus", "tunggal"], "a": 1, "p": "Alur mundur atau sorot balik menceritakan peristiwa masa lalu setelah peristiwa masa kini."}, {"lv": 2, "q": "\"Bu Rahma selalu menyisihkan sebagian gajinya untuk membiayai sekolah anak-anak tetangganya yang kurang mampu.\" Watak Bu Rahma adalah ...", "o": ["sombong", "dermawan", "pemarah", "pemalas"], "a": 1, "p": "Membiayai sekolah anak orang lain menunjukkan watak dermawan. Watak ini digambarkan lewat tindakan tokoh."}, {"lv": 2, "q": "Nilai yang berkaitan dengan adat istiadat dan kebiasaan masyarakat dalam novel disebut nilai ...", "o": ["religius", "budaya", "ekonomi", "politik"], "a": 1, "p": "Nilai budaya berkaitan dengan adat, tradisi, dan kebiasaan masyarakat."}, {"lv": 3, "q": "\"Matahari belum tinggi ketika Laila menyusuri pematang sawah. Embun masih menggantung di ujung daun padi, dan suara azan Subuh baru saja reda.\" Latar waktu dalam kutipan ini adalah ...", "o": ["siang hari", "pagi hari setelah Subuh", "sore hari", "tengah malam"], "a": 1, "p": "Petunjuk \"matahari belum tinggi\", \"embun\", dan \"azan Subuh baru saja reda\" menunjukkan pagi hari."}, {"lv": 3, "q": "Teknik penokohan dramatik (tidak langsung) contohnya adalah ...", "o": ["\"Pak Darto adalah orang yang pelit.\"", "\"Pak Darto selalu menolak meminjamkan apa pun, bahkan sebatang korek api.\"", "\"Pak Darto memiliki sifat pelit sejak kecil.\"", "\"Pengarang menggambarkan Pak Darto sebagai orang pelit.\""], "a": 1, "p": "Penokohan dramatik menunjukkan watak lewat tindakan, bukan pernyataan langsung."}, {"lv": 3, "q": "Perbedaan novel dengan cerpen yang paling tepat adalah ...", "o": ["novel lebih pendek dari cerpen", "novel memiliki konflik yang lebih kompleks, tokoh lebih banyak, dan alur yang dapat bercabang", "cerpen selalu memiliki banyak tokoh utama", "novel tidak memiliki tema"], "a": 1, "p": "Novel lebih panjang, konfliknya kompleks, tokohnya banyak, dan sering memiliki alur sampingan."}, {"lv": 3, "q": "Novel yang ditulis pengarang yang lama tinggal di daerah konflik dan menceritakan penderitaan pengungsi menunjukkan keterkaitan unsur ...", "o": ["intrinsik tema dengan alur", "ekstrinsik (latar belakang pengarang) dengan isi cerita", "sudut pandang dengan gaya bahasa", "amanat dengan judul"], "a": 1, "p": "Pengalaman hidup pengarang adalah unsur ekstrinsik yang memengaruhi isi cerita."}]}], "2": [{"id": "bin-k2-0", "name": "Kata sifat", "desc": "Kata yang menerangkan sifat benda", "idx": 0, "soal": [{"lv": 1, "q": "Benda yang permukaannya tidak kasar disebut memiliki sifat...", "o": ["halus", "keras", "tajam", "panas"], "a": 0, "p": "Benda yang tidak kasar permukaannya disebut halus."}, {"lv": 1, "q": "Gula pasir memiliki rasa yang...", "o": ["pahit", "manis", "asam", "asin"], "a": 1, "p": "Gula pasir adalah contoh benda yang rasanya manis."}, {"lv": 1, "q": "Batu adalah benda yang memiliki sifat...", "o": ["empuk", "cair", "keras", "lembut"], "a": 2, "p": "Batu terasa keras jika dipegang."}, {"lv": 1, "q": "Air es di dalam gelas terasa...", "o": ["panas", "hangat", "dingin", "pedas"], "a": 2, "p": "Air es bersuhu rendah sehingga terasa dingin."}, {"lv": 2, "q": "Buku tulis dan pensil adalah contoh benda yang memiliki sifat...", "o": ["kering", "basah", "cair", "panas"], "a": 0, "p": "Buku tulis dan pensil yang tidak terkena air bersifat kering."}, {"lv": 2, "q": "Ibu mencuci baju. Baju yang baru dicuci itu terasa...", "o": ["kering", "basah", "keras", "manis"], "a": 1, "p": "Baju yang baru dicuci dan belum dijemur mengandung air sehingga basah."}, {"lv": 2, "q": "Kain kapas sangat ringan dan mudah ditekan hingga empuk. Sifat kapas adalah...", "o": ["keras", "berat", "lembut", "tajam"], "a": 2, "p": "Kapas adalah benda yang bertekstur lembut."}, {"lv": 2, "q": "Lantai kamar mandi yang terkena air sabun sering kali terasa...", "o": ["kesat", "licin", "kasar", "keras"], "a": 1, "p": "Air sabun membuat permukaan lantai menjadi licin."}, {"lv": 3, "q": "Adik mengambil jeruk nipis di dapur lalu mencicipinya. Rasa jeruk nipis tersebut adalah...", "o": ["manis", "asin", "pahit", "asam"], "a": 3, "p": "Jeruk nipis memiliki sifat rasa yang asam."}, {"lv": 3, "q": "Ayah baru saja menyeduh kopi hitam tanpa gula. Saat diminum, kopi tersebut terasa...", "o": ["pahit", "manis", "asam", "asin"], "a": 0, "p": "Kopi hitam tanpa gula memiliki sifat rasa pahit."}, {"lv": 3, "q": "Bibi merebus air di atas kompor hingga mendidih. Saat dipegang, pancinya terasa...", "o": ["dingin", "panas", "sejuk", "basah"], "a": 1, "p": "Air yang mendidih membuat panci menjadi panas."}, {"lv": 3, "q": "Ibu membuatkan teh hangat untuk ayah. Kata yang menunjukkan sifat air teh tersebut adalah...", "o": ["dingin", "pahit", "hangat", "asin"], "a": 2, "p": "Teh buatan ibu bersuhu tidak terlalu panas, melainkan hangat."}]}, {"id": "bin-k2-1", "name": "Tanda baca", "desc": "Titik, koma, dan tanda tanya", "idx": 1, "soal": [{"lv": 1, "q": "Tanda baca apa yang selalu diletakkan di akhir kalimat berita atau pernyataan?", "o": ["Tanda titik", "Tanda koma", "Tanda tanya", "Tanda seru"], "a": 0, "p": "Kalimat berita atau pernyataan diakhiri dengan tanda titik (.) untuk menunjukkan akhir dari kalimat tersebut."}, {"lv": 1, "q": "Manakah kalimat di bawah ini yang menggunakan tanda titik (.) dengan benar di akhir kalimat?", "o": ["Ibu pergi ke pasar?", "Budi bermain bola.", "Adik minum susu,", "Halo, nama saya Ani"], "a": 1, "p": "Kalimat 'Budi bermain bola.' adalah kalimat berita yang diakhiri dengan tanda titik."}, {"lv": 1, "q": "Tanda baca yang digunakan untuk menanyakan sesuatu adalah...", "o": ["Tanda titik", "Tanda koma", "Tanda tanya", "Tanda hubung"], "a": 2, "p": "Tanda tanya (?) digunakan pada akhir kalimat tanya, seperti ketika ingin menanyakan sesuatu."}, {"lv": 1, "q": "Di mana tanda tanya (?) harus diletakkan dalam sebuah kalimat?", "o": ["Di awal kalimat", "Di tengah kalimat", "Di akhir kalimat tanya", "Di antara kata"], "a": 2, "p": "Tanda tanya selalu diletakkan di bagian paling akhir dari sebuah kalimat tanya."}, {"lv": 2, "q": "Ibu membeli buah jeruk, apel, dan mangga di toko. Tanda baca yang dipakai untuk memisahkan rincian buah tersebut adalah...", "o": ["Tanda titik", "Tanda koma", "Tanda tanya", "Tanda hubung"], "a": 1, "p": "Tanda koma (,) digunakan untuk merinci atau memisahkan kata-kata dalam satu kalimat, seperti jeruk, apel, dan mangga."}, {"lv": 2, "q": "Manakah penulisan kalimat tanya yang menggunakan tanda baca dengan benar?", "o": ["Kapan kamu pulang ke rumah.", "Di mana rumahmu?", "Siapa nama guru itu,", "Berapa umurmu."], "a": 1, "p": "Kalimat 'Di mana rumahmu?' adalah kalimat tanya yang diakhiri dengan tanda tanya (?) dengan benar."}, {"lv": 2, "q": "Perhatikan kalimat berikut: 'Ani, Siti, dan Roni sedang belajar bersama.' Fungsi tanda koma pada kalimat tersebut adalah untuk...", "o": ["Mengakhiri kalimat", "Menanyakan sesuatu", "Memisahkan nama-nama orang yang disebut lebih dari satu", "Memulai kalimat baru"], "a": 2, "p": "Tanda koma digunakan untuk merinci atau memisahkan beberapa nama orang, benda, atau kegiatan dalam satu kalimat."}, {"lv": 2, "q": "Kalimat manakah yang memerlukan tanda tanya (?) di akhir kalimatnya?", "o": ["Kucing itu sedang tidur di sofa.", "Mengapa kamu menangis tadi pagi", "Buku itu sangat tebal sekali.", "Kami pergi ke kebun binatang."], "a": 1, "p": "Kalimat 'Mengapa kamu menangis tadi pagi' adalah kalimat tanya yang menanyakan alasan, sehingga harus diakhiri tanda tanya."}, {"lv": 3, "q": "Pilihlah kalimat yang menggunakan tanda titik (.) dan tanda koma (,) dengan tepat!", "o": ["Di dalam tas ada buku, pensil dan penghapus.", "Ayah membaca koran, ibu memasak di dapur.", "Hari ini cuaca sangat cerah,", "adik bermain boneka di kamar."], "a": 1, "p": "Kalimat 'Ayah membaca koran, ibu memasak di dapur.' menggunakan tanda koma untuk memisahkan dua kalimat setara dan tanda titik di akhir."}, {"lv": 3, "q": "Manakah paragraf pendek dengan penggunaan tanda baca yang paling tepat?", "o": ["Hari sudah sore. Anak-anak bermain di lapangan. Siapa yang mau ikut?", "Kapan kamu datang? Budi membawa kue, permen dan susu.", "Ibu pergi ke pasar. Membeli sayur bayam, ikan, dan tahu?", "Di mana letak sekolahmu. Ani berjalan kaki ke sana."], "a": 0, "p": "Pilihan A menggunakan tanda titik di akhir kalimat berita dan tanda tanya di akhir kalimat tanya dengan tepat."}, {"lv": 3, "q": "Perhatikan kalimat berikut: 'Apa warna kesukaanmu, merah, biru, atau hijau?' Mengapa kalimat tersebut menggunakan tanda koma dan tanda tanya?", "o": ["Karena berisi perintah untuk mewarnai", "Karena menanyakan pilihan warna sekaligus merincinya", "Karena kalimat tersebut adalah cerita pendek", "Karena kalimat itu diakhiri dengan tanda titik"], "a": 1, "p": "Kalimat tersebut adalah kalimat tanya yang berisi rincian pilihan, sehingga memakai tanda koma untuk merinci dan tanda tanya di akhir."}, {"lv": 3, "q": "Perbaikan yang tepat untuk kalimat 'mengapa roni tidak masuk sekolah?' adalah...", "o": ["Mengapa, roni tidak masuk sekolah?", "Mengapa roni tidak masuk sekolah.", "Mengapa Roni tidak masuk sekolah?", "Mengapa roni. Tidak masuk sekolah?"], "a": 2, "p": "Awal nama orang ('Roni') harus ditulis dengan huruf kapital dan kalimat tanya harus diakhiri dengan tanda tanya (?)."}]}, {"id": "bin-k2-2", "name": "Memahami cerita pendek", "desc": "Tokoh dan isi cerita", "idx": 2, "soal": [{"lv": 1, "q": "Budi membawa payung saat hujan turun. Siapa yang membawa payung?", "o": ["Ani", "Budi", "Siti", "Doni"], "a": 1, "p": "Tokoh yang membawa payung dalam cerita adalah Budi."}, {"lv": 1, "q": "Ibu membelikan Riko sebuah bola baru. Apa yang dibeli Ibu untuk Riko?", "o": ["Boneka", "Tas", "Bola", "Buku"], "a": 2, "p": "Ibu membelikan Riko sebuah bola baru."}, {"lv": 1, "q": "Kancil berlari dengan cepat di dalam hutan. Hewan apa yang berlari di dalam hutan?", "o": ["Kancil", "Kucing", "Ayam", "Bebek"], "a": 0, "p": "Hewan yang ada di dalam cerita adalah Kancil."}, {"lv": 1, "q": "Keluarga Ani makan malam bersama di ruang makan. Di mana mereka makan malam?", "o": ["Dapur", "Kamar tidur", "Ruang tamu", "Ruang makan"], "a": 3, "p": "Keluarga Ani makan malam di ruang makan."}, {"lv": 2, "q": "Lina menyiram bunga di halaman setiap sore. Mengapa Lina pergi ke halaman?", "o": ["Menyiram bunga", "Bermain bola", "Membaca buku", "Menangkap kupu-kupu"], "a": 0, "p": "Lina pergi ke halaman untuk menyiram bunga."}, {"lv": 2, "q": "Pak Tani pergi ke sawah membawa cangkul saat pagi hari. Kapan Pak Tani pergi ke sawah?", "o": ["Malam hari", "Pagi hari", "Sore hari", "Siang hari"], "a": 1, "p": "Pak Tani pergi ke sawah pada pagi hari."}, {"lv": 2, "q": "Siti kehilangan kucing kesayangannya. Siti merasa sedih dan menangis. Bagaimana perasaan Siti?", "o": ["Senang", "Gembira", "Sedih", "Marah"], "a": 2, "p": "Siti merasa sedih karena kehilangan kucing kesayangannya."}, {"lv": 2, "q": "Doni rajin belajar setiap malam sebelum tidur. Apa yang dilakukan Doni setiap malam?", "o": ["Bermain", "Tidur", "Makan", "Belajar"], "a": 3, "p": "Doni rajin belajar setiap malam."}, {"lv": 3, "q": "Nina melihat seekor kucing kecil kedinginan di teras rumah. Nina segera mengambil selimut hangat dan memberikan makanan. Sifat Nina adalah...", "o": ["Sombong", "Penyayang", "Pemalas", "Pemberani"], "a": 1, "p": "Nina memiliki sifat penyayang karena menolong kucing yang kedinginan."}, {"lv": 3, "q": "Randi ingin membeli mainan baru, tetapi uang tabungannya belum cukup. Randi lalu memutuskan untuk terus menabung. Apa isi cerita tersebut?", "o": ["Randi langsung membeli mainan mahal", "Randi berhenti menabung", "Randi menabung agar uangnya cukup", "Randi meminta uang kepada ibu"], "a": 2, "p": "Isi cerita menunjukkan Randi memilih untuk menabung agar uangnya cukup membeli mainan."}, {"lv": 3, "q": "Dewi dan Tina mendapat tugas kelompok membuat prakarya dari kertas. Mereka bekerja sama dengan baik sehingga tugas selesai cepat. Siapa saja tokoh dalam cerita?", "o": ["Dewi dan Tina", "Ibu dan Ayah", "Riko dan Doni", "Ani dan Budi"], "a": 0, "p": "Tokoh yang melakukan kerja kelompok dalam cerita adalah Dewi dan Tina."}, {"lv": 3, "q": "Awalnya Rudi tidak suka makan sayur. Setelah ibu menjelaskan manfaatnya, Rudi kini rajin makan sayur setiap hari. Bagaimana perubahan sifat Rudi?", "o": ["Tetap tidak suka sayur", "Menjadi rajin makan sayur", "Suka makan permen", "Tidak mau makan sama sekali"], "a": 1, "p": "Rudi yang tadinya tidak suka sayur kini menjadi rajin makan sayur."}]}], "3": [{"id": "bin-k3-0", "name": "Kata kerja", "desc": "Kata yang menyatakan kegiatan", "idx": 0, "soal": [{"lv": 1, "q": "Apa yang dimaksud dengan kata kerja?", "o": ["Kata yang menyatakan sifat benda", "Kata yang menyatakan kegiatan atau suatu perbuatan", "Kata yang menunjukkan nama tempat", "Kata yang menjelaskan warna"], "a": 1, "p": "Kata kerja adalah kata yang digunakan untuk menyatakan suatu kegiatan atau perbuatan yang dilakukan oleh subjek."}, {"lv": 1, "q": "Manakah di bawah ini yang merupakan contoh kata kerja?", "o": ["Merah", "Cantik", "Membaca", "Tinggi"], "a": 2, "p": "'Membaca' adalah kegiatan yang dilakukan seseorang, sehingga termasuk kata kerja. Merah, cantik, dan tinggi adalah kata sifat."}, {"lv": 1, "q": "Ibu sedang ... sayur di dapur. Kata kerja yang tepat untuk melengkapi kalimat tersebut adalah...", "o": ["memasak", "menulis", "berlari", "membaca"], "a": 0, "p": "Kegiatan yang dilakukan di dapur berkaitan dengan makanan adalah 'memasak'."}, {"lv": 1, "q": "Perhatikan kalimat berikut: 'Budi menendang bola ke arah gawang.' Kata kerja dalam kalimat tersebut adalah...", "o": ["Budi", "bola", "menendang", "gawang"], "a": 2, "p": "Kata 'menendang' adalah kata yang menyatakan suatu tindakan atau kegiatan yang dilakukan Budi."}, {"lv": 2, "q": "Ani meminjam buku cerita di perpustakaan. Kata dasar dari kata kerja 'meminjam' adalah...", "o": ["pinjaman", "pinjam", "meminjamkan", "peminjam"], "a": 1, "p": "Kata kerja 'meminjam' berawalan 'me-' dengan kata dasar 'pinjam'."}, {"lv": 2, "q": "Manakah kelompok kata di bawah ini yang semuanya merupakan kata kerja?", "o": ["Menulis, sapu, indah", "Makan, tidur, berjalan", "Besar, rajin, pintar", "Kursi, pensil, meja"], "a": 1, "p": "Makan, tidur, dan berjalan adalah kata-kata yang menyatakan suatu kegiatan (kata kerja)."}, {"lv": 2, "q": "Ayah membaca koran di teras rumah. Imbuhan pada kata kerja 'membaca' adalah...", "o": ["me-", "mem-", "men-", "membe-"], "a": 0, "p": "Kata 'membaca' berasal dari kata dasar 'baca' yang mendapat awalan 'me-' karena huruf awal 'b' luluh dan berubah menjadi 'm' (me + baca menjadi membaca)."}, {"lv": 2, "q": "Ubahlah kata dasar 'tulis' menjadi kata kerja yang berawalan 'me-' dengan benar!", "o": ["Metulis", "Menulis", "Memtulis", "Mengtulis"], "a": 1, "p": "Kata dasar 'tulis' jika diawali imbuhan me- akan meleburkan huruf 't' menjadi 'n', sehingga menjadi 'menulis'."}, {"lv": 3, "q": "Perhatikan kalimat berikut: 'Pemerintah membangun jembatan baru di desa itu.' Kata kerja transitif dalam kalimat tersebut adalah...", "o": ["Pemerintah", "membangun", "jembatan", "baru"], "a": 1, "p": "Kata kerja transitif adalah kata kerja yang memerlukan objek. Kata 'membangun' memerlukan objek yaitu 'jembatan baru'."}, {"lv": 3, "q": "Manakah kalimat di bawah ini yang menggunakan kata kerja intransitif (tidak memerlukan objek)?", "o": ["Adik menggambar pemandangan.", "Kucing itu tidur di atas sofa.", "Kakak menyiram bunga di taman.", "Ibu membuat kue bolu."], "a": 1, "p": "Kalimat 'Kucing itu tidur di atas sofa' menggunakan kata kerja 'tidur' yang tidak memerlukan objek."}, {"lv": 3, "q": "Sinta menyapu lantai kelas setiap pagi. Jika diubah menjadi bentuk kalimat pasif, kata kerja 'menyapu' akan berubah menjadi...", "o": ["penyapu", "disapu", "tersapu", "menyapukan"], "a": 1, "p": "Kata kerja aktif berawalan 'me-' (menyapu) jika diubah ke kalimat pasif akan berubah menggunakan awalan 'di-' (disapu)."}, {"lv": 3, "q": "Pilihlah kalimat yang memuat kata kerja pasif dengan benar!", "o": ["Buku itu dibaca oleh Rina.", "Rina membaca buku itu.", "Rina sedang membaca di kamar.", "Rina membaca dengan teliti."], "a": 0, "p": "Kalimat 'Buku itu dibaca oleh Rina' menggunakan kata kerja pasif 'dibaca' yang ditandai dengan awalan 'di-'."}]}, {"id": "bin-k3-1", "name": "Huruf kapital", "desc": "Penggunaan huruf kapital", "idx": 1, "soal": [{"lv": 1, "q": "Huruf kapital biasa disebut juga dengan huruf...", "o": ["kecil", "tegak", "besar", "sambung"], "a": 2, "p": "Huruf kapital adalah istilah lain dari huruf besar."}, {"lv": 1, "q": "Manakah huruf yang penulisannya menggunakan huruf kapital?", "o": ["a", "b", "C", "d"], "a": 2, "p": "Huruf 'C' adalah bentuk huruf kapital atau huruf besar."}, {"lv": 1, "q": "Di awal penulisan kalimat, kita wajib menggunakan huruf...", "o": ["kecil", "kapital", "miring", "tebal"], "a": 1, "p": "Setiap kalimat baru harus diawali dengan menggunakan huruf kapital."}, {"lv": 1, "q": "Perhatikan kalimat berikut: 'budi gemar membaca buku.' Huruf yang seharusnya ditulis menggunakan huruf kapital adalah...", "o": ["huruf b pada kata budi", "huruf g pada kata gemar", "huruf m pada kata membaca", "huruf b pada kata buku"], "a": 0, "p": "Kata 'budi' adalah nama orang sekaligus berada di awal kalimat, sehingga huruf 'b' harus kapital menjadi 'Budi'."}, {"lv": 2, "q": "Nama bulan dan nama hari harus diawali dengan huruf...", "o": ["kecil", "kapital", "sambung", "angka"], "a": 1, "p": "Unsur nama hari dan nama bulan wajib ditulis dengan huruf kapital di awal katanya."}, {"lv": 2, "q": "Ibu membeli buah di pasar. Kata yang *tidak* perlu menggunakan huruf kapital adalah...", "o": ["Ibu", "pasar", "Semua benar", "Tidak ada yang kapital"], "a": 1, "p": "Kata 'pasar' bukan nama diri atau nama tempat khusus, sehingga ditulis dengan huruf kecil."}, {"lv": 3, "q": "Manakah kalimat di bawah ini yang menunjukkan kesalahan dalam penulisan huruf kapital?", "o": ["Ayah membaca koran setiap hari Minggu.", "Kami merayakan hari kemerdekaan pada bulan Agustus.", "Adik lahir pada hari selasa minggu lalu.", "Budi bersekolah di Sekolah Dasar Merdeka."], "a": 2, "p": "Kata 'selasa' adalah nama hari, sehingga huruf 's' seharusnya ditulis kapital menjadi 'Selasa'."}]}, {"id": "bin-k3-2", "name": "Ide pokok sederhana", "desc": "Menemukan inti bacaan", "idx": 2, "soal": [{"lv": 1, "q": "Apakah yang dimaksud dengan ide pokok dalam sebuah paragraf?", "o": ["Inti atau gagasan utama yang dibahas dalam paragraf", "Kalimat terakhir di dalam cerita", "Jumlah kata yang ada dalam paragraf", "Judul buku cerita"], "a": 0, "p": "Ide pokok adalah inti pembahasan atau gagasan utama yang menjadi dasar pengembangan sebuah paragraf."}, {"lv": 1, "q": "Di manakah letak kalimat utama yang biasanya memuat ide pokok dalam suatu paragraf?", "o": ["Hanya di tengah paragraf", "Selalu di kalimat terakhir saja", "Bisa di awal atau di akhir paragraf", "Di luar paragraf"], "a": 2, "p": "Kalimat utama yang memuat ide pokok dapat terletak di awal paragraf (deduktif) maupun di akhir paragraf (induktif)."}, {"lv": 1, "q": "Bacalah teks berikut!\nKelinci adalah hewan yang sangat lincah. Hewan ini suka melompat-lompat di halaman rumput. Kelinci juga gemar memakan wortel segar.\nApakah ide pokok dari paragraf tersebut?", "o": ["Kelinci suka makan wortel", "Ciri-ciri dan kebiasaan kelinci", "Kelinci tinggal di halaman rumput", "Cara melompat kelinci"], "a": 1, "p": "Paragraf tersebut membahas secara umum tentang kelinci yang lincah, suka melompat, dan gemar makan wortel, yang merangkum ciri-ciri dan kebiasaan kelinci."}, {"lv": 1, "q": "Bacalah teks berikut!\nSiti senang merawat tanaman di pekarangan rumahnya. Setiap sore ia rajin menyiram bunga mawar dan melati. Tanaman Siti tumbuh dengan sangat subur.\nIde pokok paragraf di atas adalah...", "o": ["Siti menyiram tanaman setiap sore", "Tanaman Siti tumbuh subur", "Hobi Siti merawat tanaman", "Bunga mawar dan melati"], "a": 2, "p": "Ide pokok dari paragraf tersebut adalah hobi Siti merawat tanaman yang dijelaskan melalui kegiatan menyiram dan kesuburan tanamannya."}, {"lv": 2, "q": "Bacalah teks berikut!\nOlahraga pagi sangat baik untuk menjaga kesehatan tubuh kita. Dengan berlari kecil atau bersepeda, aliran darah menjadi lancar. Tubuh kita pun tidak mudah terserang penyakit.\nIde pokok bacaan tersebut adalah...", "o": ["Olahraga pagi menjaga kesehatan tubuh", "Manfaat bersepeda bagi aliran darah", "Penyakit yang bisa dicegah dengan olahraga", "Cara melakukan lari kecil di pagi hari"], "a": 0, "p": "Seluruh kalimat penjelas dalam paragraf mendukung gagasan utama bahwa olahraga pagi sangat baik untuk menjaga kesehatan tubuh."}, {"lv": 2, "q": "Bacalah teks berikut!\nBuah pisang memiliki banyak manfaat bagi kesehatan tubuh. Buah ini mengandung vitamin yang baik untuk pencernaan. Selain itu, rasanya yang manis sangat disukai anak-anak.\nIde pokok paragraf di atas adalah...", "o": ["Vitamin dalam buah pisang", "Manfaat buah pisang bagi kesehatan", "Rasa manis buah pisang", "Makanan kesukaan anak-anak"], "a": 1, "p": "Kalimat utama terdapat di awal paragraf yang menyatakan bahwa buah pisang memiliki banyak manfaat bagi kesehatan tubuh."}, {"lv": 2, "q": "Bacalah teks berikut!\nSampah plastik sangat berbahaya jika dibuang sembarangan. Sampah ini tidak dapat membusuk dalam waktu yang cepat. Oleh karena itu, kita harus mengurangi penggunaan kantong plastik.\nIde pokok dari teks tersebut adalah...", "o": ["Cara membuang sampah yang benar", "Waktu pembusukan sampah plastik", "Bahaya dan penanganan sampah plastik", "Manfaat kantong plastik sehari-hari"], "a": 2, "p": "Paragraf tersebut membahas tentang bahaya sampah plastik serta anjuran untuk mengurangi penggunaannya."}, {"lv": 2, "q": "Bacalah teks berikut!\nPohon memiliki banyak fungsi bagi kehidupan di bumi. Akar pohon dapat menyerap air hujan untuk mencegah banjir. Daunnya yang rindang juga menghasilkan udara bersih.\nIde pokok bacaan tersebut adalah...", "o": ["Fungsi pohon bagi kehidupan", "Cara akar menyerap air hujan", "Penyebab terjadinya banjir", "Manfaat daun pohon yang rindang"], "a": 0, "p": "Ide pokok teks tersebut adalah fungsi pohon bagi kehidupan, yang didukung oleh kalimat penjelas tentang akar dan daun pohon."}, {"lv": 3, "q": "Bacalah teks berikut!\nSaat musim hujan tiba, warga Desa Sukamaju selalu bersiap membersihkan saluran air. Gotong royong dilakukan agar aliran air tidak tersumbat. Dengan kerja sama warga, lingkungan desa terhindar dari bencana banjir.\nIde pokok paragraf tersebut adalah...", "o": ["Persiapan warga Desa Sukamaju menghadapi hujan", "Pentingnya gotong royong membersihkan saluran air", "Saluran air yang tersumbat sampah", "Bencana banjir yang sering melanda desa"], "a": 1, "p": "Ide pokok paragraf ini menekankan pada pentingnya gotong royong dalam membersihkan saluran air untuk mencegah banjir."}, {"lv": 3, "q": "Bacalah teks berikut!\nMengonsumsi makanan bergizi sangat penting bagi masa pertumbuhan anak. Makanan seperti sayur, buah, dan ikan membantu perkembangan otak serta tubuh. Oleh karena itu, kita tidak boleh memilih-milih makanan.\nIde pokok bacaan di atas adalah...", "o": ["Akibat suka memilih-milih makanan", "Perkembangan otak anak yang sehat", "Pentingnya mengonsumsi makanan bergizi", "Manfaat ikan dan buah bagi tubuh"], "a": 2, "p": "Gagasan utama paragraf ini terletak di kalimat pertama yang menyatakan pentingnya mengonsumsi makanan bergizi bagi anak."}, {"lv": 3, "q": "Bacalah teks berikut!\nPerpustakaan sekolah selalu ramai dikunjungi siswa saat jam istirahat. Ada yang membaca buku cerita, ada pula yang meminjam buku pelajaran. Suasana yang tenang membuat siswa nyaman belajar di sana.\nIde pokok paragraf tersebut adalah...", "o": ["Suasana perpustakaan sekolah yang ramai dan nyaman", "Siswa yang gemar membaca buku pelajaran", "Aturan ketat di dalam perpustakaan", "Jumlah buku cerita di perpustakaan"], "a": 0, "p": "Paragraf tersebut membahas mengenai kondisi perpustakaan sekolah yang ramai dikunjungi serta suasananya yang nyaman bagi siswa."}, {"lv": 3, "q": "Bacalah teks berikut!\nHewan peliharaan seperti kucing memerlukan perhatian khusus dari pemiliknya. Selain diberi makan dan minum secara teratur, kucing juga harus rutin diperiksa kesehatannya ke dokter hewan. Dengan begitu, hewan peliharaan tetap sehat dan aktif.\nIde pokok paragraf di atas adalah...", "o": ["Cara memilih makanan kucing yang baik", "Perawatan yang tepat untuk hewan peliharaan", "Jadwal pemeriksaan kesehatan kucing", "Alasan kucing menjadi hewan kesayangan"], "a": 1, "p": "Ide pokok paragraf ini merangkum keseluruhan isi teks yaitu pentingnya memberikan perawatan yang tepat (makan, minum, dan kesehatan) bagi hewan peliharaan."}]}], "4": [{"id": "bin-k4-0", "name": "Ide pokok paragraf", "desc": "Kalimat utama dan ide pokok", "idx": 0, "soal": [{"lv": 1, "q": "Apa yang dimaksud dengan ide pokok paragraf?", "o": ["Kalimat terakhir dalam paragraf", "Gagasan atau inti masalah yang dibahas dalam suatu paragraf", "Judul sebuah cerita", "Jumlah kata dalam paragraf"], "a": 1, "p": "Ide pokok adalah gagasan utama, inti sari, atau masalah pokok yang menjadi dasar pengembangan sebuah paragraf."}, {"lv": 1, "q": "Perhatikan paragraf berikut!\nKelinci adalah hewan yang sangat lincah. Hewan ini suka melompat-lompat di halaman rumput. Kelinci juga memiliki telinga yang panjang.\nApakah inti atau ide pokok dari paragraf tersebut?", "o": ["Kelinci suka melompat", "Kelinci memiliki telinga panjang", "Kelinci adalah hewan yang sangat lincah", "Halaman rumput tempat bermain"], "a": 2, "p": "Ide pokok paragraf tersebut terletak di kalimat pertama, yaitu kelinci adalah hewan yang sangat lincah, yang kemudian dijelaskan oleh kalimat-kalimat penjelas di bawahnya."}, {"lv": 1, "q": "Di manakah letak kalimat utama yang memuat ide pokok pada umumnya?", "o": ["Hanya di akhir paragraf", "Hanya di tengah paragraf", "Bisa di awal, di akhir, atau di awal dan akhir paragraf", "Selalu di luar paragraf"], "a": 2, "p": "Kalimat utama yang memuat ide pokok dapat terletak di awal paragraf (deduktif), akhir paragraf (induktif), atau campuran."}, {"lv": 1, "q": "Perhatikan paragraf berikut!\nBuah pisang sangat baik untuk kesehatan tubuh. Buah ini mengandung banyak vitamin. Selain itu, pisang juga mudah dicerna oleh lambung.\nApa ide pokok dari paragraf tersebut?", "o": ["Buah pisang sangat baik untuk kesehatan tubuh", "Buah pisang mudah dicerna lambung", "Pisang mengandung vitamin B", "Cara menanam buah pisang"], "a": 0, "p": "Ide pokok paragraf ini disampaikan di awal kalimat, yakni manfaat buah pisang yang sangat baik untuk kesehatan tubuh."}, {"lv": 2, "q": "Perhatikan paragraf berikut!\n(1) Olahraga secara teratur membuat badan menjadi sehat. (2) Aliran darah di dalam tubuh menjadi lancar. (3) Selain itu, olahraga juga dapat mencegah berbagai macam penyakit berbahaya. (4) Oleh karena itu, kita harus rutin berolahraga setiap minggu.\nKalimat utama dari paragraf tersebut terdapat pada nomor...", "o": ["(1)", "(2)", "(3)", "(4)"], "a": 0, "p": "Kalimat utama terletak di kalimat nomor (1) karena bersifat umum dan menjadi gagasan dasar, sedangkan kalimat (2), (3), dan (4) adalah kalimat penjelas."}, {"lv": 2, "q": "Perhatikan paragraf berikut!\nSampah plastik sangat sulit diurai oleh tanah. Jika dibuang sembarangan, sampah ini dapat mencemari lingkungan. Bahkan, sampah plastik di laut bisa membahayakan hewan air. Maka dari itu, kita harus mengurangi penggunaan plastik.\nIde pokok paragraf tersebut adalah...", "o": ["Sampah plastik di laut yang luas", "Cara membersihkan sampah di tanah", "Bahaya dan sulitnya mengurai sampah plastik", "Hewan air yang menyukai plastik"], "a": 2, "p": "Ide pokok keseluruhan paragraf tersebut membahas mengenai sifat sampah plastik yang sulit diurai serta berbagai bahayanya bagi lingkungan."}, {"lv": 2, "q": "Paragraf yang kalimat utamanya terletak di akhir paragraf disebut paragraf...", "o": ["Deduktif", "Induktif", "Campuran", "Deskriptif"], "a": 1, "p": "Paragraf induktif adalah paragraf yang gagasan utamanya terletak di bagian akhir paragraf."}, {"lv": 2, "q": "Perhatikan paragraf berikut!\nUdara di pegunungan terasa sangat sejuk. Pemandangan hijau sejauh mata memandang. Suasana di sana juga sangat tenang dan jauh dari kebisingan kota. Tidak heran jika banyak wisatawan suka berlibur ke pegunungan.\nIde pokok paragraf di atas adalah...", "o": ["Kebisingan kota yang sangat padat", "Suasana dan kondisi alam di pegunungan", "Perjalanan jauh ke desa", "Wisatawan yang suka merusak alam"], "a": 1, "p": "Seluruh kalimat dalam paragraf tersebut menceritakan tentang suasana, udara, dan kondisi alam yang ada di pegunungan."}, {"lv": 3, "q": "Perhatikan paragraf berikut!\n(1) Membaca adalah jendela dunia untuk menambah wawasan. (2) Dengan membaca buku, kita bisa mengetahui berbagai informasi baru dari seluruh penjuru dunia. (3) Anak yang rajin membaca biasanya memiliki pengetahuan yang luas. (4) Oleh karena itu, mari kita tingkatkan gemar membaca sejak dini.\nIde pokok paragraf tersebut adalah...", "o": ["Pentingnya kegiatan membaca untuk menambah wawasan", "Cara membeli buku di toko", "Informasi dari seluruh penjuru dunia", "Jumlah anak yang rajin membaca"], "a": 0, "p": "Ide pokok paragraf ini merangkum keseluruhan isi teks bahwa membaca sangat penting dilakukan guna memperluas wawasan dan pengetahuan."}, {"lv": 3, "q": "Perhatikan paragraf berikut!\nSiswa kelas IV SD Merdeka sedang melakukan kegiatan bakti sosial di panti asuhan. Mereka membawa sumbangan berupa buku tulis, pakaian layak pakai, dan sembako. Anak-anak panti asuhan menyambut kedatangan mereka dengan penuh ceria. Kegiatan ini melatih siswa untuk memiliki kepedulian sosial yang tinggi.\nGagasan utama dari teks tersebut adalah...", "o": ["Penyambutan anak-anak panti asuhan", "Sumbangan buku dan pakaian layak pakai", "Kegiatan bakti sosial siswa kelas IV SD Merdeka", "Cara menjadi anak yang memiliki kepedulian tinggi"], "a": 2, "p": "Gagasan utama atau inti dari paragraf tersebut adalah kegiatan bakti sosial yang dilakukan oleh siswa kelas IV SD Merdeka."}, {"lv": 3, "q": "Perhatikan paragraf berikut!\nHutan mangrove memiliki peran yang sangat penting bagi wilayah pesisir. Tanaman bakau ini mampu menahan abrasi air laut ke daratan. Selain itu, akar mangrove juga menjadi tempat tinggal bagi berbagai jenis ikan kecil dan kepiting. Kelestarian hutan mangrove harus terus dijaga.\nKalimat utama paragraf tersebut terletak di...", "o": ["Kalimat pertama", "Kalimat kedua", "Kalimat ketiga", "Kalimat keempat"], "a": 0, "p": "Kalimat utama terletak di kalimat pertama ('Hutan mangrove memiliki peran yang sangat penting bagi wilayah pesisir.'), yang kemudian diperjelas oleh kalimat-kalimat berikutnya."}, {"lv": 3, "q": "Perhatikan paragraf berikut!\nKucing adalah hewan mamalia karnivora yang sering dijadikan hewan peliharaan. Bulunya yang lembut dan perilakunya yang manja membuat banyak orang menyukainya. Selain itu, kucing juga sangat lincah dalam menangkap tikus di rumah. Tidak heran jika hewan berbulu ini sangat populer di kalangan masyarakat.\nKesimpulan atau ide pokok yang paling tepat untuk paragraf tersebut adalah...", "o": ["Kucing pemangsa tikus yang ulung", "Kucing sebagai hewan peliharaan yang populer dan disukai", "Ciri-ciri fisik kucing peliharaan", "Alasan kucing menyukai ikan"], "a": 1, "p": "Ide pokok paragraf tersebut mencakup alasan mengapa kucing menjadi hewan peliharaan yang populer dan banyak disukai karena bulunya, tingkahnya, dan manfaatnya."}]}, {"id": "bin-k4-1", "name": "Sinonim dan antonim", "desc": "Persamaan dan lawan kata", "idx": 1, "soal": [{"lv": 1, "q": "Persamaan kata (sinonim) dari kata 'pintar' adalah...", "o": ["Bodoh", "Rajin", "Cerdas", "Malas"], "a": 2, "p": "Sinonim adalah kata yang memiliki arti sama. Kata 'pintar' memiliki arti yang sama dengan 'cerdas'."}, {"lv": 1, "q": "Lawan kata (antonim) dari kata 'besar' adalah...", "o": ["Kecil", "Tinggi", "Luas", "Panjang"], "a": 0, "p": "Antonim adalah kata yang maknanya berlawanan. Lawan kata dari 'besar' adalah 'kecil'."}, {"lv": 1, "q": "Sinonim dari kata 'senang' adalah...", "o": ["Sedih", "Gembira", "Kecewa", "Marah"], "a": 1, "p": "Kata 'senang' memiliki persamaan makna dengan kata 'gembira'."}, {"lv": 1, "q": "Antonim dari kata 'rajin' adalah...", "o": ["Pintar", "Giat", "Tekun", "Malas"], "a": 3, "p": "Lawan kata dari 'rajin' (giat bekerja/belajar) adalah 'malas'."}, {"lv": 2, "q": "Arti kata 'haus' memiliki persamaan dengan kata...", "o": ["Lapar", "Dahaga", "Lelah", "Mengantuk"], "a": 1, "p": "Dalam bahasa Indonesia yang baku, 'haus' bersinonim dengan 'dahaga'."}, {"lv": 2, "q": "Lawan kata yang tepat untuk kata 'panjang' adalah...", "o": ["Pendek", "Rendah", "Kecil", "Sempit"], "a": 0, "p": "Antonim dari 'panjang' adalah 'pendek'. 'Rendah' adalah lawan kata dari 'tinggi'."}, {"lv": 2, "q": "Sinonim dari kata 'berani' dalam sebuah cerita kepahlawanan adalah...", "o": ["Takut", "Gentar", "Gagah", "Pengecut"], "a": 2, "p": "Kata 'berani' memiliki kemiripan makna dengan 'gagah' atau 'perkasa' dalam konteks sifat pahlawan."}, {"lv": 2, "q": "Lawan kata dari kata 'hemat' adalah...", "o": ["Pelit", "Bakhil", "Kikir", "Boros"], "a": 3, "p": "Hemat artinya berhati-hati dalam mengeluarkan uang, lawan katanya adalah 'boros'."}, {"lv": 3, "q": "Ayah pergi ke kantor menggunakan kendaraan umum. Sinonim kata 'kendaraan' dalam kalimat tersebut adalah...", "o": ["Jalan", "Alat angkutan", "Mesin", "Bangunan"], "a": 1, "p": "Kendaraan adalah barang atau benda yang digunakan untuk mengangkut, maka sinonimnya adalah 'alat angkutan'."}, {"lv": 3, "q": "Udara di pegunungan terasa sangat sejuk pada pagi hari. Antonim dari kata 'sejuk' adalah...", "o": ["Dingin", "Hangat", "Segar", "Panas"], "a": 3, "p": "Sejuk berarti terasa dingin dan segar. Lawan kata yang paling tepat dalam konteks suhu adalah 'panas'."}, {"lv": 3, "q": "Di bawah ini, pasangan kata yang memiliki hubungan antonim (lawan kata) adalah...", "o": ["Indah - Molek", "Kuat - Perkasa", "Bising - Tenang", "Cepat - Kilat"], "a": 2, "p": "'Bising' (ramai/gaduh) berlawanan dengan 'tenang' (sunyi/diam). Pilihan lainnya adalah sinonim."}, {"lv": 3, "q": "Sikap pahlawan yang jujur membuat mereka selalu dikenang. Sinonim kata 'jujur' adalah...", "o": ["Amanah", "Curang", "Licik", "Bohong"], "a": 0, "p": "Orang yang jujur dapat dipercaya atau disebut juga 'amanah'. 'Curang' adalah lawan katanya."}]}, {"id": "bin-k4-2", "name": "Puisi anak", "desc": "Isi dan rima puisi", "idx": 2, "soal": [{"lv": 1, "q": "Persamaan bunyi vokal pada akhir baris-baris puisi disebut...", "o": ["Irama", "Rima", "Bait", "Larik"], "a": 1, "p": "Rima adalah pengulangan atau persamaan bunyi vokal pada akhir baris puisi untuk menciptakan keindahan bunyi."}, {"lv": 1, "q": "Kumpulan dari beberapa baris dalam sebuah puisi disebut...", "o": ["Paragraf", "Kalimat", "Bait", "Judul"], "a": 2, "p": "Dalam struktur puisi, baris-baris dikelompokkan menjadi satu kesatuan yang disebut dengan bait."}, {"lv": 1, "q": "Perhatikan kutipan puisi berikut:\n\nBurung berkicau di pagi hari\nMenyambut mentari yang berseri\n\nKata yang memiliki rima yang sama pada puisi di atas adalah...", "o": ["Burung dan pagi", "Menyambut dan mentari", "Hari dan berseri", "Berkicau dan menyambut"], "a": 2, "p": "Kata 'hari' dan 'berseri' memiliki bunyi akhir yang sama, yaitu bunyi 'ri', sehingga keduanya berima sama."}, {"lv": 1, "q": "Puisi yang menceritakan tentang keindahan alam biasanya berisi tentang...", "o": ["Pemandangan gunung atau pantai", "Kegiatan belajar di sekolah", "Rasa sayang pada orang tua", "Cita-cita menjadi dokter"], "a": 0, "p": "Puisi bertema alam fokus pada penggambaran unsur-unsur alam seperti gunung, laut, sawah, atau hutan."}, {"lv": 2, "q": "Buku adalah jendela dunia\nTempat ilmu disimpan rapi\nMembacanya takkan sia-sia\nAgar cerdas di masa nanti\n\nPola rima pada bait puisi di atas adalah...", "o": ["a-a-a-a", "a-a-b-b", "a-b-b-a", "a-b-a-b"], "a": 3, "p": "Baris 1 (dunia) dan 3 (sia-sia) berakhiran 'a'. Baris 2 (rapi) dan 4 (nanti) berakhiran 'i'. Maka polanya adalah silang atau a-b-a-b."}, {"lv": 2, "q": "Ibu, kau adalah pelitaku\nMenerangi jalanku yang gelap\nKasih sayangmu takkan layu\nSelalu ada di setiap lelap\n\nPerasaan yang digambarkan penyair dalam puisi tersebut adalah...", "o": ["Sedih karena ditinggal ibu", "Sayang dan syukur kepada ibu", "Marah karena keadaan gelap", "Takut saat sedang tidur"], "a": 1, "p": "Kata 'pelita' dan ungkapan 'kasih sayang takkan layu' menunjukkan rasa cinta dan terima kasih kepada ibu."}, {"lv": 2, "q": "Lengkapilah baris puisi berikut agar memiliki rima yang serasi!\n\nTerbang tinggi burung camar\nDi antara awan yang ...", "o": ["Putih", "Berpendar", "Indah", "Banyak"], "a": 1, "p": "Kata 'berpendar' memiliki bunyi akhir '-ar' yang sama dengan kata 'camar', sehingga menciptakan rima yang padu."}, {"lv": 2, "q": "Bunyi lonceng memanggilku\nTas di pundak siap melangkah\nGuru sudah menungguku\nDi depan pintu dengan ramah\n\nLatar tempat yang diceritakan dalam puisi tersebut adalah...", "o": ["Di rumah", "Di sekolah", "Di pasar", "Di taman bermain"], "a": 1, "p": "Petunjuk kata 'lonceng', 'tas', 'guru', dan 'pintu (kelas)' sangat kuat menunjukkan latar tempat di sekolah."}, {"lv": 3, "q": "Mentari tersenyum menyapa pagi\nMembangunkan bunga yang masih tertidur\n\nApa maksud dari kalimat 'Mentari tersenyum menyapa pagi' pada puisi di atas?", "o": ["Matahari bisa berbicara dan tertawa", "Matahari terbit dengan cahaya yang indah", "Matahari merasa senang karena pagi telah tiba", "Matahari sedang melihat bunga-bunga"], "a": 1, "p": "Kalimat tersebut adalah personifikasi yang menggambarkan matahari terbit dengan cerah dan indah, seolah-olah memberikan sapaan ramah."}, {"lv": 3, "q": "Hutan gundul menangis sedih\nAir mata berubah jadi banjir\nManusia hanya bisa merintih\nMenyesali hutan yang telah sirna\n\nAmanat atau pesan yang ingin disampaikan penyair dalam puisi tersebut adalah...", "o": ["Banjir adalah peristiwa yang biasa terjadi", "Kita harus menanam pohon hanya saat banjir", "Hutan boleh ditebang asalkan tidak banjir", "Kita harus menjaga kelestarian hutan agar tidak terjadi bencana"], "a": 3, "p": "Puisi ini memperingatkan pembaca tentang dampak buruk penggundulan hutan, sehingga amanatnya adalah menjaga kelestarian alam."}, {"lv": 3, "q": "Kelinciku telinganya panjang\nBulunya putih selembut kapas\nIa melompat sangat senang\nBerlari-lari di padang ...\n\nKata yang tepat untuk melengkapi puisi tersebut agar memiliki pola rima a-b-a-b adalah...", "o": ["Luas", "Hijau", "Besar", "Rumput"], "a": 0, "p": "Untuk rima a-b-a-b, baris ke-4 harus berima sama dengan baris ke-2 (kapas). Kata 'luas' memiliki akhiran bunyi 'as' yang sama dengan 'kapas'."}, {"lv": 3, "q": "Tangan kecilnya memegang sapu\nMembersihkan debu di sepanjang jalan\nTanpa lelah setiap waktu\nDemi kota yang bersih menawan\n\nSiapakah tokoh yang diceritakan dalam puisi di atas?", "o": ["Seorang guru", "Petugas kebersihan", "Anak sekolah", "Polisi lalu lintas"], "a": 1, "p": "Deskripsi menyapu jalan dan menjaga kebersihan kota merupakan ciri khas pekerjaan seorang petugas kebersihan."}]}], "5": [{"id": "bin-k5-0", "name": "Kata baku dan tidak baku", "desc": "Ejaan sesuai KBBI", "idx": 0, "soal": [{"lv": 1, "q": "Bentuk baku dari kata 'apotik' adalah...", "o": ["Apotik", "Apotek", "Apoteq", "Apotiq"], "a": 1, "p": "Kata baku yang sesuai dengan KBBI adalah 'apotek', bukan apotik."}, {"lv": 1, "q": "Manakah penulisan kata baku yang benar di bawah ini?", "o": ["Jadwal", "Jadual", "JDWL", "Jedwal"], "a": 0, "p": "Bentuk baku sesuai KBBI adalah 'jadwal' menggunakan huruf 'w'."}, {"lv": 1, "q": "Kata tidak baku dari 'izin' adalah...", "o": ["Izin", "Ijin", "Permisi", "Restu"], "a": 1, "p": "Bentuk baku adalah 'izin' (dengan huruf z), sedangkan 'ijin' adalah bentuk tidak baku."}, {"lv": 1, "q": "Penulisan kata baku yang tepat untuk kegiatan olahraga adalah...", "o": ["Aktifitas", "Aktif", "Aktivitah", "Aktivitas"], "a": 3, "p": "Bentuk baku sesuai KBBI adalah 'aktivitas' (menggunakan huruf v), bukan aktifitas."}, {"lv": 2, "q": "Ibu membeli obat di...", "o": ["Apotik", "Apotek", "Klinik", "Warung"], "a": 1, "p": "Kata baku yang tepat untuk tempat membeli obat adalah 'apotek'."}, {"lv": 2, "q": "Kalimat yang menggunakan kata baku secara tepat adalah...", "o": ["Siswa itu merubah jadwal pelajaran.", "Siswa itu mengubah jadwal pelajaran.", "Siswa itu merubah jadual pelajaran.", "Siswa itu mengubah jadual pelajaran."], "a": 1, "p": "Kata baku yang benar adalah 'mengubah' (bukan merubah) dan 'jadwal' (bukan jadual)."}, {"lv": 2, "q": "Di bawah ini yang merupakan kelompok kata baku semua adalah...", "o": ["Apotek, ijin, aktif", "Jadual, aktifitas, nasihat", "Kuitansi, apotek, aktivitas", "Sintesa, praktek, analisis"], "a": 2, "p": "Kata baku yang benar adalah kuitansi, apotek, dan aktivitas."}, {"lv": 2, "q": "Bentuk baku dari kata 'praktek' yang sering salah digunakan adalah...", "o": ["Praktik", "Praktek", "Praktekan", "Praktikan"], "a": 0, "p": "Bentuk baku sesuai KBBI adalah 'praktik' (menggunakan huruf i), bukan praktek."}, {"lv": 3, "q": "Perhatikan kalimat berikut: 'Para atlit nasional sedang berlatih di stadion.' Perbaikan kata tidak baku pada kalimat tersebut menjadi kata baku adalah...", "o": ["Atlit diubah menjadi atlet", "Stadion diubah menjadi stedion", "Nasional diubah menjadi nasionil", "Berlatih diubah menjadi berlatif"], "a": 0, "p": "Kata 'atlit' adalah bentuk tidak baku, bentuk baku yang benar sesuai KBBI adalah 'atlet'."}, {"lv": 3, "q": "Manakah kalimat berikut yang seluruh penulisan kosakatanya sudah menggunakan ragam baku?", "o": ["Kwalitet nasihat dokter itu sangat baik sekali.", "Kualitas nasihat dokter itu sangat baik bagi pasien.", "Kualitas nasehat dokter itu sangat baik.", "Kwalitas nasehat dokter itu sangat bagus."], "a": 1, "p": "Kata baku yang tepat dalam kalimat adalah 'kualitas' (bukan kwalitas) dan 'nasihat' (bukan nasehat), serta kalimat efektif."}, {"lv": 3, "q": "Analisis kalimat berikut: 'Sistem transportasi darat mengalami kemajuan pesat.' Kata tidak baku yang sering muncul dalam konteks ilmiah serupa adalah...", "o": ["Sistem", "Zaman", "Analisa", "Transportasi"], "a": 2, "p": "Kata 'analisa' sering digunakan secara tidak baku dalam ragam percakapan, padahal bentuk baku yang benar adalah 'analisis'."}, {"lv": 3, "q": "Kelompok kata di bawah ini yang semuanya merupakan kata baku berdasarkan kaidah bahasa Indonesia adalah...", "o": ["Analisis, kuitansi, apotek, teknik", "Analisa, kwitansi, apotik, tehnik", "Analisis, kwitansi, apotek, tehnik", "Analisa, kuitansi, apotik, teknik"], "a": 0, "p": "Deretan kata baku yang sesuai KBBI adalah 'analisis', 'kuitansi', 'apotek', dan 'teknik'."}]}, {"id": "bin-k5-1", "name": "Teks narasi", "desc": "Alur, tokoh, dan latar", "idx": 1, "soal": [{"lv": 1, "q": "Setiap sore, Rian selalu bermain sepak bola bersama teman-temannya di lapangan desa. Siapa tokoh utama dalam kalimat tersebut?", "o": ["Teman-teman Rian", "Rian", "Kepala desa", "Wasit"], "a": 1, "p": "Tokoh utama yang melakukan kegiatan dalam kalimat tersebut adalah Rian."}, {"lv": 1, "q": "Pagi yang cerah di kebun belakang rumah membuat Siti bersemangat menyiram tanaman bunga. Di mana latar tempat peristiwa tersebut?", "o": ["Di dalam kelas", "Di lapangan desa", "Di kebun belakang rumah", "Di ruang tamu"], "a": 2, "p": "Latar tempat yang disebutkan dalam teks adalah di kebun belakang rumah."}, {"lv": 1, "q": "Matahari mulai terbenam di ufuk barat saat Bayu pulang dari sekolah dengan berjalan kaki. Kapan latar waktu peristiwa tersebut terjadi?", "o": ["Pagi hari", "Siang hari", "Sore hari", "Malam hari"], "a": 2, "p": "Matahari terbenam menandakan latar waktu sore hari."}, {"lv": 1, "q": "Ibu memasak makanan yang lezat di dapur untuk makan malam keluarga. Siapa tokoh yang memasak dalam cerita?", "o": ["Ayah", "Ibu", "Anak", "Nenek"], "a": 1, "p": "Tokoh yang melakukan kegiatan memasak dalam cerita adalah Ibu."}, {"lv": 2, "q": "Fajar berlari sekencang-kencangnya menuju gerbang sekolah karena bel tanda masuk sudah berbunyi. Bagaimana suasana atau perasaan yang digambarkan pada awal cerita?", "o": ["Santai dan tenang", "Gelisah dan terburu-buru", "Sedih dan kecewa", "Senang dan gembira"], "a": 1, "p": "Fajar berlari kencang karena takut terlambat, menggambarkan suasana terburu-buru."}, {"lv": 2, "q": "Meskipun sering diejek karena kalah lomba menggambar, Tika tetap giat berlatih setiap hari hingga akhirnya ia menjadi juara pertama. Watak tokoh Tika dalam cerita tersebut adalah...", "o": ["Mudah menyerah", "Sombong", "Pantang menyerah", "Pemarah"], "a": 2, "p": "Tika tidak putus asa meski diejek dan terus berlatih, menunjukkan watak pantang menyerah."}, {"lv": 2, "q": "Di bawah pohon yang rindang, Andi dan Dodi berdiskusi tentang tugas kelompok ilmu pengetahuan alam. Apa latar tempat dan kegiatan yang dilakukan?", "o": ["Di perpustakaan membaca buku cerita", "Di bawah pohon yang rindang berdiskusi tugas", "Di kelas mengerjakan ulangan matematika", "Di lapangan bermain sepak bola"], "a": 1, "p": "Latar tempatnya di bawah pohon rindang dan kegiatannya berdiskusi tugas kelompok."}, {"lv": 2, "q": "Hujan deras turun mengguyur desa Sukamaju sejak siang hari, membuat aliran sungai di dekat pemukiman meluap. Unsur intrinsik narasi yang menonjol dari kalimat tersebut adalah...", "o": ["Latar waktu", "Latar tempat", "Latar suasana atau alam", "Watak tokoh"], "a": 2, "p": "Hujan deras dan sungai meluap berkaitan dengan latar keadaan alam atau suasana cerita."}, {"lv": 3, "q": "Ani melihat dompet terjatuh di halaman sekolah. Ia segera mengambilnya dan menyerahkan kepada guru piket tanpa mengambil isinya sedikit pun. Watak tokoh Ani adalah...", "o": ["Jujur dan amanah", "Serakah dan sombong", "Pemberani dan ceroboh", "Pemalu dan pendiam"], "a": 0, "p": "Ani mengembalikan dompet yang bukan haknya kepada guru, menunjukkan watak jujur dan amanah."}, {"lv": 3, "q": "Awalnya Dimas enggan meminjamkan pensilnya kepada teman sekelompok karena takut patah. Namun, setelah dinasihati guru, ia sadar dan mau berbagi. Tahapan alur cerita yang menunjukkan perubahan sikap Dimas terdapat pada bagian...", "o": ["Pengenalan tokoh", "Puncak masalah (klimaks)", "Penyelesaian (resolusi)", "Awal cerita"], "a": 2, "p": "Kesadaran tokoh dan perubahan sikap setelah diberi nasihat merupakan bagian penyelesaian atau resolusi masalah."}, {"lv": 3, "q": "Di sebuah desa kecil yang dikelilingi sawah hijau, hiduplah seorang kakek pembuat mainan kayu. Setiap hari ia tersenyum menyambut anak-anak yang datang ke teras rumahnya. Unsur latar tempat yang terdapat dalam kutipan tersebut adalah...", "o": ["Kota metropolitan yang sibuk", "Desa kecil yang dikelilingi sawah hijau", "Pegunungan salju yang dingin", "Pinggir pantai berpasir putih"], "a": 1, "p": "Teks secara jelas menyebutkan latar tempat yaitu di sebuah desa kecil yang dikelilingi sawah hijau."}, {"lv": 3, "q": "Santi sudah berjanji pada ibunya untuk langsung pulang ke rumah sepulang sekolah. Di tengah jalan, ia melihat kucing kecil terluka dan memutuskan membawanya ke klinik hewan, sehingga ia terlambat sampai rumah. Konflik dalam cerita di atas adalah...", "o": ["Santi bertengkar dengan teman sekolahnya", "Santi bingung antara menepati janji pada ibu atau menolong kucing yang terluka", "Santi kehilangan tas sekolah di klinik hewan", "Ibu marah besar karena Santi tidak suka kucing"], "a": 1, "p": "Konflik batin atau permasalahan yang dihadapi tokoh adalah dilema antara menepati janji atau menolong makhluk hidup yang kesusahan."}]}, {"id": "bin-k5-2", "name": "Kalimat efektif", "desc": "Menyusun kalimat yang benar", "idx": 2, "soal": [{"lv": 1, "q": "Kalimat yang hemat kata dan tidak boros disebut kalimat...", "o": ["Kalimat majemuk", "Kalimat efektif", "Kalimat tanya", "Kalimat perintah"], "a": 1, "p": "Kalimat efektif adalah kalimat yang disusun sesuai kaidah serta hemat dan jelas maknanya."}, {"lv": 1, "q": "Manakah ciri utama dari sebuah kalimat efektif?", "o": ["Menggunakan kata-kata yang sangat panjang", "Memiliki arti yang berbelit-belit", "Hemat dalam menggunakan kata", "Menggunakan bahasa asing"], "a": 2, "p": "Salah satu ciri kalimat efektif adalah hemat kata, tidak menggunakan kata-kata yang bermakna ganda atau berlebihan."}, {"lv": 1, "q": "Perhatikan kalimat berikut: 'Budi pergi ke pasar membeli buah.' Kalimat tersebut efektif karena...", "o": ["Mengandung kata yang diulang-ulang", "Memiliki struktur Subjek, Predikat, dan Objek yang jelas", "Menggunakan bahasa daerah", "Tidak memiliki arti yang jelas"], "a": 1, "p": "Kalimat tersebut jelas strukturnya yaitu Budi (S) pergi (P) ke pasar membeli buah (O/K)."}, {"lv": 1, "q": "Manakah di bawah ini yang merupakan contoh penulisan kata depan yang benar dalam kalimat?", "o": ["Ibu pergi ke pasar.", "Ibu pergi kepasar.", "Ibu pergi di pasar.", "Ibu pergi daripasar."], "a": 0, "p": "Kata depan 'ke' ditulis terpisah dari kata yang mengikutinya jika menunjukkan arah atau tempat."}, {"lv": 2, "q": "Perhatikan kalimat tidak efektif berikut: 'Para tamu-tamu undangan sudah berdatangan ke gedung.' Perbaikan kalimat tersebut agar menjadi efektif adalah...", "o": ["Para tamu undangan sudah berdatangan ke gedung.", "Para tamu-tamu sudah berdatangan ke gedung.", "Tamu-tamu undangan pada datang ke gedung.", "Para tamu undangan pada berdatangan."], "a": 0, "p": "Kata 'para' sudah menunjukkan jamak (banyak), jadi tidak perlu mengulang kata 'tamu' menjadi 'tamu-tamu'."}, {"lv": 2, "q": "Kalimat berikut yang tidak boros dan bermakna jelas adalah...", "o": ["Sejak dari pagi hari ia belum makan.", "Sejak pagi hari ia belum makan.", "Dari sejak pagi ia belum makan.", "Sejak dari pagi ia belum makan."], "a": 1, "p": "Kata 'sejak' dan 'dari' memiliki arti yang hampir sama, sehingga penggunaan 'sejak pagi' saja sudah cukup dan hemat."}, {"lv": 2, "q": "Perhatikan kalimat: 'Meskipun hari hujan, tetapi Andi tetap berangkat sekolah.' Agar kalimat tersebut efektif, kata yang harus dihilangkan adalah...", "o": ["Meskipun", "Hari", "Tetapi", "Berangkat"], "a": 2, "p": "Kata 'meskipun' dan 'tetapi' memiliki fungsi yang sama dalam kalimat bertingkat. Cukup gunakan salah satu saja."}, {"lv": 3, "q": "Analisis kalimat berikut: 'Demi untuk mencukupi kebutuhan keluarganya, Pak Ali bekerja keras.' Ketidakefektifan kalimat tersebut disebabkan oleh...", "o": ["Penggunaan subjek ganda", "Penggunaan kata bersinonim secara bersamaan (demi untuk)", "Kesalahan tanda baca titik", "Predikat kalimat tidak jelas"], "a": 1, "p": "Kata 'demi' dan 'untuk' memiliki makna yang sama, sehingga penggunaan keduanya secara bersamaan membuat kalimat menjadi tidak hemat (boros)."}, {"lv": 3, "q": "Manakah perbaikan kalimat tidak efektif berikut yang paling tepat?\nKalimat asal: 'Kepada Bapak Kepala Sekolah, waktu dan tempat kami persilakan.'", "o": ["Kepada Bapak Kepala Sekolah, kami persilakan.", "Bapak Kepala Sekolah, waktu dan tempat dipersilakan.", "Bapak Kepala Sekolah, kami persilakan untuk naik ke podium.", "Waktu dan tempat dipersilakan kepada Bapak Kepala Sekolah."], "a": 2, "p": "Waktu dan tempat tidak bisa dipersilakan; yang dipersilakan adalah orangnya (Bapak Kepala Sekolah)."}, {"lv": 3, "q": "Sebuah kalimat harus memiliki kejelasan unsur Subjek (S) dan Predikat (P). Kalimat di bawah ini yang tidak memiliki subjek yang jelas karena adanya kata depan adalah...", "o": ["Siswa kelas lima belajar kelompok di perpustakaan.", "Di perpustakaan, siswa kelas lima belajar kelompok.", "Bagi siswa kelas lima diwajibkan membawa kamus.", "Ibu guru menerangkan pelajaran bahasa Indonesia."], "a": 2, "p": "Awalan 'Bagi' pada awal kalimat membuat unsur subjek menjadi kabur atau hilang. Seharusnya 'Siswa kelas lima diwajibkan...'."}, {"lv": 3, "q": "Perhatikan paragraf rumpang: '... Rian menyapu halaman, laura mencuci piring.' Konjungsi atau kata hubung antar kalimat yang tepat untuk menggabungkan dua kegiatan yang dilakukan bersamaan adalah...", "o": ["Sedangkan", "Meskipun", "Karena", "Sehingga"], "a": 0, "p": "Kata hubung 'sedangkan' tepat digunakan untuk menyatakan pertentangan atau pembedaan dua kegiatan yang terjadi bersamaan."}]}], "6": [{"id": "bin-k6-0", "name": "Teks eksplanasi", "desc": "Menjelaskan proses terjadinya sesuatu", "idx": 0, "soal": [{"lv": 1, "q": "Teks yang berisi penjelasan mengenai proses terjadinya suatu fenomena alam, sosial, atau budaya disebut...", "o": ["Teks narasi", "Teks deskripsi", "Teks eksplanasi", "Teks persuasi"], "a": 2, "p": "Teks eksplanasi adalah teks yang berfungsi untuk menjelaskan proses terjadinya atau terbentuknya suatu fenomena."}, {"lv": 1, "q": "Bagian awal dari sebuah teks eksplanasi yang berisi pengenalan objek atau fenomena yang akan dibahas disebut...", "o": ["Pernyataan umum", "Deretan penjelas", "Kesimpulan", "Interpretasi"], "a": 0, "p": "Pernyataan umum berisi gambaran awal atau pengenalan tentang topik yang akan dibahas dalam teks eksplanasi."}, {"lv": 1, "q": "Bagian tengah teks eksplanasi yang menjelaskan rincian proses terjadinya suatu peristiwa secara urut dinamakan...", "o": ["Pernyataan umum", "Deretan penjelas", "Abstraksi", "Orientasi"], "a": 1, "p": "Deretan penjelas adalah bagian yang berisi penjelasan detail mengenai proses atau sebab akibat suatu fenomena."}, {"lv": 1, "q": "Bagian akhir teks eksplanasi yang berisi kesimpulan atau tanggapan penulis terhadap fenomena yang dibahas disebut...", "o": ["Klimaks", "Argumentasi", "Interpretasi", "Pernyataan umum"], "a": 2, "p": "Interpretasi merupakan bagian penutup atau kesimpulan yang berisi ulasan atau pandangan penulis."}, {"lv": 2, "q": "Perhatikan topik berikut: 'Proses terjadinya hujan.' Manakah kalimat yang paling tepat untuk mengawali paragraf pernyataan umum teks tersebut?", "o": ["Hujan turun sangat lebat di sore hari kemarin.", "Hujan adalah fenomena alam berupa turunnya titik-titik air dari langit ke bumi.", "Air hujan sangat berguna bagi tanaman di kebun.", "Kita harus menyiapkan payung sebelum hujan turun."], "a": 1, "p": "Pernyataan umum harus mendefinisikan atau mengenalkan fenomena secara umum, yaitu bahwa hujan adalah turunnya titik-titik air."}, {"lv": 2, "q": "Ciri kebahasaan yang sering ditemukan dalam teks eksplanasi untuk menunjukkan hubungan sebab akibat adalah...", "o": ["Kata ganti orang pertama (aku, kami)", "Konjungsi kausalitas (sebab, karena, oleh karena itu)", "Dialog antar tokoh yang interaktif", "Kalimat perintah yang tegas"], "a": 1, "p": "Teks eksplanasi banyak menggunakan konjungsi kausalitas karena menjelaskan proses 'mengapa' dan 'bagaimana' suatu peristiwa terjadi."}, {"lv": 2, "q": "Dalam teks eksplanasi proses pembuatan lampu pijar, informasi yang disajikan harus bersifat...", "o": ["Fiktif atau khayalan", "Subjektif berdasarkan pendapat pribadi", "Faktual berdasarkan ilmu pengetahuan", "Persuasif untuk membujuk pembaca"], "a": 2, "p": "Teks eksplanasi bersifat faktual dan ilmiah karena menjelaskan proses nyata yang terjadi berdasarkan ilmu pengetahuan."}, {"lv": 2, "q": "Urutan deretan penjelas dalam teks eksplanasi tentang 'gempa bumi' biasanya memuat penjelasan mengenai...", "o": ["Pendapat warga tentang gempa", "Penyebab pergerakan lempeng bumi hingga terjadinya getaran", "Nama-nama korban bencana gempa", "Alamat lokasi terjadinya gempa"], "a": 1, "p": "Deretan penjelas menjelaskan proses ilmiah, yaitu bagaimana pergerakan lempeng bumi menimbulkan gempa."}, {"lv": 3, "q": "Analisis kalimat berikut: 'Panas matahari menyebabkan air di permukaan bumi menguap ke udara.' Konjungsi atau kata kerja yang menunjukkan proses sebab akibat dalam kalimat tersebut adalah...", "o": ["Di permukaan", "Menyebabkan", "Ke udara", "Menguap"], "a": 1, "p": "Kata 'menyebabkan' adalah verba kausalitas yang menjelaskan hubungan sebab akibat terjadinya penguapan air."}, {"lv": 3, "q": "Bacalah ilustrasi topik berikut:\n1) Air menguap karena panas matahari.\n2) Terbentuklah awan hitam di langit.\n3) Titik-titik air jatuh sebagai hujan.\n4) Uap air mengalami kondensasi di udara.\n\nUrutan deretan penjelas yang logis dan runtut untuk proses terjadinya hujan adalah...", "o": ["1 - 4 - 2 - 3", "1 - 2 - 4 - 3", "2 - 1 - 4 - 3", "4 - 1 - 2 - 3"], "a": 0, "p": "Urutan logis proses siklus air/hujan: penguapan (1), kondensasi/pendinginan uap air menjadi awan (4), pembentukan awan (2), lalu jatuhnya titik air sebagai hujan (3)."}, {"lv": 3, "q": "Sebuah teks eksplanasi tentang 'global warming' (pemanasan global) tidak akan menggunakan unsur...", "o": ["Fakta ilmiah peningkatan suhu bumi", "Proses penumpukan gas rumah kaca", "Kisah fiktif petualangan penyelamatan bumi", "Dampak mencairnya es di kutub"], "a": 2, "p": "Teks eksplanasi bersifat objektif dan faktual, sehingga tidak menggunakan kisah fiktif atau khayalan."}, {"lv": 3, "q": "Perhatikan paragraf rumpang berikut:\n'Pembangkit Listrik Tenaga Air (PLTA) memanfaatkan aliran air sungai untuk memutar turbin. Air yang mengalir deras menabrak kincir pada turbin ... menghasilkan energi gerak yang diubah menjadi energi listrik oleh generator.'\n\nKata penghubung (konjungsi kronologis/urutan waktu) yang paling tepat untuk melengkapi bagian rumpang adalah...", "o": ["sehingga", "tetapi", "meskipun", "padahal"], "a": 0, "p": "Konjungsi 'sehingga' tepat digunakan untuk menyatakan akibat atau hasil dari proses aliran air yang menabrak turbin."}]}, {"id": "bin-k6-1", "name": "Kalimat utama dan penjelas", "desc": "Struktur paragraf", "idx": 1, "soal": [{"lv": 1, "q": "Kalimat yang berisi gagasan utama atau pokok pembicaraan dalam sebuah paragraf disebut...", "o": ["Kalimat penjelas", "Kalimat utama", "Kalimat tanya", "Kalimat perintah"], "a": 1, "p": "Kalimat utama adalah kalimat yang memuat ide pokok atau gagasan utama yang mendasari pembentukan suatu paragraf."}, {"lv": 1, "q": "Kalimat yang berfungsi untuk menguraikan, menjelaskan, atau mendukung kalimat utama disebut...", "o": ["Kalimat penjelas", "Kalimat utama", "Kalimat pembuka", "Kalimat penutup"], "a": 0, "p": "Kalimat penjelas berisi rincian, contoh, atau penjelasan lebih lanjut untuk memperjelas kalimat utama."}, {"lv": 1, "q": "Paragraf yang kalimat utamanya terletak di awal paragraf disebut paragraf...", "o": ["Induktif", "Campuran", "Deduktif", "Deskriptif"], "a": 2, "p": "Paragraf deduktif adalah paragraf yang gagasan utamanya berada di awal kalimat (umum ke khusus)."}, {"lv": 1, "q": "Jika kalimat utama terletak di akhir paragraf, maka paragraf tersebut dinamakan paragraf...", "o": ["Deduktif", "Induktif", "Persuasif", "Naratif"], "a": 1, "p": "Paragraf induktif adalah paragraf yang gagasan utamanya terletak di bagian akhir paragraf (khusus ke umum)."}, {"lv": 2, "q": "Bacalah paragraf berikut!\n(1) Kesehatan tubuh sangat dipengaruhi oleh makanan yang kita konsumsi.\n(2) Makanan yang sehat harus mengandung gizi seimbang.\n(3) Selain itu, kita juga harus rajin berolahraga.\n(4) Istirahat yang cukup turut melengkapi gaya hidup sehat.\n\nKalimat utama pada paragraf di atas terdapat pada nomor...", "o": ["(1)", "(2)", "(3)", "(4)"], "a": 0, "p": "Kalimat (1) merupakan gagasan umum yang kemudian dijelaskan lebih lanjut oleh kalimat-kalimat berikutnya mengenai makanan bergizi, olahraga, dan istirahat."}, {"lv": 2, "q": "Perhatikan ciri-ciri kalimat utama dan kalimat penjelas berikut!\n1) Bersifat khusus dan berupa uraian detail\n2) Bersifat umum dan memuat inti permasalahan\n3) Memerlukan kalimat lain untuk menjelaskan isinya\n4) Dapat berdiri sendiri meskipun tanpa kalimat penjelas\n\nManakah yang merupakan ciri-ciri dari kalimat penjelas?", "o": ["1 dan 3", "1 dan 4", "2 dan 3", "2 dan 4"], "a": 0, "p": "Kalimat penjelas bersifat khusus (1) dan memerlukan kalimat lain agar maknanya utuh (3). Pilihan 2 dan 4 adalah ciri kalimat utama."}, {"lv": 2, "q": "Bacalah teks singkat berikut!\nBanjir sering melanda kawasan perkotaan saat musim hujan tiba. Hal ini disebabkan oleh buruknya sistem drainase dan kebiasaan warga membuang sampah sembarangan ke sungai. Akibatnya, aliran air tersumbat dan meluap ke permukiman warga.\n\nGagasan utama paragraf tersebut adalah...", "o": ["Kebiasaan warga membuang sampah", "Buruknya sistem drainase di kota", "Penyebab terjadinya banjir di perkotaan", "Meluapnya air sungai ke permukiman"], "a": 2, "p": "Gagasan utama mewakili keseluruhan isi paragraf, yaitu membahas tentang penyebab terjadinya banjir di perkotaan."}, {"lv": 2, "q": "Paragraf yang memiliki kalimat utama di awal dan ditegaskan kembali di akhir paragraf disebut paragraf...", "o": ["Deduktif", "Induktif", "Campuran", "Ineratif"], "a": 2, "p": "Paragraf campuran adalah paragraf yang gagasan utamanya terletak di awal dan diulang atau ditegaskan kembali di akhir paragraf."}, {"lv": 3, "q": "Bacalah paragraf rumpang berikut dengan cermat!\n[...]. Tanaman hias di pekarangan rumah membutuhkan perawatan yang rutin. Setiap sore, Siti selalu menyiram bunga-bunga tersebut menggunakan air bersih. Selain itu, ia juga rajin memberikan pupuk alami agar tanahnya tetap subur.\n\nKalimat utama yang paling tepat untuk melengkapi awal paragraf tersebut adalah...", "o": ["Siti memiliki hobi berkebun yang sangat menyenangkan.", "Pupuk alami sangat baik untuk pertumbuhan tanaman hias.", "Air bersih sangat penting bagi kelangsungan hidup tanaman.", "Menyiram tanaman sebaiknya dilakukan pada sore hari."], "a": 0, "p": "Kalimat penjelas membahas tentang kegiatan Siti merawat tanaman hias setiap sore dan memupuknya, sehingga kalimat utamanya berkaitan dengan hobi berkebun Siti."}, {"lv": 3, "q": "Analisis kalimat-kalimat berikut dalam sebuah paragraf:\n(1) Buku adalah jendela dunia yang membuka wawasan kita.\n(2) Dengan membaca buku, kita bisa mengetahui berbagai informasi baru.\n(3) Pengetahuan tentang ilmu sains dan teknologi dapat kita peroleh dari buku.\n(4) Oleh karena itu, membiasakan diri membaca sejak kecil sangatlah penting.\n\nManakah kalimat yang berfungsi sebagai kalimat penjelas yang berisi contoh atau rincian manfaat?", "o": ["(1)", "(2)", "(4)", "(2) dan (3)"], "a": 3, "p": "Kalimat (2) dan (3) adalah kalimat penjelas yang merinci manfaat membaca buku, sedangkan kalimat (1) adalah kalimat utama dan (4) adalah kalimat penegas/kesimpulan."}, {"lv": 3, "q": "Perhatikan paragraf berikut:\nBawang putih dikenal bukan hanya sebagai bumbu dapur, tetapi juga memiliki banyak khasiat untuk kesehatan. Kandungan zat di dalamnya terbukti dapat membantu menurunkan tekanan darah tinggi. Selain itu, bawang putih juga mampu meningkatkan sistem kekebalan tubuh manusia.\n\nPernyataan yang paling tepat mengenai struktur paragraf di atas adalah...", "o": ["Kalimat utama terletak di akhir paragraf", "Kalimat utama terletak di awal paragraf, diikuti dua kalimat penjelas", "Semua kalimat dalam paragraf adalah kalimat penjelas", "Paragraf tersebut tidak memiliki kalimat utama"], "a": 1, "p": "Kalimat pertama adalah kalimat utama (deduktif), sedangkan kalimat kedua dan ketiga adalah kalimat penjelas yang merinci khasiat bawang putih."}, {"lv": 3, "q": "Dalam menyusun sebuah karangan, sebuah kalimat penjelas dinyatakan tidak padu atau menyimpang jika...", "o": ["Mendukung gagasan utama secara langsung", "Berisi contoh yang sesuai dengan topik", "Membahas topik lain yang tidak berkaitan dengan kalimat utama", "Terletak di bagian tengah paragraf"], "a": 2, "p": "Kalimat penjelas yang baik harus padu dan koheren dengan kalimat utama. Jika membahas topik lain yang tidak berkaitan, maka kalimat tersebut tidak padu."}]}, {"id": "bin-k6-2", "name": "Surat undangan", "desc": "Bagian dan bahasa surat", "idx": 2, "soal": [{"lv": 1, "q": "Bagian surat yang berisi keterangan waktu, hari, tanggal, pukul, dan tempat pelaksanaan kegiatan disebut...", "o": ["Isi surat", "Waktu dan tempat", "Penutup surat", "Salam pembuka"], "a": 1, "p": "Bagian surat undangan resmi yang mencantumkan hari, tanggal, waktu, dan tempat kegiatan disebut rincian waktu dan tempat."}, {"lv": 1, "q": "Surat undangan yang ditulis untuk keperluan keluarga, seperti undangan ulang tahun atau pernikahan, disebut surat...", "o": ["Resmi", "Pribadi", "Dinas", "Pengumuman"], "a": 1, "p": "Surat pribadi atau tidak resmi adalah surat yang dikirimkan untuk perorangan, keluarga, atau teman."}, {"lv": 1, "q": "Manakah di bawah ini yang merupakan contoh penggunaan surat resmi?", "o": ["Undangan ulang tahun teman", "Surat izin tidak masuk sekolah kepada guru", "Surat undangan rapat pembentukan pengurus kelas dari sekolah", "Undangan syukuran rumah baru paman"], "a": 2, "p": "Surat undangan rapat sekolah adalah contoh surat resmi karena dikeluarkan oleh instansi pendidikan dengan format formal."}, {"lv": 1, "q": "Bagian yang terletak di pojok kanan atas pada surat undangan resmi instansi pemerintahan atau sekolah biasanya memuat...", "o": ["Nama dan alamat pengirim atau kop surat", "Tanggal pembuatan surat", "Tanda tangan kepala sekolah", "Salam penutup"], "a": 1, "p": "Tanggal pembuatan surat pada surat resmi biasanya dicantumkan di sebelah kanan atas tanpa perlu menuliskan nama kota lagi jika sudah ada di kop surat."}, {"lv": 2, "q": "Perhatikan bagian surat berikut!\n'Yth. Bapak dan Ibu Wali Murid Kelas VI\ndi Tempat'\nBagian tersebut dalam surat undangan disebut sebagai...", "o": ["Salam pembuka", "Alamat yang dituju", "Kop surat", "Isi surat"], "a": 1, "p": "Bagian tersebut menunjukkan kepada siapa surat itu ditujukan, yang disebut sebagai alamat tujuan surat."}, {"lv": 2, "q": "Apa ciri utama bahasa yang digunakan dalam penulisan surat undangan resmi?", "o": ["Menggunakan bahasa gaul dan santai", "Menggunakan bahasa baku, singkat, padat, dan sopan", "Menggunakan banyak singkatan kata", "Menggunakan bahasa puisi yang indah"], "a": 1, "p": "Surat resmi harus menggunakan ragam bahasa baku sesuai kaidah EYD/PUEBI serta bernada sopan dan jelas."}, {"lv": 2, "q": "Bagian penutup dalam surat undangan resmi biasanya berisi...", "o": ["Harapan atas kehadiran undangan serta ucapan terima kasih", "Cerita pengalaman pribadi pengirim surat", "Permintaan maaf karena acara diundur", "Rincian biaya pelaksanaan kegiatan"], "a": 0, "p": "Penutup surat resmi umumnya berisi ucapan terima kasih atas kehadiran dan perhatian dari pihak yang diundang."}, {"lv": 2, "q": "Perhatikan kalimat penutup berikut!\n'Atas perhatian Bapak/Ibu, kami ucapkan terima kasih.'\nKalimat tersebut biasanya diletakkan pada bagian...", "o": ["Pembuka surat", "Isi pokok surat", "Penutup surat", "Lampiran surat"], "a": 2, "p": "Kalimat ucapan terima kasih atas kehadiran dan perhatian merupakan ciri khas bagian penutup surat."}, {"lv": 3, "q": "Manakah perbedaan yang paling mencolok antara surat undangan resmi dan surat undangan pribadi?", "o": ["Surat resmi menggunakan kop surat dan nomor surat, sedangkan surat pribadi tidak menggunakannya.", "Surat pribadi selalu ditulis menggunakan mesin tik, sedangkan surat resmi ditulis tangan.", "Surat resmi tidak memerlukan salam pembuka.", "Surat pribadi menggunakan bahasa yang sangat kaku dan resmi."], "a": 0, "p": "Kop surat dan nomor surat adalah ciri mutlak yang hanya ada pada surat resmi atau instansi."}, {"lv": 3, "q": "Perhatikan kutipan isi surat berikut!\n'Kami mengharapkan kehadiran Bapak/Ibu pada acara Rapat Pleno Kelulusan Siswa yang akan diselenggarakan pada hari Sabtu...' \nKutipan tersebut merupakan bagian... dari sebuah surat undangan.", "o": ["Salam pembuka", "Kalimat pembuka isi surat", "Penutup surat", "Lampiran"], "a": 1, "p": "Kalimat tersebut berfungsi sebagai pengantar atau kalimat pembuka isi surat sebelum masuk ke rincian waktu dan tempat."}, {"lv": 3, "q": "Dalam penulisan alamat tujuan pada surat resmi, penulisan kata 'Kepada' sering kali dihilangkan. Apa alasannya?", "o": ["Karena kata 'Kepada' sudah diwakili oleh singkatan 'Yth.' (Yang terhormat)", "Karena kata tersebut tidak penting dalam surat", "Karena aturan baru melarang penggunaan huruf kapital", "Karena membuat surat menjadi terlalu panjang"], "a": 0, "p": "Dalam tata naskah surat resmi yang disempurnakan, penggunaan kata 'Kepada' di depan 'Yth.' dianggap mubazir dan dianjurkan untuk dihilangkan."}, {"lv": 3, "q": "Sebuah surat undangan rapat Karang Taruna mencantumkan kalimat berikut:\n'Acara: Rapat Koordinasi HUT RI'\n'Hari/Tanggal: Minggu, 10 Agustus 2025'\n'Pukul: 19.00 WIB'\n'Tempat: Balai Warga RW 05'\nInformasi tersebut di dalam surat undangan berfungsi untuk...", "o": ["Memberitahukan identitas pengirim surat secara lengkap", "Menjelaskan rincian pelaksanaan kegiatan yang harus dihadiri oleh undangan", "Menyampaikan salam penutup kepada para peserta rapat", "Melampirkan daftar nama panitia acara"], "a": 1, "p": "Rincian acara, hari/tanggal, pukul, dan tempat berfungsi memberikan kejelasan informasi mengenai waktu dan lokasi kegiatan yang diselenggarakan."}]}], "7": [{"id": "bin-k7-0", "name": "Teks deskripsi", "desc": "Struktur dan ciri kebahasaan", "idx": 0, "soal": [{"lv": 1, "q": "Teks yang bertujuan menggambarkan suatu objek secara rinci agar pembaca seolah-olah melihat, mendengar, atau merasakan sendiri objek tersebut disebut...", "o": ["Teks eksposisi", "Teks deskripsi", "Teks prosedur", "Teks laporan"], "a": 1, "p": "Teks deskripsi adalah teks yang memaparkan objek secara jelas dan rinci untuk memberikan pengalaman indrawi kepada pembaca."}, {"lv": 1, "q": "Struktur teks deskripsi yang berisi pengenalan nama objek, lokasi, dan gambaran umum objek tersebut adalah...", "o": ["Deskripsi bagian", "Simpulan", "Identifikasi", "Penutup"], "a": 2, "p": "Identifikasi (deskripsi umum) berisi penetapan identitas objek, nama, lokasi, dan ciri umum di awal teks."}, {"lv": 1, "q": "Berikut ini yang merupakan ciri kebahasaan teks deskripsi adalah...", "o": ["Menggunakan kata kerja perintah", "Menggunakan kata yang menggambarkan perasaan pembaca", "Menggunakan kata sifat untuk menggambarkan objek secara konkret", "Menggunakan banyak istilah teknis ilmiah"], "a": 2, "p": "Teks deskripsi menggunakan kata sifat (seperti indah, besar, sejuk) untuk memerinci objek agar lebih konkret."}, {"lv": 1, "q": "Bagian 'Deskripsi Bagian' dalam teks deskripsi memuat tentang...", "o": ["Saran penulis terhadap objek", "Nama objek dan lokasi", "Perincian bagian-bagian objek berdasarkan tanggapan subjektif penulis", "Latar belakang pembuatan teks"], "a": 2, "p": "Deskripsi bagian berisi perincian detail mengenai fisik, suara, atau suasana bagian-bagian dari objek yang dideskripsikan."}, {"lv": 2, "q": "Perhatikan kalimat berikut: 'Pemandangan bawah laut Bunaken sungguh memesona. Terumbu karang yang berwarna-warni menyapa setiap mata yang memandang.'\n\nMajas yang digunakan pada kalimat kedua adalah...", "o": ["Hiperbola", "Metafora", "Personifikasi", "Sinekdoke"], "a": 2, "p": "Kata 'menyapa' adalah tindakan manusia yang diberikan pada benda mati (terumbu karang), sehingga disebut majas personifikasi."}, {"lv": 2, "q": "Manakah di antara kalimat berikut yang menggunakan cerapan indra penglihatan?", "o": ["Aroma kopi pagi ini sangat menyengat", "Kicauan burung terdengar sangat merdu", "Hamparan pasir putih membentang luas di sepanjang pantai", "Udara dingin menusuk tulang di puncak gunung"], "a": 2, "p": "Kalimat tersebut menggambarkan warna (putih) dan bentangan alam yang ditangkap oleh indra penglihatan."}, {"lv": 2, "q": "Bacalah kutipan berikut: 'Kelinci kesayanganku bernama Bagas. Ia memiliki bulu yang putih dan sangat lembut. Matanya yang bulat berwarna cokelat tampak sangat lucu.'\n\nKutipan tersebut termasuk bagian struktur...", "o": ["Identifikasi", "Deskripsi Bagian", "Simpulan", "Saran"], "a": 1, "p": "Teks tersebut merinci ciri fisik objek (bulu dan mata) secara detail, maka termasuk dalam struktur Deskripsi Bagian."}, {"lv": 2, "q": "Kalimat yang menggunakan kata khusus untuk menggambarkan warna adalah...", "o": ["Bunga itu warnanya sangat bagus", "Gaun yang ia pakai berwarna merah marun", "Pelangi memiliki banyak warna", "Pemandangan itu sangat menarik"], "a": 1, "p": "Kata 'merah marun' adalah kata khusus (spesifik) yang memberikan gambaran warna lebih jelas dibanding kata umum 'merah'."}, {"lv": 3, "q": "Perhatikan kalimat umum berikut: 'Ibuku adalah orang yang sangat baik.'\n\nKalimat perincian yang paling tepat untuk menjelaskan kalimat umum di atas adalah...", "o": ["Ibu sering memasak makanan enak untuk kami di rumah", "Wajah ibu selalu tampak ceria setiap pagi", "Ibu suka membantu tetangga dan bertutur kata sangat lembut", "Ibu bekerja keras dari pagi hingga malam hari"], "a": 2, "p": "Perincian 'suka membantu' dan 'bertutur kata lembut' secara konkret menjelaskan makna 'sangat baik' dari kalimat sebelumnya."}, {"lv": 3, "q": "Pilihlah kalimat yang menggunakan cerapan indra pendengaran dengan tepat!", "o": ["Warna air laut di pantai itu hijau toska", "Debur ombak terdengar berirama memecah keheningan", "Tekstur kue lapis itu sangat kenyal dan legit", "Cahaya lampu kota berkelap-kelip dari kejauhan"], "a": 1, "p": "Kata 'debur ombak' dan 'terdengar' melibatkan penggunaan indra pendengaran untuk memahami suasana pantai."}, {"lv": 3, "q": "Bacalah teks berikut: 'Masuk ke dalam area taman, kita akan disambut dengan udara yang sangat sejuk. Di tengah taman terdapat kolam besar dengan air mancur yang menari-nari. Di pinggir kolam, tumbuh bunga mawar yang sedang bermekaran.'\n\nApa kesan yang ingin dibangun penulis melalui teks tersebut?", "o": ["Taman tersebut sangat luas dan gersang", "Taman tersebut memberikan suasana yang asri dan tenang", "Taman tersebut tidak terawat dan kotor", "Taman tersebut penuh dengan pengunjung yang berisik"], "a": 1, "p": "Kata 'sejuk', 'air mancur menari', dan 'bunga bermekaran' memberikan kesan suasana yang indah, asri, dan tenang."}, {"lv": 3, "q": "Dalam teks deskripsi, penggunaan kata ganti 'kita' atau 'kami' sering bertujuan untuk...", "o": ["Menyembunyikan identitas penulis asli", "Menghindari penggunaan kata benda yang berulang", "Melibatkan pembaca seolah-olah ikut merasakan apa yang dideskripsikan", "Memperjelas letak objek secara geografis"], "a": 2, "p": "Kata ganti orang pertama jamak sering digunakan untuk menciptakan kedekatan subjek pembaca dengan objek yang sedang dideskripsikan."}]}, {"id": "bin-k7-1", "name": "Teks prosedur", "desc": "Langkah-langkah dan kata perintah", "idx": 1, "soal": [{"lv": 1, "q": "Teks yang berisi panduan atau langkah-langkah untuk membuat, melakukan, atau mengoperasikan sesuatu dengan benar disebut...", "o": ["Teks deskripsi", "Teks prosedur", "Teks narasi", "Teks eksplanasi"], "a": 1, "p": "Teks prosedur adalah teks yang menyajikan petunjuk atau langkah-langkah melakukan sesuatu secara berurutan."}, {"lv": 1, "q": "Bagian awal dalam struktur teks prosedur biasanya berisi...", "o": ["Kesimpulan cerita", "Tujuan pembuatan atau pengoperasian sesuatu", "Kritik dan saran", "Dialog antar tokoh"], "a": 1, "p": "Bagian pendahuluan atau awal teks prosedur umumnya menyatakan tujuan dari pembuatan atau petunjuk yang akan dilakukan."}, {"lv": 1, "q": "Perhatikan kalimat berikut: 'Potonglah sayuran tersebut menjadi bagian yang kecil-kecil.' Kalimat tersebut termasuk jenis kalimat...", "o": ["Kalimat tanya", "Kalimat berita", "Kalimat perintah (imperatif)", "Kalimat saran"], "a": 2, "p": "Kalimat perintah atau imperatif ditandai dengan adanya akhiran -lah dan berfungsi untuk menyuruh melakukan sesuatu."}, {"lv": 1, "q": "Dalam membuat jus buah, hal pertama yang biasanya dicantumkan dalam teks prosedur selain tujuan adalah...", "o": ["Daftar alat dan bahan", "Kesimpulan dan penutup", "Kesan pembaca", "Riwayat penulis"], "a": 0, "p": "Teks prosedur pembuatan sesuatu selalu mencantumkan rincian alat dan bahan yang diperlukan setelah bagian tujuan."}, {"lv": 2, "q": "Perhatikan kalimat-kalimat acak berikut:\n1) Aduk rata adonan tepung dan santan.\n2) Siapkan wadah bersih untuk mencampur bahan.\n3) Panaskan minyak di atas wajan dengan api sedang.\n\nUrutan kalimat petunjuk membuat kue tradisional yang logis adalah...", "o": ["1 - 2 - 3", "2 - 1 - 3", "3 - 2 - 1", "2 - 3 - 1"], "a": 1, "p": "Langkah yang logis dimulai dari menyiapkan wadah (2), mencampur dan mengaduk bahan (1), lalu memasak atau menggorengnya (3)."}, {"lv": 2, "q": "Ciri kebahasaan yang banyak ditemukan dalam teks prosedur untuk menunjukkan urutan langkah adalah penggunaan...", "o": ["Konjungsi temporal (pertama, kemudian, selanjutnya, lalu)", "Kata ganti penunjuk (ini, itu)", "Majas perbandingan (seperti, bagaikan)", "Kalimat langsung berupa dialog"], "a": 0, "p": "Teks prosedur menggunakan konjungsi temporal atau urutan waktu untuk menunjukkan tahapan kegiatan secara kronologis."}, {"lv": 2, "q": "Bacalah kalimat berikut: 'Masukkan dua sendok makan gula pasir ke dalam gelas.' Kata kerja (verba) utama yang terdapat dalam kalimat tersebut adalah...", "o": ["Gelas", "Gula pasir", "Masukkan", "Sendok makan"], "a": 2, "p": "Kata 'masukkan' adalah verba perbuatan atau kata kerja imperatif yang mengarahkan pembaca melakukan suatu tindakan."}, {"lv": 2, "q": "Bagian akhir dari struktur teks prosedur yang berisi penegasan ulang atau ucapan selamat mencoba disebut...", "o": ["Abstraksi", "Penutup / Simpulan", "Klimaks", "Orientasi"], "a": 1, "p": "Bagian penutup dalam teks prosedur biasanya berisi ucapan selamat mencoba atau simpulan singkat dari tahapan sebelumnya."}, {"lv": 3, "q": "Perhatikan kalimat prosedur berikut:\n'Rebuslah air hingga mendidih, ... masukkan mie instan ke dalam panci.'\nKonjungsi urutan yang paling tepat untuk melengkapi bagian rumpang adalah...", "o": ["tetapi", "kemudian", "meskipun", "karena"], "a": 1, "p": "Kata 'kemudian' atau 'lalu' adalah konjungsi temporal yang tepat untuk menyambung langkah lanjutan setelah air mendidih."}, {"lv": 3, "q": "Analisis kalimat berikut dalam sebuah teks prosedur membuat mainan origami:\n'Lipatlah kertas berbentuk persegi menjadi dua bagian yang sama besar secara simetris.'\nKeterangan cara yang terdapat pada kalimat tersebut adalah...", "o": ["menjadi dua bagian yang sama besar secara simetris", "lipatlah kertas", "berbentuk persegi", "di dalam ruangan"], "a": 0, "p": "Keterangan cara menjelaskan bagaimana suatu tindakan harus dilakukan, yaitu 'menjadi dua bagian yang sama besar secara simetris'."}, {"lv": 3, "q": "Manakah pernyataan di bawah ini yang membedakan teks prosedur dengan teks deskripsi secara tepat?", "o": ["Teks prosedur menggambarkan objek secara rinci, sedangkan teks deskripsi memberikan langkah membuat sesuatu.", "Teks prosedur berisi panduan langkah melakukan sesuatu, sedangkan teks deskripsi menggambarkan ciri fisik suatu objek.", "Teks prosedur menggunakan alur cerita fiktif, sedangkan teks deskripsi menggunakan fakta mutlak.", "Teks prosedur tidak memiliki struktur tujuan, sedangkan teks deskripsi selalu memiliki alat dan bahan."], "a": 1, "p": "Teks prosedur berfokus pada panduan/langkah kerja, sedangkan teks deskripsi berfokus pada penggambaran objek secara mendetail."}, {"lv": 3, "q": "Perhatikan langkah-langkah acak cara menggunakan blender:\n1) Tekan tombol on untuk menghidupkan mesin.\n2) Potong buah menjadi ukuran kecil lalu masukkan ke dalam blender.\n3) Colokkan kabel stop kontak ke sumber listrik.\n4) Tuang jus ke dalam gelas saji.\n\nSusunan langkah pengoperasian alat yang paling logis adalah...", "o": ["2 - 3 - 1 - 4", "3 - 2 - 1 - 4", "1 - 2 - 3 - 4", "2 - 1 - 3 - 4"], "a": 0, "p": "Langkah yang logis: menyiapkan dan memasukkan bahan ke blender (2), mencolokkan kabel (3), menyalakan mesin (1), lalu menyajikan hasil jus (4)."}]}, {"id": "bin-k7-2", "name": "Majas", "desc": "Personifikasi, hiperbola, simile, metafora", "idx": 2, "soal": [{"lv": 1, "q": "Majas yang melukiskan suatu benda mati seolah-olah bernyawa atau berperilaku seperti manusia disebut...", "o": ["Metafora", "Hiperbola", "Personifikasi", "Simile"], "a": 2, "p": "Majas personifikasi adalah gaya bahasa yang membandingkan benda mati seolah-olah hidup dan bernyawa seperti manusia."}, {"lv": 1, "q": "Perhatikan kalimat berikut: 'Suaranya menggelegar membelah angkasa.' Kalimat tersebut mengandung majas...", "o": ["Hiperbola", "Simile", "Personifikasi", "Metafora"], "a": 0, "p": "Majas hiperbola adalah majas yang mengandung pernyataan berlebihan atau melebihi kenyataan yang sebenarnya."}, {"lv": 1, "q": "Majas yang membandingkan dua hal yang pada hakikatnya berbeda tetapi dianggap sama dengan menggunakan kata perbanding (seperti, bagaikan, laksana) adalah...", "o": ["Metafora", "Simile", "Personifikasi", "Hiperbola"], "a": 1, "p": "Majas simile membandingkan sesuatu secara langsung dengan menggunakan kata-kata pembanding seperti 'bagaikan', 'seperti', atau 'laksana'."}, {"lv": 1, "q": "Perhatikan kalimat berikut: 'Dewi malam mulai menampakkan wajahnya di balik awan.' Kata 'Dewi malam' merupakan contoh majas...", "o": ["Personifikasi", "Simile", "Hiperbola", "Metafora"], "a": 3, "p": "Majas metafora menggunakan perbandingan langsung secara analogis, di mana 'Dewi malam' adalah kiasan untuk bulan."}, {"lv": 2, "q": "Perhatikan kalimat berikut: 'Angin malam berbisik lembut menyampaikan salamku kepadamu.' Majas yang dominan pada kalimat tersebut adalah...", "o": ["Hiperbola", "Personifikasi", "Simile", "Metafora"], "a": 1, "p": "Angin malam digambarkan dapat 'berbisik' layaknya manusia, yang merupakan ciri khas majas personifikasi."}, {"lv": 2, "q": "Kalimat berikut yang mengandung majas simile adalah...", "o": ["Pikiran anak itu encer sekali sehingga cepat memahami pelajaran.", "Semangatnya membara bagaikan api yang tak pernah padam.", "Kucing itu melompat menangkap cicak di dinding.", "Raja hutan itu mengaum sangat keras di tengah belantara."], "a": 1, "p": "Kalimat tersebut menggunakan kata pembanding 'bagaikan' untuk menyamakan semangat dengan api, yang merupakan ciri majas simile."}, {"lv": 2, "q": "Perhatikan kalimat berikut: 'Ayah bekerja membanting tulang demi menyekolahkan anak-anaknya.' Ungkapan 'membanting tulang' termasuk dalam kelompok majas...", "o": ["Metafora", "Hiperbola", "Personifikasi", "Simile"], "a": 0, "p": "Ungkapan atau kiasan langsung seperti 'membanting tulang' (bekerja keras) digolongkan sebagai majas metafora."}, {"lv": 2, "q": "Manakah kalimat di bawah ini yang menggunakan gaya bahasa hiperbola?", "o": ["Wajah gadis itu bersinar bagaikan rembulan.", "Pohon beringin itu merangkul tanah dengan akar-akarnya.", "Air matanya mengalir deras membentuk lautan duka.", "Perpustakaan adalah gudang ilmu yang sangat luas."], "a": 2, "p": "Pernyataan air mata membentuk lautan duka bersifat berlebihan (melebih-lebihkan kenyataan), ciri dari majas hiperbola."}, {"lv": 3, "q": "Analisis penggalan puisi berikut:\n'Hatiku hancur berkeping-keping menjadi serpihan debu ketika mendengar berita duka itu.'\nGaya bahasa yang paling dominan dalam kutipan puisi tersebut adalah...", "o": ["Hiperbola dan metafora", "Personifikasi dan simile", "Metafora dan simile", "Personifikasi dan hiperbola"], "a": 0, "p": "Hati hancur berkeping-keping dan menjadi debu adalah ungkapan berlebihan (hiperbola) serta kiasan sifat (metafora)."}, {"lv": 3, "q": "Perhatikan dua kalimat berikut!\n1) Penat dan lelah membuatku merasa seolah-olah memikul gunung di pundakku.\n2) Sang surya tersenyum hangat menyapa pagi hari yang indah.\n\nMajas yang terkandung dalam kalimat (1) dan (2) secara berurutan adalah...", "o": ["Personifikasi dan hiperbola", "Hiperbola dan personifikasi", "Simile dan metafora", "Hiperbola dan simile"], "a": 1, "p": "Kalimat (1) memikul gunung menunjukkan kepayahan yang berlebihan (hiperbola), sedangkan kalimat (2) matahari tersenyum menyapa (personifikasi)."}, {"lv": 3, "q": "Pernyataan manakah yang paling tepat untuk membedakan majas simile dan majas metafora?", "o": ["Simile menggunakan kata pembanding langsung, sedangkan metafora membandingkan secara langsung tanpa kata pembanding.", "Simile memberikan sifat manusia pada benda mati, sedangkan metafora menyatakan hal yang berlebihan.", "Simile dan metafora memiliki arti dan aturan struktur kalimat yang persis sama.", "Metafora selalu menggunakan kata 'seperti', sedangkan simile menggunakan kata 'adalah'."], "a": 0, "p": "Simile menggunakan kata pembanding (seperti, bagaikan, laksana), sedangkan metafora melakukan perbandingan langsung (analogi) tanpa kata pembanding."}, {"lv": 3, "q": "Bacalah kalimat berikut:\n'Pulpen pintar itu menari-nari di atas kertas putih dengan lincahnya.'\nIdentifikasi jenis majas yang terdapat pada kalimat tersebut adalah...", "o": ["Hiperbola karena pulpen sangat cerdas", "Simile karena menggunakan kata pembanding pulpen dan penari", "Personifikasi karena pulpen mati dianggap bisa menari seperti manusia", "Metafora karena pulpen disamakan secara langsung dengan penari"], "a": 2, "p": "Pulpen sebagai benda mati dilekati sifat atau kemampuan hidup manusia yaitu 'menari-nari', yang merupakan majas personifikasi."}]}], "8": [{"id": "bin-k8-0", "name": "Teks berita", "desc": "Unsur 5W+1H", "idx": 0, "soal": [{"lv": 1, "q": "Unsur 5W+1H dalam teks berita yang berfungsi untuk menanyakan peristiwa atau kejadian yang sedang diberitakan adalah...", "o": ["Who", "What", "Where", "When"], "a": 1, "p": "Unsur 'What' (apa) digunakan untuk mengetahui peristiwa atau kejadian apa yang sedang dibahas dalam berita."}, {"lv": 1, "q": "Unsur yang menanyakan siapa saja pihak atau tokoh yang terlibat dalam suatu peristiwa berita adalah...", "o": ["Why", "How", "Who", "Where"], "a": 2, "p": "Unsur 'Who' (siapa) digunakan untuk menunjukkan orang atau tokoh yang terlibat dalam kejadian berita."}, {"lv": 1, "q": "Kapan suatu peristiwa dalam teks berita terjadi berkaitan dengan unsur...", "o": ["When", "Where", "Why", "What"], "a": 0, "p": "Unsur 'When' (kapan) menanyakan waktu terjadinya suatu peristiwa atau kejadian dalam berita."}, {"lv": 1, "q": "Unsur berita yang digunakan untuk menanyakan tempat atau lokasi kejadian suatu peristiwa adalah...", "o": ["Who", "How", "What", "Where"], "a": 3, "p": "Unsur 'Where' (di mana) berfungsi untuk menunjukkan lokasi atau tempat berlangsungnya peristiwa."}, {"lv": 2, "q": "Bacalah penggalan teks berita berikut:\n'Gempa bumi berkekuatan 5,6 skala Richter mengguncang Kabupaten Cianjur pada Senin siang kemarin.'\nUnsur berita yang mencakup kalimat tersebut adalah...", "o": ["Who dan Why", "What dan Where", "What, Where, dan When", "How dan Who"], "a": 2, "p": "'Gempa bumi 5,6 SR' adalah apa (what), 'di Kabupaten Cianjur' adalah di mana (where), dan 'Senin siang kemarin' adalah kapan (when)."}, {"lv": 2, "q": "Unsur 'Why' dalam 5W+1H pada teks berita digunakan untuk menanyakan...", "o": ["Proses terjadinya peristiwa", "Alasan atau latar belakang mengapa peristiwa itu bisa terjadi", "Jumlah korban jiwa dalam peristiwa", "Dampak kerugian material"], "a": 1, "p": "Unsur 'Why' (mengapa) menanyakan alasan atau latar belakang penyebab terjadinya suatu peristiwa."}, {"lv": 2, "q": "Unsur 'How' dalam teks berita biasanya menjelaskan tentang...", "o": ["Siapa pelaku utama peristiwa", "Tempat kejadian perkara", "Waktu pelaksanaan kegiatan", "Bagaimana proses atau kronologi peristiwa tersebut berlangsung"], "a": 3, "p": "Unsur 'How' (bagaimana) menjelaskan proses, cara, atau kronologi suatu peristiwa dapat terjadi."}, {"lv": 2, "q": "Struktur bagian terpenting dalam teks berita yang biasanya merangkum unsur 5W+1H secara ringkas disebut...", "o": ["Kepala berita (lead)", "Tubuh berita (body)", "Ekor berita (leg)", "Kesimpulan berita"], "a": 0, "p": "Kepala berita (lead) memuat inti atau rangkuman unsur 5W+1H yang terletak di paragraf pertama."}, {"lv": 3, "q": "Bacalah kutipan berita berikut:\n'Pemerintah menaikkan harga bahan bakar minyak (BBM) demi mengalihkan subsidi ke sektor yang lebih tepat sasaran mulai tengah malam tadi.'\nUnsur 'Why' (mengapa) yang terdapat dalam kutipan berita tersebut adalah...", "o": ["Pemerintah menaikkan harga BBM", "Mulai tengah malam tadi", "Demi mengalihkan subsidi ke sektor yang lebih tepat sasaran", "Di SPBU seluruh Indonesia"], "a": 2, "p": "Alasan atau latar belakang (why) pemerintah menaikkan BBM adalah demi mengalihkan subsidi ke sektor yang lebih tepat sasaran."}, {"lv": 3, "q": "Analisis kalimat berikut:\n'Ribuan warga berdesak-desakan antre sembako murah di halaman kantor kelurahan sejak pukul 08.00 pagi.'\nUnsur 'Who' dan 'Where' dari kalimat tersebut secara berurutan adalah...", "o": ["Ribuan warga dan Halaman kantor kelurahan", "Sembako murah dan Pukul 08.00 pagi", "Kantor kelurahan dan Ribuan warga", "Sejak pukul 08.00 pagi dan Berdesak-desakan"], "a": 0, "p": "Pihak yang terlibat (Who) adalah ribuan warga, sedangkan tempat kejadian (Where) adalah di halaman kantor kelurahan."}, {"lv": 3, "q": "Manakah pernyataan di bawah ini yang paling tepat mengenai hubungan antara judul dan unsur 5W+1H dalam teks berita?", "o": ["Judul berita harus memuat seluruh jawaban 5W+1H secara lengkap.", "Judul berita biasanya mencakup unsur utama seperti 'What' atau 'Who' untuk menarik perhatian pembaca.", "Judul berita tidak ada kaitannya sama sekali dengan isi teks berita.", "Judul berita hanya memuat unsur 'Where' dan 'When'."], "a": 1, "p": "Judul berita yang baik umumnya mewakili gagasan utama (What atau Who) agar pembaca langsung mengetahui pokok masalah."}, {"lv": 3, "q": "Bacalah ilustrasi berikut:\n'Kebakaran hebat melanda pasar tradisional di pusat kota dini hari tadi akibat korsleting listrik. Petugas pemadam kebakaran mengerahkan sepuluh unit mobil dan berhasil memadamkan api setelah berjibaku selama tiga jam.'\nUnsur 'How' (bagaimana) dalam berita tersebut merujuk pada...", "o": ["Pasar tradisional di pusat kota terbakar dini hari tadi", "Korsleting listrik menjadi pemicu utama kebakaran", "Petugas mengerahkan sepuluh unit mobil dan berjibaku selama tiga jam untuk memadamkan api", "Kerugian ditaksir mencapai miliaran rupiah"], "a": 2, "p": "Unsur 'How' menjelaskan proses atau cara peristiwa itu ditangani, yaitu petugas mengerahkan mobil pemadam dan berjibaku selama tiga jam."}]}, {"id": "bin-k8-1", "name": "Teks eksposisi", "desc": "Tesis, argumen, penegasan ulang", "idx": 1, "soal": [{"lv": 1, "q": "Teks yang bertujuan untuk menyampaikan gagasan, informasi, atau pendapat mengenai suatu topik berdasarkan fakta disebut...", "o": ["Teks narasi", "Teks eksposisi", "Teks prosedur", "Teks recount"], "a": 1, "p": "Teks eksposisi adalah teks yang menyajikan informasi atau gagasan untuk memperluas pengetahuan pembaca berdasarkan argumen dan fakta."}, {"lv": 1, "q": "Bagian awal dalam struktur teks eksposisi yang berisi pengenalan isu, masalah, atau pandangan penulis secara umum disebut...", "o": ["Tesis", "Argumen", "Penegasan ulang", "Kesimpulan cerita"], "a": 0, "p": "Tesis adalah bagian pengenalan atau pendapat awal penulis yang menjadi landasan pembahasan dalam teks eksposisi."}, {"lv": 1, "q": "Bagian tengah teks eksposisi yang memuat alasan, bukti, atau pendukung untuk memperkuat pendapat penulis dinamakan...", "o": ["Tesis", "Abstraksi", "Argumen", "Orientasi"], "a": 2, "p": "Argumen berisi bukti, data, atau alasan logis yang mendukung tesis atau gagasan penulis."}, {"lv": 1, "q": "Bagian akhir teks eksposisi yang berfungsi untuk menyimpulkan kembali atau menegaskan pandangan penulis disebut...", "o": ["Resolusi", "Penegasan ulang", "Klimaks", "Koda"], "a": 1, "p": "Penegasan ulang adalah bagian penutup yang berisi penguatan kembali atas tesis yang telah dibuktikan melalui argumen."}, {"lv": 2, "q": "Perhatikan kalimat berikut: 'Pendidikan karakter sangat penting diterapkan di sekolah untuk membentengi generasi muda dari pengaruh buruk.' Kalimat tersebut dalam struktur teks eksposisi berfungsi sebagai...", "o": ["Tesis", "Argumen pendukung", "Data statistik", "Penegasan ulang"], "a": 0, "p": "Kalimat tersebut menyatakan pendapat atau gagasan utama yang akan dibahas, sehingga berfungsi sebagai tesis."}, {"lv": 2, "q": "Ciri kebahasaan yang dominan dalam teks eksposisi untuk meyakinkan pembaca adalah penggunaan...", "o": ["Kata kiasan dan majas yang indah", "Dialog interaktif antar tokoh", "Fakta dan data yang akurat (seperti angka, hasil penelitian)", "Alur cerita fiktif yang imajinatif"], "a": 2, "p": "Teks eksposisi bersifat objektif dan faktual, sehingga banyak menggunakan data serta fakta untuk memperkuat argumen."}, {"lv": 2, "q": "Manakah di bawah ini yang merupakan contoh kalimat argumen dalam teks eksposisi bertema lingkungan?", "o": ["Sampah plastik menjadi ancaman serius bagi kelestarian bumi kita.", "Berdasarkan data Kementerian Lingkungan Hidup, Indonesia menghasilkan jutaan ton sampah plastik setiap tahun.", "Oleh karena itu, mari kita jaga kebersihan lingkungan mulai dari sekarang.", "Bagaimana cara kita mengurangi penggunaan plastik sekali pakai?"], "a": 1, "p": "Kalimat yang mencantumkan data resmi instansi berfungsi sebagai argumen yang memperkuat tesis."}, {"lv": 2, "q": "Konjungsi kausalitas (sebab-akibat) yang sering digunakan dalam teks eksposisi untuk menghubungkan argumen adalah...", "o": ["Pertama, kedua, selanjutnya", "Karena, sebab, oleh karena itu, akibatnya", "Meskipun, biarpun, walau", "Dan, serta, atau"], "a": 1, "p": "Teks eksposisi sering menggunakan konjungsi kausalitas untuk menunjukkan hubungan sebab-akibat dari suatu permasalahan."}, {"lv": 3, "q": "Bacalah penggalan teks eksposisi rumpang berikut:\n'[...]. Tingginya tingkat konsumsi masyarakat terhadap kendaraan pribadi memicu kemacetan parah di kota-kota besar setiap harinya. Transportasi massal yang nyaman dan terintegrasi adalah solusi utama mengatasi masalah ini.'\nKalimat tesis yang paling tepat untuk mengawali paragraf tersebut adalah...", "o": ["Kemacetan lalu lintas kini telah menjadi masalah pelik di perkotaan.", "Sepeda motor dan mobil pribadi memenuhi jalan raya setiap hari.", "Pemerintah harus segera memperbanyak jumlah polisi lalu lintas.", "Masyarakat perkotaan gemar membeli kendaraan baru."], "a": 0, "p": "Tesis harus mencakup isu utama yang dibahas, yaitu masalah kemacetan pelik di perkotaan yang kemudian dijelaskan pada kalimat berikutnya."}, {"lv": 3, "q": "Analisis kalimat berikut dalam sebuah teks eksposisi:\n'Berdasarkan survei kesehatan nasional, konsumsi gula berlebih terbukti meningkatkan risiko penyakit diabetes pada usia muda.'\nUnsur kebahasaan dan fungsi kalimat tersebut adalah...", "o": ["Merupakan argumen yang didukung oleh fakta survei", "Merupakan pendapat subjektif penulis tanpa dasar", "Merupakan bagian penegasan ulang di akhir teks", "Merupakan kalimat tanya retoris untuk pembaca"], "a": 0, "p": "Kalimat tersebut menyajikan data hasil survei yang berfungsi sebagai argumen berbasis fakta untuk meyakinkan pembaca."}, {"lv": 3, "q": "Perhatikan susunan paragraf acak teks eksposisi berikut:\n1) Penegasan ulang mengenai pentingnya literasi digital.\n2) Tesis tentang rendahnya minat baca masyarakat di era digital.\n3) Argumen berupa data penurunan kunjungan perpustakaan dan maraknya hoaks di media sosial.\n\nSusunan struktur teks eksposisi yang runtut dan benar adalah...", "o": ["1 - 2 - 3", "2 - 3 - 1", "3 - 2 - 1", "2 - 1 - 3"], "a": 1, "p": "Struktur teks eksposisi yang runtut dimulai dari tesis (2), diikuti oleh deretan argumen pendukung (3), dan ditutup dengan penegasan ulang (1)."}, {"lv": 3, "q": "Manakah pernyataan yang paling tepat untuk membedakan teks eksposisi dengan teks persuasi?", "o": ["Teks eksposisi bertujuan meyakinkan pembaca dengan argumen dan fakta, sedangkan teks persuasi bertujuan membujuk atau mengajak pembaca melakukan sesuatu.", "Teks eksposisi menceritakan kejadian masa lalu secara kronologis, sedangkan teks persuasi menjelaskan langkah kerja.", "Teks eksposisi bersifat fiktif imajinatif, sedangkan teks persuasi bersifat ilmiah murni.", "Teks eksposisi tidak memiliki struktur tesis, sedangkan teks persuasi selalu menggunakan dialog."], "a": 0, "p": "Perbedaan utamanya terletak pada tujuan akhir: eksposisi memaparkan informasi/pendapat dengan argumen, sedangkan persuasi bertujuan mengajak atau membujuk pembaca."}]}, {"id": "bin-k8-2", "name": "Kalimat langsung dan tidak langsung", "desc": "Mengubah bentuk kalimat", "idx": 2, "soal": [{"lv": 1, "q": "Ciri utama penulisan kalimat langsung dalam sebuah teks adalah...", "o": ["Diawali dengan konjungsi 'bahwa'", "Diapit oleh tanda petik dua (\"\")", "Menggunakan intonasi yang selalu datar", "Hanya boleh digunakan dalam teks berita"], "a": 1, "p": "Kalimat langsung ditandai dengan penggunaan tanda petik dua untuk menunjukkan kutipan asli dari pembicara."}, {"lv": 1, "q": "Kata hubung (konjungsi) yang umum digunakan untuk mengubah kalimat berita langsung menjadi kalimat tidak langsung adalah...", "o": ["Seandainya", "Meskipun", "Bahwa", "Tetapi"], "a": 2, "p": "Konjungsi 'bahwa' berfungsi sebagai penghubung antara bagian pengiring dan bagian isi dalam kalimat tidak langsung."}, {"lv": 1, "q": "Manakah di bawah ini yang merupakan contoh kalimat tidak langsung?", "o": ["Ibu bertanya, \"Apakah kamu sudah makan?\"", "\"Ayo segera berangkat!\" perintah Ayah.", "Rani mengatakan bahwa ia tidak bisa ikut kerja kelompok.", "Budi berkata: Saya akan pergi ke perpustakaan."], "a": 2, "p": "Kalimat pada pilihan C tidak menggunakan tanda petik dan menggunakan konjungsi 'bahwa', yang merupakan ciri kalimat tidak langsung."}, {"lv": 1, "q": "Dalam pengubahan kalimat langsung menjadi tidak langsung, kata ganti orang pertama 'saya' biasanya berubah menjadi...", "o": ["Kamu", "Kalian", "Mereka", "Dia atau Ia"], "a": 3, "p": "Saat melaporkan ucapan orang lain, sudut pandang berubah dari orang pertama (saya) menjadi orang ketiga (dia/ia)."}, {"lv": 2, "q": "Kalimat langsung: Ibu berkata, \"Aku sangat bangga padamu.\"\nBentuk kalimat tidak langsung yang paling tepat dari kalimat tersebut adalah...", "o": ["Ibu berkata bahwa aku sangat bangga padanya.", "Ibu berkata bahwa dia sangat bangga padaku.", "Ibu berkata bahwa aku sangat bangga padaku.", "Ibu berkata bahwa dia sangat bangga padamu."], "a": 1, "p": "Kata 'Aku' (Ibu) berubah menjadi 'dia', dan 'padamu' (orang yang diajak bicara) berubah menjadi 'padaku' dalam sudut pandang pelapor."}, {"lv": 2, "q": "Kalimat tidak langsung: Ayah menanyakan kapan adik akan pulang.\nBentuk kalimat langsung yang tepat untuk kalimat tersebut adalah...", "o": ["Ayah bertanya, \"Kapan adik akan pulang?\"", "Ayah bertanya, \"Kapan aku akan pulang?\"", "Ayah berkata, \"Adik akan pulang besok.\"", "\"Kapan kamu pulang, Ayah?\" tanya adik."], "a": 0, "p": "Kalimat langsung harus mempertahankan isi pertanyaan Ayah dengan menggunakan tanda petik dan tanda tanya."}, {"lv": 2, "q": "Kalimat langsung: \"Tolong ambilkan buku itu!\" perintah Pak Guru kepada Budi.\nBentuk kalimat tidak langsung yang benar adalah...", "o": ["Pak Guru berkata bahwa Budi mengambil buku itu.", "Pak Guru menyuruh Budi untuk mengambilkan buku itu.", "Pak Guru bertanya apakah Budi bisa mengambilkan buku itu.", "Budi diperintah Pak Guru untuk membaca buku itu."], "a": 1, "p": "Kalimat perintah dalam bentuk tidak langsung diubah menggunakan kata kerja bermakna perintah seperti 'menyuruh' atau 'meminta'."}, {"lv": 2, "q": "Kalimat tidak langsung: Kakak berkata bahwa dia akan membelikanku oleh-oleh.\nBentuk kalimat langsung dari kalimat di atas adalah...", "o": ["Kakak berkata, \"Dia akan membelikanmu oleh-oleh.\"", "\"Kakak akan membelikan dia oleh-oleh,\" kata kakak.", "Kakak berkata, \"Aku akan membelikanmu oleh-oleh.\"", "\"Aku akan membelikan dia oleh-oleh,\" kata kakak."], "a": 2, "p": "Kata ganti 'dia' pada kalimat tidak langsung merujuk pada Kakak, maka di kalimat langsung kembali menjadi 'Aku'."}, {"lv": 3, "q": "Kalimat langsung: Rian berkata, \"Saya akan mengerjakan tugas ini sekarang.\"\nJika diubah menjadi kalimat tidak langsung yang memperhatikan perubahan waktu dan tempat, kalimatnya menjadi...", "o": ["Rian berkata bahwa dia akan mengerjakan tugas itu saat itu juga.", "Rian berkata bahwa saya akan mengerjakan tugas ini sekarang.", "Rian berkata bahwa dia akan mengerjakan tugas ini sekarang.", "Rian mengatakan bahwa Rian akan mengerjakan tugasnya sekarang."], "a": 0, "p": "Dalam kalimat tidak langsung yang teliti, kata penunjuk 'ini' berubah menjadi 'itu' dan 'sekarang' berubah menjadi 'saat itu'."}, {"lv": 3, "q": "Kalimat langsung: \"Kami akan berkunjung ke rumah nenek besok,\" kata mereka kepada kami.\nBentuk kalimat tidak langsung yang paling benar adalah...", "o": ["Mereka berkata bahwa kami akan berkunjung ke rumah nenek besok.", "Mereka mengatakan bahwa mereka akan berkunjung ke rumah nenek besok.", "Mereka mengatakan kepada kami bahwa mereka akan berkunjung ke rumah nenek keesokan harinya.", "Mereka mengatakan bahwa kami akan berkunjung ke rumah nenek keesokan harinya."], "a": 2, "p": "Terdapat perubahan kata ganti 'kami' menjadi 'mereka', dan keterangan waktu 'besok' menjadi 'keesokan harinya'."}, {"lv": 3, "q": "Manakah perubahan kalimat langsung ke tidak langsung di bawah ini yang paling sesuai dengan kaidah bahasa?", "o": ["\"Di mana tinggal?\" tanya Andi -> Andi menanyakan bahwa di mana saya tinggal.", "\"Aku sudah makan,\" kata Ani -> Ani berkata bahwa dia sudah makan.", "\"Jangan berisik!\" seru Ibu -> Ibu menyerukan jangan berisik.", "\"Saya lulus!\" teriak Eko -> Eko berteriak bahwa saya lulus."], "a": 1, "p": "Pilihan B adalah perubahan yang paling tepat. Pilihan A salah karena konjungsi ganda, pilihan D salah karena kata ganti tidak berubah."}, {"lv": 3, "q": "Kalimat langsung: Pak Guru bertanya kepada Andi, \"Mengapa kamu tidak masuk sekolah kemarin?\"\nBentuk kalimat tidak langsung yang paling tepat adalah...", "o": ["Pak Guru menanyakan Andi alasan kamu tidak masuk sekolah kemarin.", "Pak Guru bertanya kepada Andi mengapa dia tidak masuk sekolah kemarin.", "Pak Guru bertanya kepada Andi alasan ia tidak masuk sekolah sehari sebelumnya.", "Pak Guru menanyakan bahwa Andi tidak masuk sekolah kemarin."], "a": 2, "p": "Kalimat tidak langsung untuk pertanyaan membutuhkan perubahan kata ganti (kamu -> ia) dan keterangan waktu (kemarin -> sehari sebelumnya)."}]}], "9": [{"id": "bin-k9-0", "name": "Teks laporan percobaan", "desc": "Tujuan, alat, langkah, hasil", "idx": 0, "soal": [{"lv": 1, "q": "Teks laporan percobaan bertujuan untuk...", "o": ["Menceritakan pengalaman pribadi saat liburan", "Menginformasikan hasil pengujian atau pengamatan secara objektif", "Membujuk pembaca agar membeli produk tertentu", "Menjelaskan langkah-langkah membuat kerajinan tangan"], "a": 1, "p": "Teks laporan percobaan berfungsi untuk menyampaikan informasi hasil kerja ilmiah berdasarkan fakta dan data nyata setelah melakukan pengujian."}, {"lv": 1, "q": "Bagian teks laporan percobaan yang berisi benda-benda yang digunakan untuk melakukan kegiatan disebut...", "o": ["Hasil percobaan", "Langkah-langkah", "Alat dan bahan", "Tujuan"], "a": 2, "p": "Bagian 'Alat dan Bahan' memuat daftar peralatan serta material yang diperlukan untuk menjalankan percobaan tersebut."}, {"lv": 1, "q": "Salah satu ciri kebahasaan teks laporan percobaan yang menonjol adalah penggunaan istilah ilmiah. Manakah kata di bawah ini yang merupakan istilah ilmiah?", "o": ["Sangat bagus", "Bekerja keras", "Fotosintesis", "Berlari kencang"], "a": 2, "p": "Istilah ilmiah adalah kata yang memiliki makna khusus di bidang ilmu pengetahuan, seperti 'fotosintesis' yang merujuk pada proses pembuatan makanan pada tumbuhan."}, {"lv": 1, "q": "Pernyataan yang memuat intisari atau jawaban akhir dari percobaan yang telah dilakukan disebut...", "o": ["Simpulan", "Tujuan", "Latar Belakang", "Langkah-langkah"], "a": 0, "p": "Simpulan adalah bagian akhir yang menyimpulkan seluruh proses dan hasil percobaan berdasarkan tujuan awal yang ingin dicapai."}, {"lv": 2, "q": "Perhatikan kutipan berikut: 'Campurkan dua sendok cuka ke dalam gelas yang berisi air, kemudian amati perubahan warnanya.'\n\nKutipan tersebut termasuk ke dalam bagian struktur...", "o": ["Hasil percobaan", "Tujuan percobaan", "Langkah-langkah", "Kajian teori"], "a": 2, "p": "Kalimat tersebut menggunakan kata kerja perintah (campurkan, amati) yang menunjukkan urutan kegiatan atau instruksi kerja."}, {"lv": 2, "q": "Perhatikan data berikut:\n1) Masukkan kentang ke dalam larutan garam.\n2) Kupas kentang dan potong dadu.\n3) Timbang berat kentang setelah 15 menit.\n4) Siapkan gelas berisi air garam.\n\nUrutan langkah percobaan yang benar adalah...", "o": ["2-4-1-3", "4-2-1-3", "2-1-4-3", "4-1-2-3"], "a": 0, "p": "Urutan logisnya dimulai dengan menyiapkan bahan (2), menyiapkan wadah (4), memasukkan bahan (1), dan terakhir mengukur hasil (3)."}, {"lv": 2, "q": "Manakah kalimat berikut yang merupakan bagian 'Hasil Percobaan'?", "o": ["Kita harus menggunakan sarung tangan saat mencampur bahan kimia.", "Percobaan ini dilakukan untuk membuktikan adanya vitamin C.", "Setelah ditetesi betadine, larutan berubah warna menjadi bening.", "Potonglah buah menjadi bagian yang lebih kecil."], "a": 2, "p": "Hasil percobaan mendeskripsikan fenomena atau perubahan fisik yang terjadi dan dapat diamati secara nyata."}, {"lv": 2, "q": "Dalam teks laporan percobaan, penulisan kalimat haruslah objektif. Manakah kalimat yang memenuhi syarat tersebut?", "o": ["Percobaan ini sangat membosankan bagi kelompok kami.", "Tumbuhan yang diberi pupuk A tumbuh 5 cm lebih tinggi daripada pupuk B.", "Sepertinya campuran ini akan meledak jika dibiarkan.", "Hasil pengamatan kami menunjukkan warna yang sangat indah."], "a": 1, "p": "Kalimat objektif didasarkan pada fakta yang dapat diukur (seperti 5 cm), bukan pada opini atau perasaan penulis."}, {"lv": 3, "q": "Bacalah teks berikut: 'Tanaman yang diletakkan di tempat gelap memiliki batang yang lebih panjang namun pucat, sedangkan tanaman di tempat terang tumbuh lebih kokoh dan hijau.'\n\nSimpulan yang paling tepat untuk teks tersebut adalah...", "o": ["Tanaman lebih baik diletakkan di tempat gelap agar cepat tinggi.", "Warna tanaman tidak dipengaruhi oleh keberadaan cahaya matahari.", "Cahaya matahari menghambat pertumbuhan panjang batang secara berlebihan.", "Cahaya matahari sangat memengaruhi kualitas dan kesehatan pertumbuhan tanaman."], "a": 3, "p": "Berdasarkan perbandingan pertumbuhan (kokoh/hijau vs pucat), simpulan yang logis adalah cahaya sangat krusial bagi kualitas kesehatan tumbuhan."}, {"lv": 3, "q": "Teks laporan percobaan: 'Percobaan ini dilakukan untuk mengetahui pengaruh jenis air terhadap pertumbuhan kacang hijau. Variabel yang diubah adalah jenis air (mineral, teh, dan cucian beras).'\n\nApa tujuan utama dari percobaan tersebut?", "o": ["Mencari tahu cara menanam kacang hijau agar cepat panen.", "Menguji air mana yang paling cepat merusak tanaman.", "Menganalisis perbandingan pertumbuhan kacang hijau dengan variasi jenis air.", "Membuktikan bahwa semua air memiliki pengaruh yang identik."], "a": 2, "p": "Tujuan percobaan dirumuskan untuk mencari jawaban atas pengaruh variabel yang diuji (berbagai jenis air) terhadap subjek (kacang hijau)."}, {"lv": 3, "q": "Siswa diminta melaporkan hasil percobaan membuat pelangi buatan. Manakah rincian 'Hasil' yang paling teknis dan lengkap?", "o": ["Pelangi yang terbentuk terlihat sangat cantik di dinding kamar saya.", "Cahaya senter yang melewati gelas berisi air membiaskan spektrum warna pada kertas putih.", "Langkah-langkah yang kami lakukan sudah sesuai prosedur sehingga pelangi muncul.", "Kami memerlukan senter, gelas, air, dan cermin untuk melakukan kegiatan ini."], "a": 1, "p": "Laporan hasil yang baik harus menjelaskan mekanisme terjadinya fenomena (pembiasan cahaya) dan hasil yang teramati secara spesifik."}, {"lv": 3, "q": "Apa perbedaan mendasar antara teks prosedur dengan teks laporan percobaan?", "o": ["Teks prosedur fokus pada instruksi kerja, sedangkan laporan percobaan fokus pada data hasil dan bukti pengujian ilmiah.", "Teks prosedur cenderung lebih panjang dibandingkan teks laporan percobaan.", "Teks laporan percobaan tidak memerlukan rincian langkah-langkah pengerjaan.", "Teks prosedur bersifat objektif, sementara laporan percobaan bersifat imajinatif."], "a": 0, "p": "Teks prosedur hanya memberikan petunjuk cara melakukan sesuatu, sedangkan laporan percobaan memaparkan bukti dan kesimpulan dari suatu pengujian ilmiah."}]}, {"id": "bin-k9-1", "name": "Teks pidato persuasif", "desc": "Ajakan dan struktur pidato", "idx": 1, "soal": [{"lv": 1, "q": "Tujuan utama dari sebuah teks pidato persuasif adalah...", "o": ["Menceritakan urutan peristiwa sejarah secara detail", "Mempengaruhi dan mengajak pendengar untuk melakukan sesuatu", "Menghibur audiens dengan cerita-cerita lucu", "Menjelaskan cara mengoperasikan suatu alat"], "a": 1, "p": "Pidato persuasif bertujuan untuk meyakinkan audiens agar percaya, mengubah pandangan, atau mengikuti ajakan yang disampaikan oleh pembicara."}, {"lv": 1, "q": "Struktur teks pidato persuasif yang benar secara berurutan adalah...", "o": ["Pembukaan, Isi, Penutup", "Tujuan, Langkah-langkah, Simpulan", "Orientasi, Komplikasi, Resolusi", "Pernyataan Umum, Deskripsi Bagian, Simpulan"], "a": 0, "p": "Secara garis besar, pidato persuasif terdiri dari tiga bagian utama: Pembukaan (salam, sapaan, syukur), Isi (posisi, argumen, ajakan), dan Penutup."}, {"lv": 1, "q": "Bagian pidato yang berisi ucapan syukur kepada Tuhan dan penghormatan kepada tamu undangan disebut...", "o": ["Isi pidato", "Simpulan pidato", "Pembukaan pidato", "Penutup pidato"], "a": 2, "p": "Bagian pembukaan berfungsi untuk memulai komunikasi, mencakup salam pembuka, ucapan hormat kepada hadirin, dan puji syukur."}, {"lv": 1, "q": "Kata-kata yang menjadi ciri khas dalam teks pidato persuasif untuk mengajak audiens adalah...", "o": ["Dahulu kala, alkisah", "Mungkin, sepertinya", "Karena, sehingga", "Ayo, mari, marilah"], "a": 3, "p": "Kata imperatif dan ajakan seperti 'ayo' dan 'mari' merupakan ciri kebahasaan utama untuk menggerakkan audiens dalam teks persuasif."}, {"lv": 2, "q": "Perhatikan kalimat berikut: 'Marilah kita jaga kebersihan sekolah kita mulai dari diri sendiri dengan membuang sampah pada tempatnya.'\n\nDalam struktur pidato persuasif, kalimat tersebut termasuk ke dalam bagian...", "o": ["Pernyataan posisi", "Tahap argumen", "Penguatan pernyataan posisi", "Salam pembuka"], "a": 2, "p": "Kalimat ajakan nyata yang merupakan inti dari persuasi biasanya diletakkan pada bagian akhir isi sebagai penguatan atau penegasan ulang posisi penulis."}, {"lv": 2, "q": "Bagian 'Pernyataan Posisi' dalam pidato persuasif berisi tentang...", "o": ["Daftar pustaka dari sumber pidato", "Pandangan atau pendapat penulis terhadap isu yang dibahas", "Kumpulan data statistik untuk membuktikan kebenaran", "Permohonan maaf jika ada kata yang salah"], "a": 1, "p": "Pernyataan posisi adalah tahap awal dalam isi pidato di mana pembicara menetapkan sudut pandang atau sikapnya terhadap topik yang diangkat."}, {"lv": 2, "q": "Manakah kalimat berikut yang menggunakan pendekatan 'Etika' dalam berpidato?", "o": ["Kebersihan adalah bagian dari iman, maka menjaga lingkungan adalah kewajiban kita semua.", "Bayangkan betapa sedihnya orang tua jika kita tidak lulus sekolah.", "Sampah plastik membutuhkan waktu ratusan tahun untuk bisa terurai secara alami.", "Jika kita rajin belajar, nilai rapor kita pasti akan meningkat drastis."], "a": 0, "p": "Pendekatan etika mengaitkan ajakan dengan nilai-nilai moral, kebenaran umum, norma, atau kaidah agama."}, {"lv": 2, "q": "Perhatikan kutipan ini: 'Rekan-rekan sekalian, penggunaan gawai yang berlebihan dapat merusak kesehatan mata. Berdasarkan riset terbaru, paparan cahaya biru menghambat hormon tidur.'\n\nKutipan di atas merupakan bagian...", "o": ["Salam pembuka", "Simpulan", "Pernyataan posisi", "Tahap argumen"], "a": 3, "p": "Bagian ini menyajikan fakta, data, atau alasan logis untuk mendukung pandangan pembicara, sehingga disebut tahap rangkaian argumen."}, {"lv": 3, "q": "Bacalah kutipan pidato berikut: 'Dunia saat ini sedang menangis karena sampah plastik yang menumpuk. Jika kita tidak bergerak sekarang, anak cucu kita kelak hanya akan mewarisi lautan plastik, bukan lautan biru yang indah.'\n\nCara persuasif yang digunakan pembicara dalam kutipan tersebut adalah menyentuh aspek...", "o": ["Logika (pikiran)", "Etika (moral)", "Emosi (perasaan)", "Otoritas (kekuasaan)"], "a": 2, "p": "Penggunaan frasa 'dunia menangis' dan 'nasib anak cucu' bertujuan menggugah perasaan, simpati, atau empati audiens (pendekatan emosi)."}, {"lv": 3, "q": "Kalimat mana yang paling efektif sebagai kalimat penutup pidato persuasif bertema 'Bahaya Narkoba'?", "o": ["Narkoba adalah zat kimia yang sangat berbahaya bagi saraf manusia.", "Oleh karena itu, mari kita rapatkan barisan, katakan tidak pada narkoba demi masa depan yang gemilang!", "Demikian informasi yang saya berikan, semoga kalian tidak mengonsumsi narkoba.", "Terima kasih atas perhatiannya, mohon maaf jika ada kesalahan kata saat saya berpidato."], "a": 1, "p": "Penutup pidato persuasif yang efektif harus mengandung simpulan yang kuat disertai ajakan yang membakar semangat atau bersifat instruktif."}, {"lv": 3, "q": "Bacalah teks berikut: 'Pendidikan bukan hanya soal nilai di atas kertas. Pendidikan adalah proses membentuk karakter. Tanpa karakter, kecerdasan hanyalah alat untuk merusak diri sendiri dan orang lain.'\n\nIde pokok atau pesan yang ingin disampaikan pembicara adalah...", "o": ["Pentingnya karakter sebagai fondasi utama dalam pendidikan", "Kecerdasan tidak penting bagi masa depan seseorang", "Nilai di atas kertas adalah prioritas utama pendidikan", "Pendidikan harus dihentikan jika tidak membentuk karakter"], "a": 0, "p": "Teks tersebut menekankan bahwa inti dari pendidikan sejati adalah pembentukan karakter agar kecerdasan seseorang memberikan dampak positif."}, {"lv": 3, "q": "Dalam sebuah pidato tentang hemat energi, pembicara mengatakan: 'Satu lampu yang kita matikan hari ini adalah cahaya bagi masa depan.'\n\nMakna tersirat dari kalimat tersebut adalah...", "o": ["Lampu masa depan akan menyala otomatis jika kita mematikan lampu sekarang", "Mematikan lampu akan membuat masa depan menjadi gelap gulita", "Kita tidak membutuhkan banyak lampu untuk menerangi dunia", "Tindakan kecil saat ini berdampak besar bagi kelangsungan energi di masa depan"], "a": 3, "p": "Kalimat tersebut merupakan metafora yang menjelaskan bahwa penghematan kecil yang dilakukan saat ini sangat menentukan ketersediaan sumber daya bagi generasi mendatang."}]}, {"id": "bin-k9-2", "name": "Cerpen", "desc": "Unsur intrinsik cerpen", "idx": 2, "soal": [{"lv": 1, "q": "Pesan moral atau pelajaran hidup yang ingin disampaikan penulis kepada pembaca melalui cerpen disebut...", "o": ["Amanat", "Alur", "Latar", "Tema"], "a": 0, "p": "Amanat adalah pesan atau nasihat yang terkandung dalam cerita untuk dipetik manfaatnya oleh pembaca."}, {"lv": 1, "q": "Posisi penulis dalam membawakan cerita, misalnya menggunakan kata ganti 'Aku' atau 'Dia', disebut...", "o": ["Latar tempat", "Gaya bahasa", "Sudut pandang", "Penokohan"], "a": 2, "p": "Sudut pandang adalah cara pandang penulis dalam memposisikan dirinya di dalam sebuah cerita."}, {"lv": 1, "q": "Unsur yang berkaitan dengan keterangan tempat, waktu, dan suasana dalam cerpen adalah...", "o": ["Tema", "Latar", "Penokohan", "Konflik"], "a": 1, "p": "Latar (setting) memberikan gambaran kapan, di mana, dan dalam situasi apa peristiwa dalam cerpen terjadi."}, {"lv": 1, "q": "Rangkaian peristiwa yang menjalin sebuah cerita dari awal hingga akhir berdasarkan urutan waktu atau hubungan sebab-akibat disebut...", "o": ["Latar", "Sudut pandang", "Amanat", "Alur"], "a": 3, "p": "Alur atau plot adalah struktur jalannya peristiwa dalam cerpen yang membentuk satu kesatuan cerita."}, {"lv": 2, "q": "Perhatikan kutipan cerpen berikut: 'Mentari mulai bersembunyi di balik perbukitan. Cahaya jingga terpantul di permukaan danau yang tenang. Burung-burung terbang kembali ke sarangnya.'\n\nLatar waktu yang digambarkan dalam kutipan tersebut adalah...", "o": ["Pagi hari", "Sore hari", "Tengah malam", "Siang hari"], "a": 1, "p": "Frasa 'mentari bersembunyi' dan 'cahaya jingga' adalah ciri khas waktu senja atau matahari terbenam (sore hari)."}, {"lv": 2, "q": "Perhatikan kutipan berikut: 'Setiap kali melihat dompet temannya terbuka, ia selalu memalingkan muka dan segera menjauh. Ia tak ingin rasa iri mengalahkan kejujurannya.'\n\nWatak tokoh dalam kutipan cerpen di atas adalah...", "o": ["Pemberani", "Sombong", "Jujur", "Pemalu"], "a": 2, "p": "Tokoh memilih menjauh agar tidak tergoda mengambil milik orang lain, yang menunjukkan sifat jujur dan menjaga integritas."}, {"lv": 2, "q": "Kutipan cerpen: 'Aku menatap jendela kereta yang basah oleh air hujan. Pikiranku melayang pada kejadian setahun lalu saat aku pertama kali meninggalkan kota ini.'\n\nSudut pandang yang digunakan dalam kutipan cerpen tersebut adalah...", "o": ["Orang pertama pelaku utama", "Orang ketiga serba tahu", "Orang ketiga pengamat", "Orang kedua"], "a": 0, "p": "Penggunaan kata ganti 'Aku' yang terlibat langsung dalam pikiran dan peristiwa menunjukkan sudut pandang orang pertama pelaku utama."}, {"lv": 2, "q": "Perhatikan kutipan berikut: 'Suasana di dalam ruangan itu terasa sangat mencekam. Tak ada yang berani bersuara, bahkan untuk sekadar menarik napas panjang.'\n\nLatar suasana yang digambarkan adalah...", "o": ["Gembira", "Menyedihkan", "Mengharukan", "Tegang"], "a": 3, "p": "Kata 'mencekam' dan deskripsi 'tak ada yang berani bersuara' menggambarkan situasi yang penuh tekanan atau tegang."}, {"lv": 3, "q": "Dalam cerpen 'Rindu Ibu', tokoh utama merasa bimbang antara harus pergi merantau demi pendidikan atau tetap di desa menjaga ibunya yang sakit. Konflik yang dialami tokoh tersebut adalah...", "o": ["Konflik fisik", "Konflik sosial", "Konflik batin", "Konflik alam"], "a": 2, "p": "Konflik batin adalah pertentangan yang dialami tokoh di dalam jiwanya sendiri, seperti kebimbangan dalam mengambil keputusan."}, {"lv": 3, "q": "Penulis mendeskripsikan watak tokoh melalui cara berpakaian, cara berbicara, dan lingkungan tempat tinggalnya tanpa menyebutkan sifatnya secara langsung. Teknik penokohan ini disebut...", "o": ["Teknik analitik", "Teknik dramatik", "Teknik naratif", "Teknik objektif"], "a": 1, "p": "Teknik dramatik menggambarkan watak melalui tingkah laku, fisik, dialog, atau lingkungan secara tidak langsung."}, {"lv": 3, "q": "Perhatikan kutipan ini: 'Jangan pernah meremehkan langkah kecil. Ingatlah bahwa sebuah pohon beringin yang megah pun dulunya hanya berawal dari satu biji yang mungil.'\n\nAmanat yang paling tepat dari kutipan di atas adalah...", "o": ["Kita harus menghargai setiap proses dan usaha sekecil apa pun", "Pohon beringin adalah pohon yang paling kuat", "Biji kecil tidak akan bisa tumbuh tanpa bantuan", "Jangan bermain di bawah pohon beringin"], "a": 0, "p": "Metafora biji kecil menjadi pohon megah mengandung pesan bahwa setiap awal atau usaha kecil sangat berharga untuk kesuksesan besar."}, {"lv": 3, "q": "Sebuah cerpen dimulai dengan adegan pemakaman, lalu menceritakan masa muda tokoh hingga ia meninggal. Jenis alur yang digunakan cerpen tersebut adalah...", "o": ["Alur maju", "Alur campuran", "Alur sorot balik", "Alur mundur"], "a": 3, "p": "Alur mundur dimulai dari akhir peristiwa (kematian) lalu kembali menceritakan masa lalu tokoh tersebut."}]}]}, "ipa": {"10": [{"id": "ipa-k10-0", "name": "Fisika: Gerak lurus", "desc": "GLB dan GLBB", "idx": 0, "soal": [{"lv": 1, "q": "Karakteristik utama dari Gerak Lurus Beraturan (GLB) adalah...", "o": ["Kecepatannya berubah secara teratur", "Percepatannya selalu berubah-ubah", "Kecepatannya tetap dan percepatannya nol", "Lintasannya berbentuk melingkar"], "a": 2, "p": "Pada GLB, benda bergerak dengan kecepatan konstan (tetap), sehingga tidak ada perubahan kecepatan yang berarti percepatannya adalah nol."}, {"lv": 1, "q": "Gerak suatu benda pada lintasan lurus dengan percepatan yang konstan atau tetap disebut...", "o": ["Gerak Lurus Beraturan", "Gerak Lurus Berubah Beraturan", "Gerak Parabola", "Gerak Jatuh Bebas tanpa percepatan"], "a": 1, "p": "GLBB (Gerak Lurus Berubah Beraturan) didefinisikan sebagai gerak benda pada lintasan lurus dengan perubahan kecepatan yang teratur (percepatan tetap)."}, {"lv": 1, "q": "Satuan standar internasional (SI) untuk besaran percepatan adalah...", "o": ["m/s", "m.s", "m/s²", "km/jam"], "a": 2, "p": "Percepatan adalah perubahan kecepatan per satuan waktu. Karena kecepatan bersatuan m/s dibagi waktu (s), maka satuannya menjadi m/s²."}, {"lv": 1, "q": "Besaran vektor yang menunjukkan perubahan posisi suatu benda dari titik awal ke titik akhir disebut...", "o": ["Jarak", "Kelajuan", "Perpindahan", "Lintasan"], "a": 2, "p": "Perpindahan adalah besaran vektor yang hanya memperhitungkan posisi awal dan akhir, sedangkan jarak adalah besaran skalar panjang lintasan total."}, {"lv": 2, "q": "Sebuah mobil melaju dengan kecepatan tetap 20 m/s di jalan tol. Jarak yang ditempuh mobil tersebut selama 10 detik adalah...", "o": ["2 meter", "100 meter", "150 meter", "200 meter"], "a": 3, "p": "Menggunakan rumus GLB: s = v x t. Maka jarak s = 20 m/s x 10 s = 200 meter."}, {"lv": 2, "q": "Sebuah sepeda motor yang awalnya diam kemudian dipercepat hingga kecepatannya menjadi 15 m/s dalam waktu 5 detik. Percepatan motor tersebut adalah...", "o": ["3 m/s²", "5 m/s²", "10 m/s²", "75 m/s²"], "a": 0, "p": "Rumus percepatan: a = (vt - v0) / t. Maka a = (15 - 0) / 5 = 3 m/s²."}, {"lv": 2, "q": "Sebuah benda bergerak dari keadaan diam dengan percepatan tetap 2 m/s². Berapakah jarak yang ditempuh benda tersebut setelah bergerak selama 4 detik?", "o": ["8 meter", "16 meter", "32 meter", "64 meter"], "a": 1, "p": "Rumus jarak GLBB: s = v0.t + 1/2.a.t². Karena diam (v0=0), maka s = 1/2 x 2 x 4² = 16 meter."}, {"lv": 2, "q": "Mobil yang sedang melaju dengan kecepatan 10 m/s direm hingga berhenti dalam waktu 2 detik. Besar percepatan (perlambatan) mobil tersebut adalah...", "o": ["-5 m/s²", "5 m/s²", "-10 m/s²", "20 m/s²"], "a": 0, "p": "a = (vt - v0) / t. Karena berhenti, vt = 0. Maka a = (0 - 10) / 2 = -5 m/s². Tanda negatif menunjukkan perlambatan."}, {"lv": 3, "q": "Sebuah benda bergerak dengan kecepatan awal 5 m/s dan mengalami percepatan tetap 2 m/s². Kecepatan benda tersebut setelah menempuh jarak sejauh 6 meter adalah...", "o": ["6 m/s", "8 m/s", "9 m/s", "7 m/s"], "a": 3, "p": "Menggunakan rumus vt² = v0² + 2as. vt² = 5² + 2(2)(6) = 25 + 24 = 49. Maka vt = √49 = 7 m/s."}, {"lv": 3, "q": "Dua mobil A dan B berada di titik yang sama. Mobil A bergerak dengan kecepatan tetap 10 m/s. Mobil B yang awalnya diam mulai bergerak bersamaan dengan A dengan percepatan tetap 2 m/s². Setelah berapa detik mobil B akan menyalip mobil A?", "o": ["5 detik", "10 detik", "15 detik", "20 detik"], "a": 1, "p": "B menyalip A saat jaraknya sama (sA = sB). vA.t = 1/2.aB.t² -> 10t = 1/2 . 2 . t² -> 10t = t² -> t = 10 detik."}, {"lv": 3, "q": "Sebuah kereta api melaju dengan kecepatan 30 m/s, kemudian direm dengan perlambatan tetap 3 m/s². Jarak total yang ditempuh kereta tersebut dari mulai direm hingga berhenti sempurna adalah...", "o": ["10 meter", "100 meter", "150 meter", "300 meter"], "a": 2, "p": "Gunakan vt² = v0² + 2as. Karena berhenti vt=0 dan perlambatan a=-3. 0 = 30² + 2(-3)s -> 0 = 900 - 6s -> 6s = 900 -> s = 150 meter."}, {"lv": 3, "q": "Jika grafik hubungan kecepatan (v) terhadap waktu (t) suatu benda membentuk garis lurus miring ke atas yang dimulai dari titik asal (0,0), maka dapat dianalisis bahwa benda tersebut...", "o": ["Sedang bergerak lurus beraturan", "Memiliki kecepatan yang berkurang secara teratur", "Sedang bergerak lurus berubah beraturan dipercepat", "Berada dalam keadaan diam atau tidak bergerak"], "a": 2, "p": "Gradien atau kemiringan pada grafik v-t menunjukkan percepatan. Garis lurus miring ke atas berarti kecepatan bertambah secara teratur, yang merupakan ciri GLBB dipercepat."}]}, {"id": "ipa-k10-1", "name": "Kimia: Struktur atom", "desc": "Partikel atom dan konfigurasi elektron", "idx": 1, "soal": [{"lv": 1, "q": "Partikel penyusun atom yang bermuatan listrik negatif disebut...", "o": ["Proton", "Neutron", "Elektron", "Positron"], "a": 2, "p": "Elektron adalah partikel subatomik yang bermuatan negatif dan mengelilingi inti atom."}, {"lv": 1, "q": "Inti atom (nukleus) tersusun atas partikel...", "o": ["Elektron dan proton", "Proton dan neutron", "Elektron dan neutron", "Proton dan positron"], "a": 1, "p": "Inti atom terdiri dari nukleon, yaitu proton (bermuatan positif) dan neutron (tidak bermuatan)."}, {"lv": 1, "q": "Nomor atom suatu unsur menunjukkan jumlah...", "o": ["Neutron di dalam inti", "Total proton dan neutron", "Proton di dalam inti atom", "Elektron di kulit terluar"], "a": 2, "p": "Nomor atom (Z) menyatakan jumlah proton yang terdapat di dalam inti atom, yang pada atom netral juga sama dengan jumlah elektronnya."}, {"lv": 1, "q": "Atom netral unsur Natrium memiliki nomor atom 11 dan nomor massa 23. Jumlah neutron yang dimiliki atom tersebut adalah...", "o": ["11", "12", "23", "34"], "a": 1, "p": "Jumlah neutron dihitung dari selisih nomor massa dan nomor atom (proton): Neutron = 23 - 11 = 12."}, {"lv": 2, "q": "Suatu ion X²⁺ memiliki 18 elektron dan 20 neutron. Berapakah nomor massa dari unsur X tersebut?", "o": ["36", "38", "40", "42"], "a": 2, "p": "Ion X²⁺ bermuatan +2 berarti atom netralnya memiliki 18 + 2 = 20 elektron (dan 20 proton). Nomor massa = proton + neutron = 20 + 20 = 40."}, {"lv": 2, "q": "Konfigurasi elektron atom unsur dengan nomor atom 19 menurut teori kulit utama (K, L, M, N) adalah...", "o": ["2 - 8 - 9", "2 - 8 - 8 - 1", "2 - 17", "2 - 8 - 7 - 2"], "a": 1, "p": "Kapasitas maksimum kulit K(2), L(8), M(18). Sisa elektron setelah kulit M terisi penuh 8 adalah 1, sehingga mengisi kulit N. Konfigurasinya 2 - 8 - 8 - 1."}, {"lv": 2, "q": "Atom-atom yang memiliki nomor atom (jumlah proton) yang sama tetapi nomor massa (jumlah neutron) yang berbeda disebut...", "o": ["Isotop", "Isobar", "Isoton", "Isoelektron"], "a": 0, "p": "Isotop adalah unsur-unsur sejenis yang memiliki nomor atom sama namun nomor massanya berbeda karena jumlah neutronnya tidak sama."}, {"lv": 2, "q": "Jumlah elektron maksimum yang dapat menempati kulit atom utama bernomor n = 3 (kulit M) adalah...", "o": ["8 elektron", "18 elektron", "32 elektron", "50 elektron"], "a": 1, "p": "Jumlah maksimum elektron pada kulit utama dirumuskan dengan 2n². Untuk n = 3, maka 2(3²) = 2 x 9 = 18 elektron."}, {"lv": 3, "q": "Unsur Y memiliki konfigurasi elektron subkulit: 1s² 2s² 2p⁶ 3s² 3p³. Berapakah jumlah elektron valensi dari unsur Y tersebut?", "o": ["2 elektron", "3 elektron", "5 elektron", "15 elektron"], "a": 2, "p": "Elektron valensi adalah elektron pada kulit terluar. Untuk unsur Y, kulit terluar adalah n = 3 (3s² 3p³), sehingga jumlah elektron valensinya adalah 2 + 3 = 5."}, {"lv": 3, "q": "Ion P³⁻ memiliki konfigurasi elektron 1s² 2s² 2p⁶ 3s² 3p⁶. Berapakah nomor atom dari unsur P tersebut?", "o": ["15", "18", "21", "12"], "a": 0, "p": "Ion P³⁻ terbentuk karena atom netralnya menangkap 3 elektron, sehingga total elektronnya saat ini adalah 18. Jumlah elektron atom netral P adalah 18 - 3 = 15 (nomor atom = 15)."}, {"lv": 3, "q": "Pasangan atom atau ion berikut yang memiliki jumlah elektron yang sama (isoelektronik) adalah...", "o": ["Na (Nomor atom 11) dan Mg (Nomor atom 12)", "Na⁺ (Nomor atom 11) dan F⁻ (Nomor atom 9)", "O²⁻ (Nomor atom 8) dan Ne (Nomor atom 10)", "Cl (Nomor atom 17) dan Ar (Nomor atom 18)"], "a": 2, "p": "Ion O²⁻ (8 + 2 = 10 elektron) memiliki jumlah elektron yang sama dengan atom netral Neon (10 elektron)."}, {"lv": 3, "q": "Suatu unsur netral mempunyai konfigurasi elektron [Ar] 4s² 3d¹⁰ 4p⁴. Di periode dan golongan berapakah unsur tersebut terletak dalam tabel periodik?", "o": ["Periode 4, Golongan VI A (16)", "Periode 4, Golongan VI B", "Periode 3, Golongan IV A", "Periode 4, Golongan IV A (14)"], "a": 0, "p": "Nomor kulit terbesar adalah 4 (Periode 4). Elektron valensi berada pada 4s² 4p⁴ (total 2 + 4 = 6 elektron), sehingga berada di Golongan VI A (16)."}]}, {"id": "ipa-k10-2", "name": "Biologi: Keanekaragaman hayati", "desc": "Tingkat dan pelestarian", "idx": 2, "soal": [{"lv": 1, "q": "Keanekaragaman hayati yang menunjukkan variasi atau perbedaan bentuk, ukuran, warna, dan gen dalam satu spesies disebut...", "o": ["Keanekaragaman tingkat ekosistem", "Keanekaragaman tingkat gen", "Keanekaragaman tingkat spesies", "Keanekaragaman biosfer"], "a": 1, "p": "Keanekaragaman tingkat gen adalah variasi genetik yang terjadi dalam satu spesies yang sama, misalnya variasi pada tanaman mangga atau kucing."}, {"lv": 1, "q": "Pelestarian keanekaragaman hayati yang dilakukan di dalam habitat aslinya (in situ) contohnya adalah...", "o": ["Kebun raya dan arboretum", "Taman nasional dan suaka margasatwa", "Kebun binatang dan penangkaran", "Bank benih dan laboratorium kultur jaringan"], "a": 1, "p": "Pelestarian in situ adalah upaya konservasi flora dan fauna di dalam habitat asli mereka, seperti taman nasional, cagar alam, dan suaka margasatwa."}, {"lv": 1, "q": "Indonesia memiliki garis khayal yang memisahkan fauna tipe Asiatis di bagian barat dengan fauna tipe peralihan di bagian tengah. Garis tersebut dinamakan...", "o": ["Garis Wallace", "Garis Weber", "Garis Khatulistiwa", "Garis Meridian"], "a": 0, "p": "Garis Wallace adalah garis khayal yang memisahkan wilayah sebaran fauna tipe Asiatis dengan wilayah fauna tipe Australasea/Peralihan di Indonesia."}, {"lv": 1, "q": "Keanekaragaman hayati tingkat spesies (jenis) dapat dilihat dari adanya berbagai jenis makhluk hidup yang berbeda dalam satu...", "o": ["Famili atau genus yang sama", "Lingkungan tempat tinggal yang kotor", "Struktur kromosom individu", "Variasi genetik di dalam sel"], "a": 0, "p": "Keanekaragaman jenis (spesies) mencakup variasi antarmakhluk hidup yang berbeda spesies namun masih dalam satu famili atau genus yang sama (contoh: jahe, lengkuas, kunyit)."}, {"lv": 2, "q": "Perhatikan beberapa contoh tumbuhan berikut:\n1. Kelapa (Cocos nucifera)\n2. Pinang (Areca catechu)\n3. Aren (Arenga pinnata)\nKetiga tanaman tersebut menunjukkan keanekaragaman hayati tingkat...", "o": ["Gen", "Spesies (jenis)", "Ekosistem", "Komunitas"], "a": 1, "p": "Kelapa, pinang, dan aren berada dalam satu famili yang sama (Arecaceae/palma), namun merupakan spesies yang berbeda. Ini adalah contoh keanekaragaman tingkat spesies."}, {"lv": 2, "q": "Pelestarian eks situ adalah bentuk konservasi keanekaragaman hayati yang dilakukan di luar habitat aslinya. Tujuan utama dari pelestarian ini adalah...", "o": ["Membiarkan hewan hidup bebas tanpa campur tangan manusia", "Mengembalikan fungsi hutan gundul secara alami", "Menyelamatkan spesies dari ancaman kepunahan di habitat aslinya", "Memperluas wilayah perkebunan komersial"], "a": 2, "p": "Pelestarian eks situ (seperti di kebun binatang, kebun raya) dilakukan untuk melindungi dan mengembangbiakkan flora/fauna yang terancam punah di alam liar."}, {"lv": 2, "q": "Fauna khas Indonesia bagian timur (wilayah Papua dan sekitarnya) yang memiliki kemiripan dengan fauna benua Australia adalah...", "o": ["Harimau sumatera dan orangutan", "Burung cendrawasih dan kuskus", "Badak bercula satu dan anoa", "Gajah sumatera dan jalak bali"], "a": 1, "p": "Fauna wilayah timur Indonesia (Australis) didominasi oleh burung berbulu indah seperti cendrawasih serta mamalia berkantung seperti kuskus dan kanguru pohon."}, {"lv": 2, "q": "Faktor utama yang menyebabkan tingginya keanekaragaman tingkat ekosistem di wilayah Indonesia adalah...", "o": ["Letak geografis di iklim tropis dengan curah hujan tinggi dan variasi ketinggian tempat", "Wilayahnya yang berupa daratan luas tanpa perairan laut", "Sebagian besar wilayahnya tertutup oleh gurun pasir dan salju abadi", "Aktivitas manusia yang tinggi dalam membuka lahan industri"], "a": 0, "p": "Iklim tropis, intensitas cahaya matahari sepanjang tahun, curah hujan tinggi, serta perbedaan relief/ketinggian menciptakan berbagai macam ekosistem di Indonesia."}, {"lv": 3, "q": "Di sebuah pulau kecil, terjadi alih fungsi hutan hujan tropis menjadi perkebunan kelapa sawit monokultur. Dampak ekologis jangka panjang terhadap keanekaragaman hayati di wilayah tersebut adalah...", "o": ["Meningkatnya populasi hewan endemik secara drastis", "Terjadinya penurunan keanekaragaman tingkat gen, spesies, dan ekosistem", "Terbentuknya rantai makanan yang semakin kompleks dan stabil", "Bertambahnya cadangan air tanah secara alami"], "a": 1, "p": "Perkebunan monokultur merusak habitat asli, menghilangkan berbagai spesies flora-fauna (menurunkan keanekaragaman spesies dan gen), serta merusak ekosistem hutan."}, {"lv": 3, "q": "Pernyataan yang paling tepat untuk membedakan garis Wallace dan garis Weber adalah...", "o": ["Garis Wallace memisahkan wilayah Asiatis dan Peralihan, sedangkan garis Weber memisahkan wilayah Peralihan dan Australis", "Garis Wallace memisahkan flora darat dan laut, sedangkan garis Weber memisahkan hewan mamalia dan reptil", "Garis Wallace terletak di sebelah timur Papua, sedangkan garis Weber terletak di pulau Sumatera", "Tidak ada perbedaan mendasar antara kedua garis tersebut"], "a": 0, "p": "Garis Wallace membatasi fauna Asiatis dengan Wallacea (Peralihan), sementara garis Weber membatasi wilayah Wallacea dengan fauna Australis di bagian timur."}, {"lv": 3, "q": "Suatu daerah mengalami kerusakan parah akibat letusan gunung berapi, namun setelah beberapa tahun mulai ditumbuhi oleh tumbuhan perintis seperti lumut kerak. Proses pemulihan ekosistem ini menunjukkan tingkat keanekaragaman hayati yang berfungsi untuk...", "o": ["Menurunkan produktivitas primer tanah secara permanen", "Menjaga keseimbangan suksesi ekologis dan stabilitas lingkungan", "Mempercepat kepunahan organisme endemik di daerah tersebut", "Menghilangkan seluruh komponen biotik yang ada"], "a": 1, "p": "Keanekaragaman hayati berperan penting dalam menjaga suksesi ekologis dan pemulihan keseimbangan lingkungan setelah terjadinya suatu bencana alam."}, {"lv": 3, "q": "Penerapan prinsip pembangunan berkelanjutan (sustainable development) sangat penting dalam pemanfaatan keanekaragaman hayati agar...", "o": ["Sumber daya alam dapat dieksploitasi habis-habisan dalam waktu singkat", "Generasi masa depan tetap dapat menikmati dan memanfaatkan kekayaan sumber daya alam", "Semua jenis hewan liar dapat dipelihara bebas di rumah perkotaan", "Tidak ada lagi peraturan perlindungan hutan lindung di Indonesia"], "a": 1, "p": "Prinsip pembangunan berkelanjutan bertujuan memanfaatkan sumber daya alam secara bijak guna menjamin ketersediaannya bagi generasi di masa mendatang."}]}], "11": [{"id": "ipa-k11-0", "name": "Fisika: Fluida", "desc": "Tekanan hidrostatis, Archimedes, Pascal", "idx": 0, "soal": [{"lv": 1, "q": "Rumus tekanan hidrostatis adalah ...", "o": ["P = F × A", "P = ρ g h", "P = m g", "P = ρ V"], "a": 1, "p": "Tekanan hidrostatis bergantung pada massa jenis fluida (ρ), percepatan gravitasi (g), dan kedalaman (h)."}, {"lv": 1, "q": "Satuan SI untuk tekanan adalah ...", "o": ["Newton", "Joule", "Pascal", "Watt"], "a": 2, "p": "1 Pascal = 1 N/m²."}, {"lv": 1, "q": "Alat yang bekerja berdasarkan Hukum Pascal adalah ...", "o": ["termometer", "dongkrak hidrolik", "kapal selam", "balon udara"], "a": 1, "p": "Dongkrak hidrolik meneruskan tekanan ke segala arah sama besar (Hukum Pascal)."}, {"lv": 1, "q": "Gaya ke atas yang dialami benda di dalam zat cair dijelaskan oleh hukum ...", "o": ["Newton", "Archimedes", "Ohm", "Boyle"], "a": 1, "p": "Hukum Archimedes: benda dalam fluida mendapat gaya apung sebesar berat fluida yang dipindahkan."}, {"lv": 2, "q": "Tekanan hidrostatis pada kedalaman 5 m di dalam air (ρ = 1.000 kg/m³, g = 10 m/s²) adalah ...", "o": ["5.000 Pa", "50.000 Pa", "500 Pa", "500.000 Pa"], "a": 1, "p": "P = ρgh = 1.000 × 10 × 5 = 50.000 Pa."}, {"lv": 2, "q": "Pada dongkrak hidrolik, A₁ = 0,01 m² dan A₂ = 0,5 m². Jika F₁ = 100 N, maka F₂ adalah ...", "o": ["2 N", "500 N", "5.000 N", "50 N"], "a": 2, "p": "F₁/A₁ = F₂/A₂ → F₂ = 100 × 0,5/0,01 = 5.000 N."}, {"lv": 2, "q": "Benda bervolume 0,002 m³ tercelup seluruhnya dalam air (ρ = 1.000 kg/m³, g = 10 m/s²). Gaya apungnya adalah ...", "o": ["2 N", "20 N", "200 N", "0,2 N"], "a": 1, "p": "F_A = ρ g V = 1.000 × 10 × 0,002 = 20 N."}, {"lv": 2, "q": "Benda akan terapung di air jika ...", "o": ["massa jenis benda lebih besar dari massa jenis air", "massa jenis benda lebih kecil dari massa jenis air", "volume benda sangat kecil", "benda terbuat dari logam"], "a": 1, "p": "Benda terapung bila ρ benda < ρ fluida."}, {"lv": 3, "q": "Sebuah batu beratnya 50 N di udara dan 30 N saat tercelup penuh dalam air (ρ = 1.000 kg/m³, g = 10 m/s²). Massa jenis batu adalah ...", "o": ["1.500 kg/m³", "2.000 kg/m³", "2.500 kg/m³", "3.000 kg/m³"], "a": 2, "p": "F_A = 50 − 30 = 20 N → V = 20/(1.000×10) = 0,002 m³. Massa = 5 kg, ρ = 5/0,002 = 2.500 kg/m³."}, {"lv": 3, "q": "Sebuah balok kayu terapung di air dengan 3/4 volumenya tercelup. Massa jenis kayu adalah ...", "o": ["250 kg/m³", "750 kg/m³", "1.333 kg/m³", "1.000 kg/m³"], "a": 1, "p": "Saat terapung: ρ_kayu × V = ρ_air × V_tercelup → ρ_kayu = 3/4 × 1.000 = 750 kg/m³."}, {"lv": 3, "q": "Tekanan total pada kedalaman 10 m di danau, jika tekanan udara luar 1 × 10⁵ Pa (ρ air = 1.000 kg/m³, g = 10 m/s²), adalah ...", "o": ["1 × 10⁵ Pa", "1,1 × 10⁵ Pa", "2 × 10⁵ Pa", "1 × 10⁶ Pa"], "a": 2, "p": "P total = P₀ + ρgh = 1 × 10⁵ + 1 × 10⁵ = 2 × 10⁵ Pa."}, {"lv": 3, "q": "Pengisap kecil dan besar sebuah pompa hidrolik memiliki perbandingan diameter 1 : 5. Gaya 40 N pada pengisap kecil menghasilkan gaya pada pengisap besar sebesar ...", "o": ["200 N", "400 N", "1.000 N", "8 N"], "a": 2, "p": "Luas sebanding kuadrat diameter → perbandingan luas 1 : 25. F₂ = 40 × 25 = 1.000 N."}]}, {"id": "ipa-k11-1", "name": "Kimia: Asam dan basa", "desc": "Sifat, indikator, dan pH", "idx": 1, "soal": [{"lv": 1, "q": "Larutan dengan pH kurang dari 7 bersifat ...", "o": ["basa", "netral", "asam", "garam"], "a": 2, "p": "pH < 7 asam, pH = 7 netral, pH > 7 basa."}, {"lv": 1, "q": "Kertas lakmus merah yang dicelupkan ke larutan basa akan berubah menjadi ...", "o": ["tetap merah", "biru", "kuning", "hijau"], "a": 1, "p": "Basa mengubah lakmus merah menjadi biru."}, {"lv": 1, "q": "Contoh zat yang bersifat basa dalam kehidupan sehari-hari adalah ...", "o": ["cuka", "air jeruk", "sabun", "asam lambung"], "a": 2, "p": "Sabun bersifat basa; cuka, air jeruk, dan asam lambung bersifat asam."}, {"lv": 1, "q": "Asam yang terdapat di dalam lambung manusia adalah ...", "o": ["asam sulfat", "asam klorida (HCl)", "asam cuka", "asam sitrat"], "a": 1, "p": "Lambung menghasilkan HCl yang membantu pencernaan dan membunuh kuman."}, {"lv": 2, "q": "Larutan dengan [H⁺] = 10⁻³ M memiliki pH ...", "o": ["3", "11", "-3", "7"], "a": 0, "p": "pH = −log[H⁺] = −log 10⁻³ = 3."}, {"lv": 2, "q": "Menurut Arrhenius, asam adalah zat yang dalam air ...", "o": ["melepaskan ion OH⁻", "melepaskan ion H⁺", "menerima proton", "menerima elektron"], "a": 1, "p": "Asam Arrhenius menghasilkan ion H⁺ (H₃O⁺) dalam air; basa menghasilkan OH⁻."}, {"lv": 2, "q": "Reaksi antara asam dan basa yang menghasilkan garam dan air disebut reaksi ...", "o": ["oksidasi", "netralisasi", "pembakaran", "hidrolisis"], "a": 1, "p": "Contoh netralisasi: HCl + NaOH → NaCl + H₂O."}, {"lv": 2, "q": "Indikator fenolftalein dalam larutan basa berwarna ...", "o": ["tidak berwarna", "merah muda", "kuning", "biru"], "a": 1, "p": "Fenolftalein tidak berwarna dalam asam/netral dan merah muda dalam basa (pH > 8,3)."}, {"lv": 3, "q": "Larutan dengan [OH⁻] = 10⁻² M pada suhu 25 °C memiliki pH ...", "o": ["2", "12", "10", "14"], "a": 1, "p": "pOH = 2, sehingga pH = 14 − 2 = 12."}, {"lv": 3, "q": "pH larutan HCl 0,01 M (asam kuat, terionisasi sempurna) adalah ...", "o": ["1", "2", "0,01", "12"], "a": 1, "p": "[H⁺] = 0,01 = 10⁻² M, sehingga pH = 2."}, {"lv": 3, "q": "Pada reaksi NH₃ + H₂O ⇌ NH₄⁺ + OH⁻, menurut Brønsted-Lowry H₂O berperan sebagai ...", "o": ["basa karena menerima proton", "asam karena memberikan proton", "garam", "katalis"], "a": 1, "p": "H₂O memberikan H⁺ kepada NH₃, sehingga H₂O adalah asam Brønsted-Lowry."}, {"lv": 3, "q": "Larutan HCl dengan pH = 2 diencerkan 10 kali. pH larutan sekarang adalah ...", "o": ["1", "2", "3", "20"], "a": 2, "p": "[H⁺] turun dari 10⁻² menjadi 10⁻³ M, sehingga pH menjadi 3."}]}, {"id": "ipa-k11-2", "name": "Biologi: Sel", "desc": "Struktur dan fungsi organel", "idx": 2, "soal": [{"lv": 1, "q": "Organel sel yang berfungsi sebagai tempat respirasi sel dan penghasil energi (ATP) adalah ...", "o": ["ribosom", "mitokondria", "lisosom", "vakuola"], "a": 1, "p": "Mitokondria disebut \"pembangkit tenaga\" sel karena menghasilkan ATP."}, {"lv": 1, "q": "Struktur yang hanya dimiliki sel tumbuhan dan tidak dimiliki sel hewan adalah ...", "o": ["membran sel", "dinding sel", "mitokondria", "inti sel"], "a": 1, "p": "Dinding sel dari selulosa hanya ada pada sel tumbuhan (juga kloroplas)."}, {"lv": 1, "q": "Bagian sel yang berfungsi sebagai pusat pengendali seluruh kegiatan sel adalah ...", "o": ["sitoplasma", "nukleus (inti sel)", "ribosom", "membran sel"], "a": 1, "p": "Nukleus menyimpan materi genetik (DNA) dan mengendalikan aktivitas sel."}, {"lv": 1, "q": "Organel tempat berlangsungnya fotosintesis adalah ...", "o": ["kloroplas", "mitokondria", "badan Golgi", "sentriol"], "a": 0, "p": "Kloroplas mengandung klorofil untuk menangkap energi cahaya dalam fotosintesis."}, {"lv": 2, "q": "Organel yang berfungsi sebagai tempat sintesis protein adalah ...", "o": ["lisosom", "ribosom", "vakuola", "sentrosom"], "a": 1, "p": "Ribosom merakit asam amino menjadi protein."}, {"lv": 2, "q": "Retikulum endoplasma kasar disebut \"kasar\" karena ...", "o": ["permukaannya ditempeli ribosom", "berbentuk tidak beraturan", "mengandung banyak lemak", "terletak di dalam nukleus"], "a": 0, "p": "RE kasar ditempeli ribosom sehingga berperan dalam sintesis dan transpor protein."}, {"lv": 2, "q": "Fungsi utama badan Golgi adalah ...", "o": ["menghasilkan energi", "memodifikasi, mengemas, dan menyekresikan protein", "mencerna zat makanan", "menyimpan DNA"], "a": 1, "p": "Badan Golgi mengolah dan mengemas zat (terutama protein) untuk disekresikan."}, {"lv": 2, "q": "Sifat membran sel yang hanya meloloskan zat tertentu disebut ...", "o": ["permeabel penuh", "impermeabel", "selektif permeabel", "elastis"], "a": 2, "p": "Membran plasma bersifat selektif permeabel, mengatur keluar-masuknya zat."}, {"lv": 3, "q": "Perbedaan utama sel prokariotik dan eukariotik adalah ...", "o": ["sel prokariotik tidak memiliki membran inti", "sel prokariotik memiliki mitokondria lebih banyak", "sel eukariotik tidak memiliki ribosom", "sel eukariotik tidak memiliki DNA"], "a": 0, "p": "Prokariotik (misalnya bakteri) tidak memiliki inti bermembran; DNA-nya berada di nukleoid."}, {"lv": 3, "q": "Sel kelenjar pankreas menghasilkan banyak enzim pencernaan. Organel yang diperkirakan sangat banyak dalam sel ini adalah ...", "o": ["kloroplas dan vakuola", "RE kasar dan badan Golgi", "sentriol dan dinding sel", "lisosom saja"], "a": 1, "p": "Enzim adalah protein yang disekresikan, jadi diperlukan banyak RE kasar (sintesis) dan badan Golgi (sekresi)."}, {"lv": 3, "q": "Transpor zat melawan gradien konsentrasi yang memerlukan energi ATP disebut ...", "o": ["difusi", "osmosis", "transpor aktif", "difusi terfasilitasi"], "a": 2, "p": "Contoh transpor aktif adalah pompa natrium-kalium yang menggunakan ATP."}, {"lv": 3, "q": "Sel darah merah dimasukkan ke dalam larutan garam yang sangat pekat (hipertonik). Yang terjadi adalah ...", "o": ["sel menggembung lalu pecah", "sel mengerut (krenasi) karena air keluar dari sel", "tidak terjadi apa-apa", "sel membelah diri"], "a": 1, "p": "Air berosmosis dari dalam sel ke larutan yang lebih pekat sehingga sel mengerut."}]}], "12": [{"id": "ipa-k12-0", "name": "Fisika: Listrik arus searah", "desc": "Hukum Kirchhoff dan rangkaian", "idx": 0, "soal": [{"lv": 1, "q": "Hukum I Kirchhoff menyatakan bahwa ...", "o": ["jumlah tegangan dalam rangkaian tertutup sama dengan nol", "jumlah arus yang masuk titik cabang sama dengan jumlah arus yang keluar", "hambatan sebanding dengan panjang kawat", "daya sama dengan tegangan kali arus"], "a": 1, "p": "Hukum I Kirchhoff adalah hukum kekekalan muatan pada titik cabang."}, {"lv": 1, "q": "Satuan hambatan listrik adalah ...", "o": ["volt", "ampere", "ohm", "watt"], "a": 2, "p": "Hambatan diukur dalam ohm (Ω)."}, {"lv": 1, "q": "Hubungan tegangan, arus, dan hambatan menurut Hukum Ohm adalah ...", "o": ["V = I × R", "V = I / R", "R = V × I", "I = V × R"], "a": 0, "p": "Hukum Ohm: V = I R."}, {"lv": 1, "q": "Cara memasang voltmeter untuk mengukur tegangan sebuah lampu adalah ...", "o": ["seri dengan lampu", "paralel dengan lampu", "di dalam baterai", "tidak perlu disambung"], "a": 1, "p": "Voltmeter dipasang paralel; amperemeter dipasang seri."}, {"lv": 2, "q": "Arus 5 A masuk ke titik cabang lalu keluar melalui dua cabang. Jika salah satu cabang dialiri 2 A, arus di cabang lainnya adalah ...", "o": ["7 A", "3 A", "2,5 A", "10 A"], "a": 1, "p": "Hukum I Kirchhoff: 5 = 2 + I → I = 3 A."}, {"lv": 2, "q": "Tiga hambatan 2 Ω, 3 Ω, dan 5 Ω disusun seri. Hambatan totalnya adalah ...", "o": ["10 Ω", "1 Ω", "30 Ω", "0,97 Ω"], "a": 0, "p": "Seri: R = 2 + 3 + 5 = 10 Ω."}, {"lv": 2, "q": "Hambatan 6 Ω dan 3 Ω disusun paralel. Hambatan penggantinya adalah ...", "o": ["9 Ω", "2 Ω", "18 Ω", "4,5 Ω"], "a": 1, "p": "1/R = 1/6 + 1/3 = 3/6 → R = 2 Ω."}, {"lv": 2, "q": "Sebuah hambatan 4 Ω dihubungkan dengan sumber tegangan 12 V. Kuat arusnya adalah ...", "o": ["48 A", "3 A", "0,33 A", "16 A"], "a": 1, "p": "I = V/R = 12/4 = 3 A."}, {"lv": 3, "q": "Baterai dengan GGL 12 V dan hambatan dalam 1 Ω dihubungkan ke hambatan luar 5 Ω. Tegangan jepit baterai adalah ...", "o": ["12 V", "10 V", "2 V", "6 V"], "a": 1, "p": "I = 12/(5+1) = 2 A. Tegangan jepit V = I R = 2 × 5 = 10 V."}, {"lv": 3, "q": "Hambatan 4 Ω diseri dengan rangkaian paralel 6 Ω dan 12 Ω, lalu dihubungkan ke sumber 24 V. Arus total rangkaian adalah ...", "o": ["1 A", "2 A", "3 A", "6 A"], "a": 2, "p": "Paralel 6 dan 12 = 4 Ω; total 4 + 4 = 8 Ω. I = 24/8 = 3 A."}, {"lv": 3, "q": "Lampu bertuliskan 220 V / 100 W memiliki hambatan sebesar ...", "o": ["2,2 Ω", "484 Ω", "22.000 Ω", "0,45 Ω"], "a": 1, "p": "R = V²/P = 220²/100 = 48.400/100 = 484 Ω."}, {"lv": 3, "q": "Lampu 100 W menyala selama 5 jam per hari. Energi listrik yang dipakai dalam 30 hari adalah ...", "o": ["0,5 kWh", "15 kWh", "150 kWh", "3 kWh"], "a": 1, "p": "Per hari 100 W × 5 jam = 0,5 kWh. Selama 30 hari = 15 kWh."}]}, {"id": "ipa-k12-1", "name": "Kimia: Reaksi redoks", "desc": "Bilangan oksidasi dan reaksi", "idx": 1, "soal": [{"lv": 1, "q": "Oksidasi menurut konsep transfer elektron adalah ...", "o": ["penangkapan elektron", "pelepasan elektron", "penangkapan oksigen oleh atom H", "penurunan bilangan oksidasi"], "a": 1, "p": "Oksidasi = pelepasan elektron (biloks naik); reduksi = penangkapan elektron (biloks turun)."}, {"lv": 1, "q": "Bilangan oksidasi unsur bebas seperti Fe, O₂, dan Cl₂ adalah ...", "o": ["+1", "−1", "0", "+2"], "a": 2, "p": "Unsur bebas selalu memiliki biloks 0."}, {"lv": 1, "q": "Bilangan oksidasi oksigen dalam kebanyakan senyawa adalah ...", "o": ["+2", "−2", "0", "−1"], "a": 1, "p": "Umumnya O = −2 (kecuali pada peroksida −1 dan OF₂ +2)."}, {"lv": 1, "q": "Reduksi menurut konsep bilangan oksidasi adalah ...", "o": ["kenaikan bilangan oksidasi", "penurunan bilangan oksidasi", "biloks tetap", "pelepasan elektron"], "a": 1, "p": "Reduksi ditandai dengan turunnya biloks."}, {"lv": 2, "q": "Bilangan oksidasi Mn dalam KMnO₄ adalah ...", "o": ["+2", "+4", "+7", "+6"], "a": 2, "p": "(+1) + Mn + 4(−2) = 0 → Mn = +7."}, {"lv": 2, "q": "Bilangan oksidasi S dalam H₂SO₄ adalah ...", "o": ["+4", "+6", "−2", "+2"], "a": 1, "p": "2(+1) + S + 4(−2) = 0 → S = +6."}, {"lv": 2, "q": "Bilangan oksidasi Cr dalam K₂Cr₂O₇ adalah ...", "o": ["+3", "+6", "+7", "+12"], "a": 1, "p": "2(+1) + 2Cr + 7(−2) = 0 → 2Cr = 12 → Cr = +6."}, {"lv": 2, "q": "Pada reaksi Zn + Cu²⁺ → Zn²⁺ + Cu, zat yang bertindak sebagai reduktor adalah ...", "o": ["Cu²⁺", "Zn", "Zn²⁺", "Cu"], "a": 1, "p": "Zn mengalami oksidasi (0 → +2), sehingga Zn adalah reduktor."}, {"lv": 3, "q": "Reaksi Cl₂ + 2NaOH → NaCl + NaClO + H₂O termasuk reaksi autoredoks karena ...", "o": ["Na mengalami oksidasi dan reduksi", "Cl₂ sekaligus mengalami reduksi (menjadi −1) dan oksidasi (menjadi +1)", "tidak ada perubahan biloks", "H₂O adalah oksidator"], "a": 1, "p": "Cl berubah dari 0 menjadi −1 (NaCl) dan +1 (NaClO): disproporsionasi."}, {"lv": 3, "q": "Pada reaksi Fe₂O₃ + 3CO → 2Fe + 3CO₂, zat yang bertindak sebagai oksidator adalah ...", "o": ["CO", "Fe₂O₃", "Fe", "CO₂"], "a": 1, "p": "Fe dalam Fe₂O₃ turun dari +3 ke 0 (tereduksi), jadi Fe₂O₃ adalah oksidator."}, {"lv": 3, "q": "Bilangan oksidasi N dalam ion NH₄⁺ adalah ...", "o": ["+3", "−3", "+4", "+5"], "a": 1, "p": "N + 4(+1) = +1 → N = −3."}, {"lv": 3, "q": "Reaksi berikut yang BUKAN reaksi redoks adalah ...", "o": ["2Na + Cl₂ → 2NaCl", "NaOH + HCl → NaCl + H₂O", "Zn + 2HCl → ZnCl₂ + H₂", "CH₄ + 2O₂ → CO₂ + 2H₂O"], "a": 1, "p": "Pada netralisasi NaOH + HCl, tidak ada unsur yang biloksnya berubah."}]}, {"id": "ipa-k12-2", "name": "Biologi: Pertumbuhan dan perkembangan", "desc": "Faktor dan hormon", "idx": 2, "soal": [{"lv": 1, "q": "Pertumbuhan pada makhluk hidup adalah ...", "o": ["proses menuju kedewasaan", "pertambahan ukuran yang bersifat irreversibel (tidak dapat kembali)", "perubahan warna daun", "proses fotosintesis"], "a": 1, "p": "Pertumbuhan adalah pertambahan ukuran (volume, massa, tinggi) yang tidak dapat balik dan dapat diukur."}, {"lv": 1, "q": "Alat untuk mengukur laju pertumbuhan tumbuhan adalah ...", "o": ["termometer", "auksanometer", "barometer", "higrometer"], "a": 1, "p": "Auksanometer mengukur pertambahan panjang batang tumbuhan."}, {"lv": 1, "q": "Hormon tumbuhan yang memacu pemanjangan sel pada ujung batang adalah ...", "o": ["auksin", "etilen", "asam absisat", "kalin"], "a": 0, "p": "Auksin dihasilkan di ujung tunas dan memacu pemanjangan sel."}, {"lv": 1, "q": "Perkembangan pada makhluk hidup adalah ...", "o": ["pertambahan jumlah sel saja", "proses menuju kedewasaan atau kematangan organ", "pertambahan berat badan", "pertambahan tinggi tanaman"], "a": 1, "p": "Perkembangan bersifat kualitatif, yaitu proses menuju kedewasaan; tidak dapat diukur dengan angka."}, {"lv": 2, "q": "Hormon yang berperan dalam pematangan buah adalah ...", "o": ["giberelin", "sitokinin", "etilen", "auksin"], "a": 2, "p": "Etilen berbentuk gas dan mempercepat pematangan buah."}, {"lv": 2, "q": "Hormon yang memacu pembelahan sel dan menunda penuaan daun adalah ...", "o": ["sitokinin", "asam absisat", "etilen", "florigen"], "a": 0, "p": "Sitokinin merangsang sitokinesis dan menghambat penuaan (senesens)."}, {"lv": 2, "q": "Hormon yang menyebabkan dormansi biji dan penutupan stomata saat kekeringan adalah ...", "o": ["giberelin", "auksin", "asam absisat", "sitokinin"], "a": 2, "p": "Asam absisat (ABA) disebut hormon stres."}, {"lv": 2, "q": "Faktor berikut yang termasuk faktor internal pertumbuhan adalah ...", "o": ["cahaya matahari", "suhu", "gen dan hormon", "kelembapan tanah"], "a": 2, "p": "Faktor internal berasal dari dalam tubuh (gen, hormon); faktor lain adalah faktor eksternal."}, {"lv": 3, "q": "Kecambah yang ditanam di tempat gelap tumbuh lebih panjang tetapi pucat dan lemah. Penjelasan yang tepat adalah ...", "o": ["di tempat gelap auksin tidak dirusak cahaya sehingga pemanjangan sel lebih cepat, dan klorofil tidak terbentuk", "di tempat gelap tumbuhan berfotosintesis lebih cepat", "cahaya mempercepat kerja auksin", "kecambah di gelap kekurangan air"], "a": 0, "p": "Peristiwa ini disebut etiolasi: cahaya menghambat auksin, dan tanpa cahaya klorofil tidak terbentuk."}, {"lv": 3, "q": "Batang tanaman di dekat jendela membengkok ke arah cahaya karena ...", "o": ["auksin berkumpul di sisi yang terkena cahaya", "auksin berpindah ke sisi yang gelap sehingga sisi itu tumbuh lebih cepat", "sisi terang tumbuh lebih cepat", "etilen menarik batang ke cahaya"], "a": 1, "p": "Pada fototropisme, auksin menumpuk di sisi gelap sehingga sel-sel di sisi itu memanjang lebih cepat dan batang membengkok ke cahaya."}, {"lv": 3, "q": "Pertumbuhan sekunder yang membuat batang tumbuhan dikotil bertambah besar disebabkan oleh aktivitas ...", "o": ["meristem apikal", "kambium", "epidermis", "stomata"], "a": 1, "p": "Kambium membentuk xilem ke dalam dan floem ke luar, sehingga batang membesar."}, {"lv": 3, "q": "Petani menyemprotkan giberelin pada tanaman anggur untuk menghasilkan buah tanpa biji yang besar. Peristiwa ini disebut ...", "o": ["etiolasi", "partenokarpi", "dormansi", "absisi"], "a": 1, "p": "Partenokarpi adalah pembentukan buah tanpa pembuahan sehingga buah tidak berbiji."}]}], "3": [{"id": "ipa-k3-0", "name": "Bagian tubuh tumbuhan", "desc": "Akar, batang, daun, bunga dan fungsinya", "idx": 0, "soal": [{"lv": 1, "q": "Bagian tumbuhan yang biasanya berada di dalam tanah dan bertugas menyerap air adalah...", "o": ["Daun", "Akar", "Bunga", "Batang"], "a": 1, "p": "Akar adalah bagian tumbuhan yang tumbuh di dalam tanah dan berfungsi menyerap air serta zat hara dari dalam tanah."}, {"lv": 1, "q": "Bagian tumbuhan yang berfungsi sebagai tempat membuat makanan (fotosintesis) adalah...", "o": ["Batang", "Akar", "Daun", "Bunga"], "a": 2, "p": "Daun memiliki zat hijau daun (klorofil) yang berguna untuk membuat makanan bagi tumbuhan."}, {"lv": 1, "q": "Bagian tumbuhan yang menghubungkan akar dengan daun serta membuat tumbuhan berdiri tegak adalah...", "o": ["Batang", "Bunga", "Buah", "Biji"], "a": 0, "p": "Batang berfungsi untuk menegakkan tumbuhan serta menyalurkan air dari akar ke seluruh bagian tumbuhan."}, {"lv": 1, "q": "Bagian tumbuhan yang warnanya indah dan nantinya bisa berubah menjadi buah adalah...", "o": ["Akar", "Daun", "Batang", "Bunga"], "a": 3, "p": "Bunga adalah bagian tumbuhan yang indah dan berfungsi sebagai alat perkembangbiakan yang nantinya menghasilkan buah."}, {"lv": 2, "q": "Ibu menyiram tanaman di halaman rumah setiap sore. Air yang disiramkan ke tanah akan diserap pertama kali oleh...", "o": ["Daun", "Akar", "Batang", "Bunga"], "a": 1, "p": "Akar berada di dalam tanah, sehingga bagian tumbuhan yang pertama kali menyerap air siraman adalah akar."}, {"lv": 2, "q": "Perhatikan fungsi bagian tumbuhan berikut: menyalurkan air dari akar ke daun serta mengedarkan hasil fotosintesis ke seluruh tubuh tumbuhan. Bagian tersebut adalah...", "o": ["Bunga", "Akar", "Batang", "Biji"], "a": 2, "p": "Batang berfungsi sebagai jalur pengangkutan air dari akar ke daun dan mengedarkan hasil makanan ke bagian lain."}, {"lv": 2, "q": "Tumbuhan hijau dapat membuat makanannya sendiri karena memiliki zat hijau daun yang disebut...", "o": ["Klorofil", "Oksigen", "Karbon dioksida", "Pupuk"], "a": 0, "p": "Klorofil adalah zat hijau daun yang berperan penting dalam proses pembuatan makanan pada tumbuhan."}, {"lv": 2, "q": "Sebelum menjadi buah mangga yang manis, bagian pohon mangga yang harus tumbuh terlebih dahulu dan diserbuki serangga adalah...", "o": ["Akar mangga", "Daun mangga", "Batang mangga", "Bunga mangga"], "a": 3, "p": "Buah pada tumbuhan berasal dari penyerbukan dan pembuahan yang terjadi pada bunga."}, {"lv": 3, "q": "Ani mencabut rumput di kebun. Ia melihat rumput sangat kuat tertanam di dalam tanah dan sulit dicabut. Bagian tubuh tumbuhan manakah yang paling berperan membuat rumput tersebut kokoh tertanam?", "o": ["Akar, karena mencengkeram tanah dan memperkokoh tumbuhan", "Batang, karena menahan tiupan angin dari atas", "Daun, karena menimbun banyak air hujan", "Bunga, karena menarik perhatian tanah"], "a": 0, "p": "Selain menyerap air, akar juga berfungsi untuk mencengkeram tanah agar tumbuhan dapat berdiri kokoh."}, {"lv": 3, "q": "Budi memotong sebagian daun pada tanaman hias ibunya karena terserang ulat. Apakah tanaman tersebut masih bisa hidup?", "o": ["Tidak, karena semua bagian tumbuhan langsung mati", "Tidak, karena daun adalah satu-satunya bagian terpenting", "Ya, selama akar dan batang masih sehat serta ada daun lain yang tersisa untuk fotosintesis", "Ya, karena daun tidak memiliki fungsi apa pun bagi tumbuhan"], "a": 2, "p": "Tanaman masih bisa hidup asalkan masih ada daun yang berfungsi melakukan fotosintesis serta akar dan batang yang menyalurkan nutrisi."}, {"lv": 3, "q": "Sebuah pohon besar di halaman sekolah ditebang sebagian batangnya secara melingkar hingga kulitnya terkelupas habis. Beberapa hari kemudian, daun-daun di pohon tersebut layu dan mati. Mengapa hal ini bisa terjadi?", "o": ["Karena akar tidak bisa lagi menyerap air tanah", "Karena jalur pengangkutan air dan makanan dari akar ke daun terputus di batang", "Karena bunga tidak mendapatkan sinar matahari", "Karena daun tidak bisa menghasilkan angin"], "a": 1, "p": "Batang berfungsi sebagai saluran utama. Jika kulit atau jaringan pengangkut di batang rusak parah, air dan nutrisi tidak bisa naik ke daun."}, {"lv": 3, "q": "Mengapa sebagian besar daun tumbuhan berwarna hijau dan berbentuk tipis melebar?", "o": ["Agar mudah ditiup angin ke tempat lain", "Agar dapat menyerap cahaya matahari dengan optimal untuk membuat makanan", "Agar dapat menyerap air langsung dari awan", "Agar terlihat indah oleh hewan pemakan tumbuhan"], "a": 1, "p": "Bentuk daun yang tipis dan melebar serta berwarna hijau (mengandung klorofil) dirancang untuk menangkap cahaya matahari secara maksimal saat fotosintesis."}]}, {"id": "ipa-k3-1", "name": "Wujud benda", "desc": "Padat, cair, gas dan perubahannya", "idx": 1, "soal": [{"lv": 1, "q": "Benda yang bentuk dan volumenya selalu tetap di mana pun ia diletakkan disebut benda...", "o": ["Cair", "Gas", "Padat", "Uap"], "a": 2, "p": "Benda padat memiliki sifat bentuk dan volume yang selalu tetap atau tidak berubah meskipun dipindah tempat."}, {"lv": 1, "q": "Air di dalam gelas bentuknya menyerupai gelas, sedangkan jika dipindah ke botol bentuknya menyerupai botol. Hal ini menunjukkan sifat benda...", "o": ["Padat", "Cair", "Gas", "Keras"], "a": 1, "p": "Benda cair memiliki sifat bentuk yang berubah-ubah mengikuti wadahnya, namun volumenya tetap."}, {"lv": 1, "q": "Udara di dalam balon membuat balon mengembang ke segala arah. Hal ini membuktikan bahwa benda gas menempati...", "o": ["Ruang", "Tanah", "Batu", "Air"], "a": 0, "p": "Benda gas memiliki sifat mengisi seluruh ruangan yang ditempatinya."}, {"lv": 1, "q": "Es batu yang dibiarkan di tempat terbuka lama-kelamaan akan mencair menjadi...", "o": ["Uap air", "Air", "Gas", "Salju"], "a": 1, "p": "Es batu (benda padat) yang menyerap panas akan mengalami perubahan wujud mencair menjadi air (benda cair)."}, {"lv": 2, "q": "Ibu memasak air di dalam panci hingga mendidih. Lama-kelamaan air di dalam panci semakin berkurang karena berubah menjadi...", "o": ["Es", "Embun", "Uap air", "Minyak"], "a": 2, "p": "Air yang dipanaskan akan mengalami penguapan dan berubah wujud menjadi gas atau uap air."}, {"lv": 2, "q": "Peristiwa perubahan wujud dari cair menjadi padat disebut...", "o": ["Mencair", "Membeku", "Menguap", "Menyublim"], "a": 1, "p": "Membeku adalah perubahan wujud benda dari cair menjadi padat karena pelepasan panas (pendinginan)."}, {"lv": 2, "q": "Kapur barus yang diletakkan di dalam lemari lama-kelamaan ukurannya akan mengecil dan habis karena berubah menjadi gas. Peristiwa ini dinamakan...", "o": ["Mencair", "Membeku", "Menyublim", "Mengembun"], "a": 2, "p": "Menyublim adalah perubahan wujud benda padat menjadi gas."}, {"lv": 2, "q": "Titik-titik air di rerumputan pada pagi hari yang berasal dari uap air di udara yang mendingin disebut peristiwa...", "o": ["Mencair", "Membeku", "Mengembun", "Menguap"], "a": 2, "p": "Mengembun adalah perubahan wujud dari gas menjadi cair, contohnya terbentuknya embun di pagi hari."}, {"lv": 3, "q": "Siti memasukkan air ke dalam cetakan es, kemudian menaruhnya di dalam freezer. Beberapa jam kemudian air tersebut mengeras. Apa yang terjadi pada kalor (panas) air tersebut selama di dalam freezer?", "o": ["Kalor diserap oleh air", "Kalor dilepaskan atau dibuang ke lingkungan sekitar", "Kalor bertambah banyak", "Kalor tidak mengalami perubahan"], "a": 1, "p": "Untuk membeku, benda cair harus melepaskan panas (kalor) ke lingkungan yang lebih dingin seperti freezer."}, {"lv": 3, "q": "Ayah membuat segelas teh manis panas. Saat gelas ditutup dengan piring kecil, beberapa menit kemudian tampak titik-titik air di bagian bawah piring tersebut. Proses pembentukan titik air ini melibatkan perubahan wujud...", "o": ["Padat menjadi cair", "Cair menjadi padat", "Gas menjadi cair", "Padat menjadi gas"], "a": 2, "p": "Uap panas dari teh (gas) menyentuh permukaan piring yang lebih dingin sehingga mengembun menjadi titik-titik air (cair)."}, {"lv": 3, "q": "Budi ingin membuat agar-agar. Ia mencampur bubuk agar-agar, air, dan gula, lalu memasaknya di atas kompor hingga mendidih. Setelah dituangkan ke cetakan dan didiamkan beberapa saat, cairan agar-agar mengeras. Urutan perubahan wujud yang terjadi adalah...", "o": ["Padat ke cair lalu ke gas", "Cair ke gas lalu ke padat", "Padat ke gas lalu ke cair", "Cair ke padat"], "a": 3, "p": "Adonan agar-agar yang awalnya berupa cairan (cair) mengalami pendinginan hingga mengeras menjadi jelly (padat)."}, {"lv": 3, "q": "Di daerah pegunungan yang sangat dingin, kadang-kadang salju terbentuk langsung dari uap air di udara tanpa menjadi cair terlebih dahulu. Peristiwa kebalikan dari menyublim ini disebut...", "o": ["Membeku", "Mengembun", "Mengkristal", "Menguap"], "a": 2, "p": "Mengkristal (atau deposisi) adalah perubahan wujud dari gas langsung menjadi padat."}]}, {"id": "ipa-k3-2", "name": "Gaya di sekitar kita", "desc": "Gaya dorong dan tarik", "idx": 2, "soal": [{"lv": 1, "q": "Kegiatan yang menggunakan gaya dorong adalah...", "o": ["Menimba air dari sumur", "Membuka laci meja", "Menendang bola ke depan", "Menarik tali bendera"], "a": 2, "p": "Menendang bola membuat bola bergerak menjauh dengan cara memberikan gaya dorong menggunakan kaki."}, {"lv": 1, "q": "Saat kita membuka pintu kulkas, tangan kita melakukan...", "o": ["Gaya tarik", "Gaya dorong", "Gaya putar", "Gaya gravitasi"], "a": 0, "p": "Membuka pintu kulkas memerlukan gaya tarik agar pintu mendekat ke arah badan kita."}, {"lv": 1, "q": "Bentuk tarikan atau dorongan yang diberikan kepada suatu benda disebut...", "o": ["Energi", "Gaya", "Massa", "Daya"], "a": 1, "p": "Gaya adalah tarikan atau dorongan yang dapat mempengaruhi keadaan suatu benda."}, {"lv": 1, "q": "Benda yang awalnya diam akan bergerak jika diberi...", "o": ["Warna", "Cahaya", "Gaya", "Suara"], "a": 2, "p": "Pemberian gaya berupa dorongan atau tarikan dapat mengubah benda diam menjadi bergerak."}, {"lv": 2, "q": "Ibu mendorong troli belanjaan di supermarket. Akibat adanya gaya dorong tersebut, troli yang tadinya diam akan...", "o": ["Berhenti", "Bergerak", "Mengecil", "Hilang"], "a": 1, "p": "Gaya dorong yang diberikan ibu pada troli membuat troli mengalami perubahan posisi dari diam menjadi bergerak."}, {"lv": 2, "q": "Perhatikan kegiatan berikut: (1) Menutup pintu kelas, (2) Mengerek bendera, (3) Menekan tombol lampu, (4) Menimba air. Kegiatan yang memanfaatkan gaya dorong ditunjukkan oleh nomor...", "o": ["(1) dan (3)", "(1) dan (2)", "(2) dan (4)", "(3) dan (4)"], "a": 0, "p": "Menutup pintu dan menekan tombol lampu dilakukan dengan cara mendorong (gaya dorong)."}, {"lv": 2, "q": "Budi sedang bermain mobil-mobilan mainan. Ia menarik mobil-mobilan tersebut menggunakan tali. Peristiwa ini menunjukkan bahwa gaya dapat...", "o": ["Mengubah bentuk benda", "Mengubah wujud benda", "Mengubah arah dan membuat benda bergerak", "Menghasilkan panas"], "a": 2, "p": "Gaya tarik yang diberikan Budi menyebabkan mobil mainan yang diam menjadi bergerak."}, {"lv": 2, "q": "Ketika Andi menangkap bola kasti yang dilempar temannya, bola yang tadinya bergerak cepat lambat laun akan berhenti. Hal ini menunjukkan bahwa gaya dapat...", "o": ["Mempercepat gerak benda", "Menghentikan gerak benda", "Membuat benda melayang", "Memperbesar ukuran benda"], "a": 1, "p": "Menangkap bola memberikan gaya tahan yang membuat bola bergerak menjadi berhenti."}, {"lv": 3, "q": "Siti mengayuh sepeda perlahan, kemudian ia mengayuhnya dengan sangat kencang. Apa pengaruh gaya otot kaki Siti terhadap gerakan sepeda?", "o": ["Sepeda menjadi berhenti", "Gerak sepeda menjadi lebih cepat", "Arah sepeda berbalik ke belakang", "Bentuk ban sepeda berubah"], "a": 1, "p": "Semakin besar gaya dorong yang diberikan pada pedal sepeda, maka gerak sepeda akan semakin cepat."}, {"lv": 3, "q": "Rudi bermain sepak bola. Saat bola menggelinding ke arahnya, ia menyundul bola tersebut ke samping kanan. Peristiwa ini membuktikan bahwa gaya dapat...", "o": ["Mengubah bentuk benda", "Mengubah arah gerak benda", "Menghentikan benda selamanya", "Membuat benda bertambah berat"], "a": 1, "p": "Pemberian gaya pada bola yang sedang menggelinding dapat mengubah arah gerak bola tersebut."}, {"lv": 3, "q": "Ani meremas selembar kertas bekas hingga menjadi gumpalan bola kertas yang kusut. Pengaruh gaya otot tangan Ani pada kertas tersebut adalah...", "o": ["Mengubah bentuk benda", "Membuat benda bergerak lurus", "Menghentikan benda bergerak", "Membuat benda bertambah besar"], "a": 0, "p": "Gaya otot tangan yang meremas kertas menyebabkan bentuk kertas yang tadinya lembaran datar berubah menjadi gumpalan."}, {"lv": 3, "q": "Dua orang anak sedang bermain tarik tambang dengan kekuatan yang sama kuat dan arah yang berlawanan. Akibatnya tali tambang tidak bergeser ke kiri maupun ke kanan. Mengapa hal tersebut bisa terjadi?", "o": ["Tidak ada gaya yang bekerja sama sekali", "Gaya dorong kedua anak bernilai nol", "Gaya tarik yang diberikan kedua pihak saling mengimbangi (seimbang)", "Tali tambang berubah menjadi benda padat"], "a": 2, "p": "Jika gaya tarik dari kedua arah berlawanan memiliki besar yang sama, gaya tersebut seimbang sehingga benda tidak akan berpindah tempat."}]}], "4": [{"id": "ipa-k4-0", "name": "Siklus hidup hewan", "desc": "Metamorfosis sempurna dan tidak sempurna", "idx": 0, "soal": [{"lv": 1, "q": "Hewan yang mengalami metamorfosis sempurna melalui tahapan telur, larva, kepompong, dan dewasa adalah...", "o": ["Kecoa", "Belalang", "Kupu-kupu", "Jangkrik"], "a": 2, "p": "Kupu-kupu adalah contoh hewan bermetamorfosis sempurna karena melalui 4 tahapan termasuk fase kepompong (pupa)."}, {"lv": 1, "q": "Tahap kedua dalam siklus hidup katak setelah menetas dari telur adalah...", "o": ["Berudu (kecebong)", "Katak muda", "Katak dewasa", "Kepompong"], "a": 0, "p": "Setelah telur katak menetas, tahapan berikutnya adalah berudu atau kecebong yang hidup di air."}, {"lv": 1, "q": "Hewan muda yang bentuk tubuhnya sangat berbeda jauh dengan bentuk tubuh induknya dikatakan mengalami metamorfosis...", "o": ["Sempurna", "Tidak sempurna", "Gagal", "Langsung"], "a": 0, "p": "Metamorfosis sempurna ditandai dengan perbedaan bentuk yang sangat mencolok antara hewan muda (larva) dan hewan dewasa."}, {"lv": 1, "q": "Belalang muda yang baru menetas dari telur disebut dengan istilah...", "o": ["Ulat", "Nimfa", "Pupa", "Kecebong"], "a": 1, "p": "Nimfa adalah sebutan untuk hewan muda pada metamorfosis tidak sempurna, seperti pada belalang dan kecoa."}, {"lv": 2, "q": "Perhatikan tahapan hidup hewan berikut: (1) Telur, (2) Nimfa, (3) Dewasa. Urutan siklus hidup tersebut dialami oleh...", "o": ["Kupu-kupu", "Katak", "Nyamuk", "Kecoa"], "a": 3, "p": "Kecoa mengalami metamorfosis tidak sempurna dengan 3 tahapan utama yaitu telur, nimfa, dan dewasa."}, {"lv": 2, "q": "Pada siklus hidup nyamuk, tahapan yang hidup di dalam air sebelum menjadi nyamuk dewasa adalah...", "o": ["Telur dan ulat", "Telur dan jentik-jentik (pupa/larva)", "Nimfa dan kepompong", "Berudu dan katak muda"], "a": 1, "p": "Nyamuk bertelur di air, lalu menetas menjadi jentik-jentik (larva) dan berkembang menjadi pupa sebelum menjadi nyamuk dewasa."}, {"lv": 2, "q": "Mengapa belalang dikategorikan mengalami metamorfosis tidak sempurna?", "o": ["Karena tidak melalui tahap telur", "Karena bentuk belalang muda (nimfa) mirip dengan belalang dewasa", "Karena tidak pernah berganti kulit", "Karena hidup di dua alam"], "a": 1, "p": "Metamorfosis tidak sempurna disebut demikian karena bentuk hewan muda (nimfa) mirip dengan induknya, hanya ukuran dan sayapnya yang belum sempurna."}, {"lv": 2, "q": "Tahap kepompong (pupa) pada metamorfosis sempurna merupakan masa di mana...", "o": ["Hewan sangat aktif mencari makan", "Hewan mengalami istirahat total dan pembentukan organ tubuh baru", "Hewan langsung menjadi induk", "Telur mulai dibuahi"], "a": 1, "p": "Pada fase pupa, larva beristirahat sementara organ-organ tubuh dewasa sedang dibentuk."}, {"lv": 3, "q": "Siti mengamati sekumpulan hewan air kecil berekor tanpa kaki depan dan belakang, yang bernapas menggunakan insang luar. Beberapa minggu kemudian kaki belakangnya tumbuh dan ekornya memendek. Hewan yang diamati Siti adalah...", "o": ["Jentik nyamuk", "Berudu katak", "Ikan kecil", "Nimfa capung"], "a": 1, "p": "Deskripsi tersebut sesuai dengan tahap berudu (kecebong) yang sedang dalam proses metamorfosis menuju katak muda."}, {"lv": 3, "q": "Dalam siklus hidupnya, kupu-kupu melalui tahap ulat (larva) yang sangat aktif memakan daun. Apa peran utama tahapan ulat bagi kelangsungan hidup kupu-kupu?", "o": ["Sebagai tempat menyimpan cadangan makanan untuk fase kepompong dan persiapan menjadi kupu-kupu dewasa", "Untuk membantu penyerbukan bunga di kebun", "Sebagai pelindung telur dari serangan musuh", "Untuk mempercepat proses penguapan air di daun"], "a": 0, "p": "Fase larva (ulat) berfungsi untuk makan sebanyak-banyaknya guna mengumpulkan cadangan energi yang digunakan selama fase pupa."}, {"lv": 3, "q": "Seorang petani membasmi ulat di kebun sayurnya agar daun tidak habis. Namun, beberapa hari kemudian ia menyadari bahwa populasi kupu-kupu di sekitar kebunnya juga ikut menurun drastis. Hubungan yang tepat adalah...", "o": ["Ulat dan kupu-kupu adalah dua jenis hewan yang berbeda siklus", "Ulat adalah salah satu tahapan siklus hidup kupu-kupu", "Kupu-kupu adalah musuh alami dari ulat sayur", "Ulat tidak berhubungan dengan kupu-kupu"], "a": 1, "p": "Ulat merupakan tahap larva dari kupu-kupu. Membasmi seluruh ulat berarti memutus rantai siklus hidup kupu-kupu."}, {"lv": 3, "q": "Perhatikan ciri-ciri tahapan hidup suatu hewan: (1) Bentuk tubuh sangat berbeda dari induknya, (2) Aktif mencari makan, (3) Sering berganti kulit, (4) Masuk ke dalam fase istirahat sebelum dewasa. Ciri-ciri tersebut secara berurutan paling tepat merujuk pada metamorfosis dari...", "o": ["Belalang", "Kecoa", "Kupu-kupu", "Jangkrik"], "a": 2, "p": "Ciri-ciri tersebut (larva yang berbeda dari induk, aktif makan, hingga fase istirahat/pupa) adalah ciri khas metamorfosis sempurna pada kupu-kupu."}]}, {"id": "ipa-k4-1", "name": "Energi dan perubahannya", "desc": "Sumber dan bentuk energi", "idx": 1, "soal": [{"lv": 1, "q": "Sumber energi terbesar di bumi yang menghasilkan cahaya dan panas adalah...", "o": ["Bahan bakar minyak", "Matahari", "Angin", "Air terjun"], "a": 1, "p": "Matahari adalah sumber energi terbesar di bumi yang memancarkan energi cahaya dan panas bagi seluruh makhluk hidup."}, {"lv": 1, "q": "Alat rumah tangga yang berfungsi mengubah energi listrik menjadi energi panas adalah...", "o": ["Kipas angin", "Televisi", "Setrika", "Lampu pijar"], "a": 2, "p": "Setrika menggunakan arus listrik dan mengubahnya menjadi energi panas untuk merapikan pakaian."}, {"lv": 1, "q": "Kemampuan untuk melakukan suatu usaha atau kerja disebut...", "o": ["Energi", "Gaya", "Massa", "Suhu"], "a": 0, "p": "Energi didefinisikan sebagai kemampuan untuk melakukan usaha atau kerja."}, {"lv": 1, "q": "Makanan yang kita makan sehari-hari memberikan sumber energi bagi tubuh berupa energi...", "o": ["Listrik", "Kimia", "Bunyi", "Gerak"], "a": 1, "p": "Makanan mengandung energi kimia yang diubah oleh tubuh menjadi energi gerak dan panas untuk beraktivitas."}, {"lv": 2, "q": "Perhatikan perubahan energi berikut: (1) Kipas angin dicolokkan ke stopkontak lalu berputar, (2) Radio dinyalakan dengan baterai hingga bersuara. Perubahan energi yang benar secara berturut-turut adalah...", "o": ["Listrik menjadi gerak, dan kimia menjadi bunyi", "Panas menjadi cahaya, dan listrik menjadi gerak", "Kimia menjadi listrik, dan gerak menjadi panas", "Gerak menjadi listrik, dan bunyi menjadi kimia"], "a": 0, "p": "Kipas angin mengubah energi listrik menjadi gerak, sedangkan radio dengan baterai mengubah energi kimia menjadi bunyi."}, {"lv": 2, "q": "Pembangkit Listrik Tenaga Air (PLTA) memanfaatkan aliran air sungai atau air terjun untuk menghasilkan energi...", "o": ["Panas", "Cahaya", "Listrik", "Kimia"], "a": 2, "p": "Energi gerak dari aliran air digunakan untuk memutar turbin generator sehingga menghasilkan energi listrik."}, {"lv": 2, "q": "Saat kita menyalakan senter menggunakan baterai baru, terjadi perubahan bentuk energi dari...", "o": ["Listrik menjadi kimia lalu cahaya", "Kimia menjadi listrik lalu cahaya dan panas", "Panas menjadi gerak lalu cahaya", "Cahaya menjadi listrik lalu bunyi"], "a": 1, "p": "Baterai menyimpan energi kimia yang diubah menjadi arus listrik, lalu mengalir ke lampu senter dan diubah menjadi cahaya serta panas."}, {"lv": 2, "q": "Sumber energi alternatif yang ramah lingkungan dan berasal dari hembusan angin digunakan untuk menggerakkan...", "o": ["Kincir angin (turbin angin)", "Mesin uap kereta", "Kompor gas", "Sepeda motor"], "a": 0, "p": "Kincir angin memanfaatkan energi gerak dari angin untuk diubah menjadi energi listrik atau keperluan lainnya."}, {"lv": 3, "q": "Ibu menjemur pakaian basah di halaman rumah yang terkena terik matahari. Beberapa jam kemudian pakaian tersebut menjadi kering. Perubahan dan pemanfaatan bentuk energi yang terjadi adalah...", "o": ["Energi kimia dari matahari mengubah air menjadi es", "Energi panas matahari membuat air dalam pakaian menguap", "Energi listrik dari matahari menghasilkan angin kencang", "Energi bunyi dari udara menyerap air di baju"], "a": 1, "p": "Energi panas matahari memberikan kalor yang menyebabkan air pada pakaian basah mengalami penguapan sehingga pakaian menjadi kering."}, {"lv": 3, "q": "Rudi bermain gitar di kamarnya. Ia memetik senar gitar sehingga menghasilkan bunyi yang merdu. Bentuk perubahan energi yang terjadi saat senar gitar dipetik adalah...", "o": ["Energi listrik menjadi energi bunyi", "Energi kimia menjadi energi cahaya", "Energi gerak (kinetik) menjadi energi bunyi", "Energi panas menjadi energi gerak"], "a": 2, "p": "Gerakan jari memetik senar menciptakan getaran (energi gerak) yang merambat di udara dan menghasilkan gelombang bunyi."}, {"lv": 3, "q": "Bensin pada kendaraan bermotor merupakan sumber energi kimia. Ketika kendaraan dikendarai, terjadi berbagai perubahan energi. Manakah urutan perubahan energi yang tepat?", "o": ["Energi kimia -> Energi gerak -> Energi panas dan bunyi", "Energi listrik -> Energi kimia -> Energi cahaya", "Energi gerak -> Energi kimia -> Energi listrik", "Energi panas -> Energi bunyi -> Energi kimia"], "a": 0, "p": "Bensin (energi kimia) dibakar di dalam mesin untuk menghasilkan tenaga gerak (kinetik), serta menghasilkan sisa berupa panas dan bunyi."}, {"lv": 3, "q": "Panel surya yang dipasang di atas atap rumah berfungsi untuk menangkap sinar matahari dan mengubahnya langsung menjadi...", "o": ["Energi gerak", "Energi listrik", "Energi bunyi", "Energi kimia"], "a": 1, "p": "Panel surya (sel fotovoltaik) dirancang khusus untuk mengubah energi cahaya matahari menjadi energi listrik yang dapat digunakan di rumah."}]}, {"id": "ipa-k4-2", "name": "Bunyi", "desc": "Sumber bunyi dan perambatannya", "idx": 2, "soal": [{"lv": 1, "q": "Segala sesuatu yang menghasilkan bunyi disebut sebagai...", "o": ["Sumber bunyi", "Peredam bunyi", "Pantulan bunyi", "Gelombang suara"], "a": 0, "p": "Sumber bunyi adalah segala benda yang bergetar dan menghasilkan bunyi."}, {"lv": 1, "q": "Bunyi dapat didengar oleh telinga kita karena berasal dari benda yang sedang...", "o": ["Mendingin", "Bergetar", "Membeku", "Memancarkan cahaya"], "a": 1, "p": "Bunyi dihasilkan oleh benda yang bergetar. Getaran tersebut merambat melalui medium sampai ke telinga."}, {"lv": 1, "q": "Medium atau perantara perambatan bunyi yang paling cepat menghantarkan suara adalah...", "o": ["Zat gas (udara)", "Zat cair", "Zat padat", "Ruang hampa udara"], "a": 2, "p": "Partikel pada zat padat tersusun sangat rapat, sehingga bunyi dapat merambat paling cepat melalui zat padat dibandingkan zat cair dan gas."}, {"lv": 1, "q": "Alat komunikasi sederhana yang terbuat dari dua buah kaleng bekas yang dihubungkan dengan sebutang benang memanfaatkan perambatan bunyi melalui...", "o": ["Benda cair", "Benda padat (benang)", "Ruang hampa", "Cahaya matahari"], "a": 1, "p": "Pada telepon kaleng, benang yang tegang bertindak sebagai benda padat tempat merambatnya getaran suara."}, {"lv": 2, "q": "Perhatikan media perambatan berikut: (1) Air kolam, (2) Ruang hampa di luar angkasa, (3) Kayu meja, (4) Udara di dalam ruangan. Media yang dapat merambatkan bunyi ditunjukkan oleh nomor...", "o": ["(1), (2), dan (3)", "(1), (3), dan (4)", "(2), (3), dan (4)", "Semua benar"], "a": 1, "p": "Bunyi memerlukan zat perantara (padat, cair, atau gas) untuk merambat. Ruang hampa (2) tidak dapat merambatkan bunyi."}, {"lv": 2, "q": "Mengapa kita tidak dapat mendengar suara di ruang hampa udara (luar angkasa)?", "o": ["Karena suhu di luar angkasa sangat panas", "Karena tidak ada zat perantara atau medium untuk merambatkan getaran bunyi", "Karena gravitasi terlalu kuat", "Karena telinga tertutup helm astronot"], "a": 1, "p": "Bunyi adalah gelombang mekanik yang mutlak memerlukan medium (padat, cair, gas) untuk merambat. Di ruang hampa tidak ada partikel udara."}, {"lv": 2, "q": "Siti menyelam di dalam kolam renang. Saat temannya memukul batu di dalam air, Siti dapat mendengar suara benturan batu tersebut. Hal ini membuktikan bahwa bunyi dapat merambat melalui...", "o": ["Zat cair", "Zat padat", "Zat gas", "Ruang hampa"], "a": 0, "p": "Air di dalam kolam merupakan zat cair yang dapat menjadi medium perambatan bunyi."}, {"lv": 2, "q": "Pantulan bunyi yang terdengar hampir bersamaan dengan bunyi asli sehingga memperkuat bunyi asli disebut...", "o": ["Gema", "Gaung (kerdam)", "Desibel", "Resonansi"], "a": 1, "p": "Gaung adalah bunyi pantul yang terdengar sebagian bersamaan dengan bunyi asli sehingga suara terdengar kurang jelas."}, {"lv": 3, "q": "Ani berteriak di depan dinding tebing yang tinggi. Beberapa detik kemudian, ia mendengar suara teriakannya kembali terdengar jelas setelah suara aslinya selesai. Peristiwa ini dinamakan...", "o": ["Gaung", "Gema", "Resonansi", "Peredaman bunyi"], "a": 1, "p": "Gema adalah bunyi pantul yang terdengar jelas setelah bunyi asli selesai diucapkan, biasanya terjadi di tebing atau jurang yang jauh."}, {"lv": 3, "q": "Bioskop atau studio musik melapisi dinding ruangan mereka dengan bahan-bahan seperti busa, gabus, atau karpet tebal. Tujuan utama pemasangan bahan tersebut adalah...", "o": ["Memantulkan bunyi agar terdengar semakin keras", "Meredam bunyi agar tidak terjadi gaung atau gema yang mengganggu", "Mempercepat perambatan bunyi ke luar ruangan", "Mengubah energi bunyi menjadi energi cahaya"], "a": 1, "p": "Bahan lunak seperti busa dan karpet bersifat menyerap bunyi (peredam) sehingga mencegah pantulan suara yang memantul liar di dalam ruangan."}, {"lv": 3, "q": "Dua orang anak sedang mempraktikkan perambatan bunyi menggunakan selang plastik yang diisi penuh dengan air. Ketika salah satu anak berbicara di ujung selang, anak di ujung satunya mendengar suara dengan jelas. Medium utama yang menghantarkan bunyi pada percobaan tersebut adalah...", "o": ["Udara di dalam selang", "Dinding selang plastik", "Air di dalam selang", "Tangan anak yang memegang selang"], "a": 2, "p": "Karena selang diisi penuh oleh air dan air merupakan penghantar bunyi yang sangat baik, maka suara merambat melalui medium air di dalam selang."}, {"lv": 3, "q": "Kecepatan merambat bunyi berbeda-beda pada setiap medium. Urutan medium dari yang paling lambat hingga yang paling cepat dalam menghantarkan bunyi adalah...", "o": ["Zat padat -> Zat cair -> Zat gas", "Zat gas -> Zat cair -> Zat padat", "Zat cair -> Zat padat -> Zat gas", "Zat gas -> Zat padat -> Zat cair"], "a": 1, "p": "Bunyi merambat paling lambat di udara (gas), lebih cepat di air (cair), dan paling cepat di benda padat karena kerapatan partikelnya."}]}], "5": [{"id": "ipa-k5-0", "name": "Sistem pernapasan manusia", "desc": "Organ dan proses bernapas", "idx": 0, "soal": [{"lv": 1, "q": "Udara yang kita hirup pertama kali masuk ke dalam tubuh melalui organ...", "o": ["Mulut", "Kerongkongan", "Hidung", "Paru-paru"], "a": 2, "p": "Hidung adalah pintu masuk utama udara pernapasan yang dilengkapi dengan rambut dan lendir untuk menyaring udara."}, {"lv": 1, "q": "Di dalam paru-paru terdapat gelembung halus tempat pertukaran oksigen dan karbon dioksida yang disebut...", "o": ["Bronkus", "Alveolus", "Trakea", "Laring"], "a": 1, "p": "Alveolus adalah gelembung-gelembung halus di ujung bronkiolus yang berfungsi sebagai tempat pertukaran oksigen dan karbon dioksida."}, {"lv": 1, "q": "Organ pernapasan yang berupa pipa panjang dan tersusun atas cincin tulang rawan adalah...", "o": ["Trakea", "Bronkus", "Alveolus", "Laring"], "a": 0, "p": "Trakea atau batang tenggorokan adalah saluran pernapasan berbentuk pipa yang terletak setelah laring."}, {"lv": 1, "q": "Gas yang dibuang oleh tubuh melalui proses pengembusan napas adalah...", "o": ["Oksigen", "Nitrogen", "Hidrogen", "Karbon dioksida"], "a": 3, "p": "Manusia menghirup oksigen dan mengeluarkan karbon dioksida serta uap air sebagai sisa pernapasan."}, {"lv": 2, "q": "Apa fungsi utama dari rambut-rambut halus yang terdapat di dalam hidung?", "o": ["Membantu proses pengeluaran udara", "Mengikat oksigen yang masuk", "Menyaring debu dan kotoran dari udara", "Mengatur volume udara yang masuk"], "a": 2, "p": "Rambut hidung berfungsi untuk menyaring debu atau kotoran agar tidak masuk ke saluran pernapasan yang lebih dalam."}, {"lv": 2, "q": "Pada saat kita menghirup napas (inspirasi), posisi otot diafragma akan...", "o": ["Mendatar atau berkontraksi", "Melengkung ke atas", "Mengendur atau relaksasi", "Mengecil dan kaku"], "a": 0, "p": "Saat inspirasi, otot diafragma berkontraksi dan mendatar sehingga rongga dada membesar dan udara masuk."}, {"lv": 2, "q": "Udara yang masuk melalui hidung menjadi lebih hangat dan lembap. Hal ini disebabkan oleh peran...", "o": ["Rambut hidung", "Selaput lendir", "Tulang hidung", "Saraf pembau"], "a": 1, "p": "Selaput lendir berfungsi mengatur suhu dan kelembapan udara yang masuk agar sesuai dengan kondisi tubuh."}, {"lv": 2, "q": "Paru-paru manusia dilindungi oleh sebuah selaput pembungkus yang disebut...", "o": ["Alveolus", "Diafragma", "Pleura", "Perikardium"], "a": 2, "p": "Pleura adalah selaput tipis ganda yang melindungi paru-paru dari gesekan saat proses bernapas."}, {"lv": 3, "q": "Ketika otot diafragma relaksasi (kembali ke posisi semula), maka yang akan terjadi adalah...", "o": ["Oksigen masuk ke dalam paru-paru", "Udara keluar dari paru-paru (ekspirasi)", "Rongga dada menjadi lebih besar", "Paru-paru mengembang maksimal"], "a": 1, "p": "Saat diafragma relaksasi (melengkung ke atas), rongga dada mengecil, tekanan meningkat, dan udara terdorong keluar."}, {"lv": 3, "q": "Seseorang yang sedang berolahraga akan bernapas lebih cepat. Hal ini disebabkan karena...", "o": ["Paru-paru menyempit saat bergerak", "Tubuh membutuhkan lebih banyak energi dan oksigen", "Udara di sekitar menjadi lebih sedikit", "Otot dada mengalami kelelahan"], "a": 1, "p": "Aktivitas fisik meningkatkan kebutuhan energi, sehingga tubuh memerlukan lebih banyak oksigen melalui pernapasan yang lebih cepat."}, {"lv": 3, "q": "Perhatikan jalur berikut: Hidung -> Faring -> Laring -> X -> Bronkus. Bagian X yang merupakan batang tenggorokan adalah...", "o": ["Kerongkongan", "Alveolus", "Trakea", "Bronkiolus"], "a": 2, "p": "Trakea adalah bagian saluran pernapasan setelah laring dan sebelum bercabang menjadi bronkus."}, {"lv": 3, "q": "Jika permukaan alveolus tertutup oleh cairan atau lendir akibat penyakit, gangguan utama yang terjadi adalah...", "o": ["Rambut hidung menjadi rontok", "Nafsu makan meningkat tajam", "Terhambatnya pertukaran oksigen ke darah", "Suara menjadi lebih nyaring"], "a": 2, "p": "Alveolus adalah tempat pertukaran gas. Jika terisi lendir, oksigen sulit masuk ke darah, sehingga menyebabkan sesak napas."}]}, {"id": "ipa-k5-1", "name": "Ekosistem dan rantai makanan", "desc": "Produsen, konsumen, pengurai", "idx": 1, "soal": [{"lv": 1, "q": "Makhluk hidup yang berperan sebagai produsen dalam ekosistem sawah adalah...", "o": ["Tikus", "Belalang", "Padi", "Elang"], "a": 2, "p": "Produsen adalah makhluk hidup yang bisa membuat makanannya sendiri melalui fotosintesis, contohnya adalah tumbuhan hijau seperti padi."}, {"lv": 1, "q": "Makhluk hidup yang tidak dapat membuat makanannya sendiri dan bergantung pada makhluk hidup lain untuk makan disebut...", "o": ["Produsen", "Konsumen", "Pengurai", "Komponen abiotik"], "a": 1, "p": "Konsumen adalah organisme yang mendapatkan energi dengan cara memakan tumbuhan atau hewan lain."}, {"lv": 1, "q": "Organisme yang bertugas menguraikan sisa-sisa makhluk hidup yang telah mati menjadi zat hara adalah...", "o": ["Jamur dan bakteri", "Rumput dan pohon", "Harimau dan singa", "Ulat dan belalang"], "a": 0, "p": "Pengurai atau dekomposer (seperti jamur dan bakteri) berfungsi menghancurkan sisa organisme mati menjadi nutrisi bagi tanah."}, {"lv": 1, "q": "Sumber energi utama bagi seluruh kehidupan di dalam sebuah ekosistem berasal dari...", "o": ["Air", "Tanah", "Angin", "Matahari"], "a": 3, "p": "Energi matahari adalah sumber energi paling utama yang digunakan tumbuhan untuk membuat makanan."}, {"lv": 2, "q": "Perhatikan rantai makanan ini: Rumput -> Belalang -> Katak -> Ular. Dalam rantai makanan tersebut, katak berperan sebagai...", "o": ["Produsen", "Konsumen tingkat I", "Konsumen tingkat II", "Konsumen tingkat III"], "a": 2, "p": "Rumput (Produsen), Belalang (Konsumen I), Katak memakan belalang sehingga menjadi Konsumen II, dan Ular menjadi Konsumen III."}, {"lv": 2, "q": "Di dalam ekosistem laut, makhluk hidup yang bertindak sebagai produsen utama adalah...", "o": ["Fitoplankton", "Ikan kecil", "Ikan hiu", "Udang"], "a": 0, "p": "Fitoplankton adalah tumbuhan sangat kecil di laut yang bisa berfotosintesis, sehingga ia menjadi produsen di ekosistem air."}, {"lv": 2, "q": "Jika dalam sebuah rantai makanan di kebun jumlah ulat menurun drastis karena dibasmi manusia, maka hewan yang akan terganggu karena kekurangan makanan adalah...", "o": ["Burung pemakan ulat", "Rumput hijau", "Jamur pengurai", "Pohon mangga"], "a": 0, "p": "Burung yang sumber makanan utamanya ulat akan kesulitan bertahan hidup jika populasi ulat menghilang."}, {"lv": 2, "q": "Apa yang dimakan oleh konsumen tingkat I (konsumen primer) dalam sebuah rantai makanan?", "o": ["Hewan pemangsa", "Produsen atau tumbuhan", "Pengurai", "Bangkai hewan"], "a": 1, "p": "Konsumen tingkat I adalah hewan herbivora yang langsung memakan produsen (tumbuhan)."}, {"lv": 3, "q": "Di ekosistem sawah, populasi katak menurun drastis karena diburu manusia. Dampak yang paling mungkin terjadi pada populasi belalang dan ular adalah...", "o": ["Belalang berkurang dan ular bertambah", "Belalang bertambah dan ular berkurang", "Belalang dan ular sama-sama bertambah", "Belalang dan ular tidak terpengaruh"], "a": 1, "p": "Karena katak berkurang, belalang (makanan katak) akan meningkat, sedangkan ular (pemakan katak) akan berkurang karena lapar."}, {"lv": 3, "q": "Mengapa tumbuhan hijau selalu menempati posisi paling bawah atau awal dalam sebuah rantai makanan?", "o": ["Karena tumbuhan memiliki jumlah paling sedikit", "Karena tumbuhan dapat mengubah energi cahaya matahari menjadi energi makanan", "Karena semua hewan takut pada tumbuhan", "Karena tumbuhan tidak bisa bergerak"], "a": 1, "p": "Tumbuhan hijau adalah pintu masuk energi ke ekosistem karena kemampuannya melakukan fotosintesis."}, {"lv": 3, "q": "Dalam sebuah ekosistem kebun: Tanaman Mawar -> Kutu Daun -> Burung Kecil. Jika burung kecil banyak ditangkap, maka peristiwa yang terjadi pada tanaman mawar adalah...", "o": ["Tanaman mawar akan semakin subur", "Tanaman mawar akan rusak karena kutu daun meningkat", "Tanaman mawar akan berubah menjadi pohon besar", "Tanaman mawar akan berhenti berbunga"], "a": 1, "p": "Jika burung kecil (predator kutu) hilang, kutu daun akan berkembang biak dengan cepat dan merusak tanaman mawar."}, {"lv": 3, "q": "Bagaimana peran pengurai dalam membantu produsen (tumbuhan) tetap hidup subur?", "o": ["Pengurai melindungi tumbuhan dari serangan hama", "Pengurai memberikan oksigen langsung ke akar tumbuhan", "Pengurai mengubah sisa makhluk mati menjadi nutrisi/zat hara di tanah", "Pengurai membantu penyerbukan bunga"], "a": 2, "p": "Pengurai memecah sisa organisme mati menjadi zat hara (pupuk alami) yang sangat dibutuhkan tumbuhan untuk tumbuh."}]}, {"id": "ipa-k5-2", "name": "Kalor dan perpindahannya", "desc": "Konduksi, konveksi, radiasi", "idx": 2, "soal": [{"lv": 1, "q": "Perpindahan panas melalui zat perantara tanpa disertai perpindahan partikel zat tersebut disebut...", "o": ["Radiasi", "Konveksi", "Konduksi", "Isolasi"], "a": 2, "p": "Konduksi adalah perpindahan panas melalui benda padat (seperti logam) di mana partikel benda tersebut tidak ikut berpindah."}, {"lv": 1, "q": "Benda yang tidak dapat menghantarkan panas dengan baik disebut...", "o": ["Konduktor", "Isolator", "Radiator", "Generator"], "a": 1, "p": "Isolator adalah benda yang sulit atau tidak bisa menghantarkan panas, seperti kayu, plastik, dan kain."}, {"lv": 1, "q": "Perpindahan panas yang diikuti dengan perpindahan bagian-bagian zat perantaranya dinamakan...", "o": ["Konveksi", "Konduksi", "Radiasi", "Refleksi"], "a": 0, "p": "Konveksi terjadi pada zat cair dan gas, di mana panas berpindah bersama dengan aliran partikel zat tersebut."}, {"lv": 1, "q": "Panas matahari yang sampai ke bumi meskipun melewati ruang hampa udara merupakan contoh dari...", "o": ["Konduksi", "Konveksi", "Radiasi", "Kondensasi"], "a": 2, "p": "Radiasi adalah perpindahan panas tanpa memerlukan zat perantara (media), seperti pancaran sinar matahari."}, {"lv": 2, "q": "Mengapa pegangan atau gagang setrika biasanya terbuat dari bahan plastik atau kayu?", "o": ["Agar setrika terlihat lebih bagus", "Karena kayu adalah konduktor panas", "Agar panas dari logam tidak sampai ke tangan kita", "Agar setrika menjadi lebih berat saat digunakan"], "a": 2, "p": "Plastik dan kayu adalah isolator, gunanya untuk menghambat panas agar tangan kita tidak melepuh saat memegang setrika."}, {"lv": 2, "q": "Saat kita memasak air di panci, air yang berada di bagian bawah akan bergerak ke atas setelah panas. Peristiwa ini menunjukkan...", "o": ["Konduksi pada air", "Radiasi dari kompor", "Konveksi pada air", "Penyusutan air"], "a": 2, "p": "Air yang panas menjadi lebih ringan dan bergerak ke atas, digantikan air dingin. Aliran ini adalah ciri khas konveksi."}, {"lv": 2, "q": "Sendok logam yang dimasukkan ke dalam gelas berisi air panas, ujungnya akan ikut terasa panas setelah beberapa saat karena...", "o": ["Panas merambat melalui sendok", "Air panas meresap ke dalam sendok", "Sendok mengeluarkan energi cahaya", "Udara di sekitar gelas sangat panas"], "a": 0, "p": "Logam adalah konduktor yang baik, sehingga panas dari air merambat melalui sendok hingga ke ujungnya (konduksi)."}, {"lv": 2, "q": "Saat berkemah dan duduk di dekat api unggun, badan kita akan terasa hangat. Hal ini disebabkan oleh...", "o": ["Aliran udara panas (konveksi)", "Rambatan panas melalui tanah (konduksi)", "Pancaran panas dari api (radiasi)", "Panas yang berpindah melalui kayu api"], "a": 2, "p": "Rasa hangat dari api unggun sampai ke tubuh kita melalui pancaran atau radiasi, tanpa perlu menyentuh api tersebut."}, {"lv": 3, "q": "Seorang perajin keris memanaskan besi hingga membara. Meskipun ia memegang pangkal besi yang panjang, tangannya tetap terasa panas. Hal ini menjelaskan bahwa...", "o": ["Partikel besi berpindah menuju tangan perajin", "Besi adalah isolator yang sangat buruk", "Panas merambat melalui getaran partikel besi tanpa berpindahnya besi itu", "Panas hanya bisa berpindah jika ada bantuan angin"], "a": 2, "p": "Ini adalah analisis konduksi: panas merambat melalui partikel-partikel besi yang saling bergetar, namun besi itu sendiri tidak mengalir menuju tangan."}, {"lv": 3, "q": "Fenomena angin darat dan angin laut yang dimanfaatkan nelayan untuk pergi dan pulang melaut terjadi karena...", "o": ["Konduksi antara air laut dan daratan", "Radiasi matahari yang tidak merata", "Perpindahan panas secara konveksi pada udara", "Tarikan gravitasi bulan pada air laut"], "a": 2, "p": "Perbedaan suhu antara darat dan laut menyebabkan aliran udara (angin). Aliran massa udara karena perbedaan panas ini disebut konveksi."}, {"lv": 3, "q": "Mengapa dinding bagian dalam termos air panas terbuat dari kaca yang mengkilap seperti cermin?", "o": ["Untuk memantulkan panas kembali agar suhu air terjaga (mencegah radiasi)", "Supaya air di dalam termos terlihat lebih jernih", "Agar kaca tidak mudah pecah saat terkena air mendidih", "Untuk mempermudah pembersihan kerak di dalam termos"], "a": 0, "p": "Permukaan mengkilap berfungsi sebagai pemantul radiasi panas kembali ke dalam air, sehingga air tetap panas dalam waktu lama."}, {"lv": 3, "q": "Ibu ingin memasak sayur dengan cepat. Ia memiliki dua panci dengan ukuran sama, satu dari aluminium dan satu dari tanah liat. Ibu memilih panci aluminium karena...", "o": ["Aluminium adalah isolator yang lebih baik", "Aluminium memiliki daya hantar panas (konduktivitas) yang lebih tinggi", "Tanah liat dapat menyerap semua air sayuran", "Panci aluminium lebih ringan sehingga cepat panas"], "a": 1, "p": "Logam seperti aluminium adalah konduktor yang lebih kuat dibanding tanah liat, sehingga panas api lebih cepat sampai ke masakan."}]}], "6": [{"id": "ipa-k6-0", "name": "Tata surya", "desc": "Matahari, planet, dan satelit", "idx": 0, "soal": [{"lv": 1, "q": "Pusat dari sistem tata surya kita adalah...", "o": ["Bumi", "Bulan", "Matahari", "Jupiter"], "a": 2, "p": "Matahari adalah bintang yang menjadi pusat tata surya di mana seluruh planet dan benda langit lainnya beredar mengitarinya."}, {"lv": 1, "q": "Planet yang letaknya paling dekat dengan Matahari adalah...", "o": ["Merkurius", "Venus", "Bumi", "Mars"], "a": 0, "p": "Merkurius adalah planet pertama dalam tata surya yang posisinya paling dekat dengan Matahari."}, {"lv": 1, "q": "Planet terbesar di dalam tata surya kita adalah...", "o": ["Saturnus", "Jupiter", "Uranus", "Neptunus"], "a": 1, "p": "Jupiter adalah planet raksasa gas yang memiliki ukuran terbesar di antara semua planet dalam tata surya."}, {"lv": 1, "q": "Benda langit yang mengelilingi planet disebut sebagai...", "o": ["Meteor", "Komet", "Asteroid", "Satelit"], "a": 3, "p": "Satelit adalah benda langit yang beredar mengelilingi sebuah planet, contohnya Bulan yang mengitari Bumi."}, {"lv": 2, "q": "Planet Venus sering dijuluki sebagai \"bintang kejora\" atau \"bintang timur\" yang tampak bersinar terang di pagi atau sore hari. Hal ini disebabkan oleh...", "o": ["Venus memancarkan cahaya sendiri seperti matahari", "Venus memiliki atmosfer tebal yang memantulkan cahaya matahari dengan sangat baik", "Venus adalah planet terpanas yang menghasilkan api", "Venus letaknya sangat jauh dari bumi"], "a": 1, "p": "Venus tampak sangat terang karena awan tebal di atmosfernya memantulkan kembali cahaya matahari ke bumi."}, {"lv": 2, "q": "Perhatikan ciri-ciri planet berikut: (1) Dijuluki planet merah, (2) Memiliki dua satelit alami bernama Phobos dan Deimos, (3) Berada di antara orbit Bumi dan Jupiter. Planet yang dimaksud adalah...", "o": ["Mars", "Venus", "Saturnus", "Uranus"], "a": 0, "p": "Mars dikenal sebagai planet merah karena permukaannya kaya akan besi oksida, serta memiliki dua satelit yaitu Phobos dan Deimos."}, {"lv": 2, "q": "Pembatas antara planet dalam dan planet luar dalam tata surya terletak pada sabuk yang berisi ribuan benda langit kecil. Sabuk tersebut dinamakan...", "o": ["Sabuk Kuiper", "Sabuk Asteroid", "Galaksi Bima Sakti", "Cincin Saturnus"], "a": 1, "p": "Sabuk asteroid terletak di antara orbit planet Mars dan Jupiter, menjadi pembatas antara kelompok planet dalam dan planet luar."}, {"lv": 2, "q": "Planet Saturnus sangat mudah dikenali dan terkenal karena memiliki ciri khas yang unik, yaitu...", "o": ["Memiliki permukaan yang dipenuhi air", "Merupakan planet terkecil di tata surya", "Dikelilingi oleh sistem cincin yang sangat indah dan luas", "Berotasi searah dengan jarum jam"], "a": 2, "p": "Saturnus terkenal dengan cincin megahnya yang tersusun atas partikel es, debu, dan batuan."}, {"lv": 3, "q": "Bumi memerlukan waktu sekitar 365,25 hari untuk satu kali mengelilingi matahari (revolusi bumi). Dampak langsung dari pergerakan revolusi bumi bagi kehidupan di bumi adalah...", "o": ["Terjadinya siang dan malam", "Pergantian musim di belahan bumi utara dan selatan", "Gerak semu harian benda langit dari timur ke barat", "Perbedaan waktu di berbagai belahan dunia"], "a": 1, "p": "Revolusi bumi beserta kemiringan sumbu bumi menyebabkan terjadinya pergantian musim di berbagai belahan bumi."}, {"lv": 3, "q": "Planet Uranus memiliki keunikan dibandingkan planet-planet lainnya dalam hal arah rotasi. Bagaimana karakteristik rotasi planet Uranus?", "o": ["Uranus berotasi dari timur ke barat seperti Venus", "Uranus berotasi dengan sumbu miring hampir sejajar dengan bidang orbitnya sehingga tampak menggelinding", "Uranus tidak melakukan rotasi sama sekali", "Uranus berotasi sangat cepat hanya dalam waktu 1 jam"], "a": 1, "p": "Sumbu rotasi Uranus sangat miring (hampir 98 derajat) sehingga planet ini berputar seperti bola yang menggelinding di jalurnya."}, {"lv": 3, "q": "Mengapa Pluto yang dulunya dikategorikan sebagai planet kesembilan kini dikeluarkan dari daftar planet utama dalam tata surya dan statusnya diubah menjadi planet kerdil (dwarf planet)?", "o": ["Karena ukuran Pluto terlalu besar dan tidak mirip planet lain", "Karena orbit Pluto berpotongan dengan planet Neptunus dan tidak mampu membersihkan lingkungan di sekitar orbitnya dari benda lain", "Karena Pluto tidak memiliki satelit alami", "Karena Pluto telah menabrak matahari"], "a": 1, "p": "Berdasarkan keputusan IAU tahun 2006, planet harus memiliki ukuran yang cukup untuk membersihkan orbitnya dari benda lain, syarat yang tidak dipenuhi oleh Pluto."}, {"lv": 3, "q": "Dua planet dalam sistem tata surya kita diketahui tidak memiliki satelit alami satu pun. Planet-planet tersebut adalah...", "o": ["Merkurius dan Venus", "Bumi dan Mars", "Uranus dan Neptunus", "Mars dan Saturnus"], "a": 0, "p": "Dari kedelapan planet, hanya Merkurius dan Venus yang tidak memiliki satelit alami karena pengaruh gravitasi matahari yang terlalu kuat dan dekat."}]}, {"id": "ipa-k6-1", "name": "Rangkaian listrik sederhana", "desc": "Seri dan paralel", "idx": 1, "soal": [{"lv": 1, "q": "Rangkaian listrik yang disusun secara berderet atau berurutan tanpa cabang disebut rangkaian...", "o": ["Seri", "Paralel", "Campuran", "Terbuka"], "a": 0, "p": "Rangkaian seri adalah rangkaian komponen listrik yang disusun secara berderet dalam satu jalur aliran listrik tanpa adanya cabang."}, {"lv": 1, "q": "Sumber energi listrik yang biasa digunakan pada rangkaian listrik sederhana di sekolah untuk percobaan adalah...", "o": ["Kipas angin", "Baterai", "Kabel", "Sakelar"], "a": 1, "p": "Baterai berfungsi sebagai sumber arus listrik searah (DC) yang menyuplai energi pada rangkaian percobaan."}, {"lv": 1, "q": "Alat yang berfungsi untuk menyambung dan memutus aliran arus listrik dalam suatu rangkaian adalah...", "o": ["Kabel", "Lampu", "Sakelar", "Baterai"], "a": 2, "p": "Sakelar adalah komponen yang digunakan untuk mengontrol aliran listrik dengan cara membuka atau menutup jalur sirkuit."}, {"lv": 1, "q": "Rangkaian listrik di rumah-rumah penduduk pada umumnya disusun secara...", "o": ["Seri", "Paralel", "Tunggal", "Melingkar"], "a": 1, "p": "Rangkaian paralel banyak digunakan di rumah karena jika satu lampu mati, lampu yang lain tetap menyala dan pembagian arus lebih stabil."}, {"lv": 2, "q": "Perhatikan ciri-ciri rangkaian listrik berikut: Jika satu lampu dipadamkan atau dilepas dari soketnya, maka lampu yang lain akan ikut padam. Karakteristik tersebut dimiliki oleh rangkaian...", "o": ["Paralel", "Campuran", "Seri", "Terbuka"], "a": 2, "p": "Pada rangkaian seri, hanya terdapat satu jalur aliran listrik. Jika jalur tersebut terputus (satu lampu mati), seluruh lampu akan ikut padam."}, {"lv": 2, "q": "Budi membuat rangkaian listrik dengan dua buah lampu yang dipasang secara paralel pada papan peraga. Keuntungan utama dari penggunaan rangkaian paralel ini adalah...", "o": ["Hemat kabel dan komponen", "Jika satu lampu padam, lampu lain tetap menyala", "Semua lampu akan menyala sangat redup", "Arus listrik yang mengalir sangat kecil"], "a": 1, "p": "Rangkaian paralel memiliki banyak cabang jalur. Apabila satu lampu rusak atau mati, arus listrik tetap dapat mengalir ke jalur lampu lainnya."}, {"lv": 2, "q": "Bahan yang dapat menghantarkan arus listrik dengan baik dan biasa digunakan untuk membuat kabel listrik adalah...", "o": ["Plastik dan karet", "Kayu dan kaca", "Tembaga dan aluminium", "Kain dan kertas"], "a": 2, "p": "Tembaga dan aluminium adalah konduktor yang baik karena memiliki hambatan jenis yang kecil sehingga mudah dilalui arus listrik."}, {"lv": 2, "q": "Bahan yang tidak dapat menghantarkan arus listrik disebut isolator. Contoh bahan isolator yang sering digunakan untuk membungkus kabel adalah...", "o": ["Tembaga", "Karet atau plastik", "Besi", "Perak"], "a": 1, "p": "Karet dan plastik bersifat isolator (menghambat listrik) sehingga aman digunakan untuk melapisi kabel agar tidak tersengat aliran listrik."}, {"lv": 3, "q": "Siti merangkai tiga buah lampu identik secara seri pada sebuah baterai. Ketika sakelar ditutup, ia memerhatikan bahwa nyala ketiga lampu tersebut tampak lebih redup dibandingkan jika dipasang secara paralel. Mengapa hal tersebut bisa terjadi?", "o": ["Karena tegangan baterai terbagi ke setiap lampu dalam satu jalur seri", "Karena kabel pada rangkaian seri terlalu pendek", "Karena hambatan total rangkaian seri sangat kecil", "Karena daya baterai langsung habis seketika"], "a": 0, "p": "Pada rangkaian seri, tegangan dari sumber (baterai) harus dibagi ke setiap beban (lampu) yang terhubung berderet, sehingga tegangan tiap lampu lebih kecil dan nyawanya lebih redup."}, {"lv": 3, "q": "Perhatikan sebuah rangkaian listrik gabungan (campuran): Terdapat tiga buah lampu (L1, L2, dan L3). Lampu L1 dipasang secara seri dengan gabungan paralel lampu L2 dan L3. Apa yang akan terjadi jika lampu L1 tiba-tiba putus?", "o": ["Lampu L2 dan L3 akan tetap menyala terang", "Seluruh lampu (L1, L2, dan L3) akan padam", "Hanya lampu L2 yang menyala, sedangkan L3 padam", "Lampu L2 dan L3 akan menyala lebih terang dari sebelumnya"], "a": 1, "p": "Karena lampu L1 terhubung secara seri pada jalur utama sebelum arus bercabang ke L2 dan L3, putusnya L1 akan memutus total seluruh aliran arus dari sumber."}, {"lv": 3, "q": "Ani menyusun rangkaian listrik paralel menggunakan dua buah lampu dan dua baterai. Ia ingin membuat nyala kedua lampu tersebut menjadi lebih terang. Tindakan yang paling tepat dilakukan Ani adalah...", "o": ["Menambahkan jumlah lampu secara seri", "Menambahkan jumlah baterai secara seri pada rangkaian", "Memotong sebagian kabel penghubung", "Mengganti kawat tembaga dengan benang wol"], "a": 1, "p": "Menambahkan sumber tegangan (baterai) secara seri akan memperbesar tegangan total yang masuk ke rangkaian, sehingga arus bertambah dan lampu menyala lebih terang."}, {"lv": 3, "q": "Dalam suatu instalasi listrik sederhana, kabel penghubung yang terkelupas dan saling bersentuhan langsung tanpa melalui beban (lampu atau hambatan) dapat menyebabkan terjadinya korsleting (hubungan singkat). Dampak berbahaya dari peristiwa ini adalah...", "o": ["Lampu menyala sangat terang benderang", "Arus listrik terhenti dan baterai menjadi sangat dingin", "Aliran arus menjadi sangat besar, kabel menjadi panas, dan berpotensi menimbulkan percikan api", "Semua komponen listrik berubah menjadi magnet"], "a": 2, "p": "Korsleting terjadi ketika hambatan rangkaian mendekati nol, menyebabkan lonjakan arus listrik yang sangat besar sehingga kabel cepat panas dan berbahaya."}]}, {"id": "ipa-k6-2", "name": "Perkembangbiakan makhluk hidup", "desc": "Generatif dan vegetatif", "idx": 2, "soal": [{"lv": 1, "q": "Perkembangbiakan tumbuhan secara generatif melibatkan peleburan antara sel kelamin jantan dan sel kelamin betina. Alat perkembangbiakan generatif pada tumbuhan berbunga adalah...", "o": ["Akar", "Batang", "Bunga", "Daun"], "a": 2, "p": "Bunga adalah alat perkembangbiakan generatif pada tumbuhan karena di dalamnya terdapat benang sari (sel kelamin jantan) dan putik (sel kelamin betina)."}, {"lv": 1, "q": "Perkembangbiakan makhluk hidup tanpa melalui proses perkawinan atau peleburan sel kelamin disebut perkembangbiakan...", "o": ["Generatif", "Vegetatif", "Seksual", "Kopulasi"], "a": 1, "p": "Perkembangbiakan vegetatif adalah cara reproduksi makhluk hidup tanpa melibatkan pertemuan sel kelamin jantan dan betina (aseksual)."}, {"lv": 1, "q": "Tanaman bawang merah berkembang biak secara vegetatif alami menggunakan...", "o": ["Akar tinggal (rizoma)", "Umbi lapis", "Geragih (stolon)", "Tunas adventif"], "a": 1, "p": "Bawang merah berkembang biak dengan umbi lapis, yaitu susunan daun berlapis-lapis yang mengelilingi umbi utama."}, {"lv": 1, "q": "Hewan yang berkembang biak dengan cara melahirkan disebut juga hewan...", "o": ["Ovipar", "Vivipar", "Ovovivipar", "Fagosit"], "a": 1, "p": "Hewan vivipar adalah kelompok hewan yang berkembang biak dengan cara melahirkan anak setelah embrio berkembang di dalam tubuh induknya (beranak)."}, {"lv": 2, "q": "Perhatikan beberapa tumbuhan berikut: (1) Jahe, (2) Kunyit, (3) Lengkuas. Ketiga jenis tumbuhan tersebut berkembang biak secara vegetatif alami menggunakan...", "o": ["Umbi batang", "Akar tinggal (rizoma/rimpang)", "Spora", "Geragih"], "a": 1, "p": "Jahe, kunyit, dan lengkuas merupakan kelompok tanaman rempah yang berkembang biak menggunakan akar tinggal atau rizoma."}, {"lv": 2, "q": "Pernyataan yang paling tepat untuk membedakan perkembangbiakan generatif dan vegetatif buatan pada tumbuhan adalah...", "o": ["Generatif melibatkan bantuan manusia, sedangkan vegetatif buatan terjadi sendiri di alam", "Generatif melalui peleburan sel kelamin dan menghasilkan sifat baru, sedangkan vegetatif buatan sengaja dibantu manusia tanpa perkawinan", "Vegetatif buatan menghasilkan biji, sedangkan generatif menghasilkan umbi", "Tidak ada perbedaan yang signifikan antara keduanya"], "a": 1, "p": "Perkembangbiakan generatif melibatkan peleburan sel kelamin (kawin), sedangkan vegetatif buatan adalah perkembangbiakan aseksual yang sengaja dibantu manusia seperti mencangkok atau setek."}, {"lv": 2, "q": "Cicak dan kadal adalah contoh hewan yang berkembang biak secara generatif dengan cara bertelur. Kelompok hewan bertelur disebut...", "o": ["Vivipar", "Ovipar", "Ovovivipar", "Mammalia"], "a": 1, "p": "Ovipar adalah istilah biologis untuk hewan yang berkembang biak dengan cara bertelur, di mana embrio berkembang di dalam telur di luar tubuh induk."}, {"lv": 2, "q": "Pak Tani ingin memperbanyak tanaman mangga manis miliknya dalam jumlah banyak dengan sifat yang persis sama dengan induknya serta cepat berbuah. Teknik perkembangbiakan vegetatif buatan yang paling tepat dipilih adalah...", "o": ["Menanam biji mangga", "Mencangkok atau menyambung (enten)", "Menanam spora", "Menunggu penyerbukan alami oleh angin"], "a": 1, "p": "Mencangkok atau menyambung adalah cara vegetatif buatan yang menghasilkan keturunan dengan sifat identik dengan induknya dan lebih cepat berbuah dibanding dari biji."}, {"lv": 3, "q": "Ular boa dan hiu pasir memiliki cara perkembangbiakan generatif yang unik, yaitu sel telur dibuahi di dalam tubuh induk dan embrio berkembang di dalam telur yang tetap berada di dalam tubuh induknya hingga menetas, kemudian dilahirkan. Cara perkembangbiakan ini dinamakan...", "o": ["Ovipar", "Vivipar", "Ovovivipar", "Fragmentasi"], "a": 2, "p": "Ovovivipar adalah perkembangbiakan hewan dengan cara bertelur sekaligus melahirkan (bertelur-beranak), di mana telur menetas di dalam tubuh induk lalu dilahirkan."}, {"lv": 3, "q": "Tanaman cocor bebek memiliki tunas pada bagian daunnya yang dapat tumbuh menjadi individu baru. Apa keuntungan biologis dari perkembangbiakan vegetatif jenis ini bagi kelangsungan hidup cocor bebek?", "o": ["Menghasilkan variasi genetik yang sangat beragam pada keturunannya", "Memungkinkan tanaman berkembang biak dengan cepat tanpa harus menunggu berbunga dan menghasilkan biji", "Membuat tanaman kebal terhadap semua jenis penyakit daun", "Memperpanjang siklus hidup tanaman hingga ratusan tahun"], "a": 1, "p": "Keuntungan perkembangbiakan vegetatif adalah tumbuhan dapat menghasilkan keturunan baru dengan cepat tanpa harus melewati proses pembungaan dan penyerbukan yang memakan waktu."}, {"lv": 3, "q": "Perhatikan proses penyerbukan pada bunga: Serbuk sari jatuh ke kepala putik pada bunga yang sama. Penyerbukan jenis ini disebut penyerbukan sendiri. Apa kekurangan utama dari penyerbukan sendiri dibandingkan penyerbukan silang?", "o": ["Tanaman gagal berbuah sama sekali", "Keturunan yang dihasilkan tidak memiliki keragaman sifat atau variasi genetik yang baru", "Prosesnya memerlukan bantuan hewan penyerbuk seperti lebah", "Membutuhkan waktu bertahun-tahun untuk bertunas"], "a": 1, "p": "Penyerbukan sendiri menyatukan materi genetik dari individu yang sama (atau bunga yang sama), sehingga keturunannya sangat sedikit atau tidak memiliki variasi genetik baru."}, {"lv": 3, "q": "Hewan seperti planaria (cacing pipih) dapat berkembang biak secara aseksual apabila tubuhnya terpotong menjadi beberapa bagian, di mana setiap potongan tubuh akan tumbuh menjadi individu utuh. Metode perkembangbiakan vegetatif hewan ini disebut...", "o": ["Membelah diri", "Fragmentasi", "Tunas", "Partenogenesis"], "a": 1, "p": "Fragmentasi adalah cara perkembangbiakan hewan (seperti planaria dan bintang laut) di mana potongan tubuh hewan tersebut dapat regenerasi menjadi individu yang utuh."}]}], "7": [{"id": "ipa-k7-0", "name": "Besaran dan satuan", "desc": "Besaran pokok, turunan, dan satuan SI", "idx": 0, "soal": [{"lv": 1, "q": "Segala sesuatu yang dapat diukur dan dinyatakan dengan angka serta memiliki satuan disebut...", "o": ["Besaran", "Satuan", "Alat ukur", "Konversi"], "a": 0, "p": "Besaran adalah segala sesuatu yang dapat diukur, bernilai, dan memiliki satuan."}, {"lv": 1, "q": "Dalam Sistem Internasional (SI), satuan standar untuk besaran massa adalah...", "o": ["Gram", "Kilogram", "Miligram", "Pound"], "a": 1, "p": "Kilogram (kg) adalah satuan SI yang ditetapkan untuk besaran pokok massa."}, {"lv": 1, "q": "Kelompok besaran di bawah ini yang semuanya merupakan besaran pokok adalah...", "o": ["Panjang, massa, waktu", "Luas, volume, kecepatan", "Gaya, tekanan, massa jenis", "Suhu, kuat arus, gaya"], "a": 0, "p": "Panjang, massa, dan waktu adalah bagian dari tujuh besaran pokok dalam SI."}, {"lv": 1, "q": "Satuan baku internasional (SI) untuk besaran suhu adalah...", "o": ["Celsius", "Fahrenheit", "Kelvin", "Reamur"], "a": 2, "p": "Kelvin (K) merupakan satuan SI untuk besaran pokok suhu mutlak."}, {"lv": 2, "q": "Luas suatu ruangan berbentuk persegi panjang diukur dengan mengalikan panjang dan lebarnya. Berdasarkan hal tersebut, besaran luas dikategorikan sebagai...", "o": ["Besaran pokok", "Besaran turunan", "Besaran skalar murni", "Besaran tambahan"], "a": 1, "p": "Luas diturunkan dari besaran pokok panjang (panjang dikali lebar), sehingga termasuk besaran turunan."}, {"lv": 2, "q": "Perhatikan beberapa satuan berikut: (1) Newton, (2) Meter per sekon, (3) Sekon, (4) Meter kubik. Yang merupakan satuan untuk besaran turunan ditunjukkan oleh nomor...", "o": ["(1), (2), dan (3)", "(1), (2), dan (4)", "(2), (3), dan (4)", "Semua benar"], "a": 1, "p": "Newton (gaya), meter per sekon (kecepatan), dan meter kubik (volume) adalah satuan dari besaran turunan. Sekon adalah satuan besaran pokok waktu."}, {"lv": 2, "q": "Hasil konversi dari 2,5 kilometer ke meter adalah...", "o": ["25 meter", "250 meter", "2.500 meter", "25.000 meter"], "a": 2, "p": "1 kilometer setara dengan 1.000 meter, sehingga 2,5 km dikali 1.000 sama dengan 2.500 meter."}, {"lv": 2, "q": "Alat ukur yang memiliki ketelitian paling tinggi untuk mengukur diameter luar kelereng kecil adalah...", "o": ["Mistar", "Meteran gulung", "Jangka sorong", "Neraca ohaus"], "a": 2, "p": "Jangka sorong memiliki tingkat ketelitian hingga 0,1 mm, sangat tepat untuk mengukur benda-benda kecil seperti diameter kelereng."}, {"lv": 3, "q": "Massa jenis suatu zat cair dinyatakan dalam persamaan massa dibagi volume. Jika satuan massa dalam SI adalah kilogram (kg) dan volume adalah meter kubik (m³), maka satuan SI untuk besaran turunan massa jenis adalah...", "o": ["kg m/s", "kg/m³", "kg m²", "kg/s²"], "a": 1, "p": "Satuan SI untuk massa adalah kg dan volume adalah m³, sehingga satuan massa jenis adalah kg dibagi m³ (kg/m³)."}, {"lv": 3, "q": "Seorang siswa mengukur ketebalan plat logam tipis menggunakan mikrometer sekrup dan mencatat hasil pembacaan skala utamanya 3,5 mm serta skala noniusnya 0,22 mm. Berapa hasil pengukuran tebal plat logam tersebut?", "o": ["3,522 mm", "3,72 mm", "5,70 mm", "3,28 mm"], "a": 1, "p": "Hasil pengukuran pada mikrometer sekrup diperoleh dengan menjumlahkan skala utama dan skala nonius: 3,5 mm + 0,22 mm = 3,72 mm."}, {"lv": 3, "q": "Kecepatan mobil balap tercatat 72 kilometer per jam (km/jam). Jika dikonversikan ke dalam satuan Internasional (SI) yaitu meter per sekon (m/s), nilai kecepatan tersebut adalah...", "o": ["10 m/s", "20 m/s", "25 m/s", "36 m/s"], "a": 1, "p": "72 km/jam disetarakan dengan mengalikan 1.000 dan membagi 3.600, sehingga diperoleh 20 m/s."}, {"lv": 3, "q": "Mengapa dalam pengukuran ilmiah di laboratorium seluruh dunia disepakati untuk menggunakan satu sistem satuan standar internasional (SI), alih-alih menggunakan satuan tradisional lokal seperti hasta, depa, atau kaki?", "o": ["Karena satuan tradisional lokal bersifat tidak baku (nilainya berbeda-beda tergantung orang yang mengukur) sehingga tidak menghasilkan data yang valid secara universal", "Karena satuan internasional jauh lebih mudah dihitung menggunakan kalkulator", "Karena satuan tradisional sudah punah dan dilarang oleh pemerintah", "Karena alat ukur internasional terbuat dari bahan emas murni"], "a": 0, "p": "Satuan tradisional tidak baku karena ukurannya tidak tetap (berbeda setiap orang), sehingga diperlukan satuan internasional (SI) yang bersifat tetap, seragam, dan diakui secara global."}]}, {"id": "ipa-k7-1", "name": "Klasifikasi makhluk hidup", "desc": "Ciri dan pengelompokan", "idx": 1, "soal": [{"lv": 1, "q": "Ilmuwan yang pertama kali memperkenalkan sistem penamaan ilmiah ganda (binomial nomenklatur) adalah...", "o": ["Charles Darwin", "Gregor Mendel", "Carolus Linnaeus", "Aristoteles"], "a": 2, "p": "Carolus Linnaeus dikenal sebagai bapak taksonomi modern yang memperkenalkan sistem penanaman makhluk hidup binomial nomenklatur."}, {"lv": 1, "q": "Ciri makhluk hidup yang menunjukkan kemampuan untuk menanggapi rangsang dari luar adalah...", "o": ["Iritabilitas", "Ekskresi", "Respirasi", "Adaptasi"], "a": 0, "p": "Iritabilitas adalah kemampuan makhluk hidup dalam menerima dan menanggapi rangsangan dari lingkungan sekitar."}, {"lv": 1, "q": "Urutan takson tumbuhan dari tingkat yang tertinggi hingga terendah yang benar adalah...", "o": ["Spesies - Genus - Familia - Ordo - Kelas - Filum - Kingdom", "Kingdom - Divisi/Filum - Kelas - Ordo - Familia - Genus - Spesies", "Genus - Spesies - Ordo - Kelas - Familia - Divisi - Kingdom", "Kingdom - Ordo - Kelas - Divisi - Familia - Genus - Spesies"], "a": 1, "p": "Urutan takson dari tinggi ke rendah untuk tumbuhan adalah Kingdom, Divisi, Kelas, Ordo, Familia, Genus, dan Spesies."}, {"lv": 1, "q": "Proses pengeluaran zat sisa metabolisme dari dalam tubuh makhluk hidup disebut...", "o": ["Defekasi", "Respirasi", "Ekskresi", "Fotosintesis"], "a": 2, "p": "Ekskresi adalah proses pembuangan zat-zat sisa metabolisme yang sudah tidak berguna bagi tubuh makhluk hidup."}, {"lv": 2, "q": "Perhatikan penulisan nama ilmiah tanaman jagung berikut: *Zea mays*. Aturan penulisan binomial nomenklatur yang benar pada contoh tersebut adalah...", "o": ["Kata pertama menunjukkan petunjuk spesies dan diawali huruf kecil", "Kata kedua menunjukkan marga (genus) dan ditulis dengan huruf kapital", "Kata pertama menunjukkan marga (genus) dengan huruf kapital di awal, dan kata kedua menunjukkan spesies dengan huruf kecil", "Seluruh kata ditulis menggunakan huruf kapital dan dicetak tegak"], "a": 2, "p": "Dalam tata nama binomial, kata pertama adalah genus (huruf besar di awal) dan kata kedua adalah petunjuk spesies (huruf kecil), serta dicetak miring atau digarisbawahi terpisah."}, {"lv": 2, "q": "Kelompok hewan vertebrata yang memiliki ciri berdarah panas, bernapas dengan paru-paru, tubuh ditutupi rambut, dan umumnya melahirkan anak adalah...", "o": ["Reptilia", "Amfibi", "Aves", "Mammalia"], "a": 3, "p": "Mammalia (hewan menyusui) memiliki ciri utama berdarah panas, bernapas dengan paru-paru, berambut, dan menyusui anaknya."}, {"lv": 2, "q": "Tumbuhan lumut (Bryophyta) dan tumbuhan paku (Pteridophyta) memiliki persamaan ciri utama, yaitu...", "o": ["Belum memiliki pembuluh angkut xilem dan floem", "Berkembang biak menggunakan spora", "Menghasilkan biji sebagai alat perkembangbiakan", "Memiliki akar, batang, dan daun sejati"], "a": 1, "p": "Lumut dan paku sama-sama merupakan tumbuhan tak berbiji yang dalam siklus hidupnya berkembang biak menggunakan spora."}, {"lv": 2, "q": "Kunci determinasi sederhana membantu mengidentifikasi makhluk hidup berdasarkan...", "o": ["Nama penemunya di laboratorium", "Pilihan ciri-ciri berpasangan yang saling berlawanan", "Jumlah kromosom di dalam sel", "Asal wilayah geografis tempat ditemukan"], "a": 1, "p": "Kunci determinasi disusun berdasarkan serangkaian pernyataan berpasangan (dikotom) yang saling berlawanan untuk mengidentifikasi kelompok makhluk hidup."}, {"lv": 3, "q": "Suatu organisme diamati di bawah mikroskop dengan ciri-ciri: sel bersifat eukariotik, bersel satu (uniseluler maupun multiseluler sederhana), tidak memiliki jaringan sejati, dan hidup di tempat lembap. Organisme ini dikelompokkan ke dalam kingdom...", "o": ["Monera", "Protista", "Plantae", "Animalia"], "a": 1, "p": "Protista adalah eukariotik sederhana (uniseluler atau koloni) yang tidak memiliki diferensiasi jaringan seperti tumbuhan, hewan, atau jamur sejati."}, {"lv": 3, "q": "Dua jenis hewan memiliki nama ilmiah *Panthera leo* (singa) dan *Panthera tigris* (harimau). Berdasarkan tingkat taksonnya, kedua hewan tersebut berada pada tingkat takson yang sama yaitu pada level...", "o": ["Spesies", "Genus", "Famili", "Varietas"], "a": 1, "p": "Kata pertama (*Panthera*) menunjukkan nama marga atau genus yang sama, sedangkan kata kedua menunjukkan spesies yang berbeda."}, {"lv": 3, "q": "Bakteri dan alga hijau-biru (Cyanobacteria) dikelompokkan ke dalam kingdom Monera karena memiliki ciri khas sel yang bersifat...", "o": ["Eukariotik (memiliki membran inti sel)", "Prokariotik (tidak memiliki membran inti sel)", "Multiseluler dengan dinding sel dari zat kitin", "Memiliki klorofil sejati di dalam kloroplas"], "a": 1, "p": "Anggota kingdom Monera memiliki sel tipe prokariotik, yaitu sel yang materi inti selnya belum diselubungi oleh membran inti."}, {"lv": 3, "q": "Mengapa jamur (Fungi) tidak dimasukkan ke dalam kelompok tumbuhan (Plantae), meskipun dulunya sempat dikira tumbuhan?", "o": ["Karena jamur tidak dapat bergerak sama sekali", "Karena jamur tidak memiliki klorofil sehingga tidak dapat berfotosintesis dan dinding selnya tersusun atas zat kitin, bukan selulosa", "Karena jamur berkembang biak menggunakan biji kecil", "Karena jamur hidup sebagai parasit di dalam tanah"], "a": 1, "p": "Jamur berbeda dari tumbuhan karena bersifat heterotrof (tidak berfotosintesis) dan memiliki dinding sel dari zat kitin, sedangkan tumbuhan berfotosintesis dan berdinding selulosa."}]}, {"id": "ipa-k7-2", "name": "Zat dan perubahannya", "desc": "Perubahan fisika dan kimia", "idx": 2, "soal": [{"lv": 1, "q": "Perubahan suatu zat yang tidak menghasilkan zat jenis baru dan sifat zat penyusunnya tetap sama disebut...", "o": ["Perubahan kimia", "Perubahan fisika", "Reaksi pembakaran", "Perubahan biologis"], "a": 1, "p": "Perubahan fisika adalah perubahan wujud atau bentuk suatu zat tanpa mengubah komposisi kimia atau menghasilkan zat jenis baru."}, {"lv": 1, "q": "Contoh peristiwa yang menunjukkan terjadinya perubahan kimia dalam kehidupan sehari-hari adalah...", "o": ["Air mendidih menjadi uap", "Es batu mencair", "Besi berkarat", "Gula larut dalam air"], "a": 2, "p": "Besi berkarat adalah perubahan kimia karena menghasilkan zat baru (karat besi/ferri oksida) yang sifatnya berbeda dari besi asalnya."}, {"lv": 1, "q": "Pencampuran gula pasir ke dalam secangkir air hangat hingga larut dan terasa manis merupakan contoh dari...", "o": ["Perubahan fisika", "Perubahan kimia", "Reaksi oksidasi", "Pembentukan endapan"], "a": 0, "p": "Gula yang larut di dalam air tetap memiliki sifat rasa manis dan dapat dipisahkan kembali melalui kristalisasi, sehingga termasuk perubahan fisika."}, {"lv": 1, "q": "Ciri utama yang selalu menyertai terjadinya suatu perubahan kimia adalah...", "o": ["Terbentuknya zat baru dengan sifat yang berbeda", "Perubahan wujud dari padat menjadi cair", "Perubahan suhu lingkungan tanpa reaksi", "Perubahan ukuran dan bentuk fisik benda"], "a": 0, "p": "Karakteristik utama perubahan kimia adalah terbentuknya zat baru akibat adanya reaksi kimia."}, {"lv": 2, "q": "Perhatikan beberapa peristiwa berikut: (1) Kertas dibakar menjadi abu, (2) Lilin meleleh saat dinyalakan, (3) Susu berubah menjadi asam (basi), (4) Beras ditumbuk menjadi tepung. Peristiwa yang termasuk perubahan kimia ditunjukkan oleh nomor...", "o": ["(1) dan (2)", "(1) dan (3)", "(2) dan (4)", "(3) dan (4)"], "a": 1, "p": "Kertas dibakar (1) dan susu basi (3) menghasilkan zat baru (perubahan kimia). Lilin meleleh (2) dan beras ditumbuk (4) hanya mengubah bentuk/wujud (perubahan fisika)."}, {"lv": 2, "q": "Mengapa nyala lilin yang mencair digolongkan sebagai peristiwa yang mengalami dua jenis perubahan sekaligus (fisika dan kimia)?", "o": ["Karena batangnya mencair (fisika) dan sumbunya memendek", "Karena lelehan lilin mengalami perubahan wujud (fisika) sedangkan gas hasil pembakaran sumbu dan uap lilin menghasilkan zat sisa pembakaran seperti jelaga dan gas (kimia)", "Karena lilin dibuat dari dua bahan yang berbeda", "Karena terjadi perubahan warna pada api lilin"], "a": 1, "p": "Batang lilin yang mencair adalah perubahan fisika, sedangkan pembakaran pada sumbu lilin yang menghasilkan asap, jelaga, dan gas karbon dioksida adalah perubahan kimia."}, {"lv": 2, "q": "Pernyataan yang paling tepat untuk membedakan sifat fisika dan sifat kimia suatu zat adalah...", "o": ["Sifat fisika berkaitan dengan wujud dan penampilan luar tanpa mengubah susunan zat, sedangkan sifat kimia berkaitan dengan kemampuan zat untuk bereaksi membentuk zat lain", "Sifat fisika hanya dapat diamati setelah zat terbakar habis", "Sifat kimia tidak melibatkan perubahan zat di dalam reaksi", "Sifat fisika dan sifat kimia memiliki makna yang sepenuhnya sama"], "a": 0, "p": "Sifat fisika diamati tanpa mengubah identitas zat, sedangkan sifat kimia menunjukkan bagaimana suatu zat bereaksi atau berubah menjadi zat lain."}, {"lv": 2, "q": "Petani garam membuat garam dapur dengan cara menguapkan air laut di tambak menggunakan bantuan panas matahari. Perubahan wujud dan jenis perubahan zat yang terjadi adalah...", "o": ["Menguap dan termasuk perubahan kimia", "Menguap dan termasuk perubahan fisika", "Membeku dan termasuk perubahan kimia", "Menyublim dan termasuk perubahan kimia"], "a": 1, "p": "Penguapan air laut untuk memisahkan garam adalah pemisahan campuran secara fisik, sehingga air menguap dan zat terlarut tertinggal sebagai perubahan fisika."}, {"lv": 3, "q": "Seorang siswa mereaksikan serbuk belerang dan serbuk besi dalam tabung reaksi dengan cara dipanaskan kuat. Terbentuk zat baru berupa padatan berwarna hitam (besi(II) sulfida) yang sifat kemagnetannya hilang dan tidak dapat dipisahkan lagi dengan magnet biasa. Peristiwa ini merupakan contoh perubahan kimia karena...", "o": ["Campuran tersebut dapat dipisahkan kembali dengan mudah menggunakan tangan", "Terbentuk zat baru dengan sifat fisika dan kimia yang berbeda dari unsur-unsur pembentuk awalnya", "Hanya terjadi perubahan wujud serbuk dari padat menjadi gas", "Massa zat setelah dipanaskan menjadi bertambah sangat banyak"], "a": 1, "p": "Reaksi antara besi dan belerang menghasilkan senyawa baru yang sifat-sifatnya (seperti kemagnetan) sangat berbeda dari unsur pembentuk asalnya, membuktikan terjadinya perubahan kimia."}, {"lv": 3, "q": "Buah apel yang dikupas dan dibiarkan di udara terbuka selama beberapa menit akan berubah warna menjadi kecoklatan. Reaksi oksidasi enzimatik ini membuktikan bahwa...", "o": ["Terjadi perubahan fisika murni pada permukaan apel", "Terjadi perubahan kimia karena enzim di dalam buah bereaksi dengan oksigen di udara membentuk senyawa baru", "Buah apel mengalami penurunan massa secara drastis", "Terjadi perubahan wujud dari padat menjadi gas"], "a": 1, "p": "Perubahan warna cokelat pada buah apel menunjukkan adanya reaksi kimia antara senyawa dalam buah dengan oksigen di udara (oksidasi)."}, {"lv": 3, "q": "Pada proses fotosintesis, tumbuhan hijau menyerap air, karbon dioksida, dan energi cahaya matahari untuk menghasilkan glukosa dan oksigen. Berdasarkan tinjauan ilmu kimia, proses fotosintesis tergolong sebagai...", "o": ["Perubahan fisika karena terjadi perubahan wujud air", "Perubahan kimia karena zat-zat pereaksi (reaktan) berubah menjadi zat hasil reaksi (produk) yang memiliki struktur dan sifat baru", "Perubahan wujud benda dari gas langsung menjadi padat", "Perubahan biologi murni yang tidak melibatkan hukum kimia"], "a": 1, "p": "Fotosintesis adalah reaksi kimia kompleks di mana zat-zat sederhana diubah menjadi zat kompleks (glukosa) dan oksigen, sehingga memenuhi kriteria perubahan kimia."}, {"lv": 3, "q": "Suatu zat X dipanaskan di dalam wadah tertutup. Zat tersebut meleleh, lalu mendidih, dan terbentuk gas tanpa meninggalkan residu atau arang. Setelah gas didinginkan, terbentuk kembali cairan murni X dengan massa total yang sama persis seperti semula. Kesimpulan paling akurat mengenai fenomena tersebut adalah...", "o": ["Zat X mengalami perubahan kimia secara total", "Zat X mengalami perubahan fisika bolak-balik (reversibel) tanpa ada zat baru yang terbentuk", "Zat X mengalami dekomposisi termal permanen", "Telah terjadi reaksi pembakaran yang menghasilkan zat sisa"], "a": 1, "p": "Perubahan wujud dari padat ke cair lalu ke gas dan kembali lagi menjadi cair tanpa perubahan massa dan sifat zat menunjukkan siklus perubahan fisika yang reversibel."}]}], "8": [{"id": "ipa-k8-0", "name": "Gerak dan gaya", "desc": "Hukum Newton", "idx": 0, "soal": [{"lv": 1, "q": "Hukum I Newton sering disebut juga sebagai hukum kelembaman atau inersia. Bunyi hukum I Newton berkaitan dengan keadaan benda yang...", "o": ["Selalu bergerak dengan kecepatan tetap jika tidak ada resultan gaya yang bekerja", "Bergerak dengan percepatan yang berbanding lurus dengan massa", "Memberikan gaya aksi dan reaksi yang besarnya sama", "Mengalami percepatan gravitasi bumi"], "a": 0, "p": "Hukum I Newton menyatakan bahwa benda yang diam akan tetap diam, dan benda yang bergerak lurus beraturan akan tetap bergerak jika resultan gaya yang bekerja pada benda sama dengan nol."}, {"lv": 1, "q": "Persamaan matematis yang menyatakan hubungan antara gaya (F), massa (m), and percepatan (a) berdasarkan Hukum II Newton adalah...", "o": ["F = m / a", "F = m x a", "a = F x m", "m = F x a"], "a": 1, "p": "Berdasarkan Hukum II Newton, percepatan suatu benda berbanding lurus dengan resultan gaya yang bekerja dan berbanding terbalik dengan massanya, dirumuskan sebagai F = m x a."}, {"lv": 1, "q": "Ketika kita mendayung perahu, dayung mendorong air ke belakang, dan air mendorong perahu bergerak ke depan. Peristiwa ini merupakan penerapan dari...", "o": ["Hukum I Newton", "Hukum II Newton", "Hukum III Newton", "Hukum Kekekalan Energi"], "a": 2, "p": "Hukum III Newton menyatakan bahwa setiap ada gaya aksi akan timbul gaya reaksi yang besarnya sama tetapi berlawanan arah (aksi-reaksi)."}, {"lv": 1, "q": "Satuan internasional (SI) untuk besaran gaya adalah...", "o": ["Joule", "Watt", "Newton", "Pascal"], "a": 2, "p": "Newton (N) adalah satuan SI untuk gaya, yang setara dengan kg·m/s²."}, {"lv": 2, "q": "Sebuah mobil bermassa 1.000 kg melaju di jalan raya dengan percepatan sebesar 3 m/s². Besar resultan gaya yang bekerja pada mobil tersebut adalah...", "o": ["300 Newton", "1.000 Newton", "3.000 Newton", "333 Newton"], "a": 2, "p": "Menggunakan rumus Hukum II Newton (F = m x a), maka F = 1.000 kg x 3 m/s² = 3.000 Newton."}, {"lv": 2, "q": "Saat mobil yang sedang melaju kencang tiba-tiba diremendadak oleh pengemudi, badan penumpang di dalam mobil akan terdorong terhentak ke depan. Peristiwa ini adalah contoh nyata dari...", "o": ["Kelembaman (Inersia) berdasarkan Hukum I Newton", "Hukum II Newton tentang percepatan gerak", "Hukum III Newton tentang gaya aksi reaksi", "Gaya gesek statis maksimum"], "a": 0, "p": "Tubuh penumpang cenderung mempertahankan keadaannya yang sedang bergerak (Hukum I Newton), sehingga saat mobil berhenti mendadak, tubuh terdorong ke depan."}, {"lv": 2, "q": "Dua buah gaya bekerja pada sebuah balok secara searah. Gaya pertama F1 = 15 N dan gaya kedua F2 = 25 N. Besarnya resultan gaya (F total) yang bekerja pada balok tersebut adalah...", "o": ["10 Newton", "25 Newton", "40 Newton", "375 Newton"], "a": 2, "p": "Jika dua gaya bekerja pada arah yang sama, resultan gaya diperoleh dengan menjumlahkan kedua gaya tersebut: F total = 15 N + 25 N = 40 Newton."}, {"lv": 2, "q": "Sebuah benda bermassa 4 kg mengalami percepatan sebesar 5 m/s² akibat ditarik oleh suatu gaya tertentu. Jika massa benda tersebut diubah menjadi 10 kg dengan besar gaya tarik yang tetap sama, berapakah percepatan yang dialami benda sekarang?", "o": ["2 m/s²", "4 m/s²", "12,5 m/s²", "20 m/s²"], "a": 0, "p": "Gaya awal F = m x a = 4 kg x 5 m/s² = 20 N. Dengan gaya tetap 20 N dan massa baru 10 kg, percepatan a = F / m = 20 / 10 = 2 m/s²."}, {"lv": 3, "q": "Sebuah balok bermassa 5 kg berada di atas lantai licin tanpa gesekan. Balok tersebut ditarik mendatar oleh dua gaya yang berlawanan arah: F1 = 30 N ke kanan dan F2 = 10 N ke kiri. Percepatan yang dialami balok adalah...", "o": ["2 m/s² ke kanan", "4 m/s² ke kanan", "8 m/s² ke kiri", "40 m/s² ke kanan"], "a": 1, "p": "Resultan gaya F = 30 N - 10 N = 20 N (arah ke kanan). Percepatan a = F / m = 20 N / 5 kg = 4 m/s² ke arah kanan."}, {"lv": 3, "q": "Pernyataan manakah yang paling tepat menjelaskan mengapa roket dapat meluncur naik ke angkasa luar padahal di luar angkasa tidak ada udara untuk mendorong?", "o": ["Roket memanfaatkan gaya dorong dari roket yang menolak lapisan udara bumi", "Gas panas bertekanan tinggi disemburkan ke bawah (aksi), sehingga memunculkan dorongan reaksi yang mengarah ke atas pada roket (Hukum III Newton)", "Gaya gravitasi bulan menarik roket menjauhi bumi", "Massa roket berkurang drastis sehingga berubah menjadi benda ringan tanpa berat"], "a": 1, "p": "Roket meluncur berdasarkan Hukum III Newton. Gas buang yang disemburkan ke bawah (aksi) mendorong roket melesat naik ke atas (reaksi), tidak bergantung pada keberadaan udara di luar."}, {"lv": 3, "q": "Sebuah kotak berat bermassa M ditarik dengan gaya F di atas lantai kasar sehingga menimbulkan gaya gesek kinetik sebesar f. Kotak tersebut bergerak dengan percepatan tetap sebesar a. Jika massa kotak diduakalilipatkan (2M) dan gaya tarik yang diberikan juga dijadikan dua kali lipat (2F), bagaimana kondisi percepatan benda yang baru?", "o": ["Percepatan menjadi seperempat kali semula", "Percepatan menjadi setengah kali semula", "Percepatan tetap bernilai sama seperti semula", "Percepatan menjadi empat kali lipat"], "a": 2, "p": "Mengabaikan gaya gesek untuk penyederhanaan proporsi, a = F / m. Jika F menjadi 2F dan m menjadi 2M, maka percepatan a baru = (2F) / (2M) = F / m = tetap seperti semula."}, {"lv": 3, "q": "Seseorang bermassa 50 kg berada di dalam sebuah lift yang sedang bergerak. Jika pada suatu saat lift tersebut mendadak bergerak turun dengan percepatan 2 m/s² (dengan percepatan gravitasi g = 10 m/s²), berapakah gaya normal (tekanan kaki pada lantai lift) yang dirasakan orang tersebut?", "o": ["400 Newton", "500 Newton", "600 Newton", "100 Newton"], "a": 0, "p": "Berdasarkan hukum Newton pada lift turun: N = m(g - a). Maka N = 50 kg x (10 - 2) m/s² = 50 x 8 = 400 Newton."}]}, {"id": "ipa-k8-1", "name": "Sistem pencernaan manusia", "desc": "Organ dan enzim pencernaan", "idx": 1, "soal": [{"lv": 1, "q": "Proses pencernaan makanan secara mekanik dan kimiawi yang pertama kali terjadi di dalam tubuh manusia berlangsung di dalam...", "o": ["Lambung", "Kerongkongan", "Rongga mulut", "Usus halus"], "a": 2, "p": "Pencernaan pertama kali terjadi di rongga mulut, di mana gigi melakukan pencernaan mekanik dan air liur (enzim ptialin) melakukan pencernaan kimiawi."}, {"lv": 1, "q": "Enzim pepsin yang dihasilkan oleh lambung memiliki fungsi utama untuk mencerna zat...", "o": ["Protein menjadi pepton", "Lemak menjadi asam lemak", "Amilum menjadi glukosa", "Vitamin dan mineral"], "a": 0, "p": "Di dalam lambung, enzim pepsin bekerja dalam suasana asam untuk memecah protein menjadi pepton."}, {"lv": 1, "q": "Saluran berbentuk seperti tabung otot yang menghubungkan rongga mulut dengan lambung disebut...", "o": ["Tenggorokan", "Kerongkongan (esofagus)", "Usus 12 jari", "Uretra"], "a": 1, "p": "Kerongkongan atau esofagus adalah saluran makanan yang menyalurkan bolus dari mulut ke lambung menggunakan gerakan peristaltik."}, {"lv": 1, "q": "Organ pencernaan utama tempat terjadinya penyerapan (absorpsi) sari-sari makanan secara maksimal adalah...", "o": ["Lambung", "Usus besar", "Usus halus", "Anus"], "a": 2, "p": "Usus halus memiliki bagian vili (jonjot usus) yang berfungsi menyerap sari-sari makanan ke dalam aliran darah."}, {"lv": 2, "q": "Perhatikan fungsi organ pencernaan berikut: (1) Menyerap sisa-sisa air dari sisa makanan, (2) Membusukkan sisa makanan oleh bantuan bakteri Escherichia coli. Organ pencernaan yang dimaksud adalah...", "o": ["Usus halus", "Usus besar (kolon)", "Pankreas", "Lambung"], "a": 1, "p": "Usus besar berfungsi menyerap kembali kandungan air serta membusukkan sisa makanan menjadi feses dengan bantuan bakteri E. coli."}, {"lv": 2, "q": "Getah empedu yang dihasilkan oleh organ hati memiliki peranan penting dalam proses pencernaan, yaitu...", "o": ["Mengubah protein menjadi asam amino", "Mengemulsikan (memecah) lemak agar mudah diserap tubuh", "Membunuh kuman penyakit di dalam lambung", "Membentuk vitamin K pada usus besar"], "a": 1, "p": "Empedu menghasilkan cairan empedu yang berfungsi mengemulsikan lemak (memecah butiran lemak besar menjadi kecil) agar enzim lipase dapat bekerja."}, {"lv": 2, "q": "Gerakan meremas dan mendorong makanan secara bergelombang yang terjadi di sepanjang saluran pencernaan mulai dari kerongkongan hingga usus dinamakan gerakan...", "o": ["Peristaltik", "Translasi", "Vibrasi", "Rotasi"], "a": 0, "p": "Gerakan peristaltik adalah kontraksi dan relaksasi otot polos saluran pencernaan yang mendorong makanan bergerak maju."}, {"lv": 2, "q": "Enzim lipase yang dihasilkan oleh pankreas berperan dalam pencernaan kimiawi untuk mengubah...", "o": ["Amilum menjadi maltosa", "Protein menjadi asam amino", "Lemak menjadi asam lemak dan gliserol", "Susu menjadi kasein"], "a": 2, "p": "Enzim lipase berfungsi khusus untuk menghidrolisis lemak menjadi asam lemak dan gliserol di dalam usus halus."}, {"lv": 3, "q": "Seorang pasien mengalami gangguan kesehatan di mana dinding lambungnya meradang dan terluka akibat produksi asam lambung (HCl) yang berlebihan karena stres atau pola makan tidak teratur. Penyakit ini dikenal sebagai...", "o": ["Konstipasi", "Maag (Gastritis)", "Diare", "Apendisitis"], "a": 1, "p": "Gastritis atau maag adalah peradangan pada dinding lambung yang disebabkan oleh iritasi asam lambung berlebih atau infeksi bakteri."}, {"lv": 3, "q": "Di dalam usus halus bagian duodenum (usus 12 jari), terdapat getah pankreas yang mengandung enzim amilase, tripsin, dan lipase. Jika seseorang mengalami gangguan fungsi pankreas secara total, proses pencernaan manakah yang akan paling terganggu?", "o": ["Pencernaan karbohidrat, protein, dan lemak sekaligus", "Hanya penyerapan air di usus besar", "Pencernaan mekanik di dalam rongga mulut", "Produksi asam klorida pembunuh kuman di lambung"], "a": 0, "p": "Pankreas memproduksi tiga enzim utama pencernaan kimiawi, yaitu amilase (karbohidrat), tripsin (protein), dan lipase (lemak), sehingga kerusakan pankreas mengganggu ketiga proses tersebut."}, {"lv": 3, "q": "Mengapa makanan yang mengandung karbohidrat (seperti nasi atau roti) jika dikunyah agak lama di dalam mulut akan terasa sedikit manis?", "o": ["Karena gigi menghasilkan zat gula alami saat mengunyah", "Karena enzim ptialin (amilase) di dalam air liur mengubah sebagian amilum (polisakarida) menjadi maltosa (disakarida)", "Karena asam lambung naik ke rongga mulut", "Karena kelenjar ludah memproduksi pemanis buatan"], "a": 1, "p": "Enzim ptialin di dalam air liur mencerna karbohidrat kompleks (amilum) secara kimiawi menjadi gula sederhana (maltosa), sehingga terasa manis."}, {"lv": 3, "q": "Seseorang yang sering menahan buang air besar (BAB) atau kurang mengonsumsi makanan berserat tinggi rentan mengalami kesulitan BAB (konstipasi). Alasan fisiologis terjadinya konstipasi adalah...", "o": ["Terlalu banyak air yang diserap kembali oleh usus besar sehingga feses menjadi sangat kering dan keras", "Usus halus berhenti memproduksi enzim pencernaan", "Empedu gagal mengemulsikan lemak di usus", "Terjadi infeksi bakteri di kerongkongan"], "a": 0, "p": "Konstipasi terjadi ketika sisa makanan terlalu lama berada di dalam usus besar, menyebabkan penyerapan air berlebihan sehingga feses mengeras dan sulit dikeluarkan."}]}, {"id": "ipa-k8-2", "name": "Tekanan zat", "desc": "Tekanan zat padat, cair, dan gas", "idx": 2, "soal": [{"lv": 1, "q": "Besarnya tekanan zat padat sebanding dengan besar gaya tekan dan berbanding terbalik dengan...", "o": ["Massa benda", "Luas bidang tekan", "Volume benda", "Kecepatan benda"], "a": 1, "p": "Rumus tekanan zat padat adalah P = F / A, di mana P adalah tekanan, F adalah gaya, dan A adalah luas bidang tekan. Tekanan berbanding terbalik dengan luas permukaan."}, {"lv": 1, "q": "Alat pengukur tekanan udara luar disebut dengan...", "o": ["Termometer", "Barometer", "Higrometer", "Manometer"], "a": 1, "p": "Barometer adalah alat yang digunakan untuk mengukur tekanan udara luar atau tekanan atmosfer."}, {"lv": 1, "q": "Hukum yang menyatakan bahwa tekanan yang diberikan pada zat cair di dalam ruang tertutup akan diteruskan ke segala arah dengan sama besar adalah...", "o": ["Hukum Archimedes", "Hukum Newton", "Hukum Pascal", "Hukum Boyle"], "a": 2, "p": "Hukum Pascal berbunyi bahwa tekanan yang diberikan pada zat cair dalam ruang tertutup diteruskan ke segala arah sama besar."}, {"lv": 1, "q": "Faktor utama yang memengaruhi besarnya tekanan hidrostatis pada suatu titik di dalam zat cair adalah...", "o": ["Luas wadah tempat air", "Massa total zat cair", "Kedalaman titik dari permukaan air", "Warna zat cair"], "a": 2, "p": "Rumus tekanan hidrostatis adalah Ph = ρ × g × h, di mana h adalah kedalaman zat cair dari permukaan."}, {"lv": 2, "q": "Sebuah balok bermassa dan berukuran tertentu diletakkan di atas tanah. Agar menghasilkan tekanan yang paling besar pada tanah, posisi balok tersebut seharusnya...", "o": ["Diletakkan pada sisi yang memiliki luas penampang paling besar", "Diletakkan pada sisi yang memiliki luas penampang paling kecil", "Diletakkan secara miring membentuk sudut 45 derajat", "Diberi tambahan beban di bagian samping"], "a": 1, "p": "Karena tekanan berbanding terbalik dengan luas bidang (P = F/A), luas penampang yang paling kecil akan menghasilkan tekanan yang paling besar."}, {"lv": 2, "q": "Mengapa fondasi bangunan bertingkat dibuat lebih lebar dan besar di bagian bawahnya?", "o": ["Agar memperkecil tekanan yang diterima oleh tanah di bawahnya", "Agar memperbesar gaya tekan ke tanah", "Agar air hujan tidak mudah masuk ke dalam bangunan", "Agar estetika bangunan terlihat lebih menarik"], "a": 0, "p": "Fondasi yang lebih lebar memperbesar luas bidang tekan (A), sehingga tekanan (P) yang diberikan bangunan ke tanah menjadi lebih kecil dan tanah tidak ambles."}, {"lv": 2, "q": "Seekor ikan berenang di dalam akuarium. Faktor yang menyebabkan ikan tersebut mengalami tekanan hidrostatis yang semakin besar adalah...", "o": ["Ikan berenang semakin mendekati permukaan air", "Ikan berenang semakin mendekati dasar akuarium", "Ikan berenang diam di satu tempat", "Volume air di dalam akuarium dikurangi"], "a": 1, "p": "Semakin dalam ikan berenang (mendekati dasar), kedalaman (h) semakin besar, sehingga tekanan hidrostatis yang dialaminya juga semakin besar."}, {"lv": 2, "q": "Penerapan prinsip kerja Hukum Archimedes dapat ditemukan pada alat...", "o": ["Dongkrak hidrolik", "Rem hidrolik mobil", "Kapal laut dan kapal selam", "Pompa ban sepeda"], "a": 2, "p": "Kapal laut dan kapal selam memanfaatkan gaya ke atas (gaya Archimedes) sesuai dengan berat air yang dipindahkan."}, {"lv": 3, "q": "Sebuah dongkrak hidrolik memiliki penampang kecil dengan luas A1 dan penampang besar A2. Jika pada penampang kecil diberi gaya F1, maka gaya angkat F2 pada penampang besar akan menjadi sangat besar karena...", "o": ["Tekanan pada zat cair diteruskan ke segala arah dengan sama besar", "Gaya yang bekerja berbanding terbalik dengan luas penampang", "Volume zat cair bertambah besar di penampang kedua", "Massa jenis zat cair berubah mengikuti ukuran penampang"], "a": 0, "p": "Prinsip dongkrak hidrolik didasarkan pada Hukum Pascal, di mana tekanan di setiap bagian zat cair dalam ruang tertutup adalah sama (P1 = P2)."}, {"lv": 3, "q": "Sebuah benda dimasukkan ke dalam air dan ternyata benda tersebut melayang. Pernyataan yang benar mengenai kondisi benda tersebut adalah...", "o": ["Massa jenis benda lebih besar daripada massa jenis air", "Berat benda lebih kecil daripada gaya ke atas oleh air", "Massa jenis benda sama dengan massa jenis air", "Gaya ke atas air sama dengan nol"], "a": 2, "p": "Benda melayang terjadi ketika gaya ke atas sama dengan berat benda, yang berarti massa jenis benda sama dengan massa jenis zat cair (ρ benda = ρ air)."}, {"lv": 3, "q": "Mengapa daun telinga kita kadang terasa sakit atau berdengung saat pesawat terbang mendarat (landing) dari ketinggian?", "o": ["Tekanan udara di luar pesawat lebih kecil daripada tekanan di dalam rongga telinga", "Tekanan udara luar meningkat dengan cepat, sedangkan tekanan di dalam telinga masih menyesuaikan", "Suhu udara di dalam kabin pesawat mengalami penurunan drastis", "Getaran mesin pesawat merusak saraf pendengaran secara langsung"], "a": 1, "p": "Saat pesawat turun, tekanan udara luar meningkat lebih tinggi dibanding tekanan udara di dalam telinga tengah, sehingga gendang telinga terdorong ke dalam dan menimbulkan rasa sakit."}, {"lv": 3, "q": "Dua buah balok identik diletakkan di atas lantai. Balok pertama diletakkan dengan posisi horizontal (luas alas besar), sedangkan balok kedua diletakkan dengan posisi vertikal (luas alas kecil). Perbandingan tekanan balok pertama terhadap balok kedua adalah...", "o": ["Lebih besar", "Lebih kecil", "Sama besar", "Bergantung pada massa balok"], "a": 1, "p": "Tekanan berbanding terbalik dengan luas bidang tekan. Balok pertama memiliki luas alas lebih besar, sehingga tekanannya lebih kecil dibandingkan balok kedua."}]}], "9": [{"id": "ipa-k9-0", "name": "Listrik dinamis", "desc": "Arus, tegangan, hambatan, hukum Ohm", "idx": 0, "soal": [{"lv": 1, "q": "Satuan Internasional (SI) yang digunakan untuk menyatakan besarnya kuat arus listrik adalah...", "o": ["Volt", "Ohm", "Watt", "Ampere"], "a": 3, "p": "Kuat arus listrik dinyatakan dalam satuan Ampere (A). Volt adalah satuan tegangan, Ohm untuk hambatan, dan Watt untuk daya listrik."}, {"lv": 1, "q": "Alat yang digunakan untuk mengukur beda potensial atau tegangan listrik antara dua titik dalam suatu rangkaian adalah...", "o": ["Amperemeter", "Voltmeter", "Ohmmeter", "Barometer"], "a": 1, "p": "Voltmeter adalah alat khusus untuk mengukur tegangan listrik. Amperemeter digunakan untuk arus, dan Ohmmeter untuk hambatan."}, {"lv": 1, "q": "Arus listrik dapat mengalir dalam suatu rangkaian tertutup jika terdapat perbedaan...", "o": ["Massa benda", "Potensial listrik", "Volume zat", "Jenis bahan"], "a": 1, "p": "Arus listrik mengalir dari titik berpotensial tinggi ke potensial rendah. Tanpa adanya beda potensial (tegangan), arus tidak akan mengalir."}, {"lv": 1, "q": "Menurut Hukum Ohm, hubungan antara tegangan (V), kuat arus (I), dan hambatan (R) secara matematis dituliskan sebagai...", "o": ["V = I / R", "V = I + R", "V = I x R", "V = R / I"], "a": 2, "p": "Hukum Ohm menyatakan bahwa tegangan (V) berbanding lurus dengan kuat arus (I) dan hambatan (R), dirumuskan V = I x R."}, {"lv": 2, "q": "Dalam sebuah kawat penghantar, mengalir muatan listrik sebesar 120 Coulomb selama 2 menit. Besar kuat arus listrik yang mengalir adalah...", "o": ["1 Ampere", "2 Ampere", "60 Ampere", "240 Ampere"], "a": 0, "p": "Menggunakan rumus I = Q / t. Waktu dikonversi ke detik (2 menit = 120 s). Maka, I = 120 C / 120 s = 1 Ampere."}, {"lv": 2, "q": "Sebuah lampu memiliki hambatan sebesar 20 Ohm dan dihubungkan dengan sumber tegangan 12 Volt. Kuat arus yang mengalir pada lampu tersebut adalah...", "o": ["240 A", "1,6 A", "0,5 A", "0,6 A"], "a": 3, "p": "Berdasarkan Hukum Ohm: I = V / R. Maka, I = 12 V / 20 Ohm = 0,6 Ampere."}, {"lv": 2, "q": "Tiga buah hambatan masing-masing sebesar 4 Ohm, 6 Ohm, dan 10 Ohm disusun secara seri. Besar hambatan pengganti (total) dari rangkaian tersebut adalah...", "o": ["20 Ohm", "10 Ohm", "2 Ohm", "60 Ohm"], "a": 0, "p": "Hambatan total rangkaian seri adalah penjumlahan seluruh hambatan: Rs = 4 + 6 + 10 = 20 Ohm."}, {"lv": 2, "q": "Dua buah hambatan masing-masing bernilai 12 Ohm disusun secara paralel. Besar hambatan pengganti rangkaian tersebut adalah...", "o": ["24 Ohm", "12 Ohm", "6 Ohm", "1 Ohm"], "a": 2, "p": "Untuk hambatan paralel identik: Rp = R / n. Maka, Rp = 12 / 2 = 6 Ohm. Atau menggunakan 1/Rp = 1/12 + 1/12 = 2/12."}, {"lv": 3, "q": "Jika tegangan pada suatu rangkaian listrik dijaga tetap, namun hambatan kawatnya diperkecil menjadi setengah dari semula, maka kuat arus listriknya akan menjadi...", "o": ["Dua kali lipat semula", "Setengah kali semula", "Tetap tidak berubah", "Empat kali lipat semula"], "a": 0, "p": "Karena I = V / R, arus berbanding terbalik dengan hambatan. Jika hambatan (R) menjadi 1/2, maka arus (I) akan naik menjadi 2 kali semula."}, {"lv": 3, "q": "Sebuah kawat penghantar memiliki hambatan R. Jika kawat tersebut diganti dengan kawat sejenis dengan panjang dan suhu yang sama, tetapi diameternya dua kali lipat, maka hambatannya akan menjadi...", "o": ["4 R", "2 R", "1/2 R", "1/4 R"], "a": 3, "p": "Jika diameter 2x, maka luas penampang (A) menjadi 4x. Karena hambatan (R) berbanding terbalik dengan luas penampang, maka hambatan baru menjadi 1/4 R."}, {"lv": 3, "q": "Pada suatu percabangan rangkaian listrik, arus yang masuk adalah 15 A. Arus tersebut terbagi ke tiga cabang. Cabang pertama 5 A dan cabang kedua 3 A. Berapakah arus pada cabang ketiga?", "o": ["23 A", "7 A", "8 A", "5 A"], "a": 1, "p": "Hukum I Kirchhoff: Arus masuk = Arus keluar. 15 = 5 + 3 + I3. Maka, I3 = 15 - 8 = 7 Ampere."}, {"lv": 3, "q": "Tiga buah hambatan identik masing-masing 9 Ohm disusun paralel, lalu dihubungkan dengan baterai 6 Volt. Kuat arus total yang keluar dari baterai adalah...", "o": ["2 Ampere", "0,5 Ampere", "18 Ampere", "1,5 Ampere"], "a": 0, "p": "Rp = 9 / 3 = 3 Ohm. Kuat arus total (I) = V / Rp = 6 V / 3 Ohm = 2 Ampere."}]}, {"id": "ipa-k9-1", "name": "Pewarisan sifat", "desc": "Gen, kromosom, persilangan Mendel", "idx": 1, "soal": [{"lv": 1, "q": "Unit terkecil pembawa informasi genetik yang diturunkan dari orang tua kepada anaknya disebut...", "o": ["Sel", "Gen", "Kromosom", "Ribosom"], "a": 1, "p": "Gen adalah unit dasar pewarisan sifat yang terletak di dalam lokus kromosom dan berfungsi menentukan karakteristik makhluk hidup."}, {"lv": 1, "q": "Sifat fisik yang dapat diamati langsung pada makhluk hidup, seperti warna bunga merah atau rambut keriting, disebut...", "o": ["Genotipe", "Fenotipe", "Hereditas", "Alel"], "a": 1, "p": "Fenotipe adalah perwujudan fisik dari genotipe yang berinteraksi dengan lingkungan sehingga dapat dilihat secara kasat mata."}, {"lv": 1, "q": "Gregor Mendel menggunakan tanaman kacang ercis dalam percobaannya karena memiliki sifat yang mencolok. Ia kemudian dijuluki sebagai...", "o": ["Bapak Evolusi", "Bapak Biologi", "Bapak Genetika", "Bapak Taksonomi"], "a": 2, "p": "Gregor Mendel disebut Bapak Genetika karena ia yang pertama kali merumuskan hukum-hukum pewarisan sifat secara matematis."}, {"lv": 1, "q": "Susunan genetik suatu individu yang dilambangkan dengan pasangan huruf (seperti AA, Aa, atau aa) disebut...", "o": ["Genotipe", "Fenotipe", "Dominan", "Resesif"], "a": 0, "p": "Genotipe adalah komposisi alel atau identitas genetik suatu organisme yang tidak tampak dari luar."}, {"lv": 2, "q": "Suatu individu disebut heterozigot pada suatu gen apabila memiliki...", "o": ["Dua alel dominan yang sama", "Dua alel resesif yang sama", "Dua alel yang berbeda pada gen tersebut", "Hanya satu alel saja"], "a": 2, "p": "Heterozigot adalah kondisi genetik di mana individu memiliki dua alel yang berbeda (misal Aa) untuk satu karakter tertentu."}, {"lv": 2, "q": "Macam gamet yang akan terbentuk dari individu dengan genotipe AaBb menurut hukum perpaduan bebas adalah...", "o": ["AB dan ab", "Aa dan Bb", "AB, Ab, aB, dan ab", "A, a, B, dan b"], "a": 2, "p": "Individu AaBb akan menghasilkan empat macam gamet melalui kombinasi bebas antara alel A/a dengan alel B/b."}, {"lv": 2, "q": "Pada persilangan monohibrid dominan penuh antara mawar merah (MM) dan putih (mm), perbandingan fenotipe keturunan kedua (F2) adalah...", "o": ["1 Merah : 1 Putih", "1 Merah : 2 Merah Muda : 1 Putih", "3 Merah : 1 Putih", "Semua Merah"], "a": 2, "p": "Persilangan sesama F1 (Mm x Mm) menghasilkan rasio fenotipe 3 (dominan) berbanding 1 (resesif) pada keturunan F2."}, {"lv": 2, "q": "Persilangan antara tanaman berbunga merah dengan berbunga putih menghasilkan keturunan berbunga merah muda. Peristiwa ini menunjukkan adanya sifat...", "o": ["Dominansi penuh", "Intermediet", "Resesif", "Mutasi"], "a": 1, "p": "Intermediet terjadi jika alel dominan tidak menutupi alel resesif secara sempurna, sehingga muncul sifat campuran di antara keduanya."}, {"lv": 3, "q": "Seorang petani menyilangkan tanaman kacang biji bulat kuning (BbKk) dengan kisut hijau (bbkk). Berapa peluang munculnya keturunan kisut hijau?", "o": ["100%", "75%", "50%", "25%"], "a": 3, "p": "Persilangan testcross BbKk x bbkk menghasilkan rasio 1:1:1:1. Fenotipe kisut hijau (bbkk) memiliki peluang 1 dari 4 atau 25%."}, {"lv": 3, "q": "Sel tubuh manusia memiliki 46 kromosom (23 pasang). Berapakah jumlah kromosom yang ada pada sel telur atau sel sperma manusia?", "o": ["46 pasang", "46 buah", "23 pasang", "23 buah"], "a": 3, "p": "Sel kelamin (gamet) bersifat haploid (n), yang berarti hanya memiliki setengah dari jumlah kromosom sel tubuh (2n)."}, {"lv": 3, "q": "Jika suami bergolongan darah A heterozigot (IAi) dan istri bergolongan darah B heterozigot (IBi), kemungkinan golongan darah anaknya adalah...", "o": ["Hanya A dan B", "Hanya AB", "Hanya O", "A, B, AB, dan O"], "a": 3, "p": "Persilangan IAi x IBi dapat menghasilkan empat kombinasi golongan darah: AB (IAIB), A (IAi), B (IBi), dan O (ii)."}, {"lv": 3, "q": "Pada persilangan dihibrid (BbKk x BbKk), jika total keturunan F2 adalah 160 pohon, berapakah perkiraan jumlah pohon berfenotipe bulat kuning?", "o": ["10 pohon", "30 pohon", "90 pohon", "120 pohon"], "a": 2, "p": "Rasio fenotipe F2 dihibrid adalah 9:3:3:1. Bagian bulat kuning adalah 9/16. Perhitungannya: (9/16) x 160 = 90 pohon."}]}, {"id": "ipa-k9-2", "name": "Kemagnetan", "desc": "Sifat magnet dan elektromagnet", "idx": 2, "soal": [{"lv": 1, "q": "Bahan yang dapat ditarik oleh magnet dengan sangat kuat disebut bahan...", "o": ["Diamagnetik", "Paramagnetik", "Feromagnetik", "Nonmagnetik"], "a": 2, "p": "Bahan feromagnetik adalah bahan yang memiliki sifat magnetik kuat dan dapat ditarik kuat oleh magnet, seperti besi dan nikel."}, {"lv": 1, "q": "Bagian dari magnet batang yang memiliki kekuatan gaya tarik paling kuat terletak pada bagian...", "o": ["Kutub magnet", "Bagian tengah magnet", "Seluruh permukaan magnet", "Sisi samping magnet"], "a": 0, "p": "Kutub magnet (utara dan selatan) adalah daerah di ujung magnet yang mempunyai konsentrasi garis gaya magnet paling padat sehingga gaya tariknya paling kuat."}, {"lv": 1, "q": "Jika dua buah kutub magnet yang senama (sejenis) didekatkan, maka yang akan terjadi adalah...", "o": ["Saling tarik-menarik", "Saling tolak-menolak", "Tidak ada interaksi sama sekali", "Saling menempel secara permanen"], "a": 1, "p": "Sifat dasar magnet menyatakan bahwa kutub magnet yang sejenis akan saling tolak-menolak, sedangkan yang berlawanan jenis akan tarik-menarik."}, {"lv": 1, "q": "Cara membuat magnet dengan mengalirkan arus listrik searah (DC) melalui kawat yang dililitkan pada inti besi disebut metode...", "o": ["Induksi", "Gosokan", "Elektromagnetik", "Pemanasan"], "a": 2, "p": "Pembuatan magnet dengan arus listrik disebut elektromagnetik (elektromagnet), di mana inti besi dililiti kawat berarus DC."}, {"lv": 2, "q": "Sebuah batang besi dapat dijadikan magnet dengan cara digosok menggunakan magnet utama. Arah gosokan magnet harus...", "o": ["Bolak-balik secara sembarang", "Satu arah secara teratur", "Diputar melingkar secara cepat", "Ditekan dengan sangat kuat"], "a": 1, "p": "Penggosokan besi harus dilakukan secara searah agar domain-domain magnet di dalam besi dapat diatur menghadap ke arah yang seragam."}, {"lv": 2, "q": "Alat yang berfungsi untuk mengubah energi listrik menjadi energi gerak dengan memanfaatkan prinsip gaya Lorentz adalah...", "o": ["Generator", "Transformator", "Motor listrik", "Akumulator"], "a": 2, "p": "Motor listrik bekerja berdasarkan gaya Lorentz, yaitu prinsip interaksi antara arus listrik dalam medan magnet yang menghasilkan putaran."}, {"lv": 2, "q": "Faktor yang tidak mempengaruhi besar kekuatan medan magnet pada sebuah elektromagnet adalah...", "o": ["Jumlah lilitan kawat", "Kuat arus listrik", "Jenis inti besi", "Warna kawat kumparan"], "a": 3, "p": "Kekuatan elektromagnet dipengaruhi oleh jumlah lilitan, besar kuat arus, dan jenis inti besi. Warna kawat tidak memengaruhi kemagnetan sama sekali."}, {"lv": 2, "q": "Bahan yang sedikit ditolak oleh medan magnet karena tidak memiliki momen magnetik permanen disebut bahan...", "o": ["Feromagnetik", "Paramagnetik", "Diamagnetik", "Konduktor"], "a": 2, "p": "Bahan diamagnetik adalah bahan yang ditolak lemah oleh medan magnet, contohnya seng, emas, dan bismuth."}, {"lv": 3, "q": "Kawat lurus sepanjang 2 meter berada di dalam medan magnet homogen sebesar 5 Tesla. Jika kuat arus yang mengalir melalui kawat adalah 4 Ampere secara tegak lurus terhadap medan magnet, besar gaya Lorentz yang dialami kawat adalah...", "o": ["10 Newton", "20 Newton", "40 Newton", "80 Newton"], "a": 2, "p": "Menggunakan rumus gaya Lorentz F = B x I x l. F = 5 T x 4 A x 2 m = 40 Newton."}, {"lv": 3, "q": "Sebuah transformator memiliki efisiensi 80%. Jika daya listrik primer yang masuk adalah 100 Watt, berapakah besar daya sekunder yang dihasilkan?", "o": ["80 Watt", "100 Watt", "125 Watt", "800 Watt"], "a": 0, "p": "Efisiensi = (P_sekunder / P_primer) x 100%. 80% = (P_s / 100) x 100%, sehingga P_s = 80 Watt."}, {"lv": 3, "q": "Sebuah transformator memiliki perbandingan jumlah lilitan primer dan sekunder (Np : Ns) sebesar 1 : 4. Jika tegangan primer yang diberikan adalah 220 Volt, berapakah tegangan sekunder yang dihasilkan?", "o": ["55 Volt", "110 Volt", "440 Volt", "880 Volt"], "a": 3, "p": "Rumus trafo: Vp / Vs = Np / Ns. 220 / Vs = 1 / 4, maka Vs = 220 x 4 = 880 Volt."}, {"lv": 3, "q": "Batang besi AB didekatkan dengan magnet batang. Ternyata ujung A menarik kutub utara magnet, sedangkan ujung B menolak kutub utara magnet. Dapat disimpulkan bahwa kutub magnet pada batang besi AB adalah...", "o": ["A adalah kutub utara, B adalah kutub selatan", "A adalah kutub selatan, B adalah kutub utara", "A dan B keduanya adalah kutub utara", "A dan B bukan merupakan magnet"], "a": 1, "p": "Ujung A menarik kutub utara magnet, berarti A adalah kutub selatan. Ujung B menolak kutub utara, berarti B adalah kutub utara (karena kutub sejenis tolak-menolak)."}]}]}};
